window.SEARCH_INDEX = [{"c": "GAMES101 L08 · 第 8 讲：着色（一）——Blinn-Phong 光照模型", "t": "1. 从漫反射复习开始：为什么需要高光和环境光", "x": "上一讲我们学了 Lambertian 漫反射项：\n\\[ L_d = k_d \\frac{I}{r^2} \\max(0, \\mathbf{n} \\cdot \\mathbf{l}) \\]\n其中 \\(k_d\\) 是漫反射系数（表面颜色），\\(I/r^2\\) 是点光源到达着色点的能量（随距离平方衰减），\\(", "u": "GAMES101/101_L08.html#s1"}, {"c": "GAMES101 L08 · 第 8 讲：着色（一）——Blinn-Phong 光照模型", "t": "2. 高光项：用半程向量近似镜面反射", "x": "高光的物理直觉是：当观察方向 \\(\\mathbf{v}\\) 接近镜面反射方向 \\(\\mathbf{R}\\) 时，表面看起来最亮。直接计算 \\(\\mathbf{R}\\) 再比较 \\(\\mathbf{v}\\) 与 \\(\\mathbf{R}\\) 的夹角是可行的，但 Blinn-Phong 用了一个更省事的", "u": "GAMES101/101_L08.html#s2"}, {"c": "GAMES101 L08 · 第 8 讲：着色（一）——Blinn-Phong 光照模型", "t": "3. 环境光项与完整 Blinn-Phong 模型", "x": "环境光项是一个常数：\n\\[ L_a = k_a I_a \\]\n其中 \\(k_a\\) 是环境光系数，\\(I_a\\) 是环境光强度。它不依赖法线、光源方向或观察方向，纯粹是为了给阴影区域一个基础亮度，避免全黑。课件强调这是近似/伪造的，不是物理正确的全局光照。\n把三项加起来，得到完整的 Blinn-Ph", "u": "GAMES101/101_L08.html#s3"}, {"c": "GAMES101 L08 · 第 8 讲：着色（一）——Blinn-Phong 光照模型", "t": "4. 着色频率：平面、顶点、像素三种做法", "x": "有了着色公式，下一个问题是：在哪里计算着色？ 这称为着色频率（shading frequency）。课件给出三种经典方式：\n\n平面着色（Flat shading）：每个三角形计算一次着色，使用三角形的面法线。整个三角形颜色均匀。适合低多边形风格，但光滑表面会有明显棱角。\nGouraud 着色：每个顶", "u": "GAMES101/101_L08.html#s4"}, {"c": "GAMES101 L08 · 第 8 讲：着色（一）——Blinn-Phong 光照模型", "t": "5. 实时渲染管线：着色发生在哪一步", "x": "课件用一张流程图展示了实时渲染管线（graphics pipeline）的主要阶段：\n\n应用阶段（Application）：CPU 准备顶点数据、变换矩阵、光源等。\n顶点处理（Vertex Processing）：对每个顶点执行模型、视图、投影变换，输出屏幕空间顶点。\n三角形处理（Triangle ", "u": "GAMES101/101_L08.html#s5"}, {"c": "GAMES101 L08 · 第 8 讲：着色（一）——Blinn-Phong 光照模型", "t": "6. 着色器程序：在 GPU 上写光照", "x": "着色器程序（shader program）是运行在 GPU 上的程序，分为顶点着色器和片元着色器。课件给出一个 GLSL 片元着色器的例子：\nuniform sampler2D myTexture; // 程序参数\nuniform vec3 lightDir;       // 程序参数\nvaryi", "u": "GAMES101/101_L08.html#s6"}, {"c": "GAMES101 L08 · 第 8 讲：着色（一）——Blinn-Phong 光照模型", "t": "7. 纹理映射：给表面加上细节颜色", "x": "纹理映射（texture mapping）解决“不同位置有不同颜色”的问题。比如木地板有木纹，足球有图案。\n基本思想：3D 表面是 2D 的，每个 3D 表面点都可以映射到一张 2D 图像（纹理）上的一个位置。这个位置用纹理坐标 \\((u,v)\\) 表示，通常 \\(u,v \\in [0,1]\\)。\n", "u": "GAMES101/101_L08.html#s7"}, {"c": "GAMES101 L08 · 核心结论", "t": "Blinn-Phong 模型 = 环境光 + 漫反射 + 高光，分别用系数 k_a、k_d、k_s 控制强度。", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 核心结论", "t": "漫反射项与观察方向无关，只取决于法线 n 与光线方向 l 的夹角；高光项依赖观察方向，用半程向量 h 与法线 n 的夹角衡量。", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 核心结论", "t": "半程向量 h = (v + l) / ||v + l||，用 n·h 的幂函数近似镜面反射，指数 p 越大高光越集中。", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 核心结论", "t": "环境光是一个常数项，用来近似全局光照并填补阴影，不是物理精确的。", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 核心结论", "t": "着色频率决定光照计算发生在哪里：平面着色每三角形一次，Gouraud 每顶点一次并插值颜色，Phong 每像素一次并插值法线。", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 核心结论", "t": "逐像素着色需要插值法线，插值后必须归一化，否则光照结果会出错。", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 核心结论", "t": "实时渲染管线中，顶点处理负责坐标变换，光栅化把三角形离散成片元，片元处理执行着色（包括 Blinn-Phong 和纹理采样）。", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 核心结论", "t": "纹理映射给表面每个点一个颜色，通过纹理坐标 (u,v) 把 2D 图像映射到 3D 表面，是增加细节的主要手段。", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 术语", "t": "Blinn-Phong reflectance model / Blinn-Phong 反射模型", "x": "环境光、漫反射、高光三项相加的经典光照模型。", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 术语", "t": "Half vector / 半程向量", "x": "观察方向与光线方向的角平分线方向，用于近似镜面反射。", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 术语", "t": "Shininess / 高光指数", "x": "控制高光范围的指数 p，越大高光越集中。", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 术语", "t": "Flat shading / 平面着色", "x": "每个三角形计算一次着色，使用面法线。", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 术语", "t": "Gouraud shading / Gouraud 着色", "x": "每个顶点计算着色，三角形内插值颜色。", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 术语", "t": "Phong shading / Phong 着色", "x": "每个像素计算着色，三角形内插值法线。", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 术语", "t": "Graphics pipeline / 图形管线", "x": "从顶点到像素的实时渲染流程。", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 术语", "t": "Rasterization / 光栅化", "x": "把三角形离散成片元的过程。", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 术语", "t": "Texture mapping / 纹理映射", "x": "用 2D 图像给 3D 表面着色。", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 术语", "t": "Barycentric coordinates / 重心坐标", "x": "用于三角形内插值的坐标系统。", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 练习", "t": "写出 Blinn-Phong 反射模型的完整公式，并说明每一项的物理意义。", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 练习", "t": "已知单位向量 \\(\\mathbf{v} = (0,0,1)\\)，\\(\\mathbf{l} = (0,1,0)\\)，\\(\\mathbf{n} = (0,0,1)\\", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 练习", "t": "比较平面着色、Gouraud 着色和 Phong 着色三种频率的优缺点，并说明各自适用的场景。", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 练习", "t": "在实时渲染管线中，着色发生在哪个阶段？光栅化阶段做了什么？", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L08 · 练习", "t": "纹理映射中，纹理坐标 \\((u,v)\\) 的作用是什么？如何让纹理在表面上重复平铺？", "x": "", "u": "GAMES101/101_L08.html"}, {"c": "GAMES101 L05 · 第 5 讲：光栅化（一）——三角形与采样", "t": "1. 从投影到屏幕：视口变换", "x": "上一讲我们通过模型（Model）、视图（View）、投影（Projection）变换，把三维场景中的物体变换到了标准立方体（Canonical Cube）[-1,1]^3 中。但标准立方体还不是屏幕上的像素，我们需要把它映射到屏幕空间，这一步叫视口变换（Viewport Transformation", "u": "GAMES101/101_L05.html#s1"}, {"c": "GAMES101 L05 · 第 5 讲：光栅化（一）——三角形与采样", "t": "2. 三角形：光栅化的基本图元", "x": "光栅化的目标是把连续几何图形画到离散像素上。为什么用三角形？因为三角形是最基本的多边形，任何多边形都可以拆成三角形；而且三角形有唯一性质：\n\n保证是平面（三点确定一个平面）；\n内部定义明确（不会自交）；\n有明确的方法在顶点之间插值（重心坐标插值）。\n\n在屏幕上，我们已知三角形三个顶点投影后的位置，需", "u": "GAMES101/101_L05.html#s2"}, {"c": "GAMES101 L05 · 第 5 讲：光栅化（一）——三角形与采样", "t": "3. 采样：用像素中心判断三角形覆盖", "x": "光栅化可以看作一个二值函数：给定三角形和点 (x,y)，判断点是否在三角形内。\n\\[\n\\text{inside}(t, x, y) = \\begin{cases} 1 & \\text{点 } (x,y) \\text{ 在三角形 } t \\text{ 内} \\\\ 0 & \\text{否则} \\end{", "u": "GAMES101/101_L05.html#s3"}, {"c": "GAMES101 L05 · 第 5 讲：光栅化（一）——三角形与采样", "t": "4. 加速光栅化：包围盒与增量遍历", "x": "如果对屏幕上的每个像素都调用 inside 函数，计算量太大。实际上，三角形只覆盖屏幕的一小部分。我们可以用包围盒（Bounding Box）：取三角形三个顶点 x 和 y 的最小值和最大值，形成一个矩形，只遍历这个矩形内的像素。\n对于细长或旋转的三角形，包围盒可能仍然包含大量不在三角形内的像素。增", "u": "GAMES101/101_L05.html#s4"}, {"c": "GAMES101 L05 · 第 5 讲：光栅化（一）——三角形与采样", "t": "5. 真实显示与锯齿：采样不足的后果", "x": "真实显示器（LCD、OLED 等）的像素并不是完美的均匀色块，但本课程假设像素是均匀颜色的方块，这足以讨论光栅化。\n当我们把采样得到的二值图像送到显示器，显示器物理上发出的是离散的像素信号，而原始的三角形是连续函数。对比连续三角形和采样后的像素图像，会发现边缘呈锯齿状（Jaggies）。这就是走样（", "u": "GAMES101/101_L05.html#s5"}, {"c": "GAMES101 L05 · 核心结论", "t": "视口变换把标准立方体 [-1,1]^3 的 xy 平面映射到 [0,width]×[0,height] 的屏幕空间，z 保持不变。", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 核心结论", "t": "屏幕是像素数组，像素 (x,y) 的中心在 (x+0.5,y+0.5)，屏幕覆盖范围是 [0,width]×[0,height]。", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 核心结论", "t": "光栅化 = 对每个像素中心采样一个二值函数 inside(tri,x,y)，判断是否在三角形内。", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 核心结论", "t": "判断点是否在三角形内：用三次叉积（或重心坐标）检查点是否始终在三条边的同一侧。", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 核心结论", "t": "边界情况：点落在三角形公共边上时，可定义规则（如左上规则）避免重复或遗漏。", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 核心结论", "t": "包围盒（Bounding Box）只遍历三角形覆盖的像素区域，避免检查整个屏幕。", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 核心结论", "t": "增量遍历（Incremental Traversal）利用三角形边的连续性，适合细长或旋转的三角形。", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 核心结论", "t": "锯齿（Jaggies）是采样不足导致的走样（Aliasing），后续用反走样（Antialiasing）解决。", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 术语", "t": "Viewport Transformation / 视口变换", "x": "把标准立方体映射到屏幕像素空间的变换", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 术语", "t": "Rasterization / 光栅化", "x": "把连续几何图形转换为离散像素的过程", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 术语", "t": "Pixel / 像素", "x": "屏幕上的一个颜色小方块，是图像的基本单元", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 术语", "t": "Sampling / 采样", "x": "在离散点上评估连续函数的过程", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 术语", "t": "Inside Test / 内外测试", "x": "判断点是否在三角形内的二值函数", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 术语", "t": "Bounding Box / 包围盒", "x": "包围三角形的最小矩形，用于限制遍历范围", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 术语", "t": "Aliasing / 走样", "x": "采样不足导致的高频细节失真，表现为锯齿", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 术语", "t": "Jaggies / 锯齿", "x": "光栅化后三角形边缘出现的阶梯状现象", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 术语", "t": "Incremental Traversal / 增量遍历", "x": "利用三角形边的连续性逐行扫描像素的优化方法", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 练习", "t": "视口变换矩阵中，缩放和平移项分别是什么？如果屏幕分辨率是 800×600，写出完整的视口变换矩阵。", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 练习", "t": "如何用叉积判断点 Q 是否在三角形 P0P1P2 内？写出三个叉积表达式并说明判断条件。", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 练习", "t": "为什么光栅化后三角形边缘会出现锯齿？简述原因并列举一种减轻锯齿的方法。", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 练习", "t": "包围盒（Bounding Box）如何加速光栅化？对于细长三角形，包围盒可能有什么问题？", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L05 · 练习", "t": "在 UE 或 Unity 中，如何开启抗锯齿？至少说出两种方法。", "x": "", "u": "GAMES101/101_L05.html"}, {"c": "GAMES101 L01 · 第 1 讲：课程总览——计算机图形学是什么、学什么、怎么学", "t": "1. 图形学到底在做什么：从模型到图像的转换", "x": "计算机图形学（Computer Graphics）的核心任务，可以用一句话概括：把对三维世界的描述（模型）变成一张二维图像。这里的“模型”可以是三角形网格、曲线曲面、粒子系统、甚至是一段物理仿真规则；而“图像”就是我们最终在屏幕上看到的像素阵列。\n课件用一张对比图说明了图形学与计算机视觉（Compu", "u": "GAMES101/101_L01.html#s1"}, {"c": "GAMES101 L01 · 第 1 讲：课程总览——计算机图形学是什么、学什么、怎么学", "t": "2. 为什么值得学：智力挑战与技术挑战", "x": "课件给出了两个层面的理由。\n根本性的智力挑战：图形学要创造并交互一个逼真的虚拟世界，这要求你理解物理世界的方方面面——光如何传播、材质如何反射、物体如何运动、人眼如何感知。同时还要发明新的计算方法、显示技术和交互技术。换句话说，图形学是“用计算模拟现实”的集大成者。\n具体的技术挑战包括：\n\n透视投影", "u": "GAMES101/101_L01.html#s2"}, {"c": "GAMES101 L01 · 第 1 讲：课程总览——计算机图形学是什么、学什么、怎么学", "t": "3. 课程四大模块：光栅化、几何、光线追踪、动画仿真", "x": "本课程主要覆盖四个部分，它们构成了现代图形学的骨架。\n（1）光栅化（Rasterization）\n把三维几何图元（主要是三角形）投影到屏幕上，再把投影后的图元拆成片元（fragment，可以理解为候选像素），最后决定每个像素的颜色。课件称光栅化是“视频游戏等实时应用的金标准”，因为它的计算模式非常适", "u": "GAMES101/101_L01.html#s3"}, {"c": "GAMES101 L01 · 第 1 讲：课程总览——计算机图形学是什么、学什么、怎么学", "t": "4. 这门课不教什么：API、引擎与建模软件", "x": "课件专门用几页澄清了课程的边界，这对自学者尤其重要，可以避免走弯路。\n不教图形 API 的语法：OpenGL、DirectX、Vulkan 是图形 API，本课程不教如何调用它们。课件说：“我们学的是图形学，不是图形 API！”并承诺学完本课程后，你可以自己学会这些 API。为什么？因为 API 只", "u": "GAMES101/101_L01.html#s4"}, {"c": "GAMES101 L01 · 第 1 讲：课程总览——计算机图形学是什么、学什么、怎么学", "t": "5. 课程安排与学习工具：作业、IDE 与学术诚信", "x": "课件最后介绍了课程的后勤信息，对自学者也有参考价值。\n课程网站：所有信息（大纲、幻灯片、阅读材料）都在课程主页上，建议收藏。\n参考书：没有强制教材，但强烈推荐 Steve Marschner 和 Peter Shirley 的《Fundamentals of Computer Graphics》（第", "u": "GAMES101/101_L01.html#s5"}, {"c": "GAMES101 L01 · 核心结论", "t": "计算机图形学是把模型（Model）变成图像（Image）的过程，与计算机视觉（图像→模型）方向相反。", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 核心结论", "t": "图形学的典型应用包括：游戏、电影特效、动画、设计可视化、VR/AR、仿真、GUI、字体渲染等。", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 核心结论", "t": "本课程四大核心模块：光栅化（实时渲染基石）、曲线与网格（几何表示）、光线追踪（离线渲染金标准）、动画/模拟（运动与物理）。", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 核心结论", "t": "光栅化是游戏等实时应用的金标准；光线追踪是电影动画等离线应用的金标准。", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 核心结论", "t": "本课程讲图形学原理，不教 OpenGL/DirectX/Vulkan 的 API 语法，也不教 Maya/Blender/Unity/UE 的操作。", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 核心结论", "t": "图形学与计算机视觉没有绝对边界，但问题方向相反：图形学是模型→图像，视觉是图像→模型。", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 核心结论", "t": "课程作业以 C++ 编程为主，提供代码骨架和虚拟机镜像，要求独立完成并遵守学术诚信。", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 核心结论", "t": "推荐使用 Visual Studio 或 VS Code 等 IDE 进行 C++ 开发，避免使用纯文本编辑器。", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 术语", "t": "Computer Graphics / 计算机图形学", "x": "研究如何用计算机生成图像，核心是模型→图像。", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 术语", "t": "Computer Vision / 计算机视觉", "x": "研究如何让计算机理解图像，核心是图像→模型/描述。", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 术语", "t": "Rasterization / 光栅化", "x": "将几何图元投影并拆分成像素/片元的过程，实时渲染的基石。", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 术语", "t": "Ray Tracing / 光线追踪", "x": "从相机发射光线并递归计算交点与着色，离线渲染的金标准。", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 术语", "t": "Bezier Curve / 贝塞尔曲线", "x": "由控制点定义的光滑曲线，广泛用于建模和动画。", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 术语", "t": "Catmull-Clark Subdivision / Catmull-Clark 细分", "x": "一种曲面细分算法，通过迭代细分多边形网格得到光滑曲面。", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 术语", "t": "Mass-spring System / 质点-弹簧系统", "x": "用质点和弹簧模拟布料、软体等物理动画的方法。", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 术语", "t": "Fragment / 片元", "x": "光栅化后生成的候选像素，携带深度、颜色等属性。", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 术语", "t": "IDE / 集成开发环境", "x": "提供代码编辑、编译、调试等功能的软件，如 Visual Studio。", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 练习", "t": "用自己的话解释计算机图形学与计算机视觉的区别，并各举一个应用例子。", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 练习", "t": "本课程的四大核心模块是什么？分别对应哪种典型应用（实时/离线）？", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 练习", "t": "为什么本课程不教 OpenGL/DirectX/Vulkan 的 API 语法？学完本课程后你能做到什么？", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 练习", "t": "假设你要自学 UE 的材质系统，本课程哪些模块会直接帮助到你？请至少列出两个。", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L01 · 练习", "t": "课件推荐使用 IDE 而不是纯文本编辑器，为什么？请结合 C++ 项目开发说明。", "x": "", "u": "GAMES101/101_L01.html"}, {"c": "GAMES101 L03 · 第 3 讲：变换（一）——2D 变换与齐次坐标", "t": "1. 为什么需要变换：建模与观察", "x": "图形学里我们几乎无时无刻不在做变换。课件把动机分成两类：\n\n建模（Modeling）：场景里的物体需要被摆放、旋转、缩放。比如一个椅子模型，你可能先缩放成不同尺寸，再旋转朝向，最后平移到房间的某个位置。课件用平移、旋转、缩放三张图说明：同一个物体通过变换可以产生丰富的变化。\n观察（Viewing）：", "u": "GAMES101/101_L03.html#s1"}, {"c": "GAMES101 L03 · 第 3 讲：变换（一）——2D 变换与齐次坐标", "t": "2. 2D 线性变换：缩放、反射、切变、旋转", "x": "课件先介绍几种基本的 2D 变换，它们都可以写成 2×2 矩阵乘以向量 的形式：\n\\[ \\begin{pmatrix} x' \\\\ y' \\end{pmatrix} = \\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix} \\begin{pmatrix} x \\\\", "u": "GAMES101/101_L03.html#s2"}, {"c": "GAMES101 L03 · 第 3 讲：变换（一）——2D 变换与齐次坐标", "t": "3. 平移的困境与齐次坐标的引入", "x": "平移的公式很简单：\\( x' = x + t_x,\\ y' = y + t_y \\)。但它无法写成 \\( \\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix} \\begin{pmatrix} x \\\\ y \\end{pmatrix} \\) 的形式，因为矩阵乘法是线", "u": "GAMES101/101_L03.html#s3"}, {"c": "GAMES101 L03 · 第 3 讲：变换（一）——2D 变换与齐次坐标", "t": "4. 仿射变换与齐次坐标下的统一形式", "x": "仿射变换（Affine Transformation） 定义为线性变换加平移：\n\\[ \\begin{pmatrix} x' \\\\ y' \\end{pmatrix} = \\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix} \\begin{pmatrix} x \\\\ ", "u": "GAMES101/101_L03.html#s4"}, {"c": "GAMES101 L03 · 第 3 讲：变换（一）——2D 变换与齐次坐标", "t": "5. 变换的组合与顺序", "x": "多个变换可以按顺序作用，例如先旋转再平移：\\( x' = T \\cdot R \\cdot x \\)。矩阵乘法满足结合律，所以可以先把所有变换矩阵乘成一个矩阵，再作用于顶点：\n\\[ A_n(\\cdots A_2(A_1(x))) = (A_n \\cdots A_2 A_1) x \\]\n这样做的好处是性", "u": "GAMES101/101_L03.html#s5"}, {"c": "GAMES101 L03 · 第 3 讲：变换（一）——2D 变换与齐次坐标", "t": "6. 逆变换与 3D 变换", "x": "逆变换（Inverse Transform） 把变换撤销：如果 \\( M \\) 把 x 变到 y，那么 \\( M^{-1} \\) 把 y 变回 x。几何上，逆变换就是反向操作（例如旋转 \\( \\theta \\) 的逆是旋转 \\( -\\theta \\)）。\n3D 变换与 2D 完全类似，只是多一维：\n", "u": "GAMES101/101_L03.html#s6"}, {"c": "GAMES101 L03 · 核心结论", "t": "变换分为建模变换（对物体做平移/旋转/缩放）和视图变换（3D 到 2D 投影），是图形学最基础的工具。", "x": "", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 核心结论", "t": "2D 线性变换（缩放、旋转、切变、反射）都可以写成 2×2 矩阵乘法 x' = M x。", "x": "", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 核心结论", "t": "平移不是线性变换，无法用 2×2 矩阵表示；引入齐次坐标（增加 w 分量）后，所有仿射变换都能统一成 3×3 矩阵乘法。", "x": "", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 核心结论", "t": "齐次坐标中，2D 点写作 (x, y, 1)^T，2D 向量写作 (x, y, 0)^T；点+点得到 w=2 需除以 w 才回到点。", "x": "", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 核心结论", "t": "多个变换按顺序相乘可合并为一个矩阵，矩阵从右向左作用于向量；顺序不同结果不同（矩阵乘法不交换）。", "x": "", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 核心结论", "t": "绕任意点 c 旋转 = 平移到原点 → 旋转 → 平移回去，即 T(c)·R(α)·T(-c)。", "x": "", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 核心结论", "t": "3D 仿射变换用 4×4 矩阵表示，点 (x,y,z,1)，向量 (x,y,z,0)，一般 (x,y,z,w) 表示点 (x/w, y/w, z/w)。", "x": "", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 术语", "t": "Transformation / 变换", "x": "对物体位置、朝向、大小或观察方式的数学操作。", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 术语", "t": "Affine Transformation / 仿射变换", "x": "线性变换加平移，保持直线和平行性。", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 术语", "t": "Homogeneous Coordinates / 齐次坐标", "x": "增加 w 分量，使平移可写成矩阵乘法。", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 术语", "t": "Scale / 缩放", "x": "沿坐标轴按比例放大或缩小。", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 术语", "t": "Rotation / 旋转", "x": "绕原点（或指定点）转动一定角度。", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 术语", "t": "Shear / 切变", "x": "一个坐标随另一个坐标线性偏移。", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 术语", "t": "Reflection / 反射", "x": "关于某条轴或平面的镜像。", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 术语", "t": "Composite Transform / 组合变换", "x": "多个变换矩阵相乘得到一个总矩阵。", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 术语", "t": "Inverse Transform / 逆变换", "x": "撤销变换的矩阵，几何上是反向操作。", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 练习", "t": "写出绕原点逆时针旋转 90° 的 2D 齐次坐标矩阵，并计算点 (1,0) 变换后的坐标。", "x": "", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 练习", "t": "解释为什么平移不能用 2×2 矩阵表示，而齐次坐标可以。", "x": "", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 练习", "t": "给定变换序列：先绕原点旋转 45°，再平移到 (2,3)。写出总变换矩阵，并说明矩阵乘法顺序。", "x": "", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 练习", "t": "如何绕点 (2,2) 逆时针旋转 30°？写出矩阵表达式。", "x": "", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L03 · 练习", "t": "在 Unity 中，一个物体的 localToWorldMatrix 是如何由父级和本地变换得到的？如果先平移后旋转与先旋转后平移，结果有何不同？", "x": "", "u": "GAMES101/101_L03.html"}, {"c": "GAMES101 L04 · 第 4 讲：变换（续）——观测变换与投影", "t": "1. 三维空间里的齐次坐标与仿射变换", "x": "上一讲我们把二维变换写成了 3×3 矩阵，这一讲自然要升到三维。做法完全一样：再加一维。\n\n三维点写成 \\((x, y, z, 1)^T\\)\n三维向量写成 \\((x, y, z, 0)^T\\)\n\n为什么点和向量最后一维不同？因为平移对向量没有意义——向量只表示方向，不该被“搬走”。齐次坐标用最后一维", "u": "GAMES101/101_L04.html#s1"}, {"c": "GAMES101 L04 · 第 4 讲：变换（续）——观测变换与投影", "t": "2. 三维旋转：欧拉角与绕任意轴旋转", "x": "三维旋转比二维复杂，因为可以绕三个轴转。课件先给出绕 x、y、z 轴的基本旋转矩阵：\n\\[\nR_x(\\alpha)=\\begin{pmatrix}1&0&0&0\\\\0&\\cos\\alpha&-\\sin\\alpha&0\\\\0&\\sin\\alpha&\\cos\\alpha&0\\\\0&0&0&1\\end{p", "u": "GAMES101/101_L04.html#s2"}, {"c": "GAMES101 L04 · 第 4 讲：变换（续）——观测变换与投影", "t": "3. 视图变换：把相机搬到原点", "x": "拍照分三步：摆好人和背景（模型变换）、找好角度放相机（视图变换）、按下快门（投影变换）。这一节讲第二步。\n相机需要定义三件事：\n\n位置 \\(\\tilde{e}\\)\n朝向（gaze direction）\\(\\hat{g}\\)\n上方向 \\(\\hat{t}\\)（假设与朝向垂直）\n\n关键观察：如果相机和所有", "u": "GAMES101/101_L04.html#s3"}, {"c": "GAMES101 L04 · 第 4 讲：变换（续）——观测变换与投影", "t": "4. 正交投影：把长方体压成标准立方体", "x": "投影把三维变成二维。正交投影（Orthographic Projection）假设相机在无穷远，平行线保持平行，没有“近大远小”。\n最直观的理解：相机在原点、朝 -Z、上方向 +Y，直接把 z 坐标丢掉，就得到 xy 平面上的图。但这样得到的矩形大小任意，不方便后续处理，所以标准做法是：把任意长方体", "u": "GAMES101/101_L04.html#s4"}, {"c": "GAMES101 L04 · 第 4 讲：变换（续）——观测变换与投影", "t": "5. 透视投影：先挤压视锥，再做正交", "x": "透视投影（Perspective Projection）更符合人眼和相机：近大远小，平行线汇聚于一点。课件引用 Euclid 的“平行线永不相交”说“Euclid was wrong??!!”，其实是透视投影下平行线在图像平面上的投影会相交，这是投影的几何性质，不是欧几里得几何错了。\n透视投影的标准", "u": "GAMES101/101_L04.html#s5"}, {"c": "GAMES101 L04 · 核心结论", "t": "三维点用 (x,y,z,1)、三维向量用 (x,y,z,0) 的齐次坐标表示，仿射变换统一写成 4×4 矩阵。", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 核心结论", "t": "三维旋转可分解为绕 x、y、z 轴的欧拉角旋转，但绕 y 轴的矩阵符号与另外两个相反，因为右手系中 y 轴旋转方向特殊。", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 核心结论", "t": "Rodrigues 公式给出绕任意轴 n 旋转角度 α 的矩阵：cosα·I + (1-cosα)nn^T + sinα·N。", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 核心结论", "t": "视图变换的本质是“把相机搬到原点、朝 -Z、上方向 +Y”，同时所有物体跟着一起变，这样照片不变。", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 核心结论", "t": "M_view = R_view · T_view，其中 T_view 把相机位置移到原点，R_view 把相机的 gaze、up、right 轴对齐到 -Z、+", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 核心结论", "t": "正交投影把长方体 [l,r]×[b,t]×[f,n] 先平移到中心在原点，再缩放成长宽高均为 2 的标准立方体 [-1,1]^3。", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 核心结论", "t": "透视投影分两步：先把视锥“挤压”成长方体（M_persp->ortho），再做正交投影（M_ortho），最终 M_persp = M_ortho · M_pe", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 核心结论", "t": "透视挤压利用相似三角形和齐次坐标的“同点不同表示”性质，并利用近平面和远平面上的 z 不变来解出矩阵第三行。", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 术语", "t": "Homogeneous coordinates / 齐次坐标", "x": "用多一维表示点/向量，统一处理平移与投影。", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 术语", "t": "Affine transformation / 仿射变换", "x": "线性变换加平移，用 4×4 矩阵表示。", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 术语", "t": "Euler angles / 欧拉角", "x": "用绕三个轴的旋转角度描述三维旋转，如 roll/pitch/yaw。", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 术语", "t": "Rodrigues' rotation formula / Rodrigues 旋转公式", "x": "给定单位轴和角度直接构造旋转矩阵。", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 术语", "t": "View transformation / 视图变换", "x": "把相机搬到原点、朝 -Z、上方向 +Y，物体跟着变。", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 术语", "t": "Orthographic projection / 正交投影", "x": "平行投影，无近大远小，把长方体映射到标准立方体。", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 术语", "t": "Perspective projection / 透视投影", "x": "近大远小，平行线汇聚，先挤压视锥再做正交。", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 术语", "t": "Frustum / 视锥", "x": "透视相机可见的截头锥体区域。", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 术语", "t": "Canonical cube / 标准立方体", "x": "[-1,1]^3，投影后的归一化空间。", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 练习", "t": "写出把点 (1,2,3) 先绕 z 轴旋转 90°，再平移 (1,0,0) 的 4×4 变换矩阵，并计算结果点。", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 练习", "t": "解释为什么 R_y(α) 的 sin 项符号与 R_x、R_z 相反。", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 练习", "t": "给定相机位置 e=(0,0,5)，看向 -Z，上方向 +Y，求视图矩阵 M_view。", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 练习", "t": "正交投影中，若 l=-2, r=2, b=-1, t=1, n=1, f=-1，写出 M_ortho。", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L04 · 练习", "t": "在 UE 或 Unity 中创建一个透视相机，把 FOV 从 90° 改为 60°，观察画面变化，并解释投影矩阵中哪个量变了。", "x": "", "u": "GAMES101/101_L04.html"}, {"c": "GAMES101 L07 · 第 7 讲：着色（一）——可见性与 Blinn-Phong 光照模型", "t": "1. 从「谁挡住谁」说起：画家算法为什么不够用", "x": "上一讲我们学会了把三角形光栅化成像素，但屏幕上同一像素可能被多个三角形覆盖，最终该显示谁？最直觉的办法是画家算法（Painter's Algorithm）：像画家画油画一样，先画远处的物体，再用近处的物体覆盖它。\n这个办法的问题有两个：\n\n需要排序。要按深度从远到近画，就得对所有三角形排序，n 个三", "u": "GAMES101/101_L07.html#s1"}, {"c": "GAMES101 L07 · 第 7 讲：着色（一）——可见性与 Blinn-Phong 光照模型", "t": "2. Z-Buffer：为每个像素记一个「当前最近深度」", "x": "Z-Buffer（深度缓冲）的思路非常朴素：为每个像素（更准确地说是每个采样点）记录目前见过的最小深度值。除了帧缓冲（frame buffer）存颜色，我们再开一个缓冲存深度。\n课件特别强调一个约定：为简单起见，假设 z 永远为正，z 越小越近，z 越大越远。这一点很重要，因为不同图形 API 的深", "u": "GAMES101/101_L07.html#s2"}, {"c": "GAMES101 L07 · 第 7 讲：着色（一）——可见性与 Blinn-Phong 光照模型", "t": "3. 为什么 Z-Buffer 是 O(n)：不排序也能正确", "x": "一个常见疑问：画家算法要排序才能正确，Z-Buffer 不排序，凭什么对？\n关键在于Z-Buffer 的正确性与绘制顺序无关。对每个像素来说，它最终保留的是所有覆盖它的样本中 z 最小的那个——这等价于「取最小值」这个操作，而取最小值满足交换律和结合律，所以先画谁后画谁结果都一样。\n复杂度上，假设每", "u": "GAMES101/101_L07.html#s3"}, {"c": "GAMES101 L07 · 第 7 讲：着色（一）——可见性与 Blinn-Phong 光照模型", "t": "4. 着色是什么：局部模型只看一个点", "x": "解决了可见性，接下来解决「颜色从哪来」。课件给出 Merriam-Webster 的词典定义（用线条或色块给插图加深/上色），但在本课程里，着色（Shading）就是「把材质应用到物体上的过程」。\n本讲介绍的模型叫 Blinn-Phong 反射模型（Blinn-Phong Reflectance M", "u": "GAMES101/101_L07.html#s4"}, {"c": "GAMES101 L07 · 第 7 讲：着色（一）——可见性与 Blinn-Phong 光照模型", "t": "5. 漫反射：为什么从哪个角度看都一样亮", "x": "漫反射（Diffuse Reflection） 的物理直觉是：光线打到粗糙表面后被均匀地散射到所有方向。既然各个方向都有光出来，那么从哪个方向看，进入眼睛的能量都一样——所以表面颜色与观察方向无关。\n但「接收到多少光」和「往哪个方向看」是两件事。课件接着问：着色点到底接收了多少能量？答案由 Lamb", "u": "GAMES101/101_L07.html#s5"}, {"c": "GAMES101 L07 · 第 7 讲：着色（一）——可见性与 Blinn-Phong 光照模型", "t": "6. 把漫反射写成公式：Lambertian Shading", "x": "把「接收多少能量」和「材质反射多少」乘起来，就得到 Lambertian（漫反射）着色公式：\n\\[\nL_d = k_d \\cdot \\frac{I}{r} \\cdot \\max(0, n \\cdot l)\n\\]\n逐项解释：\n\n\\(L_d\\)：漫反射出去的光（颜色），最终贡献到像素颜色。\n\\(k_d\\", "u": "GAMES101/101_L07.html#s6"}, {"c": "GAMES101 L07 · 核心结论", "t": "画家算法按深度从远到近画，需要 O(n log n) 排序，且存在无法排序的深度循环（互相遮挡）情况。", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 核心结论", "t": "Z-Buffer 为每个像素额外存一个当前最小深度，逐三角形逐样本比较，总复杂度 O(n)，是 GPU 硬件实现的可见性算法。", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 核心结论", "t": "Z-Buffer 约定 z 越小越近，初始化深度为无穷大，只有新样本 z 更小时才写入颜色和深度。", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 核心结论", "t": "着色（Shading）是「给物体应用材质」的过程；本讲的 Blinn-Phong 是局部模型，只看着色点、法线、光源方向、视线方向，不产生阴影。", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 核心结论", "t": "漫反射与视线方向无关：光线被均匀散射到各个方向，所以从任何角度看颜色一样。", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 核心结论", "t": "Lambert 余弦定律：单位面积接收的光能量正比于 \\(\\cos\\theta = l \\cdot n\\)，光垂直照射时最亮，掠射时趋近于 0。", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 核心结论", "t": "点光源能量按距离平方衰减，课件用 \\(I/r\\) 表示到达着色点的强度（工程上常写 \\(I/r^2\\)，注意单位与约定）。", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 核心结论", "t": "漫反射项 \\(L_d = k_d (I/r) \\max(0, n \\cdot l)\\)：\\(k_d\\) 是漫反射系数（颜色），\\(\\max(0,\\cdot)\\)", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 术语", "t": "Painter's Algorithm / 画家算法", "x": "按深度从远到近绘制，需要排序且无法处理深度循环。", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 术语", "t": "Z-Buffer / 深度缓冲", "x": "为每个样本存当前最小深度，逐样本比较决定可见性，O(n)。", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 术语", "t": "Frame Buffer / 帧缓冲", "x": "存储每个像素最终颜色值的缓冲。", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 术语", "t": "Shading / 着色", "x": "把材质应用到物体上、计算表面颜色的过程。", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 术语", "t": "Blinn-Phong Reflectance Model / Blinn-Phong 反射模型", "x": "把光照拆成环境光、漫反射、高光三项的局部经验模型。", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 术语", "t": "Diffuse Reflection / 漫反射", "x": "光被均匀散射到各方向，颜色与观察方向无关。", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 术语", "t": "Lambert's Cosine Law / Lambert 余弦定律", "x": "单位面积接收光能正比于 cosθ = n·l。", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 术语", "t": "Diffuse Coefficient / 漫反射系数", "x": "公式中的 kd，表示材质反照率/颜色。", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 术语", "t": "Specular Highlights / 高光", "x": "表面接近镜面反射时出现的亮斑，与观察方向有关。", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 术语", "t": "Ambient Lighting / 环境光", "x": "近似间接光照的常数项，避免背光面全黑。", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 练习", "t": "画家算法在什么情况下会失效？Z-Buffer 为什么不需要排序也能得到正确结果？", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 练习", "t": "写出 Z-Buffer 的初始化与更新伪代码，并说明为什么深度缓冲要初始化为无穷大。", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 练习", "t": "一个点光源强度 I=100，距离着色点 r=5，表面法线与光线方向夹角 θ=60°，kd=0.8。按课件公式 \\(L_d = k_d (I/r) \\max(0,", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 练习", "t": "为什么漫反射公式里没有观察方向 v？如果强行乘上 v·n 会发生什么？", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L07 · 练习", "t": "在 UE 或 Unity 中，如何验证「着色 ≠ 阴影」？请给出一个可操作的小实验。", "x": "", "u": "GAMES101/101_L07.html"}, {"c": "GAMES101 L06 · 第 6 讲：光栅化（二）——反走样与深度缓冲", "t": "1. 从“像素中心测试”到锯齿：光栅化就是采样", "x": "上一讲我们学会了把三角形光栅化：对每个像素中心做“点是否在三角形内”的测试（point-in-triangle test），在内部就涂成三角形颜色，否则保留背景。这一讲先把这个过程换一个视角看——光栅化本质上是在二维空间上做采样。\n想象一个连续定义的三角形函数 \\( f(x,y) \\)：在三角形内部", "u": "GAMES101/101_L06.html#s1"}, {"c": "GAMES101 L06 · 第 6 讲：光栅化（二）——反走样与深度缓冲", "t": "2. 走样家族：锯齿、摩尔纹与车轮倒转", "x": "课件把各种采样瑕疵放在一起，是为了让你看到它们的共同结构：\n\n锯齿（Jaggies）：空间上采样不足，斜边变成阶梯。\n摩尔纹（Moiré Patterns）：图像本身有高频细节（例如细密条纹），采样网格与之干涉，产生大尺度花纹。课件里“隔行隔列抽样”的例子就是典型的欠采样图像。\n车轮倒转（Wagon", "u": "GAMES101/101_L06.html#s2"}, {"c": "GAMES101 L06 · 第 6 讲：光栅化（二）——反走样与深度缓冲", "t": "3. 反走样的核心思想：先模糊，再采样", "x": "既然走样是“高频没被采样住”，最直接的想法是：在采样之前把高频去掉。课件用一句话概括：Antialiasing idea: blurring (pre-filtering) before sampling。\n对比两种做法：\n\n点采样（point sampling）：每个像素只取中心一个样本，结果非红", "u": "GAMES101/101_L06.html#s3"}, {"c": "GAMES101 L06 · 第 6 讲：光栅化（二）——反走样与深度缓冲", "t": "4. 频域直觉：采样是复制频谱，滤波是把频谱变窄", "x": "课件用傅里叶（Fourier）工具把上面的直觉讲严格。核心结论有三条：\n（1）任何信号都可以分解为不同频率的正弦/余弦波之和。 图像也一样：平坦区域是低频，边缘和细节是高频。\n（2）采样 = 在频域里复制频谱。 在空间域按间隔采样，等价于在频域把原始频谱以采样频率为周期不断复制。如果原始信号含有高于", "u": "GAMES101/101_L06.html#s4"}, {"c": "GAMES101 L06 · 第 6 讲：光栅化（二）——反走样与深度缓冲", "t": "5. MSAA：用多个子样本近似盒式滤波", "x": "理论上，反走样要求我们计算“像素区域内三角形覆盖的面积比例”。精确求面积对任意三角形很麻烦，工业界的做法是超采样（supersampling）：在一个像素内取多个样本，然后平均。\n课件给出的 MSAA（Multisample Anti-Aliasing）步骤：\n\n在每个像素内取 \\( N \\time", "u": "GAMES101/101_L06.html#s5"}, {"c": "GAMES101 L06 · 第 6 讲：光栅化（二）——反走样与深度缓冲", "t": "6. 现代抗锯齿版图：FXAA、TAA 与 DLSS", "x": "课件最后用一页“Antialiasing Today”把工业界的方案串起来，并再次强调 No free lunch：\n\nFXAA（Fast Approximate AA）：后处理阶段检测图像中的边缘并做模糊。速度极快，但会糊掉细节，属于“先采样再滤波”的近似补救。\nTAA（Temporal AA）：", "u": "GAMES101/101_L06.html#s6"}, {"c": "GAMES101 L06 · 核心结论", "t": "光栅化 = 在像素中心做点采样，采样不足就会产生锯齿（jaggies）等走样现象", "x": "", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 核心结论", "t": "走样的根源是信号变化太快（高频）而采样太慢，高频被“折叠”成低频假象（aliasing）", "x": "", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 核心结论", "t": "反走样的正确顺序是“先滤波（模糊/去高频）再采样”，先采样再模糊只会得到模糊的锯齿", "x": "", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 核心结论", "t": "频域视角：采样 = 在频域复制频谱；滤波 = 把频谱变窄，避免复制时重叠", "x": "", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 核心结论", "t": "MSAA 用像素内多个子样本近似一个像素宽的盒式滤波，代价是显存与带宽，不是免费的", "x": "", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 核心结论", "t": "Z-Buffer 为每个像素记录最近深度，逐三角形逐像素做深度测试，天然处理任意绘制顺序", "x": "", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 核心结论", "t": "现代抗锯齿是折中：FXAA 后处理、TAA 时域累积、DLSS 超分，本质仍是“样本不够”的问题", "x": "", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 术语", "t": "Sampling / 采样", "x": "在连续信号上按固定间隔取离散样本的过程", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 术语", "t": "Aliasing / 走样/混叠", "x": "采样率不足导致高频伪装成低频的现象", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 术语", "t": "Jaggies / 锯齿", "x": "空间采样不足在几何边缘形成的阶梯", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 术语", "t": "Moiré Pattern / 摩尔纹", "x": "高频纹理与采样网格干涉产生的大尺度花纹", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 术语", "t": "Nyquist Frequency / 奈奎斯特频率", "x": "无失真采样要求采样率至少为信号最高频率的两倍", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 术语", "t": "Pre-filtering / 预滤波", "x": "采样前先低通滤波，去掉高于奈奎斯特频率的成分", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 术语", "t": "Box Filter / 盒式滤波器", "x": "在核窗口内做等权平均的低通滤波器", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 术语", "t": "MSAA / 多重采样抗锯齿", "x": "每像素多个子样本近似盒式滤波，主要作用于几何边缘", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 术语", "t": "TAA / 时域抗锯齿", "x": "跨帧累积样本，用时间换空间采样率", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 术语", "t": "Z-Buffer / 深度缓冲", "x": "逐像素记录最近深度，用于解决遮挡", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 练习", "t": "为什么“先采样再滤波”不能真正反走样？请用频域语言解释。", "x": "", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 练习", "t": "一个像素用 4×4 超采样，三角形覆盖了其中 6 个子样本。若三角形颜色为红色 (1,0,0)，背景为白色 (1,1,1)，求该像素最终颜色。", "x": "", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 练习", "t": "MSAA 与 SSAA（超采样抗锯齿）在工程实现上的主要区别是什么？为什么 MSAA 更便宜？", "x": "", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 练习", "t": "在 UE 里你发现画面边缘有锯齿，但项目用的是默认 Deferred 渲染。你会优先尝试哪种抗锯齿方案？如果开启 MSAA 会怎样？", "x": "", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L06 · 练习", "t": "解释为什么提高分辨率能减轻锯齿，但它和 MSAA 解决的是同一个问题的两种不同手段。", "x": "", "u": "GAMES101/101_L06.html"}, {"c": "GAMES101 L11 · 第 11 讲：几何（二）——显式表示：贝塞尔曲线与曲面", "t": "1. 显式表示：从点云到多边形网格", "x": "在图形学中，几何形状的表示大致分为两类：隐式表示（implicit）和显式表示（explicit）。隐式表示不直接给出点，而是用方程 \\( F(x,y,z)=0 \\) 描述形状（例如球体 \\( x^2+y^2+z^2-r^2=0 \\)），好处是容易判断点在内、在外还是表面上，但难以直接采样出表面点。", "u": "GAMES101/101_L11.html#s1"}, {"c": "GAMES101 L11 · 第 11 讲：几何（二）——显式表示：贝塞尔曲线与曲面", "t": "2. 贝塞尔曲线：用控制点“拉”出曲线", "x": "贝塞尔曲线（Bézier curve）是计算机图形学中最著名的参数曲线，由法国工程师 Pierre Bézier 和 Paul de Casteljau 独立提出。它的核心思想是：给定一组控制点（control points），通过递归线性插值生成一条光滑曲线。\n以三次贝塞尔曲线为例，输入四个控制点", "u": "GAMES101/101_L11.html#s2"}, {"c": "GAMES101 L11 · 第 11 讲：几何（二）——显式表示：贝塞尔曲线与曲面", "t": "3. de Casteljau 算法：递归线性插值求曲线上的点", "x": "给定参数 \\( t \\in [0,1] \\)，如何求贝塞尔曲线上对应的点？de Casteljau 算法给出了一个几何直观、数值稳定的递归方法。\n以二次贝塞尔曲线（三个控制点 \\( \\mathbf{b}_0, \\mathbf{b}_1, \\mathbf{b}_2 \\)）为例：\n\n在边 \\( \\mat", "u": "GAMES101/101_L11.html#s3"}, {"c": "GAMES101 L11 · 第 11 讲：几何（二）——显式表示：贝塞尔曲线与曲面", "t": "4. 贝塞尔曲线的代数形式：Bernstein 多项式", "x": "de Casteljau 算法是几何的，但我们可以把它展开成代数形式。对于 \\( n \\) 阶贝塞尔曲线，有：\n\\[ \\mathbf{b}^n(t) = \\sum_{j=0}^{n} \\mathbf{b}_j B_j^n(t) \\]\n其中 \\( \\mathbf{b}_j \\) 是控制点（向量），\\(", "u": "GAMES101/101_L11.html#s4"}, {"c": "GAMES101 L11 · 第 11 讲：几何（二）——显式表示：贝塞尔曲线与曲面", "t": "5. 贝塞尔曲线的关键性质与分段连续性", "x": "贝塞尔曲线有四个非常重要的性质，它们决定了它在工程中的用法：\n\n端点插值：曲线一定经过第一个和最后一个控制点。三次贝塞尔：\\( \\mathbf{b}(0)=\\mathbf{b}_0 \\)，\\( \\mathbf{b}(1)=\\mathbf{b}_3 \\)。\n端点切线与控制点连线一致：三次贝塞尔在起点处", "u": "GAMES101/101_L11.html#s5"}, {"c": "GAMES101 L11 · 第 11 讲：几何（二）——显式表示：贝塞尔曲线与曲面", "t": "6. 双三次贝塞尔曲面：可分离的 1D 求值", "x": "把贝塞尔曲线从一维参数推广到二维参数，就得到贝塞尔曲面。最常用的是双三次贝塞尔曲面片（bicubic Bézier surface patch）：输入是 4x4 控制点网格，输出是参数 \\( (u,v) \\in [0,1]^2 \\) 定义的曲面片。\n求值方法非常巧妙：可分离的 1D de Caste", "u": "GAMES101/101_L11.html#s6"}, {"c": "GAMES101 L11 · 核心结论", "t": "显式表示直接给出几何形状（点、顶点、参数曲线），隐式表示用方程 F(x,y,z)=0 定义，两者可互相转换但各有适用场景。", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 核心结论", "t": "点云是最简单的显式表示，适合大规模数据但欠采样区域难以绘制；多边形网格（三角形/四边形）是图形学中最常用的表示。", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 核心结论", "t": "贝塞尔曲线由控制点定义，de Casteljau 算法用递归线性插值求曲线上任意一点，几何直观且数值稳定。", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 核心结论", "t": "n 阶贝塞尔曲线的代数形式是 Bernstein 基函数的加权和：b^n(t)=Σ_{j=0}^n b_j B_j^n(t)，其中 B_j^n(t)=C(n,j", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 核心结论", "t": "贝塞尔曲线具有端点插值、端点切线与控制点连线一致、仿射变换不变、凸包性质。", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 核心结论", "t": "高阶贝塞尔曲线难以控制，工程上常用分段三次贝塞尔曲线，并保证 C0（端点重合）或 C1（切线方向与大小连续）连续性。", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 核心结论", "t": "双三次贝塞尔曲面是 4x4 控制点网格定义的曲面片，求值时可先对每行做 u 方向的 de Casteljau，再对得到的“移动曲线”做 v 方向的 de Cas", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 核心结论", "t": "B 样条是贝塞尔曲线的超集，具有更强控制能力，但本课程不深入展开。", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 术语", "t": "Explicit Representation / 显式表示", "x": "直接给出几何元素（点、顶点、参数方程）的表示方式。", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 术语", "t": "Implicit Representation / 隐式表示", "x": "用方程 F(x,y,z)=0 定义形状，不直接给出点。", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 术语", "t": "Point Cloud / 点云", "x": "大量离散点的集合，最简单的显式表示。", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 术语", "t": "Polygon Mesh / 多边形网格", "x": "顶点和面片组成的网格，实时渲染最常用。", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 术语", "t": "Bézier Curve / 贝塞尔曲线", "x": "由控制点定义的光滑参数曲线。", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 术语", "t": "de Casteljau Algorithm / de Casteljau 算法", "x": "递归线性插值求贝塞尔曲线上点的方法。", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 术语", "t": "Bernstein Polynomial / Bernstein 多项式", "x": "贝塞尔曲线代数形式中的基函数。", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 术语", "t": "Convex Hull / 凸包", "x": "包含一组点的最小凸集；贝塞尔曲线位于控制点凸包内。", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 术语", "t": "Bicubic Bézier Surface / 双三次贝塞尔曲面", "x": "由 4x4 控制点网格定义的曲面片。", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 术语", "t": "B-spline / B 样条", "x": "贝塞尔曲线的推广，控制能力更强，本课程不深入。", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 练习", "t": "简述点云和多边形网格作为显式表示各自的优缺点。", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 练习", "t": "给定二次贝塞尔曲线控制点 \\( \\mathbf{b}_0=(0,0) \\), \\( \\mathbf{b}_1=(1,1) \\), \\( \\mathbf{b}_2", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 练习", "t": "写出三次贝塞尔曲线的 Bernstein 形式，并说明每个基函数在 \\( t=0 \\) 和 \\( t=1 \\) 处的取值。", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 练习", "t": "解释分段贝塞尔曲线的 C0 和 C1 连续性条件，并说明为什么工程中常用分段三次贝塞尔而不是高阶贝塞尔。", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L11 · 练习", "t": "在 UE 或 Unity 中，如何用贝塞尔曲线实现一个相机沿路径飞行的效果？简述步骤。", "x": "", "u": "GAMES101/101_L11.html"}, {"c": "GAMES101 L10 · 第 10 讲：几何（一）——纹理的高级用法与几何的两种表示", "t": "1. 纹理不只是颜色：GPU 里的“内存 + 范围查询”", "x": "上一讲我们学了纹理映射、重心坐标和 MIPMAP。这一讲开头先补完纹理的“下半场”：纹理在现代 GPU 里早已不限于存颜色。课件给出一句很关键的话：在现代 GPU 中，纹理 = 内存 + 范围查询（filtering）。也就是说，纹理是一块可以被高效随机访问、并且自带滤波（最近邻、双线性、MIPMA", "u": "GAMES101/101_L10.html#s1"}, {"c": "GAMES101 L10 · 第 10 讲：几何（一）——纹理的高级用法与几何的两种表示", "t": "2. 环境贴图：用一张图记录来自四面八方的光", "x": "环境贴图（environment map）的思想是：把场景周围的光照记录在一张纹理上，渲染物体时根据反射方向去查这张图，就能得到近似的光照效果。课件引用了 Blinn &amp; Newell 1976 的工作，以及 Paul Debevec 的光探针（light probes）和 Escher 的", "u": "GAMES101/101_L10.html#s2"}, {"c": "GAMES101 L10 · 第 10 讲：几何（一）——纹理的高级用法与几何的两种表示", "t": "3. 凹凸贴图与法线贴图：用纹理伪造几何细节", "x": "纹理既然能存任意数据，那就可以存高度（height）。凹凸贴图（bump mapping）的思想是：不增加三角形，只在每个像素着色时扰动法线，让光照看起来像有凹凸细节。课件强调：扰动只用于着色计算，不改变实际几何。\n具体做法分两步：\n\n用纹理存储每个 texel 的“高度偏移” \\(h(u,v)\\)", "u": "GAMES101/101_L10.html#s3"}, {"c": "GAMES101 L10 · 第 10 讲：几何（一）——纹理的高级用法与几何的两种表示", "t": "4. 位移贴图：真正移动顶点", "x": "凹凸/法线贴图只是“骗光照”，物体的轮廓和阴影并不会真的改变。位移贴图（displacement mapping） 使用同一张高度纹理，但真正移动顶点位置。课件把它称为更进阶的方法。\n两者的区别可以用一个直观例子说明：一个光滑球体贴上凹凸贴图，看起来表面有凹凸，但球的轮廓仍然是光滑的圆；如果改用位移", "u": "GAMES101/101_L10.html#s4"}, {"c": "GAMES101 L10 · 第 10 讲：几何（一）——纹理的高级用法与几何的两种表示", "t": "5. 纹理的其他高级用法：程序化噪声、预计算着色与体渲染", "x": "课件还列举了几种纹理的高级用法，帮助建立“纹理是通用数据载体”的直觉：\n\n三维程序化噪声 + 实体建模：用 Perlin 噪声等程序化函数生成 3D 纹理，再用它定义物体的形状（例如大理石纹理、云朵）。Ken Perlin 因噪声函数获得奥斯卡技术奖。\n预计算着色（precomputed shadi", "u": "GAMES101/101_L10.html#s5"}, {"c": "GAMES101 L10 · 第 10 讲：几何（一）——纹理的高级用法与几何的两种表示", "t": "6. 几何的两种表示：隐式与显式", "x": "从这一节开始进入本课程的第二部分：几何。课件先展示了很多几何的例子（汽车、动物、人物、病毒等），然后给出核心分类：隐式（implicit） 与 显式（explicit）。\n隐式表示：不直接给出点，而是给出点满足的关系。例如球体可以定义为所有满足 \\(x^2 + y^2 + z^2 = 1\\) 的点。", "u": "GAMES101/101_L10.html#s6"}, {"c": "GAMES101 L10 · 第 10 讲：几何（一）——纹理的高级用法与几何的两种表示", "t": "7. 隐式 vs 显式：采样、内外测试与任务匹配", "x": "这一节用具体任务对比两种表示。\n采样（找出表面上的点）：\n\n隐式：难。例如 \\(f(x,y,z) = (2 - \\sqrt{x^2+y^2})^2 + z^2 - 1 = 0\\)，要找出满足的点并不直观，通常需要数值方法。\n显式：容易。给定参数曲面 \\(f(u,v)\\)，直接代入 (u,v) 就能得", "u": "GAMES101/101_L10.html#s7"}, {"c": "GAMES101 L10 · 第 10 讲：几何（一）——纹理的高级用法与几何的两种表示", "t": "8. 更多隐式表示：代数曲面、CSG、距离函数、水平集与分形", "x": "课件进一步展开隐式表示的具体类型：\n\n代数曲面（algebraic surfaces）：曲面是多项式 \\(f(x,y,z) = 0\\) 的零集。简单形状容易，复杂形状难。\n构造实体几何（CSG）：用布尔运算（并、交、差）组合隐式几何。例如 \\(\\max(f_1, f_2)\\) 表示交集，\\(\\min", "u": "GAMES101/101_L10.html#s8"}, {"c": "GAMES101 L10 · 核心结论", "t": "现代 GPU 中纹理 = 内存 + 范围查询（滤波），是把数据送到片元着色器的通用手段，颜色只是其中一种用法。", "x": "", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 核心结论", "t": "环境贴图用一张图记录来自各个方向的光照；球面贴图在顶部/底部畸变严重，立方体贴图用 6 个面大幅减少畸变，但需要方向到面的计算。", "x": "", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 核心结论", "t": "凹凸/法线贴图通过纹理存储高度，再在片元着色时扰动法线来伪造细节，不增加三角形。", "x": "", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 核心结论", "t": "位移贴图使用同一张高度纹理，但真正移动顶点，因此需要足够密的网格。", "x": "", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 核心结论", "t": "隐式几何用“点满足的关系”来定义（如 f(x,y,z)=0），显式几何直接给出点或通过参数映射给出点。", "x": "", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 核心结论", "t": "隐式表示做内外测试和光线求交容易，但采样出表面点难；显式表示采样容易，但内外测试难。", "x": "", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 核心结论", "t": "没有“最好”的表示，只有最适合当前任务的表示；复杂形状常需要多种表示混合。", "x": "", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 术语", "t": "Environment Map / 环境贴图", "x": "记录来自各个方向光照的纹理。", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 术语", "t": "Cube Map / 立方体贴图", "x": "用 6 个面存储环境，减少球面贴图的极区畸变。", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 术语", "t": "Bump Mapping / 凹凸贴图", "x": "用高度纹理扰动法线，伪造表面细节，不改变几何。", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 术语", "t": "Normal Mapping / 法线贴图", "x": "纹理直接存储法线向量，是凹凸贴图的常见变体。", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 术语", "t": "Displacement Mapping / 位移贴图", "x": "用高度纹理真正移动顶点，改变轮廓。", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 术语", "t": "Implicit Surface / 隐式曲面", "x": "用 f(x,y,z)=0 的关系定义曲面，不直接给出点。", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 术语", "t": "Explicit Surface / 显式曲面", "x": "直接给出点或通过参数映射给出点。", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 术语", "t": "Distance Function / 距离函数", "x": "给出任意点到物体的最小距离（可带符号）。", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 术语", "t": "Level Set / 水平集", "x": "用网格存储函数值，表面是插值后为零的位置。", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 术语", "t": "CSG / 构造实体几何", "x": "用布尔运算组合隐式几何。", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 练习", "t": "解释为什么球面环境贴图在顶部和底部畸变严重，而立方体贴图能减少畸变。", "x": "", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 练习", "t": "在局部坐标下，原始法线为 (0,0,1)，高度函数对 u 的导数为 dp/du = 0.2，对 v 的导数为 dp/dv = -0.1。求扰动后的法线（归一化前", "x": "", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 练习", "t": "判断点 (1/4, 1/4, 1/4) 是否在隐式曲面 f(x,y,z) = x^2 + y^2 + z^2 - 1 = 0 的内部。", "x": "", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 练习", "t": "举出两个任务，分别说明隐式表示和显式表示更合适，并解释原因。", "x": "", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L10 · 练习", "t": "在引擎里，法线贴图为什么必须关闭 sRGB 解码？如果忘记关闭会有什么现象？", "x": "", "u": "GAMES101/101_L10.html"}, {"c": "GAMES101 L12 · 第 12 讲：几何（三）——网格细分、网格简化与阴影映射", "t": "1. 网格处理的三类操作：细分、简化、正则化", "x": "拿到一个三角形网格，我们经常需要在不改变整体外观的前提下改变它的“采样密度”或“顶点分布”。这一讲开头把网格处理（Geometry Processing）归纳为三类操作：\n\n网格细分（Mesh Subdivision / Upsampling）：增加分辨率，也就是增加三角形数量，让模型更光滑、更精细", "u": "GAMES101/101_L12.html#s1"}, {"c": "GAMES101 L12 · 第 12 讲：几何（三）——网格细分、网格简化与阴影映射", "t": "2. Loop 细分：三角形网格的“一分为四”", "x": "Loop 细分（Loop Subdivision）是三角形网格最常用的细分规则。它分两步：\n\n增加三角形（顶点）：把每个三角形一分为四——取三条边的中点作为新顶点，连接它们，原来的一个三角形变成四个小三角形。\n调整顶点位置：新顶点和旧顶点的更新规则不同，这是 Loop 细分的关键。\n\n新顶点的更新：", "u": "GAMES101/101_L12.html#s2"}, {"c": "GAMES101 L12 · 第 12 讲：几何（三）——网格细分、网格简化与阴影映射", "t": "3. Catmull-Clark 细分：一般网格的通用规则", "x": "Loop 细分只适用于三角形网格，而实际模型常包含四边形、五边形等。Catmull-Clark 细分（Catmull-Clark Subdivision）是更通用的规则，适用于任意多边形网格。\n每一步细分做三件事：\n\n在每个面内加一个面点（face point）：通常取该面所有顶点的平均。\n在每条边", "u": "GAMES101/101_L12.html#s3"}, {"c": "GAMES101 L12 · 第 12 讲：几何（三）——网格细分、网格简化与阴影映射", "t": "4. 网格简化与二次误差度量（QEM）", "x": "网格简化的目标是：减少三角形数量，同时尽量保持整体形状。最直接的操作是边坍缩（Edge Collapse）：把一条边的两个端点合并成一个新顶点，删掉相邻的退化三角形。\n但“合并到哪个位置”很关键。课件指出，简单地对顶点做局部平均（local averaging）效果不好，因为会把形状“拉塌”。更好的", "u": "GAMES101/101_L12.html#s4"}, {"c": "GAMES101 L12 · 第 12 讲：几何（三）——网格细分、网格简化与阴影映射", "t": "5. 阴影映射：两趟渲染的深度比较", "x": "阴影映射（Shadow Mapping）是光栅化管线中最常用的阴影技术，是一种图像空间算法：它不需要知道场景的几何结构，只靠深度图比较。\n核心思想一句话：不在阴影中的点，必须同时被光源和相机看到。\n流程分两趟：\n第一趟：从光源渲染。把相机放在光源位置，渲染整个场景，只记录深度（不记录颜色），得到一张", "u": "GAMES101/101_L12.html#s5"}, {"c": "GAMES101 L12 · 第 12 讲：几何（三）——网格细分、网格简化与阴影映射", "t": "6. 阴影映射的问题与工程实践", "x": "阴影映射虽然简单通用，但有一系列固有问题，课件在最后专门列出：\n\n硬阴影（Hard Shadows）：点光源产生的阴影边缘是硬的，没有半影。真实世界中光源有面积，阴影边缘是渐变的（软阴影）。要软阴影需要 PCSS（Percentage-Closer Soft Shadows）或多次采样。\n质量依赖 ", "u": "GAMES101/101_L12.html#s6"}, {"c": "GAMES101 L12 · 核心结论", "t": "几何处理三大操作：细分（升采样、增面数）、简化（降采样、保形状）、正则化（面数不变、改分布）", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 核心结论", "t": "Loop 细分只适用于三角形网格：每个三角形一分为四，新顶点用周围四个旧顶点的加权平均，旧顶点用自身与邻居加权平均", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 核心结论", "t": "Catmull-Clark 细分适用于一般网格：每个面加面点、每条边加边点、连接所有新点；一次细分后所有面都变成四边形，奇异点（度不为 4）数量不再增加", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 核心结论", "t": "网格简化用边坍缩，用二次误差度量（QEM）给每条边打分：新顶点位置应使得到所有相关三角形平面的平方距离之和最小", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 核心结论", "t": "QEM 简化是贪心算法：每次坍缩分数最小的边，坍缩后更新受影响边的分数，直到达到目标面数", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 核心结论", "t": "阴影映射是图像空间算法：先从光源渲染一张深度图（shadow map），再从相机渲染，把可见点投影回光源比较深度", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 核心结论", "t": "阴影映射的核心判据：若着色点投影到光源的深度大于 shadow map 中记录的深度，说明被遮挡，处于阴影中", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 核心结论", "t": "阴影贴图的问题：只能产生硬阴影（点光源）、质量受分辨率限制、浮点深度比较需要 bias/tolerance 来避免自遮挡", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 术语", "t": "Mesh Subdivision / 网格细分", "x": "增加网格分辨率，使模型更光滑", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 术语", "t": "Mesh Simplification / 网格简化", "x": "减少三角形数量，尽量保持形状", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 术语", "t": "Mesh Regularization / 网格正则化", "x": "三角形数量不变，重新分布顶点以提高质量", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 术语", "t": "Loop Subdivision / Loop 细分", "x": "三角形网格的细分规则，一分为四并加权更新顶点", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 术语", "t": "Catmull-Clark Subdivision / Catmull-Clark 细分", "x": "一般网格的细分规则，加面点、边点后连接成四边形", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 术语", "t": "Extraordinary Vertex / 奇异点", "x": "度不为 4 的顶点，细分后数量不再增加", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 术语", "t": "Quadric Error Metrics (QEM) / 二次误差度量", "x": "用点到相关三角形平面的平方距离之和衡量简化误差", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 术语", "t": "Edge Collapse / 边坍缩", "x": "把一条边的两个端点合并，简化网格的基本操作", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 术语", "t": "Shadow Mapping / 阴影映射", "x": "从光源渲染深度图，再从相机比较深度判断阴影", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 术语", "t": "Shadow Acne / 自遮挡", "x": "深度比较精度问题导致表面出现条纹状阴影", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 练习", "t": "Loop 细分中，一个新顶点的位置由哪四个顶点决定？权重分别是多少？", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 练习", "t": "Catmull-Clark 细分一次后，非四边形面的数量是多少？奇异点的数量会如何变化？", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 练习", "t": "简述基于二次误差度量（QEM）的网格简化流程。为什么不用简单的顶点平均？", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 练习", "t": "描述阴影映射的两趟渲染流程，并说明如何判断一个点是否在阴影中。", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L12 · 练习", "t": "在 UE 或 Unity 中，阴影出现条纹状自遮挡（shadow acne），可能的原因是什么？如何调整？", "x": "", "u": "GAMES101/101_L12.html"}, {"c": "GAMES101 L18 · 第 18 讲：高级渲染——高级光传输与外观建模", "t": "1. 有偏与无偏：蒙特卡洛估计器的两种性格", "x": "这一讲是“高级专题”，课件明确说“很多内容，但非常高层，主要是科普”。我们先把最基础的概念钉死：有偏（biased）与无偏（unbiased）。\n在路径追踪里，我们用蒙特卡洛估计积分。一个估计器如果期望值永远等于真实值，不管用多少样本，它就是无偏的。反之，如果期望值有系统误差，就是有偏的。有偏里有一", "u": "GAMES101/101_L18.html#s1"}, {"c": "GAMES101 L18 · 第 18 讲：高级渲染——高级光传输与外观建模", "t": "2. 双向路径追踪与 MLT：从光源和相机同时出发", "x": "双向路径追踪（Bidirectional Path Tracing, BDPT） 的核心思想很简单：一条路径连接相机和光源。普通路径追踪只从相机出发，遇到光源就结束；BDPT 则同时从相机和光源各追踪一条子路径，然后把两条子路径的端点连接起来形成完整路径。\n这适合什么场景？课件说：当光源侧的光传输很", "u": "GAMES101/101_L18.html#s2"}, {"c": "GAMES101 L18 · 第 18 讲：高级渲染——高级光传输与外观建模", "t": "3. 光子映射：两阶段的有偏方法", "x": "光子映射（Photon Mapping） 是这一讲的重点之一，它是一种有偏的两阶段方法，特别擅长处理 SDS 路径（Specular-Diffuse-Specular，即镜面-漫反射-镜面）和生成焦散（caustics）。\n两个阶段：\n\n光子追踪（photon tracing）：从光源发射光子，让它", "u": "GAMES101/101_L18.html#s3"}, {"c": "GAMES101 L18 · 第 18 讲：高级渲染——高级光传输与外观建模", "t": "4. VCM 与即时辐射度：组合与近似", "x": "顶点连接与合并（Vertex Connection and Merging, VCM） 是 BDPT 和光子映射的结合。动机很实际：BDPT 中两条子路径的端点如果无法直接连接（比如被遮挡或方向不匹配），这些子路径就浪费了。VCM 说：别浪费，如果端点不能连接但可以合并，就用光子映射的方式处理附近“", "u": "GAMES101/101_L18.html#s4"}, {"c": "GAMES101 L18 · 第 18 讲：高级渲染——高级光传输与外观建模", "t": "5. 参与介质：雾、云与相位函数", "x": "从这一节开始进入高级外观建模（Advanced Appearance Modeling）。先讲非表面模型（Non-surface models），第一类是参与介质（Participating Media），典型例子是雾和云。\n关键物理：光在参与介质中传播时，任意一点都可能被（部分）吸收和散射。吸收让", "u": "GAMES101/101_L18.html#s5"}, {"c": "GAMES101 L18 · 第 18 讲：高级渲染——高级光传输与外观建模", "t": "6. 头发与毛发：从 Marschner 到双圆柱模型", "x": "头发/毛发/纤维属于非表面模型中的 BCSDF（Bidirectional Curve Scattering Distribution Function）一类。\nKajiya-Kay 模型是早期简化模型，把头发当作圆柱，只考虑沿切线方向的高光，效果比较“塑料”。\nMarschner 模型（Marsc", "u": "GAMES101/101_L18.html#s6"}, {"c": "GAMES101 L18 · 第 18 讲：高级渲染——高级光传输与外观建模", "t": "7. 次表面散射与 BSSRDF：光在表面下走了一段", "x": "半透明材质（Translucent Material） 如玉石、水母，视觉特征是光从不同于入射点的位置出射。这违反 BRDF 的基本假设：BRDF 假设入射和出射在同一点。\nBSSRDF（Bidirectional Surface Scattering Reflectance Distributio", "u": "GAMES101/101_L18.html#s7"}, {"c": "GAMES101 L18 · 第 18 讲：高级渲染——高级光传输与外观建模", "t": "8. 布料、细节材质与程序化外观：从纤维到噪声", "x": "布料（Cloth） 是“ twisted fibers 的集合”，有两个层级的 twist：编织或针织。渲染有三种思路：\n\n当作表面渲染：已知编织模式，计算整体行为，用 BRDF 渲染。局限：无法表现纤维级别的细节和光泽变化。\n当作参与介质渲染：用单根纤维的属性及其分布计算散射参数，把布料当作参与介", "u": "GAMES101/101_L18.html#s8"}, {"c": "GAMES101 L18 · 核心结论", "t": "无偏估计器的期望永远等于正确值；有偏估计器在样本数有限时有系统误差，但若样本数趋于无穷时收敛到正确值，则称为一致的（consistent）。", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 核心结论", "t": "BDPT 从相机和光源各追踪子路径再连接端点，适合光源侧光传输复杂的场景，但实现难、速度慢。", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 核心结论", "t": "MLT 用马尔可夫链蒙特卡洛在路径空间局部扰动，擅长探索困难路径，但收敛率难估计、逐像素收敛不均，通常不用于动画。", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 核心结论", "t": "光子映射是两阶段的有偏方法：光子追踪 + 最终收集，用局部密度估计着色，擅长 SDS 路径和焦散；有偏但一致（有偏≈模糊，一致≈样本无穷时不模糊）。", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 核心结论", "t": "VCM 结合 BDPT 与光子映射，把无法连接但可合并的子路径端点用光子合并处理。", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 核心结论", "t": "即时辐射度（IR）把受光表面当作虚拟点光源（VPL）来渲染，快且适合漫反射场景，但 VPL 靠近着色点会出现尖峰，且难处理光泽材质。", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 核心结论", "t": "参与介质中光会被吸收和散射，用相位函数描述散射的角度分布；渲染时随机选择方向和距离，并在每个着色点连接光源。", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 核心结论", "t": "头发用 Marschner 模型（R、TT、TRT 三种光路）描述，动物毛发需要双圆柱模型加入髓质散射；BSSRDF 把出射点与入射点分开，突破 BRDF 的同", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 核心结论", "t": "细节材质（如金属闪片）因法线分布高频变化导致路径采样极难，p-NDF 把像素内法线分布聚合起来解决；程序化外观用噪声函数在运行时生成细节，无需纹理。", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 术语", "t": "Unbiased / 无偏", "x": "估计器期望值永远等于真实值，与样本数无关。", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 术语", "t": "Biased / 有偏", "x": "估计器期望值有系统误差；若样本无穷时收敛则称为一致。", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 术语", "t": "BDPT / 双向路径追踪", "x": "从相机和光源各追踪子路径再连接端点，适合光源侧复杂光传输。", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 术语", "t": "MLT / Metropolis 光传输", "x": "用 MCMC 局部扰动路径，擅长困难光路，但收敛不均、不用于动画。", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 术语", "t": "Photon Mapping / 光子映射", "x": "两阶段有偏方法：光子追踪+最终收集，用局部密度估计着色。", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 术语", "t": "VPL / 虚拟点光源", "x": "即时辐射度中把光路端点当作点光源来照亮场景。", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 术语", "t": "Phase Function / 相位函数", "x": "描述参与介质中散射光的角度分布，类似介质中的 BRDF。", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 术语", "t": "BSSRDF / 双向表面散射反射分布函数", "x": "BRDF 的推广，允许入射点和出射点不同，用于次表面散射。", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 术语", "t": "p-NDF / 像素级法线分布函数", "x": "把像素覆盖区域内的法线分布聚合，解决细节材质采样困难。", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 练习", "t": "解释“有偏但一致”的含义，并说明光子映射为什么属于这一类。", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 练习", "t": "BDPT 和光子映射各自适合什么场景？为什么 BDPT 实现更难？", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 练习", "t": "Marschner 模型中的 R、TT、TRT 分别代表什么光路？双圆柱模型为什么能更好地渲染动物毛发？", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 练习", "t": "BSSRDF 与 BRDF 的核心区别是什么？偶极子近似如何简化 BSSRDF 的计算？", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L18 · 练习", "t": "在 UE 或 Unity 中，如何为皮肤材质启用次表面散射效果？请说出关键设置。", "x": "", "u": "GAMES101/101_L18.html"}, {"c": "GAMES101 L09 · 第 9 讲：着色（二）——纹理映射与重心坐标", "t": "1. 为什么需要插值：从顶点属性到光滑表面", "x": "上一讲我们知道了怎么用 Blinn-Phong 模型算一个着色点（shading point）的颜色，也知道了光栅化会把三角形变成屏幕上的像素。但一个三角形只有三个顶点，顶点上可以携带纹理坐标、颜色、法线等属性，三角形内部成千上万个像素的属性从哪来？答案就是插值（interpolation）。\n直觉", "u": "GAMES101/101_L09.html#s1"}, {"c": "GAMES101 L09 · 第 9 讲：着色（二）——纹理映射与重心坐标", "t": "2. 重心坐标：三角形内的“坐标系”", "x": "重心坐标（barycentric coordinates）是定义在三角形上的坐标系。给定三角形顶点 A、B、C，三角形内（包括边上）任意一点 P 可以写成：\n\\[ P = \\alpha A + \\beta B + \\gamma C, \\quad \\alpha + \\beta + \\gamma = 1", "u": "GAMES101/101_L09.html#s2"}, {"c": "GAMES101 L09 · 第 9 讲：着色（二）——纹理映射与重心坐标", "t": "3. 用重心坐标插值顶点属性：线性插值与透视校正", "x": "有了重心坐标，插值就变成一句话：顶点属性按重心坐标加权求和。若顶点 A、B、C 上的属性分别为 \\(V_A, V_B, V_C\\)，则三角形内点 P 处的属性为\n\\[ V = \\alpha V_A + \\beta V_B + \\gamma V_C \\]\n这里的 \\(V\\) 可以是位置、纹理坐标、颜色", "u": "GAMES101/101_L09.html#s3"}, {"c": "GAMES101 L09 · 第 9 讲：着色（二）——纹理映射与重心坐标", "t": "4. 简单纹理映射：从屏幕像素到纹理颜色", "x": "纹理映射（texture mapping）的目标是：给每个屏幕像素找到它对应的纹理颜色，作为 Blinn-Phong 模型里的漫反射系数 \\(K_d\\)（diffuse albedo）。流程可以拆成几步：\n\n光栅化后，对每个屏幕采样点（通常是像素中心）(x, y)，用重心坐标算出它在三角形内的位置。", "u": "GAMES101/101_L09.html#s4"}, {"c": "GAMES101 L09 · 第 9 讲：着色（二）——纹理映射与重心坐标", "t": "5. 纹理放大：双线性插值让图像不糊不块", "x": "纹理放大（texture magnification）发生在纹理太小、屏幕像素太大的时候：一个屏幕像素只覆盖不到一个纹素，采样点落在纹素之间。如果直接取最近的纹素（nearest），图像会出现明显的马赛克方块。\n解决办法是插值。最常用的是双线性插值（bilinear interpolation）：\n", "u": "GAMES101/101_L09.html#s5"}, {"c": "GAMES101 L09 · 第 9 讲：着色（二）——纹理映射与重心坐标", "t": "6. 纹理缩小与摩尔纹：点采样为什么不行", "x": "纹理缩小（texture minification）是反过来的情况：纹理很大、屏幕像素很小，一个像素覆盖了很多纹素。这时如果还只取一个采样点（点采样，point sampling），就会出问题：\n\n摩尔纹（moire）：高频纹理（如格子、细密条纹）在采样不足时产生低频干扰条纹。\n锯齿（jaggies", "u": "GAMES101/101_L09.html#s6"}, {"c": "GAMES101 L09 · 第 9 讲：着色（二）——纹理映射与重心坐标", "t": "7. Mipmap：用多级缩略图做快速范围查询", "x": "Mipmap 是纹理缩小的标准解法。它的思想非常朴素：预先算好一系列逐级缩小一半的纹理，形成金字塔。原始纹理是第 0 层，第 1 层是它的一半分辨率，第 2 层再一半，直到 1×1。名字来自拉丁语“multum in parvo”，意思是“小空间里装很多”。\n存储开销：每一层面积是上一层的 1/4，", "u": "GAMES101/101_L09.html#s7"}, {"c": "GAMES101 L09 · 第 9 讲：着色（二）——纹理映射与重心坐标", "t": "8. Mipmap 的局限与各向异性过滤", "x": "Mipmap 很好用，但它有一个根本假设：像素在纹理空间的足迹是正方形。这是因为 Mipmap 每一层都是各向同性的（isotropic）正方形缩略图。\n但现实中，当一个表面以很斜的角度对着相机时（比如地面向远处延伸），屏幕像素在纹理空间的足迹会被拉长成斜向的长方形。这时 Mipmap 只能按最长边", "u": "GAMES101/101_L09.html#s8"}, {"c": "GAMES101 L09 · 核心结论", "t": "重心坐标是三角形内的坐标系：任意点可表示为三个顶点坐标的加权和，权重非负则在三角形内", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 核心结论", "t": "重心坐标的几何意义是三个子三角形的面积占比，顶点处为 (1,0,0)，重心处为 (1/3,1/3,1/3)", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 核心结论", "t": "屏幕空间线性插值重心坐标后，可直接插值纹理坐标、颜色、法线等顶点属性，但透视投影下需做透视校正", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 核心结论", "t": "纹理放大时用双线性插值（bilinear）比最近邻（nearest）平滑，双三次（bicubic）更好但更贵", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 核心结论", "t": "纹理缩小时点采样会产生摩尔纹和锯齿，本质是像素覆盖多个纹素，需要范围查询（range query）", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 核心结论", "t": "Mipmap 用预计算的多级缩略图近似正方形范围查询，存储开销为原图的 1/3", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 核心结论", "t": "Mipmap 层级 D 由屏幕像素在纹理空间的足迹（footprint）决定，三线性插值在相邻两级间再做线性插值", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 核心结论", "t": "Mipmap 对斜向拉长的足迹会过模糊，各向异性过滤（如 Ripmap、EWA）能处理非正方形足迹", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 术语", "t": "Barycentric Coordinates / 重心坐标", "x": "三角形内的坐标系，用三个权重表示点的位置，权重和为 1", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 术语", "t": "Texture Magnification / 纹理放大", "x": "纹理太小、屏幕像素太大时，一个像素覆盖不到一个纹素", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 术语", "t": "Texture Minification / 纹理缩小", "x": "纹理太大、屏幕像素太小时，一个像素覆盖多个纹素", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 术语", "t": "Bilinear Interpolation / 双线性插值", "x": "在 2×2 纹素上先水平两次 lerp 再垂直一次 lerp", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 术语", "t": "Mipmap / 多级渐远纹理", "x": "预计算的一系列逐级减半的纹理金字塔，用于快速范围查询", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 术语", "t": "Trilinear Interpolation / 三线性插值", "x": "在相邻两级 Mipmap 上分别双线性采样，再按小数层级线性插值", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 术语", "t": "Anisotropic Filtering / 各向异性过滤", "x": "允许不同方向不同缩放，处理斜向拉长的像素足迹，减少过模糊", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 术语", "t": "Moire / 摩尔纹", "x": "高频纹理采样不足时产生的低频干扰条纹", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 术语", "t": "Texel / 纹素", "x": "纹理图像中的一个像素单元", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 术语", "t": "Range Query / 范围查询", "x": "查询一个区域内的平均值，与点查询相对，是纹理缩小的本质需求", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 练习", "t": "三角形顶点 A(0,0)、B(1,0)、C(0,1)，点 P(0.2, 0.3)。求 P 的重心坐标，并判断 P 是否在三角形内。", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 练习", "t": "一张 1024×1024 的纹理，开启 Mipmap 后总存储是多少？如果每个纹素 4 字节，总共多少 MB？", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 练习", "t": "已知某像素在纹理空间的导数 |du/dx|=0.5, |dv/dx|=0, |du/dy|=0, |dv/dy|=0.5（单位：纹素/像素），求 Mipmap ", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 练习", "t": "为什么 Mipmap 在斜视角下会过模糊？各向异性过滤如何改进？", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L09 · 练习", "t": "在 UE 或 Unity 里，如何为一个地面材质开启各向异性过滤并观察效果？请写出操作步骤。", "x": "", "u": "GAMES101/101_L09.html"}, {"c": "GAMES101 L15 · 第 15 讲：光线追踪（光传输与全局光照）——从辐射度量到渲染方程", "t": "1. 把光量化：辐射度量学的基本量", "x": "上一讲我们学了光线求交和 BVH 加速，但「光线追踪到底在追什么」还没回答。这一讲先用辐射度量学（radiometry）把「光」变成可以计算的物理量。\n课件从最底层的量开始：\n\n辐射能量（radiant energy） \\(Q\\)，单位焦耳（J）。这是电磁辐射的总能量，在图形学里几乎不直接用。\n辐射", "u": "GAMES101/101_L15.html#s1"}, {"c": "GAMES101 L15 · 第 15 讲：光线追踪（光传输与全局光照）——从辐射度量到渲染方程", "t": "2. 辐照度与 Lambert 余弦定律：为什么冬天冷、夏天热", "x": "辐照度（irradiance） 定义为单位面积上入射的功率：\n\\[ E(x) = \\frac{d\\Phi(x)}{dA} \\]\n单位是 W/m²，或者 lux（lm/m²）。它描述「一个表面点接收了多少光」。\n关键点是 Lambert 余弦定律（Lambert's cosine law）：当光斜着照", "u": "GAMES101/101_L15.html#s2"}, {"c": "GAMES101 L15 · 第 15 讲：光线追踪（光传输与全局光照）——从辐射度量到渲染方程", "t": "3. 辐射亮度：渲染真正要求的东西", "x": "辐射亮度（radiance） 是描述环境中光分布的基本场量。课件原话：radiance 是和光线（ray）关联的量，渲染就是在计算 radiance。\n定义是：单位立体角、单位投影面积上的功率：\n\\[ L(p,\\omega) = \\frac{d\\Phi(p,\\omega)}{d\\omega\\, dA", "u": "GAMES101/101_L15.html#s3"}, {"c": "GAMES101 L15 · 第 15 讲：光线追踪（光传输与全局光照）——从辐射度量到渲染方程", "t": "4. 辐照度与辐射亮度的关系：半球积分", "x": "这一节把 irradiance 和 radiance 用积分连起来，是后面反射方程的直接铺垫。\n对一个表面点 \\(p\\)，来自各个方向的入射 radiance 累加起来，就是它接收的总辐照度：\n\\[ E(p) = \\int_{H} L_i(p,\\omega)\\cos\\theta\\, d\\omega ", "u": "GAMES101/101_L15.html#s4"}, {"c": "GAMES101 L15 · 第 15 讲：光线追踪（光传输与全局光照）——从辐射度量到渲染方程", "t": "5. BRDF：一个表面点如何分配反射光", "x": "现在我们知道表面接收了多少光（irradiance），问题是：这些光反射到各个方向分别是多少？这就是 双向反射分布函数（BRDF, Bidirectional Reflectance Distribution Function） 要回答的。\n课件先描述物理过程：从方向 \\(\\omega_i\\) 来的", "u": "GAMES101/101_L15.html#s5"}, {"c": "GAMES101 L15 · 第 15 讲：光线追踪（光传输与全局光照）——从辐射度量到渲染方程", "t": "6. 反射方程与渲染方程：把光传输写成积分方程", "x": "把 BRDF 代回积分，就得到 反射方程（reflection equation）：\n\\[ L_r(p,\\omega_r) = \\int_{H} f_r(p,\\omega_i \\to \\omega_r)\\, L_i(p,\\omega_i)\\cos\\theta_i\\, d\\omega_i \\]\n意思是", "u": "GAMES101/101_L15.html#s6"}, {"c": "GAMES101 L15 · 第 15 讲：光线追踪（光传输与全局光照）——从辐射度量到渲染方程", "t": "7. 算子形式与诺伊曼级数：直接光、间接光、全局光照", "x": "课件把渲染方程写成算子形式：\n\\[ L = E + KL \\]\n其中 \\(L\\) 是出射 radiance 的向量/函数，\\(E\\) 是自发光，\\(K\\) 是 光传输算子（light transport operator），它把「入射 radiance」映射成「经过 BRDF 和余弦加权后的反射 r", "u": "GAMES101/101_L15.html#s7"}, {"c": "GAMES101 L15 · 第 15 讲：光线追踪（光传输与全局光照）——从辐射度量到渲染方程", "t": "8. 概率论复习：为蒙特卡洛积分做准备", "x": "渲染方程是个积分，实际求解要用蒙特卡洛方法，所以课件最后复习了概率论。\n随机变量（random variable） \\(X\\)：表示一个随机过程的取值。离散情况下，每个取值 \\(x_i\\) 有概率 \\(p_i\\)，要求 \\(p_i \\ge 0\\) 且 \\(\\sum p_i = 1\\)。例如六面骰子，", "u": "GAMES101/101_L15.html#s8"}, {"c": "GAMES101 L15 · 核心结论", "t": "辐射亮度（radiance）是描述光线的基本量，渲染就是在求每个方向上的 radiance。", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 核心结论", "t": "辐照度（irradiance）是单位面积接收的功率，radiance 对半球积分再乘余弦就是 irradiance。", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 核心结论", "t": "BRDF 描述「从某个入射方向来的光，有多少被反射到某个出射方向」，单位是 1/sr。", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 核心结论", "t": "反射方程把出射 radiance 写成对入射 radiance 的半球积分，但入射 radiance 又依赖其他点的出射 radiance，所以是递归的。", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 核心结论", "t": "加上自发光项就得到渲染方程：L_o = L_e + ∫ L_i f_r (n·ω_i) dω_i，它是第二类 Fredholm 积分方程。", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 核心结论", "t": "把渲染方程写成算子形式 L = E + KL，展开成 L = E + KE + K²E + …，每一项对应光线弹射次数。", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 核心结论", "t": "直接光照 = E + KE（光栅化着色大致到此为止），全局光照需要 K²E 及更高阶项。", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 核心结论", "t": "概率论是下一讲蒙特卡洛积分的基础：PDF 描述随机变量取值的相对概率，期望值是对 PDF 加权平均。", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 术语", "t": "Radiant flux / 辐射通量", "x": "单位时间通过的能量，单位 W 或 lm。", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 术语", "t": "Radiant intensity / 辐射强度", "x": "单位立体角内的功率，单位 W/sr。", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 术语", "t": "Irradiance / 辐照度", "x": "单位面积接收的功率，单位 W/m² 或 lux。", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 术语", "t": "Radiance / 辐射亮度", "x": "单位立体角、单位投影面积的功率，单位 W/(sr·m²) 或 nit。", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 术语", "t": "Solid angle / 立体角", "x": "球面面积除以半径平方，单位 sr，微分式含 sinθ。", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 术语", "t": "BRDF / 双向反射分布函数", "x": "出射 radiance 与入射 irradiance 之比，单位 sr⁻¹。", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 术语", "t": "Rendering equation / 渲染方程", "x": "描述光传输的积分方程，Kajiya 1986 年提出。", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 术语", "t": "Fredholm integral equation / Fredholm 积分方程", "x": "未知函数出现在积分号内外的积分方程，渲染方程是第二类。", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 术语", "t": "Neumann series / 诺伊曼级数", "x": "L = E + KE + K²E + … 的展开，对应光线弹射次数。", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 术语", "t": "PDF / 概率密度函数", "x": "描述连续随机变量取值的相对概率，积分必须为 1。", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 练习", "t": "一个点光源总功率为 Φ = 100 W，向所有方向均匀发光。求距离 2 m 处的辐照度 E。", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 练习", "t": "写出渲染方程的完整形式，并说明每一项的物理含义。", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 练习", "t": "把渲染方程写成算子形式 L = E + KL，展开成诺伊曼级数，并指出直接光照和一次弹射全局光照分别对应哪几项。", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 练习", "t": "为什么光栅化管线只能做直接光照，而做不了全局光照？用渲染方程的展开式解释。", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L15 · 练习", "t": "一个六面骰子，求掷出点数的期望值。如果骰子被做了手脚，1 点概率为 0.5，其余各面概率相等，期望值变成多少？", "x": "", "u": "GAMES101/101_L15.html"}, {"c": "GAMES101 L13 · 第 13 讲：光线追踪（一）——Whitted 风格光线追踪与求交", "t": "1. 为什么需要光线追踪：光栅化搞不定的全局效果", "x": "光栅化（Rasterization）把三角形投影到屏幕、逐像素着色，速度很快，适合实时渲染。但它本质上是一个局部（local）着色模型：每个像素的颜色只取决于该点直接可见的光源和材质，很难处理光线在场景中多次反弹带来的效果。\n课件列举了光栅化难以处理的几类全局效果（global effects）：\n", "u": "GAMES101/101_L13.html#s1"}, {"c": "GAMES101 L13 · 第 13 讲：光线追踪（一）——Whitted 风格光线追踪与求交", "t": "2. 光线的基本假设与光线投射", "x": "课件先给出关于光线的三条（物理上并不完全正确、但图形学中够用的）假设：\n\n光线沿直线传播（忽略波动性）。\n光线之间互不碰撞（忽略干涉、衍射）。\n光线从光源出发进入眼睛；但物理在路径反转下不变（光路可逆性，reciprocity），所以我们可以反过来从眼睛发射光线。\n\n第三条是光线追踪的关键：我们不需", "u": "GAMES101/101_L13.html#s2"}, {"c": "GAMES101 L13 · 第 13 讲：光线追踪（一）——Whitted 风格光线追踪与求交", "t": "3. Whitted 风格递归光线追踪", "x": "简单的光线投射只做局部着色，仍然无法处理反射和折射。Whitted（1980）提出递归光线追踪（recursive ray tracing）：在光线与物体的交点处，除了向光源发射 shadow ray 外，还继续发射反射光线（reflected ray）和折射光线（refracted ray），递归", "u": "GAMES101/101_L13.html#s3"}, {"c": "GAMES101 L13 · 第 13 讲：光线追踪（一）——Whitted 风格光线追踪与求交", "t": "4. 光线与隐式曲面求交：球与一般曲面", "x": "光线用参数方程表示：\n\\[ \\mathbf{r}(t) = \\mathbf{o} + t\\mathbf{d}, \\quad 0 \\le t \n其中 \\(\\mathbf{o}\\) 是起点，\\(\\mathbf{d}\\) 是方向（通常归一化），\\(t\\) 是沿光线的“时间”参数。\n与球求交：球心 \\(\\m", "u": "GAMES101/101_L13.html#s4"}, {"c": "GAMES101 L13 · 第 13 讲：光线追踪（一）——Whitted 风格光线追踪与求交", "t": "5. 光线与三角形求交：平面法 + 重心坐标", "x": "三角形是最基本的渲染图元，光线与三角形求交是光线追踪的核心操作。课件给出两种思路：\n思路一：先求与平面的交点，再判断是否在三角形内。\n平面由法线 \\(\\mathbf{N}\\) 和平面上一点 \\(\\mathbf{p}_0\\) 定义，平面方程为：\n\\[ (\\mathbf{p} - \\mathbf{p}_", "u": "GAMES101/101_L13.html#s5"}, {"c": "GAMES101 L13 · 第 13 讲：光线追踪（一）——Whitted 风格光线追踪与求交", "t": "6. 包围盒（AABB）加速：让求交变快", "x": "朴素光线追踪对每个像素、每条光线都要与场景中所有三角形求交，复杂度为 #像素 × #三角形 × #反弹次数，非常慢。课件用 70 万、2000 万三角形的场景说明性能挑战。\n包围盒（Bounding Volume） 的思路：用一个简单的几何体把复杂物体包起来。如果光线连包围盒都没碰到，就不可能碰到物", "u": "GAMES101/101_L13.html#s6"}, {"c": "GAMES101 L13 · 核心结论", "t": "光栅化快但只能处理局部光照，软阴影、光泽反射、间接光照等全局效果需要光线追踪。", "x": "", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 核心结论", "t": "光线追踪的基本假设：光线沿直线传播、互不碰撞、光路可逆；因此可以从眼睛反向发射光线。", "x": "", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 核心结论", "t": "光线投射（Ray Casting）：每个像素发一条 eye ray，求最近交点，在交点做局部着色（如 Blinn-Phong），并向光源发 shadow ray", "x": "", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 核心结论", "t": "Whitted 风格递归光线追踪：在交点处继续发射反射光线和折射光线，递归收集颜色，并乘以相应的 Fresnel/衰减系数。", "x": "", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 核心结论", "t": "光线与隐式曲面求交：将光线方程代入曲面方程，解出实数正根 t。", "x": "", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 核心结论", "t": "光线与三角形求交可分解为：先求与三角形所在平面的交点，再判断交点是否在三角形内；Möller–Trumbore 算法直接给出重心坐标，更快。", "x": "", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 核心结论", "t": "包围盒（AABB）加速：先用简单包围盒快速排除不相交的物体，只有光线与包围盒相交时才进一步测试内部图元。", "x": "", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 核心结论", "t": "光线与 AABB 求交：分别计算光线与三对 slab 的 t_min/t_max，取 t_enter = max{t_min}，t_exit = min{t_m", "x": "", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 术语", "t": "Ray Tracing / 光线追踪", "x": "从眼睛发射光线并递归追踪光路，以计算全局光照效果。", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 术语", "t": "Ray Casting / 光线投射", "x": "每个像素发一条光线，求最近交点并做局部着色。", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 术语", "t": "Whitted-Style Ray Tracing / Whitted 风格光线追踪", "x": "在交点处递归发射反射/折射光线的经典光线追踪算法。", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 术语", "t": "Primary Ray / 主光线", "x": "从眼睛出发的第一条光线。", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 术语", "t": "Secondary Ray / 次级光线", "x": "在交点处生成的反射或折射光线。", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 术语", "t": "Shadow Ray / 阴影光线", "x": "从交点指向光源、用于判断可见性的光线。", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 术语", "t": "AABB / 轴对齐包围盒", "x": "边平行于坐标轴的包围盒，用于加速光线求交。", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 术语", "t": "Möller–Trumbore / Möller–Trumbore 算法", "x": "快速计算光线与三角形交点及重心坐标的算法。", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 术语", "t": "Barycentric Coordinates / 重心坐标", "x": "用三个顶点权重表示三角形内点的方法。", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 术语", "t": "Reciprocity / 光路可逆性", "x": "光线路径反转后物理规律不变，因此可从眼睛反向追踪。", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 练习", "t": "光栅化为什么难以处理软阴影和间接光照？光线追踪如何解决？", "x": "", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 练习", "t": "光线起点为 \\(\\mathbf{o}=(0,0,0)\\)，方向 \\(\\mathbf{d}=(0,0,-1)\\)（已归一化），球心 \\(\\mathbf{c}=(0", "x": "", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 练习", "t": "光线与 AABB 求交时，为什么取 \\(t_{\\text{enter}}=\\max\\{t_{\\min}\\}\\)、\\(t_{\\text{exit}}=\\min\\{", "x": "", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L13 · 练习", "t": "在 UE 或 Unity 中，哪些功能使用了光线追踪？请举出至少两个，并说明它们对应本讲的哪个概念。", "x": "", "u": "GAMES101/101_L13.html"}, {"c": "GAMES101 L20 · 第 20 讲：颜色与感知——从光场到色彩空间", "t": "1. 全光函数：把“能看到的一切”参数化", "x": "我们能看到的世界，本质上是一堆光线。全光函数（Plenoptic Function） 试图用一个函数描述“一个人在任何时间、任何位置、任何方向、任何波长上看到的光强”。它的完整形式是：\n\\[ P(\\theta, \\phi, \\lambda, t, V_x, V_y, V_z) \\]\n其中 \\(\\th", "u": "GAMES101/101_L20.html#s1"}, {"c": "GAMES101 L20 · 第 20 讲：颜色与感知——从光场到色彩空间", "t": "2. 从全光函数到 4D 光场：光线复用与双平面参数化", "x": "完整全光函数维度太高，难以存储。课件做了两个关键简化：\n\n忽略时间与波长：只考虑静态、单色光（或三通道分别处理）。\n假设光线在真空中沿直线传播、无衰减、无散射：一条光线在空间中传播时，其辐射亮度（radiance）保持不变。\n\n于是，一条光线可以由“3D 位置 + 2D 方向”描述，但沿光线方向移动", "u": "GAMES101/101_L20.html#s2"}, {"c": "GAMES101 L20 · 第 20 讲：颜色与感知——从光场到色彩空间", "t": "3. 光场相机：先拍照后对焦", "x": "传统相机每个像素记录的是辐照度（irradiance），即来自所有方向的光的积分。光场相机则用微透镜阵列（microlens array） 放在传感器前，每个微透镜对应一个“宏像素”，其下的多个传感器像素记录来自不同方向的光线。这样每个宏像素记录的是辐亮度（radiance） 的方向分布，即一小块光", "u": "GAMES101/101_L20.html#s3"}, {"c": "GAMES101 L20 · 第 20 讲：颜色与感知——从光场到色彩空间", "t": "4. 颜色的物理与生理基础：光谱、锥细胞与同色异谱", "x": "颜色不是光的固有属性，而是人的感知现象。课件强调：“不同波长的光不是‘颜色’”。要理解颜色，需要从物理和生理两个层面看。\n物理层面：光是一种电磁波，可见光波长约 380–780 nm。描述光源的物理量是光谱功率分布（Spectral Power Distribution, SPD），即每个波长上的能", "u": "GAMES101/101_L20.html#s4"}, {"c": "GAMES101 L20 · 第 20 讲：颜色与感知——从光场到色彩空间", "t": "5. 颜色匹配实验与 CIE RGB / XYZ 颜色空间", "x": "既然颜色感知是三维的，我们能否用三种基色光混合出任意颜色？加色颜色匹配实验回答了这个问题。实验装置：一边是待测单色光，另一边是三种基色光（如红、绿、蓝）的混合，观察者调节三种基色的强度直到两边看起来一样。\n实验发现，对于某些波长，无论如何调节，都无法用三种基色匹配，除非把其中一种基色加到待测光一侧（", "u": "GAMES101/101_L20.html#s5"}, {"c": "GAMES101 L20 · 第 20 讲：颜色与感知——从光场到色彩空间", "t": "6. 色度图与色域：颜色空间的边界", "x": "在 CIE XYZ 空间中，任意颜色由 (X,Y,Z) 表示。为了将亮度与颜色本身分开，定义色度（chromaticity）：\n\\[ x = \\frac{X}{X+Y+Z},\\quad y = \\frac{Y}{X+Y+Z},\\quad z = \\frac{Z}{X+Y+Z} \\]\n由于 \\(x+y", "u": "GAMES101/101_L20.html#s6"}, {"c": "GAMES101 L20 · 第 20 讲：颜色与感知——从光场到色彩空间", "t": "7. 感知组织的颜色空间：HSV、CIELAB 与对立色理论", "x": "RGB 和 XYZ 是面向设备的颜色空间，而艺术家和设计师更习惯用色调（hue）、饱和度（saturation）、明度（value/lightness） 来描述颜色。HSV 颜色空间正是这样组织的：H 表示色调（颜色的种类），S 表示饱和度（颜色的鲜艳程度），V 表示明度（整体亮度）。它广泛用于颜色", "u": "GAMES101/101_L20.html#s7"}, {"c": "GAMES101 L20 · 第 20 讲：颜色与感知——从光场到色彩空间", "t": "8. 减色空间 CMYK 与总结", "x": "前面讨论的都是加色（additive） 颜色空间：光越加越亮，如 RGB 显示器。印刷则使用减色（subtractive） 颜色空间：颜料吸收某些波长，反射其余波长，混合越多越暗。CMYK 使用青（Cyan）、品红（Magenta）、黄（Yellow）和黑（Key）四种墨水。\n课件留下一个问题：如果", "u": "GAMES101/101_L20.html#s8"}, {"c": "GAMES101 L20 · 核心结论", "t": "全光函数 P(θ,φ,λ,t,Vx,Vy,Vz) 描述了所有可能看到的视觉信息，是“视觉现实”的完整参数化。", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 核心结论", "t": "忽略时间与波长、假设光线在真空中沿直线传播且无衰减，全光函数降为 4D 光场（2D 位置 + 2D 方向），可用双平面参数化 (s,t,u,v) 组织。", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 核心结论", "t": "光场相机通过微透镜阵列同时记录位置与方向信息，实现先拍照后对焦，但牺牲空间分辨率且成本高。", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 核心结论", "t": "颜色不是光的固有属性，而是人眼三种锥细胞（S、M、L）对光谱的响应结果，大脑只收到三个响应值。", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 核心结论", "t": "同色异谱：不同光谱可以产生相同的 (S,M,L) 响应，因此可用三种基色复现绝大多数颜色，这是 RGB 显示的基础。", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 核心结论", "t": "CIE RGB 颜色匹配实验得到颜色匹配函数，任意光谱的颜色可由积分得到三刺激值；但存在负值，故引入虚基色 CIE XYZ。", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 核心结论", "t": "CIE XYZ 中 Y 表示亮度，x+y+z=1 定义色度，常用 (x,y) 色度图表示所有可见颜色；色域是基色能产生的颜色范围。", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 核心结论", "t": "HSV 按艺术直觉组织颜色（色调、饱和度、明度），CIELAB 追求感知均匀，对立色理论（红-绿、蓝-黄、黑-白）有神经学依据。", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 术语", "t": "Plenoptic Function / 全光函数", "x": "描述所有可能可见光线的函数，包含位置、方向、波长、时间。", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 术语", "t": "Light Field / 光场", "x": "全光函数在静态、单色、真空假设下的 4D 降维，记录光线在空间中的分布。", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 术语", "t": "Microlens Array / 微透镜阵列", "x": "光场相机中用于同时记录空间和方向信息的透镜阵列。", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 术语", "t": "Spectral Power Distribution (SPD) / 光谱功率分布", "x": "描述光源在每个波长上的能量分布。", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 术语", "t": "Metamerism / 同色异谱", "x": "不同光谱产生相同 (S,M,L) 响应，看起来颜色相同。", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 术语", "t": "CIE XYZ / CIE XYZ 颜色空间", "x": "虚基色颜色空间，匹配函数处处为正，Y 表示亮度。", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 术语", "t": "Chromaticity / 色度", "x": "由 XYZ 归一化得到的 (x,y)，描述颜色而不含亮度。", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 术语", "t": "Gamut / 色域", "x": "一组基色能产生的所有颜色的集合，在色度图上是一个区域。", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 术语", "t": "HSV / HSV 颜色空间", "x": "用色调、饱和度、明度组织颜色，符合艺术直觉。", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 术语", "t": "CIELAB / CIELAB 颜色空间", "x": "追求感知均匀的颜色空间，L* 亮度，a* 红绿，b* 蓝黄。", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 练习", "t": "解释全光函数如何从 7D 降维到 4D 光场，并说明每一步假设。", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 练习", "t": "为什么 CIE RGB 颜色匹配函数会出现负值？CIE XYZ 如何解决这个问题？", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 练习", "t": "给定一个光谱 s(λ)，如何计算它在 CIE XYZ 空间中的三刺激值？写出公式并说明各符号含义。", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 练习", "t": "在 UE 或 Unity 中，为什么材质颜色通常要从 sRGB 转换到线性空间？如果不转换会怎样？", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L20 · 练习", "t": "解释同色异谱现象，并说明它对彩色显示器设计的启示。", "x": "", "u": "GAMES101/101_L20.html"}, {"c": "GAMES101 L22 · 第 22 讲：动画（续）——单粒子模拟与流体初步", "t": "1. 从单个粒子开始：速度场与一阶常微分方程", "x": "模拟一大群粒子之前，先看一个粒子怎么动。课件假设空间中存在一个速度场（velocity vector field），它是位置和时间的函数：\n\\[ \\mathbf{v} = \\mathbf{v}(\\mathbf{x}, t) \\]\n想象一条河，每个位置的水流方向和快慢都不同，粒子只是“随波逐流”。粒子", "u": "GAMES101/101_L22.html#s1"}, {"c": "GAMES101 L22 · 第 22 讲：动画（续）——单粒子模拟与流体初步", "t": "2. 显式欧拉法：最简单，也最容易翻车", "x": "欧拉法（Euler's method），也叫前向欧拉法（Forward Euler）或显式欧拉法（Explicit Euler），做法极其直接：用当前时刻的速度乘以时间步长，加到当前位置上。\n\\[ \\mathbf{x}_{t+\\Delta t} = \\mathbf{x}_t + \\Delta t \\", "u": "GAMES101/101_L22.html#s2"}, {"c": "GAMES101 L22 · 第 22 讲：动画（续）——单粒子模拟与流体初步", "t": "3. 中点法与改进欧拉法：用“半步”或“平均”修正方向", "x": "既然用起点速度代表整段不好，那就想办法估计区间中段或两端的平均速度。\n中点法（Midpoint method / Modified Euler）分三步：\n\n\n先用欧拉法走半步，得到中点位置：\n\\[ \\mathbf{x}_{mid} = \\mathbf{x}(t) + \\frac{\\Delta t}{", "u": "GAMES101/101_L22.html#s3"}, {"c": "GAMES101 L22 · 第 22 讲：动画（续）——单粒子模拟与流体初步", "t": "4. 自适应步长与隐式欧拉法：用误差估计和“未来”换稳定", "x": "自适应步长（Adaptive step size）不固定 \\(\\Delta t\\)，而是根据误差估计动态调整：\n\n用步长 T 走一大步，得到 \\(\\mathbf{x}_T\\)；\n用步长 T/2 走两小步，得到 \\(\\mathbf{x}_{T/2}\\)；\n比较两者误差 \\(\\|\\mathbf{x}_T", "u": "GAMES101/101_L22.html#s4"}, {"c": "GAMES101 L22 · 第 22 讲：动画（续）——单粒子模拟与流体初步", "t": "5. Runge-Kutta 与 Verlet：高阶方法与“直接掰位置”", "x": "Runge-Kutta 家族（RK 方法）是一类高阶 ODE 求解器，特别擅长处理非线性问题。最常用的是四阶版本 RK4：它在一步内采样四次斜率，加权平均后推进，精度远高于欧拉法。课件给出了 RK4 的初始条件和递推形式（涉及 \\(k_1,k_2,k_3,k_4\\) 四个斜率项）。工程上，RK4 常", "u": "GAMES101/101_L22.html#s5"}, {"c": "GAMES101 L22 · 第 22 讲：动画（续）——单粒子模拟与流体初步", "t": "6. 刚体与流体：从粒子到更复杂的系统", "x": "刚体模拟（Rigid body simulation）是粒子模拟的简单推广：每个刚体除了位置、速度，还多了朝向（orientation）、角速度、转动惯量等属性。积分时位置和朝向都要推进，受力还要产生力矩。课件只给了一句“考虑更多属性”，但这是从质点走向真实物体的关键一步。\n流体模拟（Fluid s", "u": "GAMES101/101_L22.html#s6"}, {"c": "GAMES101 L22 · 核心结论", "t": "单粒子运动由速度场 v(x,t) 决定，位置对时间的一阶常微分方程 dx/dt = v(x,t) 可用前向数值积分逐步推进。", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 核心结论", "t": "显式（前向）欧拉法最简单也最不稳定：步长越大误差越大，误差会累积甚至导致模拟发散。", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 核心结论", "t": "中点法用半步处的速度更新位置；改进欧拉法用起点和终点速度的平均；两者都比显式欧拉更准。", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 核心结论", "t": "自适应步长通过比较一大步与两小步的结果来估计误差，误差超阈值就减小步长重算，实用但可能被迫用极小步长。", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 核心结论", "t": "隐式欧拉法用下一时刻的速度/导数，需要解非线性方程（如牛顿法），稳定性好得多，局部截断误差 O(h²)、全局 O(h)。", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 核心结论", "t": "Verlet/基于位置的积分在每步后直接约束粒子位置，简单快速但非物理、会耗散能量。", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 核心结论", "t": "刚体模拟类似粒子模拟，只是每个刚体多了朝向、角速度、转动惯量等属性。", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 核心结论", "t": "流体可用拉格朗日（质点）或欧拉（网格）视角模拟；MPM 把粒子携带物性与网格数值积分结合起来。", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 术语", "t": "Velocity vector field / 速度场", "x": "空间中每一点的速度，是位置和时间的函数 v(x,t)。", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 术语", "t": "ODE (Ordinary Differential Equation) / 常微分方程", "x": "只含一个自变量导数的方程，这里指 dx/dt = v(x,t)。", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 术语", "t": "Explicit / Forward Euler / 显式（前向）欧拉法", "x": "用当前速度乘以步长更新位置，简单但不稳定。", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 术语", "t": "Midpoint method / 中点法", "x": "先走半步取中点速度，再用中点速度走整步。", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 术语", "t": "Adaptive step size / 自适应步长", "x": "比较一大步与两小步的误差，动态调整步长。", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 术语", "t": "Implicit Euler / 隐式欧拉法", "x": "用下一时刻的导数，需解非线性方程，稳定性好。", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 术语", "t": "RK4 / 四阶 Runge-Kutta 法", "x": "一步内采样四个斜率加权，精度高但开销大。", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 术语", "t": "Verlet integration / Verlet 积分", "x": "每步后直接约束位置再反算速度，简单但耗散能量。", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 术语", "t": "Lagrangian / Eulerian / 拉格朗日/欧拉视角", "x": "跟质点走 vs 看固定网格，两种模拟大量物质的方式。", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 术语", "t": "MPM (Material Point Method) / 物质点法", "x": "粒子携带物性、网格做积分的混合流体/固体模拟方法。", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 练习", "t": "写出单粒子在速度场中运动的一阶常微分方程，并说明“一阶”和“常”各指什么。", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 练习", "t": "用显式欧拉法，步长 Δt=0.1，初始位置 x=0，速度场恒为 v=2（单位/秒），求 3 步后的位置。若真实解是 x=2t，3 步后误差是多少？", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 练习", "t": "简述中点法与改进欧拉法各自如何估计一步内的平均速度，并说明为什么它们比显式欧拉更准。", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 练习", "t": "隐式欧拉法为什么需要牛顿法？它的局部和全局截断误差阶分别是多少？步长减半时误差大致如何变化？", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L22 · 练习", "t": "在 UE 或 Unity 中做一个粒子沿速度场运动的小实验：分别用显式欧拉和 Verlet 约束，观察步长变大时的表现差异，并记录现象。", "x": "", "u": "GAMES101/101_L22.html"}, {"c": "GAMES101 L14 · 第 14 讲：光线追踪加速与辐射度量学基础", "t": "1. 为什么需要加速结构：从暴力求交到包围盒", "x": "上一讲我们实现了 Whitted 风格的光线追踪，但有一个致命问题：每条光线都要和场景中所有物体求交。假设场景有 100 万个三角形，每条光线做 100 万次求交，而每个像素可能发射多条光线，计算量会爆炸。\n加速的核心思想是用包围盒（Bounding Box）快速排除不可能相交的区域。轴对齐包围盒（", "u": "GAMES101/101_L14.html#s1"}, {"c": "GAMES101 L14 · 第 14 讲：光线追踪加速与辐射度量学基础", "t": "2. 均匀网格：预处理与光线遍历", "x": "均匀网格（Uniform Grids）把场景的包围盒切成规则的三维格子，每个物体登记到它覆盖的所有格子中。\n预处理步骤：\n\n找到场景的包围盒（Bounding Box）。\n根据分辨率创建网格。\n对每个物体，将它存入所有与之重叠的格子。\n\n光线与场景求交：\n\n按光线传播顺序逐步穿过网格（类似 2D 的", "u": "GAMES101/101_L14.html#s2"}, {"c": "GAMES101 L14 · 第 14 讲：光线追踪加速与辐射度量学基础", "t": "3. 空间划分：KD-Tree 的构建与遍历", "x": "空间划分（Spatial Partitions）不把空间切成固定格子，而是递归地把空间切成不重叠的区域，形成树结构。常见例子有八叉树（Oct-Tree）、BSP 树和 KD 树。本讲以 KD 树为例（2D 示意，3D 同理）。\nKD-Tree 预处理：\n\n每次选一个轴（x、y 或 z）和一个分割位置", "u": "GAMES101/101_L14.html#s3"}, {"c": "GAMES101 L14 · 第 14 讲：光线追踪加速与辐射度量学基础", "t": "4. 物体划分：BVH 的构建与遍历", "x": "BVH（Bounding Volume Hierarchy）是物体划分：把物体集合递归地分成不相交的子集，每个子集用一个包围盒包住。与 KD-Tree 不同，BVH 的包围盒可以重叠，但每个物体只属于一个叶子节点。\nBVH 构建步骤：\n\n计算当前物体集合的包围盒。\n递归地将物体集合分成两个子集。\n重", "u": "GAMES101/101_L14.html#s4"}, {"c": "GAMES101 L14 · 第 14 讲：光线追踪加速与辐射度量学基础", "t": "5. 空间划分 vs 物体划分：一张表看清区别", "x": "KD-Tree（空间划分）和 BVH（物体划分）是两种思路，容易混淆。课件用一张对比图总结：\n\n\n\n特性\n空间划分（KD-Tree）\n物体划分（BVH）\n\n\n\n\n划分对象\n空间区域\n物体集合\n\n\n区域是否重叠\n不重叠\n包围盒可重叠\n\n\n物体归属\n一个物体可属于多个区域\n一个物体只属于一个叶子\n\n\n构", "u": "GAMES101/101_L14.html#s5"}, {"c": "GAMES101 L14 · 第 14 讲：光线追踪加速与辐射度量学基础", "t": "6. 辐射度量学：为什么需要物理正确的光照单位", "x": "在 Assignment 中我们实现 Blinn-Phong 模型，光强 I 通常随便取一个数（比如 10）。但 Whitted 风格光线追踪给出的结果物理上不正确——它没有能量守恒，也没有真实的度量单位。辐射度量学（Radiometry）提供了一套测量光照的物理量和单位，是路径追踪（Path Tr", "u": "GAMES101/101_L14.html#s6"}, {"c": "GAMES101 L14 · 第 14 讲：光线追踪加速与辐射度量学基础", "t": "7. 角度与立体角：从 2D 弧长到 3D 球面面积", "x": "角度（Angle）是圆弧长度与半径之比：θ = l / r，单位弧度（rad）。整个圆有 2π 弧度。\n立体角（Solid Angle）是球面面积与半径平方之比：Ω = A / r²，单位球面度（sr）。整个球面有 4π 球面度。\n微分立体角：在球坐标下，球面上一个小面积元 dA = (r dθ)(", "u": "GAMES101/101_L14.html#s7"}, {"c": "GAMES101 L14 · 核心结论", "t": "均匀网格加速光线求交：预处理建格、运行时按光线顺序遍历格子，适合均匀分布的大规模物体。", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 核心结论", "t": "网格分辨率需权衡：太少没加速，太多遍历开销大；经验公式为 #cells = C * #objs，C ≈ 27（3D）。", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 核心结论", "t": "空间划分（KD-Tree）将空间切成不重叠区域，一个物体可属于多个区域；物体划分（BVH）将物体集合分成不相交子集，包围盒可重叠。", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 核心结论", "t": "BVH 构建：递归将物体集二分，每次重新计算包围盒，直到节点物体数足够少；划分策略常用最长轴 + 中位数分割。", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 核心结论", "t": "BVH 遍历：若光线与节点包围盒不相交则返回；叶子节点测试所有物体；内部节点递归左右子树取最近交点。", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 核心结论", "t": "辐射度量学提供物理正确的光照度量：辐射能量 Q [J]、辐射通量 Φ [W]、辐射强度 I [W/sr]、辐照度 E [W/m²]、辐亮度 L [W/(sr·m", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 核心结论", "t": "立体角 Ω 是球面面积与半径平方之比，单位球面总立体角为 4π sr；微分立体角 dω = sinθ dθ dφ。", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 核心结论", "t": "各向同性点光源的辐射强度 I = Φ / (4π)，即通量均匀分布在 4π 立体角上。", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 术语", "t": "Uniform Grids / 均匀网格", "x": "将空间切成规则格子，物体存入重叠格子，适合均匀分布场景。", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 术语", "t": "Spatial Partition / 空间划分", "x": "递归将空间切成不重叠区域，如 KD-Tree、Oct-Tree。", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 术语", "t": "BVH / 层次包围盒", "x": "将物体集合递归二分，每个节点有包围盒，物体只存叶子。", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 术语", "t": "Radiant Flux / 辐射通量", "x": "单位时间发射/接收的能量，Φ = dQ/dt，单位 W 或 lm。", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 术语", "t": "Radiant Intensity / 辐射强度", "x": "点光源单位立体角发射的功率，I = dΦ/dω，单位 W/sr 或 cd。", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 术语", "t": "Irradiance / 辐照度", "x": "单位面积接收的辐射通量，E = dΦ/dA，单位 W/m²。", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 术语", "t": "Radiance / 辐亮度", "x": "单位立体角、单位投影面积的辐射通量，L = d²Φ/(dω dA cosθ)。", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 术语", "t": "Solid Angle / 立体角", "x": "球面面积与半径平方之比，Ω = A/r²，单位 sr，整球 4π sr。", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 术语", "t": "Isotropic / 各向同性", "x": "向所有方向均匀发射，强度 I = Φ/(4π)。", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 练习", "t": "简述均匀网格（Uniform Grids）的预处理步骤和光线遍历流程，并说明它在什么情况下会失效。", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 练习", "t": "给定一个包含 4 个物体的场景，请手工构建一棵 BVH（用最长轴+中位数分割），并画出树结构。", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 练习", "t": "写出 BVH 遍历的递归伪代码，并解释为什么最后要返回两个子节点中较近的交点。", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 练习", "t": "一个各向同性点光源的总辐射通量为 1000 lm，求其辐射强度（单位 cd）。若该光源照射到距离 2m 处的一个垂直于光线的表面，求该表面的辐照度（假设点光源近", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L14 · 练习", "t": "在 UE 中创建一个 Point Light，将 Intensity 单位设为 Candela，数值设为 100。这对应辐射度量学中的哪个量？如果改为 Lume", "x": "", "u": "GAMES101/101_L14.html"}, {"c": "GAMES101 L19 · 第 19 讲：相机、镜头与光场", "t": "1. 从针孔到镜头：为什么相机需要镜头", "x": "相机成像的本质是捕获光线。最早的相机是针孔相机（pinhole camera）：一个暗箱，前面开一个小孔，光线通过小孔投射到后方的传感器上。针孔成像的原理是：物体上每一点发出的光线中，只有沿着直线穿过小孔的那一条能到达传感器，因此每个传感器点只接收来自一个方向的光，形成清晰的像。\n但针孔相机有两个致", "u": "GAMES101/101_L19.html#s1"}, {"c": "GAMES101 L19 · 第 19 讲：相机、镜头与光场", "t": "2. 视场角与焦距：镜头能看到多宽", "x": "视场角（Field of View, FOV） 描述相机能看到的场景范围。对于给定的传感器尺寸，FOV 由镜头的焦距（focal length） 决定。\n课件给出公式：\n\\[ \\text{FOV} = 2 \\arctan\\left(\\frac{h}{2f}\\right) \\]\n其中 \\(h\\) 是传", "u": "GAMES101/101_L19.html#s2"}, {"c": "GAMES101 L19 · 第 19 讲：相机、镜头与光场", "t": "3. 曝光三要素：光圈、快门、ISO", "x": "曝光（Exposure） 是传感器接收到的总光量，公式为：\n\\[ H = T \\times E \\]\n其中 \\(T\\) 是曝光时间（由快门控制），\\(E\\) 是辐照度（单位面积功率，由光圈和焦距控制）。\n三个控制曝光的手段：\n\n光圈（Aperture）：通过改变光圈大小控制进光量。光圈大小用 F 数", "u": "GAMES101/101_L19.html#s3"}, {"c": "GAMES101 L19 · 第 19 讲：相机、镜头与光场", "t": "4. 薄透镜方程与光线追踪构图", "x": "真实镜头由多片透镜组成，但为了简化，我们使用薄透镜近似（Thin Lens Approximation）：假设透镜厚度可忽略，所有折射发生在同一平面。\n薄透镜的性质：\n\n平行于光轴的光线经过透镜后通过焦点。\n通过焦点的光线经过透镜后平行于光轴。\n通过透镜中心的光线方向不变。\n\n薄透镜方程（高斯形式）", "u": "GAMES101/101_L19.html#s4"}, {"c": "GAMES101 L19 · 第 19 讲：相机、镜头与光场", "t": "5. 弥散圆与景深：为什么背景会模糊", "x": "当物体不在对焦平面上时，其像点不会汇聚在传感器上，而是形成一个模糊的光斑，称为弥散圆（Circle of Confusion, CoC）。\nCoC 大小计算：\n\\[ C = A \\frac{|z_s - z_i|}{z_i} \\]\n其中 \\(A\\) 是光圈直径，\\(z_s\\) 是传感器到透镜的距离，", "u": "GAMES101/101_L19.html#s5"}, {"c": "GAMES101 L19 · 第 19 讲：相机、镜头与光场", "t": "6. 薄透镜光线追踪：在渲染中模拟景深", "x": "在光线追踪中，我们可以用薄透镜模型模拟景深。基本步骤如下：\n\n设置参数：选择传感器尺寸、镜头焦距 \\(f\\)、光圈直径 \\(A\\)，以及感兴趣物体的深度 \\(z_o\\)。\n计算像距：根据薄透镜方程 \\(1/f = 1/z_o + 1/z_i\\) 计算传感器位置 \\(z_i\\)。\n对于每个像素：\n  ", "u": "GAMES101/101_L19.html#s6"}, {"c": "GAMES101 L19 · 核心结论", "t": "成像 = 合成 + 捕获；相机通过镜头将场景光线聚焦到传感器上。", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 核心结论", "t": "针孔相机无镜头，每个传感器点接收来自所有方向的光，导致图像模糊且进光量少。", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 核心结论", "t": "薄透镜方程：1/f = 1/z_o + 1/z_i，描述物距、像距与焦距的关系。", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 核心结论", "t": "视场角 FOV = 2 arctan(h / (2f))，焦距越短 FOV 越大，传感器尺寸影响等效焦距。", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 核心结论", "t": "曝光量 H = T × E，由快门时间 T 和辐照度 E（受光圈和焦距控制）决定，ISO 是增益。", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 核心结论", "t": "F 数 N = f / D，表示光圈大小，F 数越小光圈越大，进光量越多，景深越浅。", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 核心结论", "t": "弥散圆 CoC 与光圈直径成正比，与像距和传感器距离之差成正比；景深是 CoC 可接受范围内的物距范围。", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 核心结论", "t": "薄透镜光线追踪：从传感器像素采样光线，经过镜头随机点，再聚焦到物平面，可模拟景深。", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 术语", "t": "Pinhole Camera / 针孔相机", "x": "无镜头，通过小孔成像，进光量少且可能衍射模糊。", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 术语", "t": "Focal Length / 焦距", "x": "透镜中心到焦点的距离，决定视场角。", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 术语", "t": "Field of View (FOV) / 视场角", "x": "相机能看到的场景角度范围，与焦距和传感器尺寸有关。", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 术语", "t": "Exposure / 曝光", "x": "传感器接收的总光量，由快门时间和辐照度决定。", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 术语", "t": "F-Number (F-Stop) / F 数", "x": "焦距与光圈直径的比值，表示光圈大小，F 数越小光圈越大。", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 术语", "t": "Circle of Confusion (CoC) / 弥散圆", "x": "离焦物点在传感器上形成的模糊光斑大小。", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 术语", "t": "Depth of Field (DOF) / 景深", "x": "图像中清晰的范围，由光圈、焦距和对焦距离决定。", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 术语", "t": "Thin Lens Equation / 薄透镜方程", "x": "1/f = 1/z_o + 1/z_i，描述物距、像距与焦距的关系。", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 术语", "t": "Rolling Shutter / 卷帘快门", "x": "传感器逐行曝光，导致快速运动物体变形。", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 练习", "t": "一个 50mm 焦距的镜头，传感器尺寸为 36mm×24mm，求水平视场角（FOV）。", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 练习", "t": "一个相机光圈设置为 f/4，焦距为 50mm，求光圈直径。若改为 f/2.8，光圈直径是多少？", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 练习", "t": "解释为什么在光线追踪中，薄透镜相机能产生景深效果，而针孔相机不能。", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 练习", "t": "在 UE 中，如何设置相机以实现浅景深效果？列出关键参数。", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L19 · 练习", "t": "计算：焦距 f=50mm，物距 z_o=1m，求像距 z_i。若传感器位于 z_i 处，对焦清晰，求距离相机 2m 处的物体在传感器上的弥散圆直径（光圈直径 A", "x": "", "u": "GAMES101/101_L19.html"}, {"c": "GAMES101 L21 · 第 21 讲：动画——关键帧、物理模拟、运动学与绑定", "t": "1. 动画是什么：把模型变成时间的函数", "x": "计算机动画（Computer Animation）最直白的定义是“让东西活起来”。课件把它看作建模的延伸：静态场景描述的是“物体长什么样”，动画则把场景模型表示成时间的函数，输出一串按顺序播放的图片，从而产生运动感。\n这里有两个关键点。第一，动画既是沟通工具也是艺术载体，课件特别指出美学问题常常主导", "u": "GAMES101/101_L21.html#s1"}, {"c": "GAMES101 L21 · 第 21 讲：动画——关键帧、物理模拟、运动学与绑定", "t": "2. 关键帧动画：关键姿态 + 补间", "x": "关键帧动画（Keyframe Animation）的工作方式很像传统手绘：主美或首席动画师只画关键帧（keyframes）——动作中最重要的几个姿态；助手（人或计算机）负责画中间帧（in-between frames，简称补间 tweening）。在 3D 中，每个关键帧可以看成一个参数向量，里面装", "u": "GAMES101/101_L21.html#s2"}, {"c": "GAMES101 L21 · 第 21 讲：动画——关键帧、物理模拟、运动学与绑定", "t": "3. 物理模拟：牛顿定律与数值积分", "x": "物理模拟（Physical Simulation）不靠动画师摆姿态，而是用数值方法“算”出运动。起点是牛顿第二定律：\n\\[ F = ma \\]\n已知力、质量和当前状态，就能求出加速度 \\( a = F/m \\)。课件给出的显式欧拉（Explicit Euler）更新为：\n\\[ v(t+\\Delta ", "u": "GAMES101/101_L21.html#s3"}, {"c": "GAMES101 L21 · 第 21 讲：动画——关键帧、物理模拟、运动学与绑定", "t": "4. 弹簧质点系统：胡克定律、阻尼与结构", "x": "弹簧质点系统（Mass Spring System）是理解物理模拟最好的玩具模型。理想弹簧的力由胡克定律（Hooke's Law）给出：\n\\[ f_{a\\to b} = k_s (b - a) \\]\n\\[ f_{b\\to a} = -f_{a\\to b} \\]\n其中 \\( k_s \\) 是劲度系数。", "u": "GAMES101/101_L21.html#s4"}, {"c": "GAMES101 L21 · 第 21 讲：动画——关键帧、物理模拟、运动学与绑定", "t": "5. 粒子系统：用大量简单粒子模拟复杂现象", "x": "粒子系统（Particle Systems）把动态系统建模为大量粒子的集合，每个粒子的运动由一组物理或非物理的力决定。它之所以在图形学和游戏里流行，是因为容易理解、容易实现、可扩展：想要快就少放粒子，想要细节就多放粒子。\n每一帧的流程是固定的：\n\n按需创建新粒子；\n计算每个粒子受到的力；\n更新位置与", "u": "GAMES101/101_L21.html#s5"}, {"c": "GAMES101 L21 · 第 21 讲：动画——关键帧、物理模拟、运动学与绑定", "t": "6. 正向运动学：从关节角度算末端位置", "x": "运动学（Kinematics）研究位置、速度、加速度的几何关系，不考虑力。角色骨架是一个关节（joint）组成的树结构：根节点连接躯干，再分叉到四肢和头。关节类型包括铰链关节（1D 旋转）、球关节（2D 旋转）和平移关节（prismatic joint）。\n正向运动学（Forward Kinemat", "u": "GAMES101/101_L21.html#s6"}, {"c": "GAMES101 L21 · 第 21 讲：动画——关键帧、物理模拟、运动学与绑定", "t": "7. 逆向运动学：从末端位置反求关节角度", "x": "逆向运动学（Inverse Kinematics, IK）反过来：动画师给出末端执行器的目标位置，计算机求满足约束的关节角度。两段手臂可以解析求解（余弦定理），但一般 N 连杆问题很难，原因有三：\n\n多解：同一个末端位置可能对应多组关节角度（肘部朝上或朝下）；\n可能无解：目标超出可达范围；\n高维非线", "u": "GAMES101/101_L21.html#s7"}, {"c": "GAMES101 L21 · 第 21 讲：动画——关键帧、物理模拟、运动学与绑定", "t": "8. 绑定、混合变形与动作捕捉", "x": "绑定（Rigging）是在角色上搭建一套高层控制，让动画师能快速直观地修改姿态、形变和表情。课件把它比作提线木偶的绳子：它捕捉角色所有有意义的变形，但每个角色都不一样，制作成本高，需要艺术与技术双重训练。\n混合变形（Blend Shapes）不走骨骼，而是直接插值表面顶点位置。典型用法是面部表情：建", "u": "GAMES101/101_L21.html#s8"}, {"c": "GAMES101 L21 · 核心结论", "t": "动画的本质是把场景模型表示为时间的函数，输出连续帧序列产生运动感。", "x": "", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 核心结论", "t": "关键帧动画由动画师给出关键姿态，计算机或助手生成中间帧（补间），每个参数通常用样条而非线性插值。", "x": "", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 核心结论", "t": "物理模拟基于牛顿第二定律，用数值积分（如显式欧拉）逐步更新位置与速度。", "x": "", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 核心结论", "t": "弹簧质点系统中，弹簧力正比于形变（胡克定律），需要非零静止长度与阻尼来避免永久振荡。", "x": "", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 核心结论", "t": "粒子系统用大量粒子加简单力（引力、斥力、阻尼、碰撞）模拟流体、鸟群等复杂现象。", "x": "", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 核心结论", "t": "正向运动学由关节角度算末端位置，逆向运动学由末端位置反求关节角度，后者有多解、无解与数值求解问题。", "x": "", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 核心结论", "t": "绑定是角色上的高层控制，混合变形直接插值顶点位置，动作捕捉用真实数据驱动动画但有成本与艺术调整问题。", "x": "", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 术语", "t": "Keyframe Animation / 关键帧动画", "x": "动画师给出关键姿态，计算机补间生成中间帧。", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 术语", "t": "Tweening / 补间", "x": "在关键帧之间生成中间帧的过程。", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 术语", "t": "Explicit Euler / 显式欧拉积分", "x": "用当前速度与加速度直接更新下一时刻状态，简单但可能不稳定。", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 术语", "t": "Hooke's Law / 胡克定律", "x": "弹簧力正比于形变量，方向沿弹簧轴线。", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 术语", "t": "Damping / 阻尼", "x": "消耗系统能量、抑制振荡的力，分全局速度阻尼与内部阻尼。", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 术语", "t": "Particle System / 粒子系统", "x": "用大量粒子加简单力模拟流体、鸟群等复杂现象。", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 术语", "t": "Forward Kinematics / 正向运动学", "x": "由关节角度计算末端位置。", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 术语", "t": "Inverse Kinematics / 逆向运动学", "x": "由末端目标位置反求关节角度，常有多解或无解。", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 术语", "t": "Rigging / 绑定", "x": "角色上的高层控制层，便于快速调整姿态与表情。", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 术语", "t": "Blend Shapes / 混合变形", "x": "直接对顶点位置做线性组合生成表情等形变。", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 术语", "t": "Uncanny Valley / 恐怖谷", "x": "人造角色接近真人但不够真时，观众情绪反应变负面的现象。", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 练习", "t": "显式欧拉积分中，如果时间步长 \\( \\Delta t \\) 取得过大，弹簧质点系统会发生什么？为什么？", "x": "", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 练习", "t": "一根弹簧连接点 a=(0,0) 与 b=(3,0)，静止长度 l=1，劲度系数 k_s=2。求 a 对 b 的弹簧力向量。", "x": "", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 练习", "t": "正向运动学与逆向运动学的输入输出分别是什么？为什么 IK 通常比 FK 难？", "x": "", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 练习", "t": "在引擎中实现布料时，为什么弯曲弹簧（bending spring）的刚度要远小于结构弹簧？", "x": "", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L21 · 练习", "t": "设计一个简单的鸟群粒子系统，写出每帧对每只鸟施加的三条规则及对应的力方向。", "x": "", "u": "GAMES101/101_L21.html"}, {"c": "GAMES101 L02 · 第 2 讲：线性代数复习——向量与矩阵", "t": "1. 为什么图形学离不开线性代数", "x": "图形学里几乎所有东西最终都要落到“向量”和“矩阵”上：一个点的位置是向量，一个方向是向量，平移/旋转/缩放是矩阵，光照计算里求夹角用点乘，判断三角形内外用叉乘。这一讲不追求数学上的完备，而是把后续课程要用的工具快速过一遍，建立几何直觉。\n\\n课件里提到，图形学依赖的基础数学包括线性代数、微积分、统计", "u": "GAMES101/101_L02.html#s1"}, {"c": "GAMES101 L02 · 第 2 讲：线性代数复习——向量与矩阵", "t": "2. 向量：方向、长度与归一化", "x": "向量（vector）通常写成 \\( \\vec{a} \\) 或粗体 a，也可以用起点和终点表示：\\( \\vec{AB} = B - A \\)。它有两个属性：方向（direction）和长度（length），但没有绝对起点（no absolute starting position）。这一点在图形学里非", "u": "GAMES101/101_L02.html#s2"}, {"c": "GAMES101 L02 · 第 2 讲：线性代数复习——向量与矩阵", "t": "3. 点乘：夹角、投影与前后判断", "x": "点乘（dot product，也叫内积）的结果是一个标量：\\( \\vec{a}\\cdot\\vec{b} = \\|\\vec{a}\\|\\|\\vec{b}\\|\\cos\\theta \\)。如果两个向量都是单位向量，那么 \\( \\cos\\theta = \\hat{a}\\cdot\\hat{b} \\)，点乘直接给", "u": "GAMES101/101_L02.html#s3"}, {"c": "GAMES101 L02 · 第 2 讲：线性代数复习——向量与矩阵", "t": "4. 叉乘：垂直方向、左右与内外", "x": "叉乘（cross product）的结果是一个向量，它同时垂直于原来的两个向量，方向由右手定则（right-hand rule）决定。课件强调：叉乘在构建坐标系时非常有用。\n\\n叉乘有一些重要性质：\\( \\vec{x}\\times\\vec{y} = +\\vec{z} \\)，\\( \\vec{y}\\ti", "u": "GAMES101/101_L02.html#s4"}, {"c": "GAMES101 L02 · 第 2 讲：线性代数复习——向量与矩阵", "t": "5. 正交基与坐标系：为什么需要多套坐标", "x": "正交基（orthonormal basis）是一组两两垂直且长度为 1 的向量。在三维中，如果 \\( \\vec{u},\\vec{v},\\vec{w} \\) 满足 \\( \\|\\vec{u}\\|=\\|\\vec{v}\\|=\\|\\vec{w}\\|=1 \\)，\\( \\vec{u}\\cdot\\vec{v}=\\v", "u": "GAMES101/101_L02.html#s5"}, {"c": "GAMES101 L02 · 第 2 讲：线性代数复习——向量与矩阵", "t": "6. 矩阵：乘法、转置与逆", "x": "矩阵（matrix）是二维数组，m 行 n 列。矩阵加法与数乘都是逐元素操作。矩阵乘法要求左矩阵的列数等于右矩阵的行数：\\( (M\\times N)(N\\times P) = (M\\times P) \\)。结果矩阵的第 (i,j) 个元素是左矩阵第 i 行与右矩阵第 j 列的点乘。\n\\n矩阵乘法不满", "u": "GAMES101/101_L02.html#s6"}, {"c": "GAMES101 L02 · 第 2 讲：线性代数复习——向量与矩阵", "t": "7. 用矩阵统一表示点乘与叉乘", "x": "课件最后把点乘和叉乘都写成矩阵形式，目的是让后续的变换和推导更统一。\n\\n点乘可以写成 \\( \\vec{a}\\cdot\\vec{b} = \\vec{a}^T\\vec{b} \\)：把 \\( \\vec{a} \\) 转置成行向量，再乘以列向量 \\( \\vec{b} \\)，结果是一个 1×1 矩阵，也就是标", "u": "GAMES101/101_L02.html#s7"}, {"c": "GAMES101 L02 · 核心结论", "t": "向量表示方向与长度，没有固定起点；单位向量只表示方向，归一化就是除以模长。", "x": "", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 核心结论", "t": "点乘 \\( \\vec{a}\\cdot\\vec{b} = \\|\\vec{a}\\|\\|\\vec{b}\\|\\cos\\theta \\)，可求夹角、投影、判断前后；单位向", "x": "", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 核心结论", "t": "叉乘结果垂直于两向量，方向由右手定则决定，可用于构建坐标系、判断左右与内外。", "x": "", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 核心结论", "t": "正交基 \\( \\vec{u},\\vec{v},\\vec{w} \\) 满足两两垂直且长度为 1，任意向量可表示为三个基向量的投影组合。", "x": "", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 核心结论", "t": "矩阵乘法要求左矩阵列数等于右矩阵行数，结果元素是左行点乘右列；矩阵乘法一般不可交换。", "x": "", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 核心结论", "t": "矩阵与向量相乘是变换点的关键操作；转置交换行列，逆矩阵满足 \\( AA^{-1}=A^{-1}A=I \\)。", "x": "", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 核心结论", "t": "点乘可写成 \\( \\vec{a}^T\\vec{b} \\)，叉乘可写成反对称矩阵（对偶矩阵）乘以向量，统一到矩阵框架。", "x": "", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 术语", "t": "Vector / 向量", "x": "有方向和大小的量，没有固定起点。", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 术语", "t": "Normalization / 归一化", "x": "把向量除以自身长度，得到单位向量。", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 术语", "t": "Dot Product / 点乘", "x": "结果标量，等于两向量长度乘夹角余弦。", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 术语", "t": "Cross Product / 叉乘", "x": "结果向量，垂直于两输入向量，方向由右手定则决定。", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 术语", "t": "Orthonormal Basis / 正交基", "x": "两两垂直且长度为 1 的一组基向量。", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 术语", "t": "Matrix Multiplication / 矩阵乘法", "x": "左矩阵行点乘右矩阵列，一般不满足交换律。", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 术语", "t": "Transpose / 转置", "x": "交换矩阵的行和列。", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 术语", "t": "Inverse Matrix / 逆矩阵", "x": "满足 AA^{-1}=I 的矩阵，顺序反转规则 (AB)^{-1}=B^{-1}A^{-1}。", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 术语", "t": "Dual Matrix / 对偶矩阵", "x": "把叉乘写成反对称矩阵乘向量的形式。", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 练习", "t": "已知 \\( \\vec{a}=(1,2,2) \\)，求它的单位向量。", "x": "", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 练习", "t": "已知 \\( \\vec{a}=(1,0,0) \\)，\\( \\vec{b}=(0,1,0) \\)，求 \\( \\vec{a}\\times\\vec{b} \\) 和 \\(", "x": "", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 练习", "t": "判断点 P 是否在三角形 ABC 内部，写出用叉乘的判断思路。", "x": "", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 练习", "t": "矩阵 A 是 3×2，矩阵 B 是 2×4，AB 的维度是多少？BA 能乘吗？", "x": "", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L02 · 练习", "t": "在 UE 里，为什么法线向量不能直接加上平移？", "x": "", "u": "GAMES101/101_L02.html"}, {"c": "GAMES101 L17 · 第 17 讲：材质与外观——从 BRDF 到微表面模型", "t": "1. 材质即 BRDF：从外观到数学", "x": "在图形学中，我们看到的“材质”本质上是光线与表面相互作用的方式。课件用一只咖啡杯的例子说明：同一个模型，赋予不同的材质，渲染结果截然不同。那么材质在数学上是什么？答案是 BRDF（双向反射分布函数，Bidirectional Reflectance Distribution Function）。\n\\", "u": "GAMES101/101_L17.html#s1"}, {"c": "GAMES101 L17 · 第 17 讲：材质与外观——从 BRDF 到微表面模型", "t": "2. 漫反射：为什么 BRDF 是常数除以 π", "x": "漫反射（Diffuse / Lambertian）材质的特点是：入射光被均匀地反射到所有出射方向，与观察方向无关。现实中的粉笔、粗糙墙面近似这种材质。\n\\n假设入射光是均匀的（各方向辐射亮度 \\(L_i\\) 相同），那么出射辐射亮度 \\(L_o\\) 应该等于多少？根据能量守恒，出射的总辐射通量不能超", "u": "GAMES101/101_L17.html#s2"}, {"c": "GAMES101 L17 · 第 17 讲：材质与外观——从 BRDF 到微表面模型", "t": "3. 完美镜面反射与折射：方向怎么算", "x": "光泽材质（Glossy）和理想反射/折射材质（如金属、玻璃、水）需要处理镜面反射和折射。\n完美镜面反射：入射角等于反射角，且反射方向与入射方向关于法线对称。设入射方向为 \\(\\omega_i\\)（指向表面），法线为 \\(n\\)，则反射方向：\n\\[\n\\omega_o = 2(\\omega_i \\cdo", "u": "GAMES101/101_L17.html#s3"}, {"c": "GAMES101 L17 · 第 17 讲：材质与外观——从 BRDF 到微表面模型", "t": "4. 菲涅尔项：为什么掠射角更亮", "x": "菲涅尔效应描述的是：反射率随入射角变化。垂直入射时反射率最低，掠射角（接近 90°）时反射率趋近于 1。这就是为什么水面在远处看起来像镜子，而近处能看清水下。\n\\n菲涅尔项与光的偏振有关，精确计算需要区分 s 偏振和 p 偏振，公式较复杂。课件给出的是Schlick 近似，它简单且足够准确：\n\\[\\", "u": "GAMES101/101_L17.html#s4"}, {"c": "GAMES101 L17 · 第 17 讲：材质与外观——从 BRDF 到微表面模型", "t": "5. 微表面理论：粗糙表面 = 大量微小镜面", "x": "真实世界没有完美光滑的表面。微表面理论（Microfacet Theory）认为：宏观上粗糙的表面，在微观上由大量朝向各异的微小镜面（microfacet）组成。每个微表面都是完美镜面，但它们的法线方向分布不同。\n\\n关键思想：\n\n如果微表面法线集中在一个方向（接近宏观法线），表面看起来光滑（glo", "u": "GAMES101/101_L17.html#s5"}, {"c": "GAMES101 L17 · 第 17 讲：材质与外观——从 BRDF 到微表面模型", "t": "6. 各向同性与各向异性：方向性从哪来", "x": "各向同性（Isotropic）材质：BRDF 只依赖于入射和出射方向与法线的夹角，以及方位角之差，即：\n\\[\\nf_r(\\theta_i, \\phi_i; \\theta_r, \\phi_r) = f_r(\\theta_i, \\theta_r, \\phi_r - \\phi_i).\n\\]\\n如果进一步各", "u": "GAMES101/101_L17.html#s6"}, {"c": "GAMES101 L17 · 第 17 讲：材质与外观——从 BRDF 到微表面模型", "t": "7. 测量 BRDF：从现实到数据", "x": "既然 BRDF 决定材质，那么如何获得真实材质的 BRDF？答案是测量。测量 BRDF 可以避免开发复杂的解析模型，并且能自动包含所有散射效应。\n\\n测量设备称为角反射计（gonioreflectometer），它通过机械臂移动光源和传感器，测量不同入射和出射方向下的反射率。基本流程：对于每个出射方", "u": "GAMES101/101_L17.html#s7"}, {"c": "GAMES101 L17 · 核心结论", "t": "材质在图形学中就是 BRDF：它定义了入射光如何被表面散射到各个出射方向。", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 核心结论", "t": "漫反射 BRDF 是常数 \\(f_r = \\rho/\\pi\\)，其中 \\(\\rho\\) 是反照率（颜色），除以 \\(\\pi\\) 是为了能量守恒。", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 核心结论", "t": "完美镜面反射满足入射角等于反射角，且反射方向与入射方向关于法线对称。", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 核心结论", "t": "折射遵循 Snell 定律 \\(\\eta_i \\sin\\theta_i = \\eta_t \\sin\\theta_t\\)，当光从光密介质射向光疏介质且入射角过大时", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 核心结论", "t": "菲涅尔项描述反射率随入射角变化：掠射角越大，反射越强；Schlick 近似给出简单公式。", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 核心结论", "t": "微表面理论把粗糙表面看作大量微小镜面，其 BRDF 由法线分布 D、几何遮蔽 G 和菲涅尔 F 三项组成。", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 核心结论", "t": "各向异性 BRDF 依赖方位角差 \\(\\phi_r - \\phi_i\\)，由表面微观结构的方向性导致，如拉丝金属。", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 核心结论", "t": "BRDF 必须满足非负性、互易性和能量守恒，这些性质可用于验证和简化模型。", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 术语", "t": "BRDF / 双向反射分布函数", "x": "描述入射光如何被表面反射到出射方向的函数。", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 术语", "t": "Diffuse / Lambertian / 漫反射", "x": "光线均匀反射到所有方向，BRDF 为常数 \\( \\rho/\\pi \\)。", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 术语", "t": "Specular Reflection / 镜面反射", "x": "入射角等于反射角，反射方向关于法线对称。", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 术语", "t": "Snell's Law / 斯涅尔定律", "x": "描述折射角与入射角的关系：\\(\\eta_i \\sin\\theta_i = \\eta_t \\sin\\theta_t\\)。", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 术语", "t": "Total Internal Reflection / 全反射", "x": "光从光密到光疏介质且入射角大于临界角时，全部反射。", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 术语", "t": "Fresnel Term / 菲涅尔项", "x": "反射率随入射角变化，掠射角反射增强。", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 术语", "t": "Microfacet Theory / 微表面理论", "x": "粗糙表面由大量微小镜面组成，用统计分布描述。", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 术语", "t": "Isotropic / Anisotropic / 各向同性/各向异性", "x": "BRDF 是否依赖方位角，各向异性有方向性高光。", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 术语", "t": "Reciprocity / 互易性", "x": "交换入射和出射方向，BRDF 值不变。", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 练习", "t": "证明漫反射 BRDF 为 \\(f_r = \\rho/\\pi\\) 时，若入射光均匀且 \\(\\rho=1\\)，出射辐射亮度等于入射辐射亮度。", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 练习", "t": "光从空气（\\(\\eta_i=1\\)）射入玻璃（\\(\\eta_t=1.5\\)），入射角为 45°，求折射角。", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 练习", "t": "解释为什么金属的菲涅尔反射率在垂直入射时可能很高，而玻璃只有约 4%。", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 练习", "t": "微表面 BRDF 中三项 D、F、G 分别代表什么？如果粗糙度增加，D 函数会如何变化？", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L17 · 练习", "t": "在 UE 中创建一个拉丝金属材质，需要调整哪些参数？", "x": "", "u": "GAMES101/101_L17.html"}, {"c": "GAMES101 L16 · 第 16 讲：光线追踪（三）——蒙特卡洛路径追踪", "t": "1. 从渲染方程到蒙特卡洛：为什么需要数值积分", "x": "上一讲我们得到了渲染方程（Rendering Equation）：\n\\[\\nL_o(p, \\omega_o) = L_e(p, \\omega_o) + \\int_{\\Omega^+} L_i(p, \\omega_i) f_r(p, \\omega_i, \\omega_o) (n \\cdot \\omeg", "u": "GAMES101/101_L16.html#s1"}, {"c": "GAMES101 L16 · 第 16 讲：光线追踪（三）——蒙特卡洛路径追踪", "t": "2. 蒙特卡洛积分：用随机平均估计定积分", "x": "直觉：定积分是曲线下的面积。与其精确算面积，不如在区间里随机撒点，取这些点函数值的平均，再乘以区间长度。撒的点越多，估计越准。\n定义：要估计 \\(\\int_a^b f(x)\\,dx\\)，从一个概率密度函数（PDF）\\(p(x)\\) 中独立采样 \\(X_i\\)，构造蒙特卡洛估计量（Monte Carl", "u": "GAMES101/101_L16.html#s2"}, {"c": "GAMES101 L16 · 第 16 讲：光线追踪（三）——蒙特卡洛路径追踪", "t": "3. 直接光照的蒙特卡洛解法", "x": "现在把蒙特卡洛用到渲染方程上。先只考虑直接光照：着色点 \\(p\\) 只接收来自光源的光，不接收其他物体反射的光。\n\\n渲染方程：\n\\[\\nL_o(p, \\omega_o) = \\int_{\\Omega^+} L_i(p, \\omega_i) f_r(p, \\omega_i, \\omega_o) (n", "u": "GAMES101/101_L16.html#s3"}, {"c": "GAMES101 L16 · 第 16 讲：光线追踪（三）——蒙特卡洛路径追踪", "t": "4. 全局光照：让光线递归弹射", "x": "直接光照只算光源直接照到 \\(p\\) 的光。但现实中，光线打到其他物体后还会反射到 \\(p\\)——这就是间接光照（indirect illumination）。\n关键观察：如果从 \\(p\\) 发出的光线打到了物体上的点 \\(q\\)，那么 \\(q\\) 也会把光反射给 \\(p\\)。反射多少？就是 \\(q", "u": "GAMES101/101_L16.html#s4"}, {"c": "GAMES101 L16 · 第 16 讲：光线追踪（三）——蒙特卡洛路径追踪", "t": "5. 俄罗斯轮盘赌：让递归停下来且不损失能量", "x": "递归必须停，但直接砍掉弹射次数会丢失能量（画面变暗），因为光确实会一直弹。\n俄罗斯轮盘赌（Russian Roulette, RR）用一个概率技巧解决：\n\n设定一个概率 \\(P \\in (0,1)\\)。\n以概率 \\(P\\) 继续发射光线，并把返回结果除以 \\(P\\)：\\(L_o / P\\)。\n以概率", "u": "GAMES101/101_L16.html#s5"}, {"c": "GAMES101 L16 · 第 16 讲：光线追踪（三）——蒙特卡洛路径追踪", "t": "6. 对光源采样：把浪费的光线找回来", "x": "N=1 + RR 的路径追踪已经正确，但效率很低：半球均匀采样时，只有极少数方向能打到光源（尤其光源小的时候），大量光线浪费在打不到光源的方向上。\n解决思路：直接对光源采样。蒙特卡洛允许任意 PDF，所以我们可以让采样点落在光源上。\n\\n但渲染方程是在立体角上积分，而光源采样是在面积上。需要换元：\n", "u": "GAMES101/101_L16.html#s6"}, {"c": "GAMES101 L16 · 第 16 讲：光线追踪（三）——蒙特卡洛路径追踪", "t": "7. 像素、路径与最终图像", "x": "路径追踪的光线生成（ray generation）和普通光线追踪类似：对每个像素，在像素内均匀采样多个位置，从相机向采样点发射光线，打到场景后调用 shade，把结果累加平均。\n\\nray_generation(camPos, pixel)\n  pixel_radiance = 0\n  在像素内均匀", "u": "GAMES101/101_L16.html#s7"}, {"c": "GAMES101 L16 · 核心结论", "t": "蒙特卡洛积分用随机采样的平均值估计定积分：\\(F_N = \\frac{1}{N}\\sum_{i=1}^N \\frac{f(X_i)}{p(X_i)}\\)，样本越", "x": "", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 核心结论", "t": "渲染方程是一个半球上的积分，可以直接用蒙特卡洛方法数值求解，得到正确的直接光照着色算法。", "x": "", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 核心结论", "t": "路径追踪在着色点随机选一个方向弹射光线，递归地收集间接光照，从而渲染全局光照。", "x": "", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 核心结论", "t": "递归不会自然停止，必须用俄罗斯轮盘赌（Russian Roulette）以概率 \\(P\\) 继续并除以 \\(P\\)，保证期望不变且算法终止。", "x": "", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 核心结论", "t": "对半球均匀采样时大量光线浪费在打不到光源上；改为对光源采样（直接光照）可显著降低噪声。", "x": "", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 核心结论", "t": "对光源采样需要把渲染方程从立体角积分转换为面积积分，引入几何项 \\(\\frac{\\cos\\theta'}{\\|x'-p\\|^2}\\)。", "x": "", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 核心结论", "t": "路径追踪是“几乎 100% 正确”的全局光照算法，结果是照片级真实的；现代光线追踪泛指一般光传输求解。", "x": "", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 术语", "t": "Monte Carlo Integration / 蒙特卡洛积分", "x": "用随机采样平均估计定积分的方法", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 术语", "t": "Probability Density Function (PDF) / 概率密度函数", "x": "描述随机变量取值可能性的函数，积分必须为 1", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 术语", "t": "Estimator / 估计量", "x": "由样本构造的随机变量，期望等于真实值则无偏", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 术语", "t": "Path Tracing / 路径追踪", "x": "每个着色点只采一条光线、递归弹射的全局光照算法", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 术语", "t": "Russian Roulette / 俄罗斯轮盘赌", "x": "以概率 P 继续并除以 P，使递归终止且期望不变", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 术语", "t": "SPP / 每像素采样数", "x": "每个像素发射的路径数，越高噪声越低", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 术语", "t": "Global Illumination / 全局光照", "x": "包含间接光照的完整光传输", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 术语", "t": "Solid Angle / 立体角", "x": "单位球面上投影面积，单位球面度为 sr", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 术语", "t": "Whitted-Style Ray Tracing / Whitted 式光线追踪", "x": "只做镜面反射/折射、漫反射停止的简化光线追踪", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 练习", "t": "用蒙特卡洛积分估计 \\(\\int_0^1 x^2 dx\\)，取均匀分布 PDF，写出估计量并说明 N=1000 时的大致误差量级。", "x": "", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 练习", "t": "路径追踪中为什么令 N=1？如果 N=100、弹射 5 次，总光线数是多少？", "x": "", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 练习", "t": "俄罗斯轮盘赌中，若 P=0.8，某条路径的着色结果为 L=10，问该路径返回值的期望是多少？单次运行可能返回什么？", "x": "", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 练习", "t": "把渲染方程从立体角积分转换为光源面积积分，写出转换公式并解释每个因子的含义。", "x": "", "u": "GAMES101/101_L16.html"}, {"c": "GAMES101 L16 · 练习", "t": "实现一个简单的路径追踪器：场景一个面积光源 + 一个漫反射球，用对光源采样 + 半球采样 + RR，渲染 64 SPP，观察噪声并解释来源。", "x": "", "u": "GAMES101/101_L16.html"}, {"c": "GAMES104 L01 · 第 1 讲：游戏引擎导论——什么是游戏引擎，它为什么是现代计算机技术的奇迹", "t": "1. 为什么游戏引擎是现代计算机技术的奇迹", "x": "这一讲的开篇没有直接给定义，而是先给了一个“体量”上的震撼：游戏产业的市场规模已经达到千亿美元级别，超过电影与音乐产业的总和；而支撑这些游戏的引擎，覆盖了计算机科学几乎所有的分支。\n课件用一张图把“游戏引擎技术覆盖的主要计算机科学领域”铺开：渲染、动画、物理、人工智能、音频、网络、数据结构、编译原理", "u": "GAMES104/104_L01.html#s1"}, {"c": "GAMES104 L01 · 第 1 讲：游戏引擎导论——什么是游戏引擎，它为什么是现代计算机技术的奇迹", "t": "2. 游戏引擎的定义：框架、工具与复杂度的艺术", "x": "课件给出了一个比较正式的定义：游戏引擎是主要面向电子游戏开发的软件框架，通常包含相关的库与支持程序。这个定义里有两个关键词：框架（framework） 和 支持程序（support programs）。\n“框架”意味着它提供了一套可复用的骨架：渲染循环、资源管理、输入处理、场景组织等，开发者在其上填", "u": "GAMES104/104_L01.html#s2"}, {"c": "GAMES104 L01 · 第 1 讲：游戏引擎导论——什么是游戏引擎，它为什么是现代计算机技术的奇迹", "t": "3. 从 Wolfenstein 3D 到 Quake：引擎史就是一部技术突破史", "x": "课件用了几页篇幅讲早期历史，这不是怀旧，而是因为现代引擎的很多设计思想在那个时候就定型了。\nJohn Carmack 与 Wolfenstein 3D（1992）：课件称他为“游戏引擎之父”。他的关键贡献不是某个算法，而是一种组织方式——把“执行核心功能”的引擎代码与“填充游戏内容的资产”分离。在此", "u": "GAMES104/104_L01.html#s3"}, {"c": "GAMES104 L01 · 第 1 讲：游戏引擎导论——什么是游戏引擎，它为什么是现代计算机技术的奇迹", "t": "4. 引擎的家族与中间件：商业、自研、免费，以及渲染/物理/动画/音频", "x": "课件把游戏引擎按来源分成三类：商业引擎（Commercial Engine）、自研引擎（In-house Engine）、免费引擎（Free Engine）。\n\n商业引擎：如 Unreal Engine、Unity，授权给外部使用，通常有完善的工具链与技术支持。\n自研引擎：大厂内部使用，如 EA 的", "u": "GAMES104/104_L01.html#s4"}, {"c": "GAMES104 L01 · 第 1 讲：游戏引擎导论——什么是游戏引擎，它为什么是现代计算机技术的奇迹", "t": "5. 引擎到底包含什么：从基础元素到工具链", "x": "课件用一张大图（Basic Elements）展示了引擎的组成，可以分成几层来看：\n第一层：引擎结构与分层（Engine structure and layers）。引擎通常分为工具层、功能层、核心层、平台层。工具层是编辑器和资源管线；功能层是渲染、动画、物理等；核心层是数学库、容器、内存管理；平台", "u": "GAMES104/104_L01.html#s5"}, {"c": "GAMES104 L01 · 第 1 讲：游戏引擎导论——什么是游戏引擎，它为什么是现代计算机技术的奇迹", "t": "6. 实时约束下的工程：为什么引擎要“做取舍”", "x": "课件用“God with Limited Power in Realtime”这句话点出了引擎工程的核心矛盾：你想要模拟一个无限细节的世界，但算力、内存、带宽都是有限的，而且必须在实时内完成。\n课件展示了“模拟复杂度”的示意图：从物体（Object）到地形（Terrain）、粒子（Particle）", "u": "GAMES104/104_L01.html#s6"}, {"c": "GAMES104 L01 · 第 1 讲：游戏引擎导论——什么是游戏引擎，它为什么是现代计算机技术的奇迹", "t": "7. 课程路线图：Mini Engine、作业与项目", "x": "最后一部分是课程信息，虽然看起来“不技术”，但对自学者很重要，因为它告诉你这门课希望你达到什么程度、怎么练。\n课件给出的课程组成包括：\n\nMini Engine：一个迷你运行时框架 + 迷你编辑器，目标是帮你建立游戏引擎的基础知识体系。也就是说，你不是只看幻灯片，而是要亲手搭一个能跑的小引擎。\n作业", "u": "GAMES104/104_L01.html#s7"}, {"c": "GAMES104 L01 · 核心结论", "t": "游戏引擎是“主要面向电子游戏开发的软件框架”，通常包含相关库与支持程序；它既是技术底座，也是生产力工具，更是驾驭复杂度的艺术。", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 核心结论", "t": "引擎的核心价值在于把“执行核心功能”的代码与“填充具体游戏内容”的资产分离——这一思想从 John Carmack 的 Wolfenstein 3D 时代就确立", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 核心结论", "t": "Doom 定义了 FPS 类型并首创在线分发、3D 图形、网络对战与 WAD 模组支持；Quake 则带来完整实时 3D 渲染与 OpenGL 硬件加速。", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 核心结论", "t": "现代引擎按来源可分为商业引擎、自研引擎与免费引擎；按中间件可分为渲染、物理、动画、音频等模块。", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 核心结论", "t": "游戏引擎远不止渲染：它要模拟一个无限细节的世界，涉及数学、物理、AI、动画、音频、网络、工具链等几乎所有计算机科学主要领域。", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 核心结论", "t": "实时是硬约束：引擎要在 1/30 或 1/60 秒内完成一帧的全部模拟与渲染，因此必须在“有限算力”下做大量取舍。", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 核心结论", "t": "引擎同时服务程序员（可扩展 API）、美术/策划（协作工具链）与运营（在线更新），是一个多角色协作平台。", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 核心结论", "t": "本课程以“搭框架、抓主干”为路线，通过 Mini Engine 与分阶段作业，把引擎的主要系统亲手实现一遍。", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 术语", "t": "Game Engine / 游戏引擎", "x": "主要面向电子游戏开发的软件框架，包含相关库与支持程序。", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 术语", "t": "Middleware / 中间件", "x": "引擎中可替换的独立模块，如物理、音频、动画。", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 术语", "t": "In-house Engine / 自研引擎", "x": "公司内部为特定项目深度优化的引擎。", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 术语", "t": "Toolchain / 工具链", "x": "编辑器、资源管线、调试工具等支撑开发效率的工具集合。", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 术语", "t": "Reflection / 反射", "x": "让程序在运行时获取类型信息，常用于把变量/函数暴露到编辑器。", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 术语", "t": "Data Schema / 数据模式", "x": "对系统所处理数据结构的正式描述。", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 术语", "t": "Graph-Driven / 图形驱动", "x": "用可视化节点图搭建逻辑，如蓝图。", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 术语", "t": "Motion Matching / 运动匹配", "x": "一种基于数据检索的动画技术，减少手工状态机。", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 术语", "t": "DOP/ECS / 面向数据编程/实体组件系统", "x": "把数据与代码分离、按数据布局优化的编程范式。", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 术语", "t": "Lockstep Synchronization / 锁步同步", "x": "所有客户端按相同输入推进相同逻辑的同步方式。", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 练习", "t": "用自己的话给出游戏引擎的定义，并说明“框架”和“支持程序”分别指什么。", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 练习", "t": "Wolfenstein 3D、Doom、Quake 各自在引擎史上解决了什么关键问题？", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 练习", "t": "列举游戏引擎的主要子系统（至少 6 个），并各用一句话说明它解决什么问题。", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 练习", "t": "解释“God with Limited Power in Realtime”这句话的含义，并举两个引擎中“做取舍”的例子。", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L01 · 练习", "t": "如果你只用 UE 做游戏，为什么还要学 Mini Engine？请给出至少两条理由。", "x": "", "u": "GAMES104/104_L01.html"}, {"c": "GAMES104 L02 · 第 2 讲：纵览游戏引擎的分层架构", "t": "1. 为什么要分层：从“代码海洋”到五层结构", "x": "打开一个商业引擎的源码目录，第一反应通常是“代码海洋，从哪下手？”。课件用这个问题开场，给出的答案是：分层（layered architecture）。\n把引擎想象成一栋楼：地基（平台层）埋在地下，承重墙（核心层）支撑整体，水电管线（资源层）贯穿各层，房间功能（功能层）按用途划分，最后是装修与家具（", "u": "GAMES104/104_L02.html#s1"}, {"c": "GAMES104 L02 · 第 2 讲：纵览游戏引擎的分层架构", "t": "2. 资源层：把磁盘文件变成运行时能安全引用的资产", "x": "资源层要回答的问题是：如何离线访问我的数据？ 课件把资源管线拆成三段。\n第一段：资源导入（Resource Importing）。 美术在 DCC（Maya、Blender、Photoshop）里产出的原始文件格式五花八门，引擎不直接读它们，而是导入成统一的元资产文件格式（meta asset，如 ", "u": "GAMES104/104_L02.html#s2"}, {"c": "GAMES104 L02 · 第 2 讲：纵览游戏引擎的分层架构", "t": "3. 功能层：用 tick 让世界“活”起来", "x": "功能层是引擎的“肌肉”：渲染、相机、动画、物理、脚本、AI、输入。课件用一句很朴素的话概括：让世界可见、可动、可玩。\n所有这些系统怎么协同？答案是游戏循环（game loop）。课件给了一段极简伪代码：\n// game_main.cpp\nvoid tick(int delta_time) {\n   ", "u": "GAMES104/104_L02.html#s3"}, {"c": "GAMES104 L02 · 第 2 讲：纵览游戏引擎的分层架构", "t": "4. 核心层：数学、容器与内存——性能的地基", "x": "核心层不直接实现玩法，但决定了引擎性能的上限。课件列了三块。\n数学库（Math Library）。 线性代数：旋转、平移、缩放，矩阵、样条（splines）、四元数（quaternion）。四元数用于避免万向节死锁，是骨骼动画与相机的标配。\n数学效率（Math Efficiency）。 课件举了 Q", "u": "GAMES104/104_L02.html#s4"}, {"c": "GAMES104 L02 · 第 2 讲：纵览游戏引擎的分层架构", "t": "5. 平台层：把操作系统、图形 API 和硬件差异关进笼子", "x": "平台层的职责是：面向不同平台，向上层提供与平台无关的服务与信息。课件分三块。\n文件系统（File System）。 不同平台路径分隔符不同（Windows 反斜杠 \\，Unix 正斜杠 /），还有环境变量、目录遍历差异。平台层统一这些细节，上层只写“逻辑路径”。\n图形 API（Graphics AP", "u": "GAMES104/104_L02.html#s5"}, {"c": "GAMES104 L02 · 第 2 讲：纵览游戏引擎的分层架构", "t": "6. 工具层与第三方库：让非程序员也能创作", "x": "工具层的目标是 释放创造力（Unleash the Creativity）：让策划、美术、TA 不写引擎代码也能做游戏。课件列出编辑器家族：关卡编辑器（Level Editor）、动画编辑器（Animation Editor）、着色器编辑器（Shader Editor）、UI 编辑器（UI Edit", "u": "GAMES104/104_L02.html#s6"}, {"c": "GAMES104 L02 · 第 2 讲：纵览游戏引擎的分层架构", "t": "7. 分层架构的收益与 Pilot 迷你引擎实践", "x": "课件用一页总结 为什么分层：\n\n解耦与降低复杂度（Decoupling and Reducing Complexity）：下层独立于上层，上层不知道下层实现。\n应对演进需求（Response for Evolving Demands）：上层演进快，下层稳定。\n\n这两条不是口号，而是工程约束：它决定了", "u": "GAMES104/104_L02.html#s7"}, {"c": "GAMES104 L02 · 核心结论", "t": "游戏引擎采用分层架构：工具层 → 功能层 → 资源层 → 核心层 → 平台层，越往下越稳定、越往上越可定制。", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 核心结论", "t": "分层的目的是解耦与降低复杂度：下层不知道上层是谁，上层不关心下层的实现细节。", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 核心结论", "t": "资源层用元资产文件（.ast）、GUID、句柄系统和生命周期管理，把“磁盘上的文件”变成“运行时可安全引用的对象”。", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 核心结论", "t": "功能层由游戏循环（game loop）驱动，每个 tick 依次推进动画、物理、逻辑、渲染等子系统；渲染通常跑在独立线程。", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 核心结论", "t": "核心层是引擎的地基：数学库（向量/矩阵/四元数）、自定义容器、内存池与缓存友好设计，直接决定性能上限。", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 核心结论", "t": "平台层负责屏蔽操作系统、图形 API、硬件架构差异，向上提供与平台无关的服务（文件系统、RHI）。", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 核心结论", "t": "工具层（编辑器、DCC 管线）让非程序员也能创作内容，是引擎“可用性”的关键。", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 核心结论", "t": "Pilot 迷你引擎按同样的分层实现，是理解本讲概念的最佳实践样本。", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 术语", "t": "Layered Architecture / 分层架构", "x": "把系统按稳定性与职责分成多层，依赖只向下。", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 术语", "t": "Meta Asset (.ast) / 元资产文件", "x": "资源导入后的统一中间格式，运行时读取更快。", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 术语", "t": "GUID / 全局唯一标识符", "x": "资源引用的稳定 ID，避免路径改名导致引用断裂。", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 术语", "t": "Handle / 句柄", "x": "资源的间接引用编号，屏蔽内存地址变化。", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 术语", "t": "Game Loop / Tick / 游戏循环/心跳", "x": "每帧依次驱动输入、逻辑、动画、物理、渲染的循环。", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 术语", "t": "RHI / 渲染硬件接口", "x": "平台层对图形 API 的抽象，屏蔽 GPU 与 SDK 差异。", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 术语", "t": "UMA / 统一内存访问", "x": "CPU/GPU 共享内存的硬件架构，影响拷贝策略。", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 术语", "t": "Memory Arena / 内存竞技场", "x": "整块分配、整块释放的分配器，适合帧级临时数据。", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 术语", "t": "DCC / 数字内容创作工具", "x": "Maya/Blender/Photoshop 等美术工具，产出原始资产。", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 术语", "t": "Asset Conditioning Pipeline / 资产调理管线", "x": "DCC 到引擎之间的格式转换、压缩、LOD 生成流程。", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 练习", "t": "判断以下代码应放在哪一层，并说明理由：(a) 一个求向量叉积的函数；(b) 读取 Windows 注册表获取安装路径；(c) 角色跳跃的玩法逻辑；(d) 把 P", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 练习", "t": "课件说“Handle vs Post Address”。请解释为什么资源系统用句柄而不是直接返回内存指针，并举一个会出问题的场景。", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 练习", "t": "一个 tick 中依次执行 input、logic、animation、physics、render。若物理步进耗时过长导致帧率下降，你会如何调整架构？", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 练习", "t": "为什么核心层要“避免内存碎片”并“把数据放一起”？请从缓存局部性角度解释，并给出一个容器设计建议。", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L02 · 练习", "t": "对照 UE 或 Unity，列出三个能体现“分层架构”的具体模块，并说明它们分别属于哪一层。", "x": "", "u": "GAMES104/104_L02.html"}, {"c": "GAMES104 L04 · 第 4 讲：游戏引擎中的渲染——从硬件到管线", "t": "1. 游戏渲染到底在解决什么问题", "x": "课件开篇先给了一个对比：图形学理论课关心的是“表示正确、数学正确”，可以离线慢慢算；而游戏引擎渲染是实时的，必须在 30 FPS（甚至 60/120 FPS、VR）下，把成千上万个物体、几十种效果画出来。\n游戏渲染的挑战可以归纳为四条：\n\n海量物体与效果：数万个物体、几十种材质与光照效果。\n复杂硬件", "u": "GAMES104/104_L04.html#s1"}, {"c": "GAMES104 L04 · 第 4 讲：游戏引擎中的渲染——从硬件到管线", "t": "2. 渲染管线的数据流：顶点、三角形、材质与像素", "x": "课件把渲染的“积木”拆成三层数据：\n\n顶点数据（Vertex Data）与三角形数据（Triangle Data）：数百万个顶点和三角形。\n材质参数（Material Parameters）与纹理（Textures）：决定表面看起来是什么。\n像素：数千万像素，每个像素要跑几百条 ALU 指令、做十几", "u": "GAMES104/104_L04.html#s2"}, {"c": "GAMES104 L04 · 第 4 讲：游戏引擎中的渲染——从硬件到管线", "t": "3. 理解 GPU：SIMT、GPC/SM 与性能边界", "x": "课件用一页讲 SIMD 与 SIMT：\n\nSIMD（Single Instruction Multiple Data）：一条指令同时处理多个数据点。\nSIMT（Single Instruction Multiple Threads）：SIMD 与多线程结合的并行执行模型，是 GPU 的典型模型。\n\n", "u": "GAMES104/104_L04.html#s3"}, {"c": "GAMES104 L04 · 第 4 讲：游戏引擎中的渲染——从硬件到管线", "t": "4. 可渲染对象：网格、子网格与材质", "x": "游戏世界里“一切都是游戏对象”，对象用组件方式描述，其中 Mesh Render Component（网格渲染组件） 负责渲染。一个可渲染对象由这些积木组成：\n\n网格图元（Mesh Primitive）：三角形/四边形等基本图元。\n顶点缓冲与索引缓冲：顶点数据（位置、法线、UV 等）放在顶点缓冲（V", "u": "GAMES104/104_L04.html#s4"}, {"c": "GAMES104 L04 · 第 4 讲：游戏引擎中的渲染——从硬件到管线", "t": "5. 可见性剔除：尽量少画", "x": "对每个视角，场景里大量物体根本不需要画。剔除的核心是用最简单的包围体做便宜的相交测试。课件列了好包围体的标准：相交测试便宜、贴合紧、计算便宜、易于旋转和变换、占用内存少。\n常见的剔除层次：\n\n视锥剔除（View Frustum Culling）：用包围盒/包围球与视锥做测试。\n层次化剔除：四叉树（Q", "u": "GAMES104/104_L04.html#s5"}, {"c": "GAMES104 L04 · 第 4 讲：游戏引擎中的渲染——从硬件到管线", "t": "6. 纹理压缩与建模方式：内容侧的成本", "x": "纹理压缩是游戏引擎的“必知项”。传统图像压缩（JPG/PNG）压缩率高、画质好，但设计目标是整张图压缩/解压；而 GPU 采样需要随机访问——任意一个像素都要能快速取到。所以游戏纹理用块压缩（Block Compression）：把纹理切成固定大小的块（如 4×4），每块独立解码。\n常见格式：PC ", "u": "GAMES104/104_L04.html#s6"}, {"c": "GAMES104 L04 · 第 4 讲：游戏引擎中的渲染——从硬件到管线", "t": "7. GPU-Driven 与 Cluster-Based Mesh Pipeline（含 Nanite）", "x": "随着 GPU 越来越强，越来越多工作被搬到 GPU，这就是 GPU-Driven。课件给了两个代表性架构：\n\nGPU-Driven Rendering Pipeline（2015）：Mesh Cluster Rendering——单次 drawcall 里画任意数量网格，由 GPU 按 cluste", "u": "GAMES104/104_L04.html#s7"}, {"c": "GAMES104 L04 · 核心结论", "t": "游戏渲染是工程优化问题：要在有限 CPU/GPU 带宽和内存下稳定达到 30/60/120 FPS。", "x": "", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 核心结论", "t": "GPU 是 SIMT 架构：同一指令并行处理大量数据，因此要避免分支发散、提高缓存与带宽效率。", "x": "", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 核心结论", "t": "一个模型由多个子网格（submesh）组成，每个子网格对应一种材质，绘制时按材质排序并合批。", "x": "", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 核心结论", "t": "可见性剔除（视锥、BVH、PVS、GPU 剔除）的目标是“尽量少画”，是引擎渲染性能的关键。", "x": "", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 核心结论", "t": "纹理必须用块压缩（BC7/ASTC 等）以支持随机访问和快速解码，不能直接用 JPG/PNG。", "x": "", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 核心结论", "t": "现代管线把剔除与绘制决策搬到 GPU（GPU-Driven），Nanite 用层次化 Cluster + 持久线程 CS 实现无缝 LOD。", "x": "", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 核心结论", "t": "引擎设计深受硬件架构影响：理解硬件才能理解渲染管线为什么长这样。", "x": "", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 术语", "t": "SIMT / 单指令多线程", "x": "GPU 的并行执行模型，SIMD 与多线程结合，Warp 内同指令执行。", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 术语", "t": "Warp / 线程束", "x": "GPU 以一组线程（通常 32 个）为单位执行同一条指令，分支发散代价高。", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 术语", "t": "Submesh / 子网格", "x": "索引缓冲的一段 offset/count，绑定独立材质，解决单模型多材质。", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 术语", "t": "View Frustum Culling / 视锥剔除", "x": "用包围体与视锥做相交测试，排除视锥外物体。", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 术语", "t": "BVH / 包围体层次结构", "x": "层次化包围体树，加速剔除与相交测试。", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 术语", "t": "PVS / 潜在可见集", "x": "预计算区域间可见性，运行时查表，适合静态场景。", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 术语", "t": "Block Compression / 块压缩", "x": "把纹理切块独立解码，支持 GPU 随机访问，如 BC7/ASTC。", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 术语", "t": "GPU-Driven / GPU 驱动渲染", "x": "把剔除与绘制决策搬到 GPU，支撑海量图元。", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 术语", "t": "Nanite / Nanite 虚拟几何", "x": "UE5 的层次化 cluster LOD + GPU 剔除方案，无需特殊硬件。", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 术语", "t": "TMU Bound / 纹理单元瓶颈", "x": "纹理采样次数过多导致 TMU 成为性能瓶颈。", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 练习", "t": "为什么游戏纹理不能直接用 JPG/PNG，而要用 BC7/ASTC 这类块压缩格式？", "x": "", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 练习", "t": "一个模型有 3 个材质，引擎如何组织数据才能一次上传网格、分材质绘制？", "x": "", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 练习", "t": "视锥剔除中，包围体需要满足哪些条件？为什么包围盒过大会导致剔除失效？", "x": "", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 练习", "t": "简述 Nanite 的核心思想，并说明它为什么不需要特殊硬件支持。", "x": "", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L04 · 练习", "t": "实践：在 UE 中打开 `stat unit`，观察 Frame/Game/Draw/GPU 四项，判断你的场景是 CPU 还是 GPU 瓶颈，并说明下一步优化", "x": "", "u": "GAMES104/104_L04.html"}, {"c": "GAMES104 L03 · 第 3 讲：如何构建游戏世界", "t": "1. 游戏世界由什么组成：从无人机到空气墙", "x": "这一讲要回答一个很朴素的问题：游戏世界到底由什么构成？ 课件先给出一张分层图（Tool Layer、Function Layer、Resource Layer、Core Layer、Platform Layer），然后从最上层的“世界内容”切入。\n把镜头拉近，一个典型的战场场景里有：\n\n静态游戏对象", "u": "GAMES104/104_L03.html#s1"}, {"c": "GAMES104 L03 · 第 3 讲：如何构建游戏世界", "t": "2. 怎么描述一个游戏对象：属性、行为与继承的困境", "x": "课件用一个具体需求开场：“我想要一架无人机！”那现实中我们怎么描述一架无人机？\n\n形状（属性）\n位置（属性）\n移动（行为）\n电池容量（属性）\n……\n\n归纳起来就是：属性（Property）+ 行为（Behavior）。于是最直觉的写法是定义一个类：\nclass Drone {\n    Positio", "u": "GAMES104/104_L03.html#s2"}, {"c": "GAMES104 L03 · 第 3 讲：如何构建游戏世界", "t": "3. 组件化：用“拼装”代替“分类”", "x": "课件用两个现实类比讲组件化（Component）：\n\n工程机械：挖掘机、装载机、压路机，底盘、动臂、铲斗、驾驶舱等部件可以互换组合。\n枪械：HK416、M4、AR 系列，枪管、护木、弹匣、瞄具按接口组合。\n\n对应到无人机，它由这些组件构成：Transform（变换）、Motor（动力）、Model（", "u": "GAMES104/104_L03.html#s3"}, {"c": "GAMES104 L03 · 第 3 讲：如何构建游戏世界", "t": "4. 让世界动起来：Tick 循环的两种组织方式", "x": "对象描述好了，接下来要每帧更新它们的状态，这就是 Tick（也叫 Update）。课件对比了两种组织方式。\n基于对象的 Tick（Object-based Tick）：每个游戏对象内部依次调用自己的各个组件。\nGO1: Motor → Controller → Animation\nGO2: Moto", "u": "GAMES104/104_L03.html#s4"}, {"c": "GAMES104 L03 · 第 3 讲：如何构建游戏世界", "t": "5. 对象之间怎么交互：事件机制", "x": "世界活了，但对象不能各玩各的。课件抛出一个具体问题：“怎么让一颗弹药在游戏里爆炸？”\n最直接的写法是硬编码（Hardcode）：弹药爆炸时，依次调用士兵、直升机、石头、坦克的受伤逻辑。\nvoid OnExplode() {\n    soldier.TakeDamage(...);\n    helic", "u": "GAMES104/104_L03.html#s5"}, {"c": "GAMES104 L03 · 第 3 讲：如何构建游戏世界", "t": "6. 怎么管理这么多对象：场景与空间查询", "x": "对象多了就要管理。课件给出的容器是场景（Scene）：游戏对象都在场景里被统一管理。\n管理要解决的核心问题是查询：\n\n按唯一 ID 查（精确查找某个对象）。\n按位置查（“我周围有哪些对象？”——这是最常用的）。\n\n如果场景里有成千上万个对象，逐个遍历就是大海捞针（A needle in a hays", "u": "GAMES104/104_L03.html#s6"}, {"c": "GAMES104 L03 · 第 3 讲：如何构建游戏世界", "t": "7. 本讲收束：五句话记住游戏世界的骨架", "x": "课件最后用五条 Takeaway 收束全讲，这也是整讲的骨架：\n\n一切都是对象（Everything is an object）——可见的、不可见的，统一抽象。\n游戏对象用组件化方式描述（Game object could be described in the component-based wa", "u": "GAMES104/104_L03.html#s7"}, {"c": "GAMES104 L03 · 核心结论", "t": "游戏世界里的一切都是游戏对象（Game Object）", "x": "", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 核心结论", "t": "游戏对象用“属性 + 行为”描述，但用继承分类会很快遇到“分类不完美”的问题", "x": "", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 核心结论", "t": "组件化（Component）用组合代替继承，把 Transform、Model、Physics、AI 等拆成可插拔的部件", "x": "", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 核心结论", "t": "游戏对象的状态在 Tick 循环中更新；按组件组织 Tick 比按对象组织更高效（可并行、缓存友好）", "x": "", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 核心结论", "t": "对象间通过事件（Event）机制交互，发送与处理解耦，避免硬编码耦合", "x": "", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 核心结论", "t": "游戏对象由场景（Scene）统一管理，借助网格、四叉树/八叉树、BVH、BSP、场景图等空间结构加速查询", "x": "", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 核心结论", "t": "商业引擎（UE/Unity）的 GameObject/Entity + Component 体系正是这一讲的工程实现", "x": "", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 术语", "t": "Game Object / 游戏对象", "x": "游戏世界中的基本实体，可见或不可见，统一抽象", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 术语", "t": "Component / 组件", "x": "可插拔的功能部件，用组合代替继承描述对象", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 术语", "t": "Tick / 帧更新", "x": "每帧调用以更新对象状态，可按对象或按组件组织", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 术语", "t": "Event / 事件", "x": "对象间消息机制，发送与处理解耦", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 术语", "t": "Scene / 场景", "x": "统一管理游戏对象的容器", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 术语", "t": "Quadtree / Octree / 四叉树 / 八叉树", "x": "层次化空间分割结构，加速按位置查询", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 术语", "t": "BVH / 包围体层次", "x": "按包围盒合并成树，用于射线检测与碰撞粗筛", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 术语", "t": "BSP / 二叉空间分割", "x": "用平面递归分割空间，早期用于室内可见性", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 术语", "t": "Scene Graph / 场景图", "x": "按父子关系组织对象，变换沿层级累积", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 术语", "t": "ECS / 实体-组件-系统", "x": "按组件类型连续存储、系统批量处理的架构，本讲组件化 Tick 的延伸", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 练习", "t": "为什么课件说“游戏世界没有完美的分类”？请举一个继承会崩掉的例子。", "x": "", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 练习", "t": "对比基于对象与基于组件的 Tick，各写一条优点和一条代价。", "x": "", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 练习", "t": "爆炸事件机制相比硬编码好在哪里？工程上要注意什么？", "x": "", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 练习", "t": "场景里有 10 万个对象，要频繁查询“玩家周围 50 米内有哪些对象”，你会选什么空间结构？为什么？", "x": "", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L03 · 练习", "t": "在 UE 或 Unity 里，找一个你熟悉的 Actor/GameObject，列出它挂载的组件，并说明如果不用组件化、改用继承要写多少个类。", "x": "", "u": "GAMES104/104_L03.html"}, {"c": "GAMES104 L07 · 第 7 讲：游戏引擎中的渲染——后处理与渲染管线", "t": "1. 环境光遮蔽：让角落暗下来", "x": "环境光遮蔽（Ambient Occlusion, AO）用来近似环境光在物体表面被周围几何体遮挡而衰减的效果。直觉上，墙角、缝隙、物体接触处接收到的环境光更少，所以更暗。\nAO 的数学定义是可见性函数沿法线半球积分：\n\\[ A(p) = \\frac{1}{\\pi} \\int_{\\Omega} V(p", "u": "GAMES104/104_L07.html#s1"}, {"c": "GAMES104 L07 · 第 7 讲：游戏引擎中的渲染——后处理与渲染管线", "t": "2. 雾效：深度、高度与体积", "x": "雾效（Fog）在游戏中不仅营造氛围，还用来表达距离感、遮蔽远处细节（配合 LOD）。\n深度雾（Depth Fog）：根据像素到相机的距离 \\(z\\) 计算雾因子，再与雾颜色混合。常见三种曲线：\n\n线性雾：\\( f = \\frac{end - z}{end - start} \\)\n指数雾：\\( f =", "u": "GAMES104/104_L07.html#s2"}, {"c": "GAMES104 L07 · 第 7 讲：游戏引擎中的渲染——后处理与渲染管线", "t": "3. 抗锯齿：从采样不足到时间累积", "x": "走样（Aliasing）是高频信号在有限分辨率下采样不足产生的 artifacts，表现为锯齿边缘、纹理闪烁、高光闪烁。\n抗锯齿的通用策略：用某种采样模式获取更多样本，加权求和得到像素颜色。\nSSAA（超采样抗锯齿）：以更高分辨率渲染再降采样，最简单但成本高（4x 分辨率意味着 4x 像素着色）。\n", "u": "GAMES104/104_L07.html#s3"}, {"c": "GAMES104 L07 · 第 7 讲：游戏引擎中的渲染——后处理与渲染管线", "t": "4. 后处理：Bloom、色调映射与调色", "x": "后处理（Post-processing）是对最终图像应用的算法，用于风格化（调色、对比度）或真实感（色调映射、景深）。\nBloom：模拟镜头的光晕。物理基础是镜头无法完美聚焦，点光源会形成艾里斑（Airy Disk）。实现步骤：\n\n阈值提取亮部（亮度超过阈值）。\n高斯模糊（可分离卷积，先水平后垂直）", "u": "GAMES104/104_L07.html#s4"}, {"c": "GAMES104 L07 · 第 7 讲：游戏引擎中的渲染——后处理与渲染管线", "t": "5. 渲染管线：前向、延迟与 Tile-based", "x": "渲染管线（Rendering Pipeline）管理所有渲染操作的执行顺序和资源分配。\n前向渲染（Forward Rendering）：对每个物体、每个光源计算着色，累加到颜色缓冲。简单，支持透明和 MSAA，但光源多时开销大（每物体每光源）。\n延迟渲染（Deferred Rendering）：先渲", "u": "GAMES104/104_L07.html#s5"}, {"c": "GAMES104 L07 · 第 7 讲：游戏引擎中的渲染——后处理与渲染管线", "t": "6. 真实管线与显示同步", "x": "真实渲染管线面临复杂并行工作同步、大量瞬态资源（生命周期短于一帧）、资源状态管理等挑战。\nFrame Graph：用有向无环图（DAG）描述一帧内 Pass 与资源的依赖关系，自动管理资源生命周期和状态转换，优化内存和同步。\n显示同步：GPU 帧率波动会导致画面撕裂（Screen Tearing），", "u": "GAMES104/104_L07.html#s6"}, {"c": "GAMES104 L07 · 核心结论", "t": "AO 是环境光被遮挡的近似，屏幕空间方法用深度缓冲估计可见性，成本低但有局限。", "x": "", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 核心结论", "t": "雾效不仅是氛围，还能表达深度；高度雾沿视线积分，体积雾用体素近似。", "x": "", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 核心结论", "t": "抗锯齿本质是采样不足导致的高频走样；SSAA/MSAA 靠增加采样，FXAA 靠图像分析，TAA 靠时间累积。", "x": "", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 核心结论", "t": "Bloom 模拟镜头的光晕，通过阈值提取、高斯模糊、金字塔降采样再合成。", "x": "", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 核心结论", "t": "Tone Mapping 把 HDR 映射到 SDR，ACES 是电影级曲线；Color Grading 用 LUT 做风格化调色。", "x": "", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 核心结论", "t": "前向渲染每物体每光源计算，延迟渲染先写 G-Buffer 再统一着色，Tile-based 按屏幕分块剔除光源。", "x": "", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 核心结论", "t": "现代管线用 Frame Graph 管理 Pass 与资源依赖，用垂直同步/可变刷新率解决画面撕裂。", "x": "", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 术语", "t": "Ambient Occlusion / 环境光遮蔽", "x": "近似环境光被遮挡的衰减", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 术语", "t": "SSAO / 屏幕空间环境光遮蔽", "x": "用深度缓冲在屏幕空间估计 AO", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 术语", "t": "HBAO / 水平角环境光遮蔽", "x": "基于深度高度场的水平角遮挡", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 术语", "t": "GTAO / 地面真值环境光遮蔽", "x": "补上余弦因子和多次反弹的 AO", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 术语", "t": "Fog / 雾效", "x": "模拟大气散射，表达深度", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 术语", "t": "Anti-aliasing / 抗锯齿", "x": "减少采样不足导致的走样", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 术语", "t": "TAA / 时间抗锯齿", "x": "利用历史帧和运动向量累积采样", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 术语", "t": "Bloom / 泛光", "x": "模拟镜头光晕的亮部模糊效果", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 术语", "t": "Tone Mapping / 色调映射", "x": "将 HDR 颜色映射到 SDR 显示范围", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 术语", "t": "LUT / 查找表", "x": "颜色映射表，用于调色", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 术语", "t": "Deferred Rendering / 延迟渲染", "x": "先写 G-Buffer 再统一光照", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 术语", "t": "Frame Graph / 帧图", "x": "管理 Pass 与资源依赖的 DAG", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 练习", "t": "简述 SSAO 的基本原理和两个主要局限性。", "x": "", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 练习", "t": "给定线性雾参数 start=10, end=100，求距离 z=50 处的雾浓度因子 f。", "x": "", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 练习", "t": "比较 SSAA、MSAA、FXAA、TAA 四种抗锯齿方案的成本与质量。", "x": "", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 练习", "t": "简述延迟渲染的优缺点，并说明为什么它不适合透明物体。", "x": "", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L07 · 练习", "t": "在 UE 中如何实现一个简单的 Color Grading LUT 调色？描述步骤。", "x": "", "u": "GAMES104/104_L07.html"}, {"c": "GAMES104 L06 · 第 6 讲：游戏引擎中的渲染——大地形、天空与云", "t": "1. 为什么大地形不能直接用网格 + 材质堆出来", "x": "开放世界游戏（如《荒野大镖客 2》《微软模拟飞行》）的地形有巨大的地理尺度、丰富的地貌（植被、河流、起伏山峰、高山积雪），如果直接用传统的「网格 + 材质」逐三角形建模，数据量和制作成本都不可接受。\n游戏引擎的解决思路是用高度场（Heightfield）表示地形：把地形看作一个二维网格，每个格子存一", "u": "GAMES104/104_L06.html#s1"}, {"c": "GAMES104 L06 · 第 6 讲：游戏引擎中的渲染——大地形、天空与云", "t": "2. 自适应细分：让远处的三角形少、近处的三角形多", "x": "如果整个地形都用 1m 精度的网格，三角形数量会爆炸。自适应网格细分（Adaptive Mesh Tessellation） 的核心思想是：根据视点距离和屏幕误差动态调整网格密度，近处密、远处疏。\n课件给出两条优化黄金法则：\n\n视点相关误差界（View-dependent error bound）：", "u": "GAMES104/104_L06.html#s2"}, {"c": "GAMES104 L06 · 第 6 讲：游戏引擎中的渲染——大地形、天空与云", "t": "3. 地形材质：从简单泼溅到虚拟纹理", "x": "地形需要混合多种材质（草地、岩石、雪、泥土）。纹理泼溅（Texture Splatting） 用一张混合图（Splat Map）的每个通道控制一种材质的权重，在着色器里按权重混合。\n简单混合（Simple Blending）是线性插值，过渡平滑但显得不自然，因为现实中材质边界往往有高度差。改进方案：", "u": "GAMES104/104_L06.html#s3"}, {"c": "GAMES104 L06 · 第 6 讲：游戏引擎中的渲染——大地形、天空与云", "t": "4. 天空与大气：用物理散射模型渲染真实天空", "x": "天空的颜色来自大气散射。课件把大气看作参与介质（Participating Media）：充满粒子的体积，光与粒子发生吸收（Absorption）和散射（Scattering）。描述这一过程的方程是辐射传输方程（RTE）和体积渲染方程（VRE）。\n两种主要散射：\n\n瑞利散射（Rayleigh Sca", "u": "GAMES104/104_L06.html#s4"}, {"c": "GAMES104 L06 · 第 6 讲：游戏引擎中的渲染——大地形、天空与云", "t": "5. 体积云：用噪声密度场和光线步进渲染云", "x": "云的建模有三种方式：\n\n网格建模（Mesh-Based）：质量高但开销大，不支持动态天气。\n公告板（Billboard）：效率高但视觉效果有限，云类型少。\n体积云建模（Volumetric Cloud Modeling）：用 3D 密度场表示云，支持真实形状、大尺度云和动态天气，但需要仔细优化性能。", "u": "GAMES104/104_L06.html#s5"}, {"c": "GAMES104 L06 · 第 6 讲：游戏引擎中的渲染——大地形、天空与云", "t": "6. 其他地形相关技术：非高度场地形、浮点精度与道路贴花", "x": "除了高度场，课件还提到几种扩展技术：\n\n非高度场地形（Non-Heightfield Terrain）：用体素（Voxel）表示地形，通过 Marching Cubes 算法提取等值面，支持洞穴和悬垂。Marching Cubes 用查找表把每个体素立方体的 8 个顶点状态映射为三角形。Transv", "u": "GAMES104/104_L06.html#s6"}, {"c": "GAMES104 L06 · 核心结论", "t": "大地形用高度场（Heightfield）表示：一张二维高度图 + 网格，但高度场无法表达洞穴、悬崖等非单值高度结构。", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 核心结论", "t": "自适应细分是地形渲染的核心优化：根据视点距离与屏幕误差动态调整网格密度，两条黄金法则是视点相关误差界和与地面真值比较。", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 核心结论", "t": "四叉树细分易于管理和剔除，但网格灵活性差且需要处理 T-Junction；三角形细分更灵活但管理复杂。", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 核心结论", "t": "纹理泼溅用混合图（Splat Map）混合多种材质，简单混合会显得不自然，高度图混合和偏置混合能改善过渡。", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 核心结论", "t": "虚拟纹理（Virtual Texture）按需加载地形材质块，解决超大世界泼溅图显存爆炸的问题。", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 核心结论", "t": "大气散射中，瑞利散射由小分子引起、短波长散射更强（天空蓝），米氏散射由气溶胶引起、各波长均匀且前向性强（太阳光晕、雾）。", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 核心结论", "t": "预计算大气散射把透射率、单次散射、多次散射存成 LUT，但预计算成本高且难以动态调整；生产级方案通过简化多次散射和固定视点来加速。", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 核心结论", "t": "体积云用 3D 噪声密度场 + 光线步进渲染，支持动态天气，但性能开销大，需要大步进 + 密集步进的优化策略。", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 术语", "t": "Heightfield / 高度场", "x": "用二维高度图表示地形的方法，无法表达非单值高度结构。", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 术语", "t": "Adaptive Mesh Tessellation / 自适应网格细分", "x": "根据视点距离和误差动态调整网格密度。", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 术语", "t": "T-Junction / T 形接缝", "x": "不同 LOD 网格拼接时出现的裂缝，需要缝合处理。", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 术语", "t": "Texture Splatting / 纹理泼溅", "x": "用混合图权重混合多种地形材质的技术。", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 术语", "t": "Virtual Texture / 虚拟纹理", "x": "按需加载纹理瓦片，解决超大世界显存问题。", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 术语", "t": "Rayleigh Scattering / 瑞利散射", "x": "小分子引起的散射，短波长更强，天空呈蓝色。", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 术语", "t": "Mie Scattering / 米氏散射", "x": "气溶胶引起的散射，各波长均匀，前向性强。", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 术语", "t": "LUT / 查找表", "x": "预计算并存储的表格，用于加速渲染计算。", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 术语", "t": "Volumetric Cloud / 体积云", "x": "用 3D 密度场和光线步进渲染的云。", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 术语", "t": "Marching Cubes / 移动立方体", "x": "从体素密度场提取等值面三角形的算法。", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 练习", "t": "解释高度场地形为什么无法表达洞穴，并给出一种在高度场上实现洞穴的工程技巧。", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 练习", "t": "四叉树细分和三角形细分各有什么优缺点？分别适合什么场景？", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 练习", "t": "瑞利散射和米氏散射的主要区别是什么？分别解释天空为什么是蓝色、太阳为什么有光晕。", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 练习", "t": "体积云渲染中，光线步进为什么要分大步进和密集步进两步？", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L06 · 练习", "t": "在 UE 中如何实现地形材质的高度混合？简述操作步骤。", "x": "", "u": "GAMES104/104_L06.html"}, {"c": "GAMES104 L09 · 第 9 讲：来自社区的声音——动画系统进阶", "t": "1. 为什么需要动画混合：从简单动画到真实游戏", "x": "课件一开始展示了几张社区同学做的滤镜效果（卡通滤镜、暗角、径向模糊），然后切入正题：真实游戏里的动画远比“播放一个片段”复杂。\n简单动画就是播放一个 Clip；但真实游戏中，角色要走路、跑步、转弯、跳跃、鼓掌、点头……这些动作不能靠一个个独立片段硬切，否则会出现跳变、不自然。于是需要一套受控的动画混", "u": "GAMES104/104_L09.html#s1"}, {"c": "GAMES104 L09 · 第 9 讲：来自社区的声音——动画系统进阶", "t": "2. 混合权重怎么算：以走路到跑步为例", "x": "课件用“走路到跑步”的案例讲权重计算。假设走路速度 1.5 m/s，跑步速度 5.0 m/s，当前速度 \\(v\\) 在两者之间，则跑步片段的权重为：\n\\[ w_{\\text{run}} = \\frac{v - v_{\\text{walk}}}{v_{\\text{run}} - v_{\\text{wa", "u": "GAMES104/104_L09.html#s2"}, {"c": "GAMES104 L09 · 第 9 讲：来自社区的声音——动画系统进阶", "t": "3. Blend Space：把输入参数映射到多个片段", "x": "1D Blend Space：用一个输入值（如速度）在多个片段间混合。例如方向性移动中，玩家可以朝多个角度移动，可以用三个片段（左移、前移、右移）混合出任意角度。\n2D Blend Space：用两个输入值（如横向速度和纵向速度）混合。课件指出，由于横向移动速度通常低于前向，角色进入跑步状态的条件不", "u": "GAMES104/104_L09.html#s3"}, {"c": "GAMES104 L09 · 第 9 讲：来自社区的声音——动画系统进阶", "t": "4. 动作状态机：管理有状态的动画切换", "x": "Blend Space 是“同步”的混合，但跳跃这类动作是有状态的：起跳、空中、落地，每个阶段播放不同片段。这时用动作状态机（Action State Machine, ASM）。\nASM 由节点（Node）和过渡（Transition）组成。节点类型包括 Blend Space 和 Clip；过渡", "u": "GAMES104/104_L09.html#s4"}, {"c": "GAMES104 L09 · 第 9 讲：来自社区的声音——动画系统进阶", "t": "5. Blend Tree：用树形结构组织混合", "x": "当混合逻辑变复杂（多层 ASM、多个混合操作），用混合树（Blend Tree）来表达。课件用表达式树类比：\\(a + (b \\times c) + d \\times (e + f)\\) 可以表示成一棵树。\nBlend Tree 的节点分两类：\n\n终端节点（叶节点）：Clip、Blend Space", "u": "GAMES104/104_L09.html#s5"}, {"c": "GAMES104 L09 · 第 9 讲：来自社区的声音——动画系统进阶", "t": "6. IK：让脚踩到地面、手摸到目标", "x": "反向运动学（Inverse Kinematics, IK）：已知末端执行器（End-effector）的目标位置，反解关节旋转。课件用“脚如何踩到地面”引入：角色在斜坡上行走时，脚需要贴合地面，这时用 IK 调整脚的位置。\n两骨骼 IK：有解析解。给定大腿和小腿长度、目标位置，用余弦定理求出膝关节角", "u": "GAMES104/104_L09.html#s6"}, {"c": "GAMES104 L09 · 第 9 讲：来自社区的声音——动画系统进阶", "t": "7. 面部动画与动画重定向", "x": "面部动画：人脸由复杂肌肉驱动，精度要求高。FACS（Facial Action Coding System） 把面部动作分解为动作单元（Action Units, AU），表情是 AU 的组合。实现方式：\n\nMorph Target（关键姿态混合）：只存储与中性脸不同的顶点偏移（叠加混合），按权重混", "u": "GAMES104/104_L09.html#s7"}, {"c": "GAMES104 L09 · 核心结论", "t": "动画混合的本质是对多个姿态做加权平均（LERP），权重由游戏参数（速度、方向等）驱动。", "x": "", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 核心结论", "t": "Blend Space 把一维或二维的输入参数映射到多个动画片段的权重，是移动类动画的标准做法。", "x": "", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 核心结论", "t": "骨骼遮罩混合让不同身体部位播放不同动画；叠加混合把差异片段加到基础片段上，适合点头、呼吸等叠加动作。", "x": "", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 核心结论", "t": "动作状态机（ASM）用节点和过渡管理有状态的动画切换，交叉淡入淡出解决切换时的跳变。", "x": "", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 核心结论", "t": "Blend Tree 用树形结构组织混合操作，终端节点是 Clip/Blend Space/ASM，非终端节点是 LERP、Additive 等混合节点。", "x": "", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 核心结论", "t": "IK 用运动学方程反解关节旋转，使末端执行器到达目标位置；两骨骼 IK 有解析解，多关节 IK 常用 CCD、FABRIK 或 Jacobian 迭代。", "x": "", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 核心结论", "t": "面部动画可用 FACS 动作单元 + Morph Target 实现，也可用 UV 纹理或肌肉模型；重定向让动画在不同骨架间复用，但需处理偏移、朝向和脚部锁定。", "x": "", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 术语", "t": "Animation Blending / 动画混合", "x": "多个动画片段共同影响最终姿态的技术。", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 术语", "t": "LERP / 线性插值", "x": "按权重在两个值之间线性过渡。", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 术语", "t": "Blend Space / 混合空间", "x": "把输入参数映射到多个片段权重的数据结构。", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 术语", "t": "Skeleton Masked Blending / 骨骼遮罩混合", "x": "按骨骼设置混合权重，让不同部位播放不同动画。", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 术语", "t": "Additive Blending / 叠加混合", "x": "把差异片段加到基础片段上。", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 术语", "t": "Action State Machine (ASM) / 动作状态机", "x": "用节点和过渡管理有状态的动画切换。", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 术语", "t": "Cross Fade / 交叉淡入淡出", "x": "切换时源片段淡出、目标片段淡入。", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 术语", "t": "Blend Tree / 混合树", "x": "用树形结构组织混合操作。", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 术语", "t": "Inverse Kinematics (IK) / 反向运动学", "x": "已知末端目标位置反解关节旋转。", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 术语", "t": "FACS / 面部动作编码系统", "x": "把面部动作分解为动作单元的系统。", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 术语", "t": "Retargeting / 动画重定向", "x": "让动画在不同骨架间复用。", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 练习", "t": "走路速度 1.5 m/s，跑步速度 5.0 m/s，当前速度 3.0 m/s，求跑步片段的混合权重。", "x": "", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 练习", "t": "简述骨骼遮罩混合与叠加混合的区别，并各举一个使用场景。", "x": "", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 练习", "t": "动作状态机中，交叉淡入淡出有什么作用？两种常见方式是什么？", "x": "", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 练习", "t": "两骨骼 IK 在 3D 空间中为什么需要参考向量？", "x": "", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L09 · 练习", "t": "动画重定向时，为什么要用骨盆高度对齐移动并用 IK 锁定脚部？", "x": "", "u": "GAMES104/104_L09.html"}, {"c": "GAMES104 L05 · 第 5 讲：游戏引擎中的渲染——光照、材质与着色器", "t": "1. 渲染这件事：光子、材质与着色器", "x": "这一讲的开场把渲染拆成三个参与者：光照（Lighting）、材质（Material）、着色器（Shader）。\n\n光照是起点：光子从光源发出、在场景里反弹、被吸收，最后进入相机。课件原话是“光子的发射、反弹、吸收与感知是渲染中一切事物的起源”。\n材质回答“物质如何与光子反应”：金属反射强、皮肤有次表", "u": "GAMES104/104_L05.html#s1"}, {"c": "GAMES104 L05 · 第 5 讲：游戏引擎中的渲染——光照、材质与着色器", "t": "2. 渲染方程与它的三大挑战", "x": "渲染方程（简化写法）是：\n\\[ L_o(x, \\omega_o) = L_e(x, \\omega_o) + \\int_{\\Omega} f_r(x, \\omega_i, \\omega_o)\\, L_i(x, \\omega_i)\\, (n \\cdot \\omega_i)\\, d\\omega_i \\]\n", "u": "GAMES104/104_L05.html#s2"}, {"c": "GAMES104 L05 · 第 5 讲：游戏引擎中的渲染——光照、材质与着色器", "t": "3. 经典近似：简单光源 + 环境光 + 环境贴图", "x": "既然方程解不动，早期引擎的做法是“先忘掉抽象概念（辐射度、微表面、BRDF 等）”，用一套简单光源方案顶上：\n\n主光（Main Light）：多数情况用方向光（Directional Light），特殊场景用点光/聚光灯。它解决挑战 1b 的“光源复杂度”——只算一盏主光。\n环境光（Ambient ", "u": "GAMES104/104_L05.html#s3"}, {"c": "GAMES104 L05 · 第 5 讲：游戏引擎中的渲染——光照、材质与着色器", "t": "4. Blinn-Phong 材质：便宜好用的第一代方案", "x": "Blinn-Phong 是在 Phong 模型上把“反射方向与视线方向的夹角”换成“半程向量与法线的夹角”，高光项变成：\n\\[ L_{spec} = k_s \\, (n \\cdot h)^{p} \\, L_i \\, \\max(0, n \\cdot l) \\]\n其中 \\(h = \\mathrm{nor", "u": "GAMES104/104_L05.html#s4"}, {"c": "GAMES104 L05 · 第 5 讲：游戏引擎中的渲染——光照、材质与着色器", "t": "5. 阴影：从阴影贴图到级联、PCF、PCSS、VSSM", "x": "阴影的本质是“光被不透明物体挡住的空间”。课件先提了三种已过时的方法（平面阴影 planar shadow、阴影体 shadow volume、投影纹理 projective texture），然后重点讲阴影贴图（Shadow Map）：从光源视角渲染一张深度图，着色时把像素变换到光源空间比较深度，", "u": "GAMES104/104_L05.html#s5"}, {"c": "GAMES104 L05 · 第 5 讲：游戏引擎中的渲染——光照、材质与着色器", "t": "6. 预计算全局光照：Lightmap 与 Light Probe", "x": "间接光（Indirect Illumination）对画面真实感至关重要（P26 对比直接光 vs 直接+间接光）。但实时算递归积分太贵，于是工业界用预计算：离线把场景的间接光烘出来，运行时只查表。\n要表示间接光，课件提出三个要求：压缩率高（一个关卡要存上百万个辐射度探针）、易于和材质函数做积分、能", "u": "GAMES104/104_L05.html#s6"}, {"c": "GAMES104 L05 · 第 5 讲：游戏引擎中的渲染——光照、材质与着色器", "t": "7. PBR：微表面理论、BRDF 与两种工作流", "x": "PBR（Physically Based Rendering）用微表面理论（Microfacet Theory）建模材质：表面由无数微小镜面组成，BRDF 由三部分构成：\n\n法线分布函数 NDF（Normal Distribution Function）：微表面法线朝向半程向量的概率。课件对比了 B", "u": "GAMES104/104_L05.html#s7"}, {"c": "GAMES104 L05 · 第 5 讲：游戏引擎中的渲染——光照、材质与着色器", "t": "8. IBL 与着色器管理：把 PBR 跑起来", "x": "IBL（Image-Based Lighting） 用一张表示全方向远处光照的图像来照亮物体。直接解渲染方程需要蒙特卡洛大量采样，太慢。工业界的做法是 split-sum 近似：把积分拆成“光照项”和“BRDF 项”的乘积。\n\n光照项：预过滤环境贴图（pre-filtered environment", "u": "GAMES104/104_L05.html#s8"}, {"c": "GAMES104 L05 · 核心结论", "t": "渲染的本质是解渲染方程：出射辐射度 = 自发光 + 半球上入射辐射度 × BRDF × 余弦项的积分；它递归、积分昂贵、可见性复杂。", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 核心结论", "t": "游戏引擎的实时渲染不是“解方程”，而是“用工程近似把方程拆成可负担的几块”：主光+环境光、Blinn-Phong 材质、阴影贴图。", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 核心结论", "t": "Blinn-Phong 便宜、稳定、易调，但不能量守恒、难建模复杂材质，是“第一波 3A 画质”的基础，后来被 PBR 取代。", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 核心结论", "t": "阴影贴图解决可见性（挑战 1a），级联阴影解决大世界透视走样，PCF/PCSS/VSSM 解决硬边和软阴影质量。", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 核心结论", "t": "预计算 GI 用 Lightmap（静态表面）+ Light Probe（动态物体）把间接光烘进 SH 系数，运行时极便宜，但只能处理静态场景/静态光。", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 核心结论", "t": "PBR 用微表面 BRDF（NDF+几何项+菲涅尔）让材质能量守恒、参数直观，工业界主流是 Metallic-Roughness 工作流。", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 核心结论", "t": "IBL 用 split-sum 近似把环境光照拆成预过滤环境贴图（光照项）和 BRDF LUT（材质项），实现廉价的 PBR 环境反射。", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 核心结论", "t": "Uber Shader + 宏变体是引擎管理海量着色器的标准做法，代价是编译时间和包体膨胀。", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 术语", "t": "Rendering Equation / 渲染方程", "x": "描述出射辐射度等于自发光加半球入射辐射度按 BRDF 与余弦项积分。", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 术语", "t": "Radiance / Irradiance / 辐射度 / 辐照度", "x": "辐射度是某方向单位立体角单位面积功率，辐照度是入射到表面的单位面积功率。", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 术语", "t": "BRDF / 双向反射分布函数", "x": "描述材质如何把入射方向的光反射到出射方向。", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 术语", "t": "Blinn-Phong / Blinn-Phong 光照模型", "x": "用半程向量与法线夹角计算高光的经验模型，便宜但不能量守恒。", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 术语", "t": "Shadow Map / 阴影贴图", "x": "从光源视角渲染深度图，着色时比较深度判断遮挡。", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 术语", "t": "Cascade Shadow / 级联阴影", "x": "把视锥体分段、每段一张阴影贴图，解决大世界透视走样。", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 术语", "t": "PCF / PCSS / VSSM / 百分比渐近过滤 / 软阴影 / 方差软阴影", "x": "阴影贴图抗锯齿与软阴影的三种递进技术。", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 术语", "t": "Spherical Harmonics (SH) / 球谐函数", "x": "定义在球面上的函数系，用低阶系数压缩低频辐照度。", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 术语", "t": "Lightmap / Light Probe / 光照贴图 / 光照探针", "x": "预计算 GI 的两种落地方式：表面 texel 与空间点。", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 术语", "t": "Microfacet / NDF / G / F / 微表面理论 / 法线分布 / 几何项 / 菲涅尔", "x": "PBR BRDF 的三要素。", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 术语", "t": "IBL / Split Sum / 基于图像的光照 / 拆分求和近似", "x": "把环境光积分拆成预过滤贴图与 BRDF LUT 两项。", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 术语", "t": "Uber Shader / Variant / 超级着色器 / 变体", "x": "用一个超大着色器加宏编译出大量变体来管理海量材质。", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 练习", "t": "用自己的话解释渲染方程的三大挑战，并各举一个本讲提到的工程应对方案。", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 练习", "t": "写出 Blinn-Phong 的高光项，并说明为什么它“不能量守恒”。", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 练习", "t": "级联阴影解决什么问题？它又带来什么新问题，怎么缓解？", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 练习", "t": "Lightmap 和 Light Probe 分别适合什么对象？各写一条优点和一条缺点。", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L05 · 练习", "t": "IBL 的 split-sum 近似把积分拆成哪两项？各自预计算成什么？", "x": "", "u": "GAMES104/104_L05.html"}, {"c": "GAMES104 L10 · 第 10 讲：物理系统——从刚体到碰撞检测与求解", "t": "物理系统在游戏里到底解决什么问题", "x": "物理系统是游戏引擎中最“反直觉”的模块之一：它模拟的是现实世界的规律，但目标却不是物理精确，而是看起来对、跑得快、可控。课件开篇用四张图概括了物理在游戏中的四类用途：\n\n物理直觉（Physical Intuition）：让玩家凭生活经验就能预测物体行为，比如箱子被推会滑动、球会弹跳。\n动态环境（Dy", "u": "GAMES104/104_L10.html#s1"}, {"c": "GAMES104 L10 · 第 10 讲：物理系统——从刚体到碰撞检测与求解", "t": "物理世界与视觉世界：Actor 与形状", "x": "游戏里你看到的模型（视觉世界）和物理引擎计算的对象（物理世界）是两套数据。物理世界只关心简化后的碰撞形状和运动状态，渲染世界关心顶点、材质、骨骼。两者通过同步机制关联：物理算完位置后，把变换写回渲染对象。\n物理世界的基本单位叫 Actor（物理 actor），每个 Actor 至少包含：\n\n一个或多", "u": "GAMES104/104_L10.html#s2"}, {"c": "GAMES104 L10 · 第 10 讲：物理系统——从刚体到碰撞检测与求解", "t": "形状属性：质量、质心、摩擦与弹性", "x": "形状不只是几何，还带物理属性。课件重点讲了四个：\n\n质量与密度（Mass and Density）：质量通常由密度乘以体积得到。密度让不同材质的物体有不同“手感”，比如木头和铁。\n质心（Center of Mass）：质量分布的中心。质心位置决定物体如何倾倒。课件用 Gomboc 形状举例：质心低且", "u": "GAMES104/104_L10.html#s3"}, {"c": "GAMES104 L10 · 第 10 讲：物理系统——从刚体到碰撞检测与求解", "t": "力、冲量与运动积分：为什么半隐式欧拉是默认", "x": "物理引擎每帧要做的事可以概括为：根据受力更新速度，再根据速度更新位置。课件先讲牛顿定律：\n\n第一定律：没有外力时速度不变，\\( v_{t+\\Delta t} = v_t \\)，\\( x_{t+\\Delta t} = x_t + v_t \\Delta t \\)。\n第二定律：\\( F = m a \\)，", "u": "GAMES104/104_L10.html#s4"}, {"c": "GAMES104 L10 · 第 10 讲：物理系统——从刚体到碰撞检测与求解", "t": "刚体转动：角速度、转动惯量与力矩", "x": "刚体除了平动还有转动。课件用一组对应关系把线性量和角量并列：\n\n\n\n线性量\n角量\n\n\n\n\n位置 \\( x \\)\n朝向 \\( R \\)（矩阵或四元数）\n\n\n线速度 \\( v = \\dot{x} \\)\n角速度 \\( \\omega \\)\n\n\n线加速度 \\( a \\)\n角加速度 \\( \\alpha = \\d", "u": "GAMES104/104_L10.html#s5"}, {"c": "GAMES104 L10 · 第 10 讲：物理系统——从刚体到碰撞检测与求解", "t": "碰撞检测：Broad Phase 与 Narrow Phase", "x": "碰撞检测分两个阶段，这是所有物理引擎的标准架构：\nBroad Phase（粗筛）：快速找出可能重叠的物体对。它用 AABB（轴对齐包围盒）做粗略判断，目标是“不漏掉，但可以多报”。常见算法：\n\nBVH 树（Bounding Volume Hierarchy）：把场景组织成树，动态更新。课件提到动态 ", "u": "GAMES104/104_L10.html#s6"}, {"c": "GAMES104 L10 · 第 10 讲：物理系统——从刚体到碰撞检测与求解", "t": "碰撞求解与场景查询：让物体分开并回答“打中了没”", "x": "检测到碰撞后，要求解，让物体不再穿透。课件列出三种思路：\n\n罚力（Penalty Force）：按穿透深度施加一个弹簧力把物体推开。简单但需要很大的力和很小的步长，游戏里很少用。\n速度约束（Velocity Constraints）：在速度层面施加冲量，消除沿法线方向的相对速度。主流方法是顺序冲量法", "u": "GAMES104/104_L10.html#s7"}, {"c": "GAMES104 L10 · 第 10 讲：物理系统——从刚体到碰撞检测与求解", "t": "工程优化：休眠、岛、连续碰撞与确定性", "x": "物理系统很贵，工程上必须优化。课件讲了几个关键手段：\n\n岛（Island）：把相互接触的物体分成一组，组与组之间独立求解，便于并行。\n休眠（Sleeping）：长时间不动的物体停止模拟，节省 CPU。被其他物体撞到或受力时唤醒。\n连续碰撞检测（CCD）：快速物体可能在一帧内穿过薄墙，这叫隧穿（Tun", "u": "GAMES104/104_L10.html#s8"}, {"c": "GAMES104 L10 · 核心结论", "t": "物理世界是视觉世界的简化近似，用简单形状包裹复杂模型，追求实时而非绝对精确。", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 核心结论", "t": "Actor 分为静态、动态、运动学、触发器四类：动态受力和冲量影响，运动学由动画或脚本驱动但能推动动态物体，触发器只检测不阻挡。", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 核心结论", "t": "形状选择要兼顾简单与贴合：球、胶囊、盒最常用，凸包用于复杂刚体，三角网格只能用于静态物体，高度场用于地形。", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 核心结论", "t": "显式欧拉会发散，隐式欧拉会螺旋衰减，半隐式欧拉（先更新速度再更新位置）在游戏中最常用且稳定。", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 核心结论", "t": "刚体转动需要角速度、转动惯量、角动量、力矩，转动惯量描述质量分布，力矩等于位置叉乘力。", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 核心结论", "t": "碰撞检测分两阶段：Broad Phase 用 AABB 快速筛出可能重叠的物体对，Narrow Phase 用 GJK/SAT 等精确计算接触点和法线。", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 核心结论", "t": "碰撞求解主流是速度约束加顺序冲量法，通过迭代施加冲量消除穿透方向的速度。", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 核心结论", "t": "工程上还要处理休眠、岛、连续碰撞检测（TOI）和确定性模拟，以兼顾性能与正确性。", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 术语", "t": "Actor / 物理 actor", "x": "物理世界中的基本对象，包含形状、质量和运动状态。", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 术语", "t": "Kinematic / 运动学", "x": "不受物理规律驱动、由脚本或动画设置位置的 actor。", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 术语", "t": "Trigger / 触发器", "x": "不阻挡但能检测进入/离开的碰撞体。", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 术语", "t": "Semi-implicit Euler / 半隐式欧拉", "x": "先更新速度再更新位置的积分方法，游戏物理常用。", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 术语", "t": "Moment of Inertia / 转动惯量", "x": "描述质量分布对旋转难易程度的量。", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 术语", "t": "Broad Phase / 粗筛阶段", "x": "用 AABB 快速找出可能碰撞的物体对。", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 术语", "t": "Narrow Phase / 精筛阶段", "x": "精确计算接触点、法线和穿透深度。", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 术语", "t": "GJK / GJK 算法", "x": "基于 Minkowski 差判断凸形状是否相交的迭代算法。", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 术语", "t": "SAT / 分离轴定理", "x": "若存在一个轴能分开两个凸形状，则它们不相交。", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 术语", "t": "CCD / 连续碰撞检测", "x": "防止快速物体隧穿的检测方式。", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 练习", "t": "显式欧拉、隐式欧拉、半隐式欧拉在模拟圆周运动时分别有什么表现？为什么游戏物理默认用半隐式欧拉？", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 练习", "t": "一个质量为 2kg 的球以 3m/s 撞墙，弹性系数为 0.5，求碰撞后法线方向速度大小。", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 练习", "t": "为什么动态 Actor 不能使用三角网格作为碰撞形状？应该用什么替代？", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 练习", "t": "简述 Broad Phase 和 Narrow Phase 的分工，并各举一个算法。", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L10 · 练习", "t": "在 UE 中如何防止快速子弹穿透薄墙？请说出至少两种方法。", "x": "", "u": "GAMES104/104_L10.html"}, {"c": "GAMES104 L08 · 第 8 讲：动画系统——从 2D 精灵到蒙皮骨骼与压缩", "t": "1. 游戏动画到底难在哪：四个绕不开的约束", "x": "在动手写骨骼插值之前，先要明白游戏动画和影视动画的根本区别。课件把挑战归纳为四类：\n交互与动态（Interactive and dynamic）：影视动画是线性播放，游戏动画要根据玩家输入、物理状态、AI 决策实时变化。同一个角色可能上一帧在跑、下一帧被击中倒地，动画系统必须能立刻响应并平滑过渡。\n", "u": "GAMES104/104_L08.html#s1"}, {"c": "GAMES104 L08 · 第 8 讲：动画系统——从 2D 精灵到蒙皮骨骼与压缩", "t": "2. 2D 动画：精灵图与 Live2D 的分层变形", "x": "2D 动画是理解动画系统最好的入口，因为它把「帧」和「插值」的概念暴露得最直接。\n精灵动画（Sprite Animation）是赛璐珞动画的电子等价物：一张小位图（sprite）按时间序列切换，就形成动画。课件提到多视角精灵（multi-view sprite），即同一个动作从不同角度各画一套，玩家", "u": "GAMES104/104_L08.html#s2"}, {"c": "GAMES104 L08 · 第 8 讲：动画系统——从 2D 精灵到蒙皮骨骼与压缩", "t": "3. 3D 动画的五种做法：从刚体层级到蒙皮骨骼", "x": "进入 3D 后，课件用「自由度（DoF, Degrees of Freedom）」这个统一视角来分类。自由度就是一个系统独立变量的个数。\n刚体层级动画（Rigid Hierarchical Animation）：角色由多个刚体部件组成，部件之间有父子关系，动画就是给每个关节设变换。这是最早的 3D ", "u": "GAMES104/104_L08.html#s3"}, {"c": "GAMES104 L08 · 第 8 讲：动画系统——从 2D 精灵到蒙皮骨骼与压缩", "t": "4. 骨骼、关节与绑定姿势：蒙皮动画的数据基础", "x": "要理解蒙皮，先把几个名词钉死。\n关节（Joint）与骨骼（Bone）：课件特意区分——关节是动画师直接操作的对象，骨骼是关节之间的连接可视化。很多引擎里两者一一对应，术语混用，但概念上关节才是变换的载体。\n骨架（Skeleton）是一棵关节的层级树，每个关节存相对于父关节的局部变换。人类骨骼通常 5", "u": "GAMES104/104_L08.html#s4"}, {"c": "GAMES104 L08 · 第 8 讲：动画系统——从 2D 精灵到蒙皮骨骼与压缩", "t": "5. 旋转的数学：欧拉角为什么不够用，四元数怎么救场", "x": "骨骼姿势里最麻烦的是旋转。课件花了大篇幅讲旋转数学，因为这是插值和压缩的基础。\n欧拉角（Euler Angle）用绕 x、y、z 三个轴的旋转角描述朝向，直观、省空间，编辑器里到处都是。但它有两个致命问题：\n\n顺序依赖（Order Dependence）：先绕 x 再绕 y，和先绕 y 再绕 x，结", "u": "GAMES104/104_L08.html#s5"}, {"c": "GAMES104 L08 · 第 8 讲：动画系统——从 2D 精灵到蒙皮骨骼与压缩", "t": "6. 蒙皮矩阵：把顶点从绑定姿势搬到当前姿势", "x": "这是整讲最核心的公式。先给直觉：蒙皮就是「每个顶点跟着几个关节走，按权重混合」。\n设网格顶点 \\( V \\) 在绑定姿势下绑定到关节 \\( j \\)。绑定姿势下关节 \\( j \\) 在模型空间的变换记为 \\( B_j \\)（bind pose matrix）。当前时刻 \\( t \\) 关节 \\( j", "u": "GAMES104/104_L08.html#s6"}, {"c": "GAMES104 L08 · 第 8 讲：动画系统——从 2D 精灵到蒙皮骨骼与压缩", "t": "7. 姿势插值与运行时管线：从 Clip 到屏幕", "x": "动画片段（Clip）本质上是一串骨骼姿势（skeleton poses）的序列，每个姿势在时间轴上是一个关键帧。运行时要在关键帧之间插值。\n平移和缩放用线性插值（LERP）：\\( P = (1-t)P_0 + tP_1 \\)。简单、够用。\n旋转不能用 LERP，要用四元数插值。课件给了两个方案：\n\n", "u": "GAMES104/104_L08.html#s7"}, {"c": "GAMES104 L08 · 第 8 讲：动画系统——从 2D 精灵到蒙皮骨骼与压缩", "t": "8. 动画压缩：在视觉误差内把数据砍到十分之一", "x": "原始动画数据大到不可接受：课件估算单片段大小 = 帧数 × 关节数 × 每关节数据量，再乘以角色数和片段数，轻松上 GB。压缩分四步走。\n第一步：DoF 裁剪（DoF Reduction）。人形骨骼的缩放通常不变，直接丢掉 scale 轨道；平移只有骨盆和面部关节需要，其余丢掉；旋转保留。这一步能砍", "u": "GAMES104/104_L08.html#s8"}, {"c": "GAMES104 L08 · 核心结论", "t": "游戏动画的核心矛盾是「交互实时」与「数据量/真实感」之间的权衡，所有技术选择都围绕这个矛盾展开。", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 核心结论", "t": "2D 精灵动画是赛璐珞动画的电子化，Live2D 用分层网格变形在 2D 上模拟 3D 感，成本低但视角受限。", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 核心结论", "t": "3D 动画按自由度划分：刚体层级动画控制关节变换，顶点动画自由度最高但数据量最大，蒙皮骨骼动画是工业标准折中。", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 核心结论", "t": "蒙皮矩阵 = 当前姿势矩阵 × 逆绑定矩阵，把顶点从绑定空间变换到当前姿势空间，再用权重混合多个关节的影响。", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 核心结论", "t": "欧拉角有万向节死锁和顺序依赖，四元数用四个数表示旋转，插值更稳定，是骨骼旋转的标准表示。", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 核心结论", "t": "NLERP 快但角速度不均匀，SLERP 角速度均匀但计算贵；小角度下两者几乎等价，实际引擎常按角度阈值切换。", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 核心结论", "t": "动画压缩的本质是「在可接受的视觉误差内删数据」：裁掉不变的 DoF、抽关键帧、量化浮点、再用误差补偿兜底。", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 核心结论", "t": "误差会沿骨骼层级传播，所以压缩精度要按关节敏感度自适应分配，而不是一刀切。", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 术语", "t": "DoF (Degrees of Freedom) / 自由度", "x": "系统独立变量的个数，用来衡量动画技术的灵活度与数据量。", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 术语", "t": "Bind Pose / 绑定姿势", "x": "网格绑定到骨骼时的初始姿势，常见 T-pose 或 A-pose。", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 术语", "t": "Inverse Bind Pose Matrix / 逆绑定矩阵", "x": "把顶点从模型空间拉回关节局部空间的矩阵，绑定时刻预计算。", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 术语", "t": "Skinning Matrix / 蒙皮矩阵", "x": "当前姿势矩阵乘以逆绑定矩阵，把顶点从绑定姿势搬到当前姿势。", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 术语", "t": "Skinning Matrix Palette / 蒙皮矩阵调色板", "x": "所有关节蒙皮矩阵打包成的数组，传给 GPU 顶点着色器。", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 术语", "t": "Euler Angle / 欧拉角", "x": "用绕三个轴的旋转角描述朝向，直观但有顺序依赖和万向节死锁。", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 术语", "t": "Gimbal Lock / 万向节死锁", "x": "中间轴到 90 度时两轴重合，丢失一个自由度。", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 术语", "t": "Quaternion / 四元数", "x": "四个数表示旋转，无死锁、插值平滑，骨骼旋转的标准表示。", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 术语", "t": "NLERP / SLERP / 归一化线性插值 / 球面线性插值", "x": "四元数插值的两种方案，前者快但角速度不均，后者均匀但贵。", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 术语", "t": "Morph Target / 变形目标", "x": "预存若干关键形状，运行时线性混合，常用于面部表情。", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 练习", "t": "一个顶点 V 绑定到关节 j，绑定姿势下关节 j 的模型空间矩阵为 B_j，当前时刻为 P_j(t)。写出该顶点的蒙皮矩阵，并解释为什么需要逆矩阵。", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 练习", "t": "为什么骨骼旋转插值要用四元数而不是欧拉角？请至少说出两个原因。", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 练习", "t": "NLERP 和 SLERP 有什么区别？在什么情况下可以放心用 NLERP？", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 练习", "t": "一个动画片段有 60 帧、80 个关节，每个关节每帧存旋转（四元数 4 个 float）、平移（3 个 float）、缩放（3 个 float），每个 floa", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L08 · 练习", "t": "在 UE 或 Unity 里找一个带骨骼的角色，查看它的骨骼数量和每个顶点的最大骨骼影响数，并说明如果骨骼数超过 Shader 常量缓冲区上限会发生什么。", "x": "", "u": "GAMES104/104_L08.html"}, {"c": "GAMES104 L12 · 第 12 讲：粒子系统与音频系统", "t": "1. 粒子系统是什么：从雪花到刀光", "x": "粒子系统（Particle System）是游戏里制造「模糊、大量、动态」视觉效果的主力工具。课件引用了 William Reeves 的定义：粒子系统是大量微小粒子的集合，这些粒子共同表现一个模糊物体；粒子随着时间被生成、在系统内移动和变化、最终消亡。\n三层结构：\n\n粒子（Particle）：通常", "u": "GAMES104/104_L12.html#s1"}, {"c": "GAMES104 L12 · 第 12 讲：粒子系统与音频系统", "t": "2. 粒子怎么动：模拟与常见属性", "x": "粒子模拟（Simulate）控制粒子随时间如何变化。最核心的更新规则是每帧执行：\n\\[\n\\vec{v}_{t+1} = \\vec{v}_t + \\vec{a} \\, \\Delta t\n\\]\n\\[\n\\vec{p}_{t+1} = \\vec{p}_t + \\vec{v}_{t+1} \\, \\Delta ", "u": "GAMES104/104_L12.html#s2"}, {"c": "GAMES104 L12 · 第 12 讲：粒子系统与音频系统", "t": "3. 粒子长什么样：Billboard、Mesh 与 Ribbon", "x": "粒子最终要渲染出来，课件介绍了三种粒子类型：\n\nBillboard 粒子：每个粒子是一个 sprite（二维贴图），但它看起来像 3D 的，因为它始终面向相机（always face the camera）。这是最常用、最省性能的类型，适合火焰、烟雾、光晕。\nMesh 粒子：每个粒子是一个 3D 模", "u": "GAMES104/104_L12.html#s3"}, {"c": "GAMES104 L12 · 第 12 讲：粒子系统与音频系统", "t": "4. 半透明粒子的排序与低分辨率渲染", "x": "粒子通常是半透明的，渲染时需要 Alpha 混合：\n\\[\nC_{\\text{result}} = C_{\\text{src}} \\cdot \\alpha_{\\text{src}} + C_{\\text{dst}} \\cdot (1 - \\alpha_{\\text{src}})\n\\]\n混合顺序至关重要", "u": "GAMES104/104_L12.html#s4"}, {"c": "GAMES104 L12 · 第 12 讲：粒子系统与音频系统", "t": "5. GPU 粒子：把模拟搬到显卡上", "x": "当粒子数量达到数万甚至百万级时，CPU 逐粒子更新会成为瓶颈。GPU 粒子利用计算着色器（Compute Shader）的高度并行性来模拟粒子。\n为什么用 GPU：\n\n粒子模拟是高度并行的任务，适合大量粒子同时计算。\n解放 CPU 去处理游戏逻辑。\n容易访问深度缓冲来做碰撞。\n\n帧流程（课件以「粒子", "u": "GAMES104/104_L12.html#s5"}, {"c": "GAMES104 L12 · 第 12 讲：粒子系统与音频系统", "t": "6. 声音的物理与数字基础", "x": "声音在游戏中承担娱乐、增强真实感、营造氛围三大作用。课件用「有声音/无声音」的对比图说明声音对体验的巨大影响。\n物理量：\n\n声压（Sound Pressure）：声波引起的局部大气压偏离，单位帕斯卡（Pa）。\n质点速度（Particle Velocity）：介质中粒子传递波时的速度，单位 m/s。\n", "u": "GAMES104/104_L12.html#s6"}, {"c": "GAMES104 L12 · 第 12 讲：粒子系统与音频系统", "t": "7. 3D 音频：空间化、衰减与遮挡", "x": "3D 音频让声音从场景中的特定位置发出，并随听者位置变化。\n声源（3D Sound Source）：一个单声道音频信号，从特定位置发出。\n听者（Listener）：虚拟麦克风，拥有位置、速度、朝向。\n空间化（Spatialization）：把声音相对听者定向的技术，包括：\n\n声像平移（Panning", "u": "GAMES104/104_L12.html#s7"}, {"c": "GAMES104 L12 · 核心结论", "t": "粒子系统由粒子、发射器、系统三层组成：发射器定义生成规则、模拟逻辑和渲染方式，系统是多个发射器的集合。", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 核心结论", "t": "粒子模拟的核心是每帧用加速度更新速度、用速度更新位置；重力、颜色、大小、旋转、碰撞等都是在此框架上叠加的模块。", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 核心结论", "t": "Billboard 粒子始终面向相机，Mesh 粒子是 3D 模型，Ribbon 粒子把相邻粒子连成条带，常用于刀光、拖尾。", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 核心结论", "t": "半透明粒子必须按到相机的距离排序才能正确混合；排序粒度从粗到细分为系统间、发射器间、粒子间，全局排序最准确但开销大。", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 核心结论", "t": "低分辨率粒子渲染先把粒子画到半分辨率缓冲，再用双边升采样合成到全分辨率场景，可大幅降低填充率开销。", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 核心结论", "t": "GPU 粒子用计算着色器并行模拟，核心是粒子池 + 死/活列表 + 原子操作，每帧执行生成、模拟、剔除、排序、渲染、交换列表。", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 核心结论", "t": "3D 音频需要声源（单声道信号 + 位置）和听者（虚拟麦克风：位置、速度、朝向），通过声像平移、衰减、遮挡、混响等营造空间感。", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 核心结论", "t": "等功率声像平移保持左右声道功率恒定（用正弦/余弦曲线），比线性平移听感更自然；距离衰减近似球面波声压随距离反比下降。", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 术语", "t": "Particle System / 粒子系统", "x": "大量微小粒子的集合，用于表现模糊、动态的视觉效果。", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 术语", "t": "Emitter / 发射器", "x": "定义粒子的生成规则、模拟逻辑和渲染方式。", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 术语", "t": "Billboard / 公告板", "x": "始终面向相机的二维 sprite，常用于火焰、烟雾。", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 术语", "t": "Ribbon Particle / 条带粒子", "x": "把相邻粒子连接成条带，用于刀光、拖尾。", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 术语", "t": "Alpha Blending / Alpha 混合", "x": "按透明度混合源颜色与目标颜色，需要正确排序。", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 术语", "t": "Compute Shader / 计算着色器", "x": "GPU 上的通用并行计算程序，用于 GPU 粒子模拟。", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 术语", "t": "PCM / 脉冲编码调制", "x": "数字音频的标准编码方式：采样、量化、编码。", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 术语", "t": "Nyquist-Shannon Theorem / 奈奎斯特-香农采样定理", "x": "采样频率至少为信号最高频率的两倍才能无失真恢复。", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 术语", "t": "Spatialization / 空间化", "x": "把声音相对听者定向的技术，包括声像平移、声场、双耳音频。", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 术语", "t": "Doppler Effect / 多普勒效应", "x": "波源与观察者相对运动导致频率变化的现象。", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 练习", "t": "粒子系统由哪三层组成？发射器的三大职责是什么？", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 练习", "t": "为什么半透明粒子需要排序？全局排序与层级排序各有什么优缺点？", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 练习", "t": "写出等功率声像平移的左右增益公式（设声像位置 x∈[0,1]），并说明为什么它比线性平移好。", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 练习", "t": "简述 GPU 粒子的帧流程（从初始化到交换列表）。", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L12 · 练习", "t": "在 UE 或 Unity 中实现一个「火焰 + 烟雾」的粒子效果，你会如何组织发射器和渲染类型？", "x": "", "u": "GAMES104/104_L12.html"}, {"c": "GAMES104 L14 · 第 14 讲：工具链（Tool Chains）——从世界编辑器到协同编辑", "t": "1. 游戏生产现场与工具链的定位", "x": "游戏生产不是一个人写代码，而是一群思维模式完全不同的人围着同一堆数据干活：美术从 DCC（Maya、Blender、ZBrush）导出模型和贴图，策划在表格和编辑器里摆关卡、调数值，程序写系统逻辑。工具链（Tool Chains）就是把这些人和数据粘起来的整套软件基础设施。\n这一讲要解决的核心矛盾有", "u": "GAMES104/104_L14.html#s1"}, {"c": "GAMES104 L14 · 第 14 讲：工具链（Tool Chains）——从世界编辑器到协同编辑", "t": "2. 世界编辑器：一个特殊模式下的游戏引擎", "x": "世界编辑器的视口（Viewport）不是“画出来的预览图”，而是由完整游戏引擎在编辑器模式下实时渲染的结果。这意味着你在编辑器里看到的光照、材质、后处理，和运行时是同一套代码路径——这正是 WYSIWYG 的技术保证。\n但编辑器模式需要很多运行时不需要的东西：Gizmo（移动/旋转/缩放手柄）、网格", "u": "GAMES104/104_L14.html#s2"}, {"c": "GAMES104 L14 · 第 14 讲：工具链（Tool Chains）——从世界编辑器到协同编辑", "t": "3. 编辑操作的基础设施：鼠标拾取、变换与地形环境", "x": "编辑器里最高频的操作是“选中一个东西”。鼠标拾取（Mouse Picking）有两条经典路线：\nRTT（Render to Texture）：把每个对象用唯一颜色（ID）渲染到一张离屏纹理，鼠标位置读回该像素颜色，反查对象。\n\n优点：实现简单，天然支持“框选/范围查询”，能处理遮挡（只取最前面的像素", "u": "GAMES104/104_L14.html#s3"}, {"c": "GAMES104 L14 · 第 14 讲：工具链（Tool Chains）——从世界编辑器到协同编辑", "t": "4. 插件架构：系统与对象类型的自由组合", "x": "商业软件几乎都支持插件：Chrome 扩展、Qt Creator 插件、UE 的 Editor Plugin。课件的关键洞察是：任何系统（System）与任何对象类型（Object Type）的交叉点都可以做成插件——比如“地形系统 × 笔刷工具”“动画系统 × 序列编辑器”。\n多个插件同时作用于同", "u": "GAMES104/104_L14.html#s4"}, {"c": "GAMES104 L14 · 第 14 讲：工具链（Tool Chains）——从世界编辑器到协同编辑", "t": "5. 叙事工具与反射：Sequencer 为什么能绑定任何属性", "x": "游戏里的叙事（Storytelling）在引擎中表现为时间轴上的参数变化：在某个时间点播放声音、播放特效、播放动画、调整灯光……把这些能力做成可视化工具，就是 Sequencer（UE）/ Timeline（Unity）。\nSequencer 的几个核心概念：\n\nTrack（轨道）：引用场景中的 A", "u": "GAMES104/104_L14.html#s5"}, {"c": "GAMES104 L14 · 第 14 讲：工具链（Tool Chains）——从世界编辑器到协同编辑", "t": "6. 协同编辑：把冲突关进笼子", "x": "大项目里，很多人同时改很多资产，版本管理极其困难。合并冲突（Merging Conflicts）是最大的问题：每次更新或上传资产都要花大量时间解冲突。\n减少冲突的第一类手段是把资产拆小：\n\n分层（Layering the World）：世界拆成多个层，每层存一个资产文件，不同人改不同层。优点：合理分", "u": "GAMES104/104_L14.html#s6"}, {"c": "GAMES104 L14 · 核心结论", "t": "世界编辑器是“编辑器模式”下的完整游戏引擎，视口就是引擎渲染结果；编辑器专用代码必须与运行时隔离。", "x": "", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 核心结论", "t": "编辑器里一切皆可编辑对象，属性编辑由 Schema 驱动，内容浏览器管理资产缩略图与共享。", "x": "", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 核心结论", "t": "鼠标拾取两条路：RTT（把对象 ID 渲染到离屏纹理再读回）简单但多画一帧；射线检测（Ray Casting）快但需要空间查询结构。", "x": "", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 核心结论", "t": "地形用高度图+纹理图+植被实例/分布图描述；环境编辑靠规则系统解耦各子系统，样条用于道路/河流等线性要素。", "x": "", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 核心结论", "t": "插件架构让系统与对象类型自由组合，组合方式有覆盖、分布式、管线与洋葱圈四种。", "x": "", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 核心结论", "t": "反射把代码元信息变成可查询的映射表，是 Sequencer 绑定属性轨道和可视化脚本的基础；C++ 反射靠 Clang AST + 宏标记 + 代码生成实现。", "x": "", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 核心结论", "t": "协同编辑的核心是减少冲突：分层、分块、OFPA 把资产拆小；实例锁/资产锁避免同时修改；OT/CRDT 解决分布式操作合并与撤销重做。", "x": "", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 术语", "t": "Tool Chains / 工具链", "x": "把 DCC、编辑器、资产管线、版本控制串起来的整套生产基础设施。", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 术语", "t": "WYSIWYG / 所见即所得", "x": "编辑时看到的效果与运行时一致，是高质量生产的硬要求。", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 术语", "t": "Schema-Driven / 模式驱动", "x": "由类型声明决定属性面板显示哪些字段，面板自动生成。", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 术语", "t": "RTT (Render to Texture) / 渲染到纹理", "x": "把对象 ID 渲染到离屏纹理再读回，用于鼠标拾取。", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 术语", "t": "Ray Casting / 射线检测", "x": "从相机经鼠标发射线与场景求交，快速拾取对象。", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 术语", "t": "Reflection / 反射", "x": "程序在运行时检查、内省、修改自身结构的能力。", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 术语", "t": "AST (Abstract Syntax Tree) / 抽象语法树", "x": "源代码语法结构的树形抽象表示，反射工具从它提取类型信息。", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 术语", "t": "OFPA (One File Per Actor) / 每个 Actor 一个文件", "x": "UE5 的资产拆分方式，把 Actor 实例数据存到外部文件以减少冲突。", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 术语", "t": "OT (Operation Transform) / 操作变换", "x": "把操作抽象成原子操作序列并变换合并，解决协同编辑冲突。", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 术语", "t": "CRDT / 无冲突复制数据类型", "x": "可并发更新并自动合并的数据结构。", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 练习", "t": "世界编辑器为什么被称为“特殊版本的游戏引擎”？编辑器专用代码如果不隔离会有什么后果？", "x": "", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 练习", "t": "比较鼠标拾取的 RTT 与 Ray Casting 两种方案：各自适合什么场景？为什么 RTT 难以选中被遮挡的对象？", "x": "", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 练习", "t": "Sequencer 如何做到把任意 Actor 的任意属性绑定到属性轨道？请从反射的角度解释，并说明 C++ 反射的基本实现步骤。", "x": "", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 练习", "t": "一个大团队要协同编辑同一个开放世界，你会如何组合使用分层、分块、OFPA 与锁来减少冲突？请说明每种手段解决什么问题、有什么代价。", "x": "", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L14 · 练习", "t": "为什么说“锁不是万能的”？三人协同编辑时，用户 2 按撤销，期望发生什么？OT/CRDT 如何从根本上解决这类问题？", "x": "", "u": "GAMES104/104_L14.html"}, {"c": "GAMES104 L11 · 第 11 讲：物理系统的应用——角色、布娃娃、布料、破坏与载具", "t": "1. 角色控制器：为什么不能直接用刚体", "x": "角色控制器（Character Controller）是玩家在游戏里最常接触的物理对象，但它恰恰不是一个普通的刚体。课件先对比了两者：\n\n刚体动力学：完全受物理规则支配，有惯性、有弹性、会被撞飞。\n角色控制器：需要“可控的刚体交互”——几乎无限摩擦、没有弹性、能瞬间加速/刹车/转向，甚至能瞬移。\n\n", "u": "GAMES104/104_L11.html#s1"}, {"c": "GAMES104 L11 · 第 11 讲：物理系统的应用——角色、布娃娃、布料、破坏与载具", "t": "2. 角色控制器的细节：台阶、坡度、体积变化与推动物体", "x": "角色控制器要处理的不只是“往前走”，还有一堆边界情况：\n\n自动台阶（Auto Stepping）：遇到矮台阶时，用“台阶偏移”做一次扫掠，把角色抬上去。但课件指出它有个问题——会留下虚拟间隙（Virtual Gap），角色看起来像浮在台阶上一点点。\n坡度限制（Slope Limits）：设置最大可攀", "u": "GAMES104/104_L11.html#s2"}, {"c": "GAMES104 L11 · 第 11 讲：物理系统的应用——角色、布娃娃、布料、破坏与载具", "t": "3. 布娃娃：把骨骼绑到刚体上", "x": "布娃娃（Ragdoll）用来表现角色死亡、被击飞等“失去控制”的状态。为什么需要它？课件给了两个场景：倒在地上、倒在悬崖边——纯动画很难表现这种和环境交互的随机姿势，而物理可以。\n实现思路是把骨骼映射到刚体：给关键关节（头、胸、骨盆、四肢）各绑一个刚体，刚体之间用关节约束（Joint Constra", "u": "GAMES104/104_L11.html#s3"}, {"c": "GAMES104 L11 · 第 11 讲：物理系统的应用——角色、布娃娃、布料、破坏与载具", "t": "4. 动画与布娃娃的混合", "x": "布娃娃不能一直“软”着，否则角色永远爬不起来。课件给出两种状态：\n\n运动学状态（Kinematic State）：刚体由动画驱动，物理不参与。\n动态状态（Dynamic State）：刚体由物理模拟驱动。\n\n角色死亡时从运动学切到动态，复活时再切回来。更高级的做法是物理-动画混合（Physics-A", "u": "GAMES104/104_L11.html#s4"}, {"c": "GAMES104 L11 · 第 11 讲：物理系统的应用——角色、布娃娃、布料、破坏与载具", "t": "5. 布料模拟：从动画到质点弹簧", "x": "布料（Cloth）在游戏里很常见：旗帜、披风、裙摆。课件给出三种实现路线，成本从低到高：\n\n基于动画（Animation-based）：美术在 DCC 工具里做好布料动画，引擎直接播放。优点便宜、可控；缺点不交互、不随机。\n基于刚体（Rigid Body-based）：把布料骨骼绑到刚体上，用约束连", "u": "GAMES104/104_L11.html#s5"}, {"c": "GAMES104 L11 · 第 11 讲：物理系统的应用——角色、布娃娃、布料、破坏与载具", "t": "6. 积分方法：从半隐式欧拉到 Verlet", "x": "布料模拟需要把受力变成位置。课件先回顾半隐式欧拉（Semi-Euler）：\n\\[ v_{t+\\Delta t} = v_t + a(t)\\Delta t \\]\n\\[ x_{t+\\Delta t} = x_t + v_{t+\\Delta t}\\Delta t \\]\n然后推导 Verlet 积分。把上式", "u": "GAMES104/104_L11.html#s6"}, {"c": "GAMES104 L11 · 第 11 讲：物理系统的应用——角色、布娃娃、布料、破坏与载具", "t": "7. 破坏系统：碎块、连通图与伤害传播", "x": "破坏（Destruction）不只是视觉效果，它能让游戏世界更生动，也是很多游戏的核心机制。课件给出的实现框架是：\n\n碎块层级（Chunk Hierarchy）：把模型按层级切分，不同层级有不同的伤害阈值。比如大块需要更大伤害才碎，碎了之后变成更小的块。\n连通图（Connectivity Graph", "u": "GAMES104/104_L11.html#s7"}, {"c": "GAMES104 L11 · 第 11 讲：物理系统的应用——角色、布娃娃、布料、破坏与载具", "t": "8. 载具：四个力与重心", "x": "载具（Vehicle）模拟从风格化到真实有一整个光谱。课件给出的机制建模是：一个刚体作为车身，轮子用形状表示，悬挂用场景查询模拟。核心是四个力：\n\n牵引力（Traction Force）：由引擎扭矩经齿轮和差速器传到车轮，\\( T = T_{engine} \\times g \\times d \\)，", "u": "GAMES104/104_L11.html#s8"}, {"c": "GAMES104 L11 · 第 11 讲：物理系统的应用——角色、布娃娃、布料、破坏与载具", "t": "9. PBD 与 XPBD：基于位置的求解", "x": "前面布料和破坏都提到 PBD。基于位置的动力学（Position Based Dynamics, PBD） 的核心思想是：不直接解力，而是把约束直接投影到位置上。\n课件先回顾约束求解：用拉格朗日力学建模约束，比如碰撞约束（非穿透、摩擦、恢复系数）、布料约束（拉伸、弯曲）。约束函数 \\( C(\\mat", "u": "GAMES104/104_L11.html#s9"}, {"c": "GAMES104 L11 · 核心结论", "t": "角色控制器本质是运动学刚体：不受物理规则驱动，但能推开别人，靠扫掠检测+切向滑动+台阶偏移+坡度限制来获得手感。", "x": "", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 核心结论", "t": "布娃娃把关键骨骼绑到刚体上，用球窝/铰链/枢轴等关节约束连接；约束类型必须匹配人体解剖结构，否则姿势会诡异。", "x": "", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 核心结论", "t": "动画与布娃娃可以混合：运动学状态由动画驱动，动态状态由物理驱动，中间用权重插值，甚至可以用物理结果反过来驱动动画（Powered Ragdoll）。", "x": "", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 核心结论", "t": "布料模拟从便宜到贵依次是：纯动画、刚体骨骼驱动、网格质点弹簧/PBD；质点弹簧的受力包括重力、风力、空气阻力、弹簧力和阻尼力，常用 Verlet 积分求解。", "x": "", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 核心结论", "t": "破坏系统用 Voronoi 图把模型切成碎块，用连通图和连通值记录碎块之间的连接强度，受击时按冲量计算伤害并沿连通图传播，断开连接就产生新刚体。", "x": "", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 核心结论", "t": "载具模拟的核心是四个力：牵引力（来自引擎扭矩）、悬挂力（弹簧）、纵向力（牵引+阻力+滚阻）、侧向力（侧偏刚度×侧偏角）；重心位置影响俯仰、转向不足/过度和重量转", "x": "", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 核心结论", "t": "PBD 把约束直接投影到位置上，快速稳定，但约束满足度难控制；XPBD 用柔度（compliance）处理刚度，并重新引入刚体朝向。", "x": "", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 术语", "t": "Character Controller / 角色控制器", "x": "用运动学刚体+扫掠检测实现的可控角色移动组件。", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 术语", "t": "Kinematic Actor / 运动学刚体", "x": "不受物理规则驱动、但能推开其他物体的刚体。", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 术语", "t": "Sweep Test / 扫掠检测", "x": "沿移动方向扫掠形状，检测是否撞到环境。", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 术语", "t": "Ragdoll / 布娃娃", "x": "把骨骼绑到刚体上、用关节约束连接的物理模拟。", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 术语", "t": "Mass-Spring System / 质点弹簧系统", "x": "布料模拟的基础模型，顶点是质点，边是弹簧。", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 术语", "t": "Verlet Integration / Verlet 积分", "x": "只用位置递推、不需显式存速度的积分方法。", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 术语", "t": "Voronoi Diagram / Voronoi 图", "x": "把平面/空间按最近种子点划分成细胞，用于生成碎块。", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 术语", "t": "Connectivity Graph / 连通图", "x": "碎块之间的连接关系图，边上记录断开所需伤害。", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 术语", "t": "PBD / 基于位置的动力学", "x": "把约束直接投影到位置上的求解方法。", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 术语", "t": "Ackermann Steering / 阿克曼转向", "x": "让左右轮转角不同，避免低速转弯打滑。", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 练习", "t": "为什么角色控制器通常用运动学刚体而不是普通刚体？请至少说出两个原因。", "x": "", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 练习", "t": "写出质点弹簧系统中单个顶点的受力方程，并说明 Verlet 积分的递推公式。", "x": "", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 练习", "t": "简述用 Voronoi 图生成 3D 碎块的流程，并说明连通图和支撑图分别起什么作用。", "x": "", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 练习", "t": "载具模拟中，重心位置如何影响转向特性？前重和后重分别导致什么？", "x": "", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L11 · 练习", "t": "PBD 的约束投影公式是什么？它相比传统力求解有什么优缺点？", "x": "", "u": "GAMES104/104_L11.html"}, {"c": "GAMES104 L15 · 第 15 讲：玩法系统（Gameplay）——事件机制、脚本系统与 3C", "t": "1. 玩法系统为什么难：三个挑战", "x": "课件开篇先给“难”下定义，而不是直接讲技术。玩法系统的挑战可以归为三类：\n（1）多系统协作。 以格斗游戏的一次攻击为例：玩家按键 → 角色动画播放 → 命中判定 → 特效与音效 → UI 血条变化 → 手柄震动反馈。这一串跨越了输入、动画、物理/碰撞、音频、UI、特效、外设多个子系统，任何一个环节的", "u": "GAMES104/104_L15.html#s1"}, {"c": "GAMES104 L15 · 第 15 讲：玩法系统（Gameplay）——事件机制、脚本系统与 3C", "t": "2. 让对象说话：发布-订阅事件机制", "x": "课件用“士兵、直升机、石头、坦克”说明：如果每个对象都直接持有其他对象的指针并调用对方方法，世界会变成一张全连接网，加一个新对象就要改很多旧代码。解法是把通信抽象成消息（message/event）：发送方只负责“喊一声”，不关心谁听；接收方只订阅自己关心的事件类别。这就是发布-订阅模式（publi", "u": "GAMES104/104_L15.html#s2"}, {"c": "GAMES104 L15 · 第 15 讲：玩法系统（Gameplay）——事件机制、脚本系统与 3C", "t": "3. 立即派发 vs 事件队列：两种时序策略的代价", "x": "事件派发有两种基本策略。\n立即派发（Immediate）：事件一发生，同步调用所有回调。实现最简单，但课件指出三个问题：\n\n回调井（deep well of callbacks）：炸弹爆炸 → 士兵受伤 → 触发死亡事件 → 掉落物品 → 触发拾取……调用栈越陷越深，调试困难。\n阻塞：某个回调里做重", "u": "GAMES104/104_L15.html#s3"}, {"c": "GAMES104 L15 · 第 15 讲：玩法系统（Gameplay）——事件机制、脚本系统与 3C", "t": "4. 脚本系统：为什么让策划直接写逻辑", "x": "早期游戏逻辑基本用 C/C++ 写：编译成机器码、性能高、工具链成熟。但随着硬件进化、游戏需求变复杂，纯编译语言的三个问题暴露出来：\n\n迭代慢：改一行逻辑要编译、链接、打包、重启。\n门槛高：策划/美术无法直接控制逻辑，只能写需求文档，再经过程序员翻译，沟通损耗大。\n易崩溃：原生代码里一个越界就可能带", "u": "GAMES104/104_L15.html#s4"}, {"c": "GAMES104 L15 · 第 15 讲：玩法系统（Gameplay）——事件机制、脚本系统与 3C", "t": "5. 可视化脚本：连线就是一门编程语言", "x": "可视化脚本（visual scripting）面向非程序员（策划、美术），拖拽比敲代码不易出错，还能直接看到逻辑结构。但课件强调一个关键认知：可视化脚本也是一门编程语言，它必须补齐编程语言的要素：\n\n变量（Variable）：基本类型（整数、浮点）与复杂类型（结构体/对象），分成员变量与局部变量。可", "u": "GAMES104/104_L15.html#s5"}, {"c": "GAMES104 L15 · 第 15 讲：玩法系统（Gameplay）——事件机制、脚本系统与 3C", "t": "6. 3C：角色、操作、相机决定手感", "x": "课件把玩法体验的第一要素归结为 3C：Character（角色）、Control（操作）、Camera（相机）。三者共同决定“玩起来是什么感觉”。\n角色（Character）：不只是模型，还包括移动、战斗、生命/法力、技能天赋等。课件强调“移动看起来简单，做好很难”：AAA 游戏里每个基础动作状态都", "u": "GAMES104/104_L15.html#s6"}, {"c": "GAMES104 L15 · 核心结论", "t": "玩法系统的核心矛盾是“多系统协作 + 玩法多样 + 快速迭代”，工程上要用解耦和脚本化来应对。", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 核心结论", "t": "事件机制把世界通信抽象为消息，用发布-订阅模式解耦发送方与处理方；关键是事件定义、回调注册、事件派发三件套。", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 核心结论", "t": "回调注册与执行的时间点不同，必须处理对象生命周期安全：强引用要手动反注册，弱引用要检查对象是否已销毁。", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 核心结论", "t": "立即派发实现简单但会形成深回调井、阻塞主线程、难以并行；事件队列能延迟/批量处理，但要付出序列化、时间线不确定、一帧延迟的代价。", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 核心结论", "t": "脚本语言带来快速迭代、热更新和沙箱稳定，但性能通常低于编译语言；Lua 轻量成熟，C# 在 Unity 中兼顾易用与性能。", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 核心结论", "t": "可视化脚本本质是编程语言：变量用数据引脚与连线，语句/表达式用节点，控制流用执行引脚与连线，函数用函数图，类用蓝图。", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 核心结论", "t": "3C 是决定玩法体验的第一要素：角色（移动/战斗/状态机）、操作（输入到逻辑、情境感知、组合键）、相机（POV/FOV、弹簧臂、相机特效与相机管理）。", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 核心结论", "t": "相机的主观感受往往由多个基础调整叠加而成，例如速度感 = FOV 变化 + 相机抖动 + 特效 + 音效。", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 术语", "t": "Gameplay / 玩法系统", "x": "把规则、交互、反馈组织成玩家体验的引擎上层系统", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 术语", "t": "Publish-subscribe / 发布-订阅模式", "x": "发送方按事件类型发消息，订阅方按类型收消息，双方不直接持有", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 术语", "t": "Event Queue / 事件队列", "x": "事件先入队、未来统一处理，可批量但可能延迟一帧", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 术语", "t": "Ring Buffer / 环形缓冲", "x": "固定容量、首尾相接的队列实现，适合高频事件", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 术语", "t": "Scripting Language / 脚本语言", "x": "运行在 VM 上、支持热更新、易学易写的语言", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 术语", "t": "Bytecode / 字节码", "x": "脚本编译后的中间表示，由虚拟机解释/执行", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 术语", "t": "Hot Update / 热更新", "x": "游戏运行中替换脚本逻辑，不重启进程", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 术语", "t": "Visual Scripting / 可视化脚本", "x": "用节点与连线表达的编程语言，最终也编译为字节码", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 术语", "t": "3C / 角色、操作、相机", "x": "Character、Control、Camera，决定玩法体验的第一要素", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 术语", "t": "Spring Arm / 弹簧臂", "x": "相机跟随组件，遇障碍自动拉近，避免穿墙", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 练习", "t": "为什么课件说“立即派发”会形成“回调井”？请举一个游戏中的连锁事件例子，并说明事件队列如何缓解它。", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 练习", "t": "事件参数用键值表（key-value table）和用强类型 C++ 类各有什么优缺点？", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 练习", "t": "某项目把所有事件都放进事件队列，玩家反馈“开枪有一点点延迟”。请分析原因并给出两种修正方案。", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 练习", "t": "可视化脚本为什么被称为“一门编程语言”？请把它与文本脚本的五个要素一一对应。", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L15 · 练习", "t": "请设计一个第三人称射击的相机方案：角色在掩体后、瞄准时拉近、被击中时抖动。写出你会调整的 4 个参数及理由。", "x": "", "u": "GAMES104/104_L15.html"}, {"c": "GAMES104 L17 · 第 17 讲：社区之声与进阶 AI 系统——HTN、GOAP、MCTS 与机器学习入门", "t": "1. 从社区反馈到本讲主线：为什么需要更高级的 AI", "x": "这一讲开头先处理了一些社区事务：T 恤样式投票结果、感谢社区贡献的笔记、以及几个 Q&amp;A 问题（例如“AI 直接读玩家操作指令”的看法）。这些内容本身不是技术核心，但传递了一个信号：现代游戏引擎的 AI 系统已经不再是简单的“巡逻-追击-攻击”状态机，社区和玩家都在期待更聪明、更自然的行为。", "u": "GAMES104/104_L17.html#s1"}, {"c": "GAMES104 L17 · 第 17 讲：社区之声与进阶 AI 系统——HTN、GOAP、MCTS 与机器学习入门", "t": "2. HTN：像人一样分层做计划", "x": "分层任务网络（HTN）的核心直觉是：人做计划是分层的。比如“我要解毒”，可以分解为“找到药水”和“使用药水”；“找到药水”又可以分解为“去商店买”或“去野外采”。每一层只关心当前层的选择，而不是一上来就列出一长串原子动作。\nHTN 框架包含几个关键部分：\n\n世界状态（World State）：一组属", "u": "GAMES104/104_L17.html#s2"}, {"c": "GAMES104 L17 · 第 17 讲：社区之声与进阶 AI 系统——HTN、GOAP、MCTS 与机器学习入门", "t": "3. GOAP：从目标反向找动作", "x": "目标导向动作规划（GOAP）比 HTN 更自动化：它不预先规定任务层次，而是把每个动作描述成“前提条件 + 效果 + 代价”，然后从目标状态反向搜索，找到一条从当前状态到目标状态的动作序列。\nGOAP 的结构包括：\n\n传感器与世界状态：和 HTN 类似，传感器收集信息，世界状态是一组属性。\n目标集（", "u": "GAMES104/104_L17.html#s3"}, {"c": "GAMES104 L17 · 第 17 讲：社区之声与进阶 AI 系统——HTN、GOAP、MCTS 与机器学习入门", "t": "4. MCTS：在“脑内”模拟成千上万局", "x": "蒙特卡洛树搜索（MCTS）的直觉像下棋：高手会在脑中模拟很多种走法，选择看起来最有希望的那一步。MCTS 把这种“脑内模拟”变成算法：它维护一棵搜索树，节点是游戏状态，边是动作，通过大量随机模拟来评估每个动作的价值。\nMCTS 的一次迭代包含四个步骤：\n\n选择（Selection）：从根节点开始，按", "u": "GAMES104/104_L17.html#s4"}, {"c": "GAMES104 L17 · 第 17 讲：社区之声与进阶 AI 系统——HTN、GOAP、MCTS 与机器学习入门", "t": "5. 机器学习基础：四种学习范式与强化学习", "x": "课件把机器学习分为四类：\n\n监督学习（Supervised Learning）：从带标签的数据中学习，比如给大量“状态-正确动作”对，训练网络模仿。\n无监督学习（Unsupervised Learning）：从无标签数据中找结构，游戏 AI 中较少直接使用。\n半监督学习（Semi-supervise", "u": "GAMES104/104_L17.html#s5"}, {"c": "GAMES104 L17 · 第 17 讲：社区之声与进阶 AI 系统——HTN、GOAP、MCTS 与机器学习入门", "t": "6. 用机器学习构建进阶游戏 AI：从状态设计到训练策略", "x": "课件以 RTS 游戏为例，展示如何把游戏建模成 DRL 问题：\n\n状态（State）：包括地图信息（高度、可见性、迷雾、可通行、可建造）、单位信息（类型、所有者、状态、位置等）。\n动作（Action）：对每个单位，动作包括“做什么”（移动、攻击、建造）、“对谁”、“在哪里”、“何时”。\n奖励（Rew", "u": "GAMES104/104_L17.html#s6"}, {"c": "GAMES104 L17 · 核心结论", "t": "HTN 用分层任务分解来规划：复合任务通过方法分解为子任务，原始任务对应具体动作，规划时按顺序检查前提条件并更新世界状态。", "x": "", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 核心结论", "t": "GOAP 从目标反向搜索动作，每个动作有前提、效果和代价，最终用 A* 等算法在状态-动作-代价图中找最低代价路径。", "x": "", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 核心结论", "t": "MCTS 通过大量随机模拟来评估动作价值，用 UCB 公式平衡探索与利用，适合状态空间巨大甚至“无限”的博弈场景。", "x": "", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 核心结论", "t": "强化学习用马尔可夫决策过程（MDP）建模：智能体在环境中根据策略选择动作，获得奖励，目标是最大化长期回报。", "x": "", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 核心结论", "t": "游戏 AI 的机器学习落地需要精心设计状态表示、动作空间、奖励函数和神经网络结构，AlphaStar 和 OpenAI Five 是典型工程案例。", "x": "", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 核心结论", "t": "监督学习需要高质量标注数据，强化学习需要可模拟的环境和稠密奖励；实际项目常采用“宏观用学习、微观用 FSM/BT”的混合架构。", "x": "", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 术语", "t": "HTN (Hierarchical Tasks Network) / 分层任务网络", "x": "用分层任务分解来生成计划，复合任务通过方法分解为子任务。", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 术语", "t": "GOAP (Goal-Oriented Action Planning) / 目标导向动作规划", "x": "从目标反向搜索动作，每个动作有前提、效果和代价。", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 术语", "t": "MCTS (Monte Carlo Tree Search) / 蒙特卡洛树搜索", "x": "通过大量随机模拟评估动作价值，用 UCB 平衡探索与利用。", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 术语", "t": "UCB (Upper Confidence Bounds) / 上置信界", "x": "MCTS 中选择节点的公式，兼顾平均奖励和访问次数。", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 术语", "t": "MDP (Markov Decision Process) / 马尔可夫决策过程", "x": "强化学习的数学框架，包含状态、动作、奖励、转移概率和策略。", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 术语", "t": "Policy / 策略", "x": "从状态到动作概率的映射，记作 π(a|s)。", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 术语", "t": "Supervised Learning / 监督学习", "x": "从带标签数据中学习输入到输出的映射。", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 术语", "t": "Reinforcement Learning / 强化学习", "x": "智能体通过与环境交互、根据奖励信号学习策略。", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 术语", "t": "Self-Play / 自我对弈", "x": "智能体与自己或历史版本对战来提升策略，AlphaStar 使用多池训练。", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 练习", "t": "HTN 中原始任务和复合任务的区别是什么？规划时如何处理复合任务？", "x": "", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 练习", "t": "GOAP 的反向规划中，如何确定一个动作是否应该被选中？请结合前提、效果和代价说明。", "x": "", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 练习", "t": "MCTS 的 UCB 公式中，两项分别代表什么？如果探索常数 c 设得过大或过小，会有什么现象？", "x": "", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 练习", "t": "假设你要为一个 RTS 游戏设计强化学习的状态和动作，请列出至少 5 个状态特征和 3 类动作。", "x": "", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L17 · 练习", "t": "在什么情况下你会选择监督学习而不是强化学习？请结合数据、奖励和环境三个因素说明。", "x": "", "u": "GAMES104/104_L17.html"}, {"c": "GAMES104 L16 · 第 16 讲：游戏 AI 基础——导航、转向、群体模拟、感知与决策", "t": "1. 导航总览：从地图表示到平滑路径", "x": "游戏 AI 的移动基础是导航（Navigation）：让 AI 自动从地图上一点走到另一点。课件把导航拆成三个步骤：\n\n地图表示（Map Representation）：告诉 AI 哪里可以走。玩家的可行走区域由角色控制器决定（例如碰撞胶囊体），AI 需要一张“可行走区域”的抽象地图。\n寻路（Pat", "u": "GAMES104/104_L16.html#s1"}, {"c": "GAMES104 L16 · 第 16 讲：游戏 AI 基础——导航、转向、群体模拟、感知与决策", "t": "2. 路点网络与网格：简单直观的两种表示", "x": "路点网络（Waypoint Network） 是最早也最直观的表示：设计师在地图上放置关键点（waypoint），并在可以通行的点之间连边。使用时，AI 先找到离自己最近的路点，再在路点网络上寻路，最后从出口路点走到目标。它的优点是实现简单、寻路极快（节点少），适合大型地图；缺点是灵活性差——AI ", "u": "GAMES104/104_L16.html#s2"}, {"c": "GAMES104 L16 · 第 16 讲：游戏 AI 基础——导航、转向、群体模拟、感知与决策", "t": "3. 导航网格（NavMesh）：3D 可行走区域的凸多边形表示", "x": "导航网格（Navigation Mesh，NavMesh）用一组相邻的凸多边形来近似角色的可行走区域。相比网格，它直接贴合 3D 表面，没有重叠，精度高且寻路快。\n为什么用凸多边形？ 寻路会生成一系列需要穿过的多边形（称为多边形走廊 Polygon Corridor）。凸多边形保证从一条边进入后，可", "u": "GAMES104/104_L16.html#s3"}, {"c": "GAMES104 L16 · 第 16 讲：游戏 AI 基础——导航、转向、群体模拟、感知与决策", "t": "4. 寻路算法：从 DFS/BFS 到 A*", "x": "地图表示抽象为图后，寻路就是图上的最短路径问题。课件依次介绍了：\n\n深度优先搜索（DFS）：扩展最近加入的节点，不保证最短路径，可能绕远。\n广度优先搜索（BFS）：扩展最早加入的节点，在无权图上保证最短路径，但盲目扩展所有方向。\nDijkstra 算法：带权图的最短路径，每次扩展当前代价最小的节点，", "u": "GAMES104/104_L16.html#s4"}, {"c": "GAMES104 L16 · 第 16 讲：游戏 AI 基础——导航、转向、群体模拟、感知与决策", "t": "5. 路径平滑与漏斗算法", "x": "A* 在导航网格上生成的原始路径是穿过多边形序列的折线，往往有锯齿和多余拐角。直接让角色沿折线走会显得机械。路径平滑的目标是生成一条自然、最短的平滑路径。\n课件介绍的 漏斗算法（Funnel Algorithm / String Pulling） 是常用方法：\n\n把路径想象成一根绳子，起点和终点固定", "u": "GAMES104/104_L16.html#s5"}, {"c": "GAMES104 L16 · 第 16 讲：游戏 AI 基础——导航、转向、群体模拟、感知与决策", "t": "6. 转向行为（Steering）：从路径到运动", "x": "寻路给出了一条路径，但角色不能瞬间转向或变速。转向行为（Steering Behaviors）负责把路径转化为受运动能力约束的平滑运动。课件以车辆为例：车辆受最大线加速度、最大角速度等限制，不能精确跟随路径。\n常见的转向行为：\n\nSeek / Flee：朝目标加速或远离目标。计算期望速度（指向目标）", "u": "GAMES104/104_L16.html#s6"}, {"c": "GAMES104 L16 · 第 16 讲：游戏 AI 基础——导航、转向、群体模拟、感知与决策", "t": "7. 群体模拟与碰撞避免", "x": "群体模拟（Crowd Simulation）处理大量个体在同一环境中的运动，包括碰撞避免、集群（Swarming）等。课件将模型分为三类：\n\n微观模型（Microscopic）：自底向上，关注每个个体的运动。典型是 Reynolds 的 Boids 规则模型（分离、对齐、聚合），实现简单但难以模拟复", "u": "GAMES104/104_L16.html#s7"}, {"c": "GAMES104 L16 · 第 16 讲：游戏 AI 基础——导航、转向、群体模拟、感知与决策", "t": "8. 感知系统与经典决策算法", "x": "感知（Sensing） 是 AI 获取信息的方式，包括：\n\n内部信息：自身位置、HP、护甲、Buff 等，可直接访问。\n静态空间信息：导航数据、战术地图、掩体点、智能对象（Smart Object）。\n动态空间信息：影响图（Influence Map，标记视野区域等）、游戏对象（角色位置、状态）。\n", "u": "GAMES104/104_L16.html#s8"}, {"c": "GAMES104 L16 · 核心结论", "t": "导航分为三步：地图表示、寻路、路径平滑；常用地图表示有路点网络、网格、导航网格和稀疏体素八叉树。", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 核心结论", "t": "A* 用 f(n)=g(n)+h(n) 选择扩展节点，h(n) 必须不高估真实代价才能保证最优；启发函数越接近真实代价，搜索越快。", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 核心结论", "t": "导航网格用凸多边形表示可行走区域，路径平滑常用漏斗算法（String Pulling）消除锯齿。", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 核心结论", "t": "转向行为（Steering）将路径转化为受运动能力约束的平滑运动，核心是计算期望速度并限制加速度。", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 核心结论", "t": "群体模拟分微观（规则驱动）、宏观（连续流）、介观（分组）三类；碰撞避免常用力模型和速度障碍（VO/RVO）。", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 核心结论", "t": "感知系统包括内部信息、静态空间信息（导航数据、战术地图、掩体点）和动态空间信息（影响图、游戏对象）。", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 核心结论", "t": "行为树通过组合节点（Sequence、Selector、Parallel）和执行节点（条件、动作）组织逻辑，每帧从根节点 Tick，具有模块化、反应性、易调试的", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 核心结论", "t": "行为树的缺点是每帧从根节点遍历开销大，反应性越强需要检查的条件越多。", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 术语", "t": "Navigation Mesh (NavMesh) / 导航网格", "x": "用凸多边形表示可行走区域的 3D 地图表示", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 术语", "t": "A* Algorithm / A* 算法", "x": "结合 Dijkstra 和启发式搜索的最短路径算法", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 术语", "t": "Heuristic Function / 启发函数", "x": "估计从当前节点到终点代价的函数，影响 A* 的搜索行为", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 术语", "t": "Funnel Algorithm / 漏斗算法", "x": "路径平滑算法，通过收窄漏斗找到最短路径拐点", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 术语", "t": "Steering Behavior / 转向行为", "x": "将路径转化为受运动约束的平滑运动的技术", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 术语", "t": "Crowd Simulation / 群体模拟", "x": "模拟大量个体运动的模型，分微观、宏观、介观", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 术语", "t": "Reciprocal Velocity Obstacle (RVO) / 互惠速度障碍", "x": "双方各承担一半避让责任的碰撞避免算法", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 术语", "t": "Behavior Tree (BT) / 行为树", "x": "用树形结构组织 AI 决策逻辑的算法", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 术语", "t": "Blackboard / 黑板", "x": "行为树中存储共享数据的键值存储", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 术语", "t": "Finite State Machine (FSM) / 有限状态机", "x": "通过状态和转换条件描述行为的经典模型", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 练习", "t": "简述导航网格（NavMesh）相比网格（Grid）表示的三个优点。", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 练习", "t": "在 A* 算法中，如果启发函数 h(n) 高估了真实代价，会发生什么？为什么？", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 练习", "t": "用伪代码描述 Seek 转向行为，并说明如何限制加速度。", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 练习", "t": "行为树中的 Sequence 和 Selector 节点有什么区别？请各举一个游戏中的例子。", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L16 · 练习", "t": "在 UE 中，如何为一个 AI 角色设置导航网格和基本的行为树？请列出关键步骤。", "x": "", "u": "GAMES104/104_L16.html"}, {"c": "GAMES104 L21 · 第 21 讲：动态全局光照与 Lumen", "t": "1. 为什么全局光照是实时渲染的硬骨头", "x": "先给直觉：现实世界里，你看到的一面白墙，除了被灯直接照亮的部分，还会被周围物体反射过来的光“二次照亮”。这种光在场景里来回弹射、最终照亮阴影和背光面的现象，就是全局光照（Global Illumination, GI）。没有 GI，画面会显得“死黑”、物体像贴纸；有了 GI，颜色会互相渗透（colo", "u": "GAMES104/104_L21.html#s1"}, {"c": "GAMES104 L21 · 第 21 讲：动态全局光照与 Lumen", "t": "2. 蒙特卡洛积分与重要性采样：用随机换速度", "x": "渲染方程是一个高维积分，解析解不存在。课件给出的第一把钥匙是蒙特卡洛积分（Monte Carlo Integration）：用随机采样的平均值近似积分。直觉是“撒点求平均”——在积分域里随机撒 \\(N\\) 个样本，算被积函数值除以概率密度，再取平均。公式为：\n\\[ \\int f(x) \\, dx \\", "u": "GAMES104/104_L21.html#s2"}, {"c": "GAMES104 L21 · 第 21 讲：动态全局光照与 Lumen", "t": "3. 屏幕空间之前的 GI：RSM 与 LPV", "x": "在硬件光追普及前，工业界用“注入虚拟光源”的思路做 GI。反射阴影贴图（Reflective Shadow Maps, RSM） 是 2005 年的经典方案：它把阴影贴图上的每个像素当作一个间接光源（虚拟点光源），记录该像素的世界坐标、法线和辐射度。着色时，对每个表面点收集附近若干 RSM 像素的贡", "u": "GAMES104/104_L21.html#s3"}, {"c": "GAMES104 L21 · 第 21 讲：动态全局光照与 Lumen", "t": "4. 体素化 GI：SVOGI 与 VXGI", "x": "稀疏体素八叉树 GI（Sparse Voxel Octree GI, SVOGI） 和 体素全局光照（Voxel Global Illumination, VXGI） 把场景体素化，用体素存储辐射度和不透明度，再用锥体追踪（Cone Tracing） 查询间接光。课件详细讲了 VXGI 的流程：\n\n", "u": "GAMES104/104_L21.html#s4"}, {"c": "GAMES104 L21 · 第 21 讲：动态全局光照与 Lumen", "t": "5. 屏幕空间 GI：SSGI 的快与局限", "x": "屏幕空间全局光照（Screen Space Global Illumination, SSGI） 复用当前帧的屏幕空间数据（颜色、深度、法线）做光线步进，近似间接光。直觉是：既然屏幕上的像素已经包含了场景可见部分的光照，那就可以在屏幕空间里“发射光线”去采样这些像素的颜色，当作间接光。\n课件讲了 S", "u": "GAMES104/104_L21.html#s5"}, {"c": "GAMES104 L21 · 第 21 讲：动态全局光照与 Lumen", "t": "6. Lumen 第一阶段：用 SDF 做快速光线追踪", "x": "Lumen 是 UE5 的实时全局光照方案，课件把它拆成三个阶段，第一阶段是在任何硬件上都能快速追踪光线。核心工具是有向距离场（Signed Distance Field, SDF）：场景中每个点存储到最近表面的距离，表面内部为负、外部为正。SDF 的好处是光线求交可以用球体步进（Sphere Tr", "u": "GAMES104/104_L21.html#s6"}, {"c": "GAMES104 L21 · 第 21 讲：动态全局光照与 Lumen", "t": "7. Lumen 第二阶段：辐射度注入与缓存", "x": "有了快速光线追踪，下一步是缓存光照，避免每帧重算。Lumen 用 Surface Cache 缓存表面光照：为每个 Mesh 生成若干 Mesh Card（沿轴向正交相机捕获的卡片），把表面 albedo、法线、深度等写入卡片图集。然后分两个 Pass：Card Capture 和 Card Res", "u": "GAMES104/104_L21.html#s7"}, {"c": "GAMES104 L21 · 第 21 讲：动态全局光照与 Lumen", "t": "8. Lumen 第三阶段：Screen Probe 与全像素着色", "x": "最后一步是把缓存的光照插值到每个像素。Lumen 在屏幕空间放置 Screen Probe：以 8x8 像素为一个 tile，每个 tile 放置若干探针（通常 2x2），探针用八面体映射（octahedron mapping）存储全方向辐射度。探针的放置是自适应的，用层级结构在几何边缘处加密。\n探", "u": "GAMES104/104_L21.html#s8"}, {"c": "GAMES104 L21 · 核心结论", "t": "全局光照的本质是求解渲染方程，它把直接光照和无数次弹射的间接光照统一在一个积分里。", "x": "", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 核心结论", "t": "实时渲染无法精确求解渲染方程，只能用蒙特卡洛积分做近似，采样数越少噪点越多。", "x": "", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 核心结论", "t": "重要性采样让采样分布匹配被积函数（如余弦项、GGX 项），在相同采样数下显著降噪。", "x": "", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 核心结论", "t": "RSM 把阴影贴图上的每个像素当作虚拟光源，LPV 用 3D 网格传播辐射度，VXGI 用体素化场景 + 锥体追踪，SSGI 复用屏幕空间数据做光线步进。", "x": "", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 核心结论", "t": "SSGI 快但只能处理屏幕内可见的间接光，屏幕外信息缺失导致漏光/缺失；VXGI 能处理屏幕外但体素化有遮挡不准确和内存开销。", "x": "", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 核心结论", "t": "Lumen 用 Mesh SDF 做快速光线求交，用 Surface Cache 缓存表面光照，用 Screen Probe + World Probe 做辐射", "x": "", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 核心结论", "t": "Lumen 的核心取舍是：用低分辨率、低采样数的光线追踪 + 时域/空间降噪，换取实时性能。", "x": "", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 术语", "t": "Global Illumination (GI) / 全局光照", "x": "考虑光在场景中多次弹射的渲染方法，包含直接光和间接光。", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 术语", "t": "Rendering Equation / 渲染方程", "x": "描述表面出射光等于自发光加半球积分的能量平衡方程。", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 术语", "t": "Monte Carlo Integration / 蒙特卡洛积分", "x": "用随机采样平均值近似积分，样本数越多越精确。", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 术语", "t": "Importance Sampling / 重要性采样", "x": "让采样 PDF 匹配被积函数形状，降低方差。", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 术语", "t": "Reflective Shadow Map (RSM) / 反射阴影贴图", "x": "把阴影贴图像素当作虚拟光源做一次弹射 GI。", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 术语", "t": "Light Propagation Volume (LPV) / 光传播体积", "x": "用 3D 网格注入并传播辐射度的 GI 方法。", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 术语", "t": "Voxel Global Illumination (VXGI) / 体素全局光照", "x": "体素化场景后用锥体追踪查询间接光。", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 术语", "t": "Screen Space Global Illumination (SSGI) / 屏幕空间全局光照", "x": "复用屏幕空间数据做光线步进近似间接光。", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 术语", "t": "Signed Distance Field (SDF) / 有向距离场", "x": "存储到最近表面距离的场，用于快速光线求交。", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 术语", "t": "Spherical Harmonics (SH) / 球谐函数", "x": "用少量系数表示低频方向分布，用于光照插值。", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 练习", "t": "请用自己的话解释：为什么实时渲染不能直接求解渲染方程？蒙特卡洛积分在其中扮演什么角色？", "x": "", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 练习", "t": "比较 RSM、LPV、VXGI、SSGI 四种 GI 方案：各自的核心数据结构是什么？主要优点和缺点是什么？", "x": "", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 练习", "t": "Lumen 为什么需要 Global SDF 和 Mesh SDF 两级距离场？只用其中一种会有什么问题？", "x": "", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 练习", "t": "在 UE5 中开启 Lumen 后，场景出现“墙后漏光”和“暗部噪点闪烁”，请分别分析可能原因并给出至少两条排查/修正建议。", "x": "", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L21 · 练习", "t": "假设一个像素的间接光积分中，被积函数在半球上近似为常数 2，若用均匀 PDF（\\(p = 1/(2\\pi)\\)）采样 100 次，估计值的方差与用余弦 PDF ", "x": "", "u": "GAMES104/104_L21.html"}, {"c": "GAMES104 L19 · 第 19 讲：在线游戏架构（下）——角色同步、命中判定、MMO 架构与反作弊", "t": "1. 角色移动同步：为什么远端角色看起来一顿一顿", "x": "在多人游戏里，玩家看到自己的角色是“本地即时响应”的，但看到别人的角色却是“网络延迟后的历史状态”。如果直接把收到的位置包贴上去，远端角色就会一跳一跳（choppy）。课件的出发点就是：如何让远端角色在屏幕上平滑移动，同时又不偏离服务器权威状态太远。\n两种基本手段：\n\n插值（Interpolatio", "u": "GAMES104/104_L19.html#s1"}, {"c": "GAMES104 L19 · 第 19 讲：在线游戏架构（下）——角色同步、命中判定、MMO 架构与反作弊", "t": "2. 外推的进阶：投影速度混合与碰撞时的物理混合", "x": "朴素外推在直线运动时没问题，但角色/车辆会转弯、会撞墙。课件给出两个改进：\n投影速度混合（Projective Velocity Blending）：在时刻 \\(t_0\\) 收到角色在 \\(p_0\\)、速度 \\(v_0\\)、加速度 \\(a_0\\)。外推时不是简单 \\(p = p_0 + v_0 \\D", "u": "GAMES104/104_L19.html#s2"}, {"c": "GAMES104 L19 · 第 19 讲：在线游戏架构（下）——角色同步、命中判定、MMO 架构与反作弊", "t": "3. 命中判定：为什么你“明明打中了”却没掉血", "x": "网络射击游戏最经典的抱怨是“我打中了但没伤害”。课件先解释原因：由于延迟、插值偏移和时间差，你屏幕上看到的敌人位置，并不是服务器上敌人的真实位置。你看到的是“过去”的敌人。\n于是命中判定（Hit Registration）要解决的是：让所有玩家对“这一枪是否命中”达成共识。课件给的流程是：\n\n客户端", "u": "GAMES104/104_L19.html#s3"}, {"c": "GAMES104 L19 · 第 19 讲：在线游戏架构（下）——角色同步、命中判定、MMO 架构与反作弊", "t": "4. 延迟补偿（Lag Compensation）：把世界回卷到开火那一刻", "x": "Lag Compensation 的定义：当玩家命令到达服务器时，服务器把世界状态回卷到该玩家“当时看到”的时刻，再做判定。\n课件给出的回卷时间公式是：\n\\[\n\\text{RewindTime} = \\text{Current Server Time} - \\text{Packet Latency}", "u": "GAMES104/104_L19.html#s4"}, {"c": "GAMES104 L19 · 第 19 讲：在线游戏架构（下）——角色同步、命中判定、MMO 架构与反作弊", "t": "5. MMOG 后端：把一个大游戏拆成一组服务", "x": "MMOG（Massively Multiplayer Online Game）的特点是大量玩家、长在线、复杂子系统。课件把后端拆成若干层：\n\nLink Layer：\nLogin Server：验证客户端连接、账号认证；\nGateway：非常重要的接入层，负责连接保持、协议解析、转发；\nLobby：玩", "u": "GAMES104/104_L19.html#s5"}, {"c": "GAMES104 L19 · 第 19 讲：在线游戏架构（下）——角色同步、命中判定、MMO 架构与反作弊", "t": "6. 带宽优化：少发、发小、发得巧", "x": "课件先算了一笔账：带宽 = 玩家数 × 更新频率 × 每次状态变化的数据量。影响因素包括玩家数量 \\(n\\)、更新频率 \\(f\\)、每个对象的状态大小。带宽贵（按流量计费）、带宽高会推高延迟，所以必须优化。\n三类手段：\n1）数据压缩：同步数据里有大量浮点数。做法包括：\n\n定点化/量化：位置只保留必要", "u": "GAMES104/104_L19.html#s6"}, {"c": "GAMES104 L19 · 第 19 讲：在线游戏架构（下）——角色同步、命中判定、MMO 架构与反作弊", "t": "7. 反作弊：从内存混淆到 AI 检测的分层对抗", "x": "课件先给了一组触目惊心的数字：相当比例的玩家遇到作弊就会退游。作弊方式五花八门：\n\n修改/读取内存：改坐标、改血量、透视；\n破解客户端：反编译、改逻辑；\n系统层调用：改 DirectX 内核、改渲染流程（如去雾、透视）；\n拦截/篡改网络包：中间人改包；\nAI 作弊：不碰代码，只看屏幕画面做识别（YO", "u": "GAMES104/104_L19.html#s7"}, {"c": "GAMES104 L19 · 第 19 讲：在线游戏架构（下）——角色同步、命中判定、MMO 架构与反作弊", "t": "8. 可扩展的大世界：无缝分区与跨服复制", "x": "单个 Game Server 撑不住大世界，就要分区（Zoning）：把大世界切成多个区域，分给不同服务器。\n无缝分区（Seamless Zones）的关键设计：\n\n边界宽度 ≥ 最大 AOI 半径：这样玩家在边界附近时，两侧服务器都能覆盖他的 AOI，不会出现“对象突然消失”；\n实体状态：分为“活", "u": "GAMES104/104_L19.html#s8"}, {"c": "GAMES104 L19 · 核心结论", "t": "网络同步的本质是“在延迟下让远端看起来平滑且公平”：插值用过去两个快照做平滑，外推用历史状态预测当前，二者常混合使用。", "x": "", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 核心结论", "t": "外推在碰撞时会“穿墙/卡住”，需要物理模拟混合（Physics Simulation Blending）把外推状态与服务器权威状态做可调混合。", "x": "", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 核心结论", "t": "命中判定通常是客户端先判、服务器再校验；服务器校验需要“回卷”到玩家开火时刻的世界状态，回卷时间 = 当前服务器时间 − 网络延迟 − 客户端插值偏移。", "x": "", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 核心结论", "t": "MMOG 后端按职责拆成多个服务（登录、网关、大厅、角色、游戏逻辑、交易、社交、匹配、存储），通过注册中心做服务发现与健康检查。", "x": "", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 核心结论", "t": "带宽优化三板斧：压缩同步数据（定点化/量化）、只同步相关对象（AOI/空间网格/正交链表/PVS）、按距离降低更新频率。", "x": "", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 核心结论", "t": "反作弊是分层对抗：内存混淆、可执行文件加壳、文件哈希校验、流量加密、内核级反作弊、AI 行为检测、人工 Overwatch、统计异常检测。", "x": "", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 核心结论", "t": "大世界靠分区（Zoning）扩展：无缝分区要求边界宽度 ≥ 最大 AOI 半径，实体跨边界时做状态迁移与协同复制。", "x": "", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 术语", "t": "Interpolation / 插值", "x": "在两个已收到的快照之间平滑，代价是看到“过去”的状态。", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 术语", "t": "Extrapolation / Dead Reckoning / 外推 / 航位推算", "x": "用历史状态预测当前，延迟低但可能预测错。", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 术语", "t": "Projective Velocity Blending / 投影速度混合", "x": "外推时把速度方向逐渐混合到最新快照方向，避免直线冲过头。", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 术语", "t": "Hit Registration / 命中判定", "x": "让所有玩家对“这一枪是否命中”达成共识的机制。", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 术语", "t": "Lag Compensation / 延迟补偿", "x": "服务器把世界回卷到玩家开火时刻再判定。", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 术语", "t": "AOI (Area of Interest) / 兴趣区域", "x": "以玩家为中心的相关对象范围，只同步圈内对象。", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 术语", "t": "Consistent Hashing / 一致性哈希", "x": "节点增删只影响相邻区间的哈希分片方案。", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 术语", "t": "Service Discovery / 服务发现", "x": "服务注册 + 查询/监听 + 健康检查，让调用方找到可用实例。", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 术语", "t": "Seamless Zoning / 无缝分区", "x": "大世界切分给多台服务器，边界重叠保证体验连续。", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 术语", "t": "Anti-Cheat / 反作弊", "x": "内存混淆、加壳、哈希校验、加密、SDK、AI 检测、人工审查的组合。", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 练习", "t": "解释插值与外推的区别，并各举一个适合的游戏场景。", "x": "", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 练习", "t": "服务器收到命中事件时，当前服务器时间为 10.000s，测得单程延迟 80ms，客户端插值缓冲 50ms，求回卷时间；并说明为什么不能只用 RTT/2。", "x": "", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 练习", "t": "一个 MMO 有 5000 个玩家在同一区域，每 50ms 同步一次，每个对象状态 40 字节，估算原始带宽并给出至少三种优化手段。", "x": "", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 练习", "t": "为什么无缝分区的边界宽度必须 ≥ 最大 AOI 半径？如果小于会怎样？", "x": "", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L19 · 练习", "t": "列举至少四种作弊方式及对应的防护手段，并说明为什么反作弊没有“银弹”。", "x": "", "u": "GAMES104/104_L19.html"}, {"c": "GAMES104 L20 · 第 20 讲：面向数据编程与 Job System", "t": "1. 为什么“写代码”不等于“跑得快”：硬件与操作系统的现实", "x": "这一讲开场先泼一盆冷水：代码执行并不像看起来那么简单。你写的 for 循环、虚函数调用、new 一个对象，最终都要落到具体的 CPU、缓存、操作系统调度器上。同一段逻辑，数据放得不一样、线程怎么切，性能可能差一个数量级。\n先厘清两个最基础的概念：\n\n进程（Process）：一个应用程序的实例，拥有自", "u": "GAMES104/104_L20.html#s1"}, {"c": "GAMES104 L20 · 第 20 讲：面向数据编程与 Job System", "t": "2. 并行编程基础：完美并行、数据竞争与锁的代价", "x": "并行问题按依赖程度可以排成一条谱：\n\n完美并行（Embarrassingly Parallel）：任务之间几乎无依赖、无需通信。比如对每个粒子独立积分、对每个像素独立着色。这类问题并行收益最直接。\n另一端是强依赖问题：后一步必须等前一步的结果，并行度很低。\n\n只要多个线程同时访问同一内存位置，且至少", "u": "GAMES104/104_L20.html#s2"}, {"c": "GAMES104 L20 · 第 20 讲：面向数据编程与 Job System", "t": "3. 看不见的顺序：编译器重排、CPU 乱序与内存屏障", "x": "即使你写对了加锁，还有一个更隐蔽的坑：你写的顺序不一定是执行的顺序。\n\n编译器重排（Compiler Reordering）：优化器为了减少访存、填充流水线，会调整指令顺序。课件给的例子是 a = b + 1; b = 1; 这类语句在开启优化后可能被换序。\nCPU 乱序执行（Out-of-orde", "u": "GAMES104/104_L20.html#s3"}, {"c": "GAMES104 L20 · 第 20 讲：面向数据编程与 Job System", "t": "4. 游戏引擎的并行框架演进：从固定线程到任务图", "x": "把并行落到引擎架构上，课件给了一条清晰的演进路线：\n\n固定多线程（Fixed Multi-thread）：渲染一个线程、模拟一个线程、逻辑一个线程、网络一个线程……实现简单、职责清楚。问题是负载不均衡：某一帧物理很重、渲染很轻，核就闲着；而且核数增加时无法扩展。\nFork-Join + 线程池：把可", "u": "GAMES104/104_L20.html#s4"}, {"c": "GAMES104 L20 · 第 20 讲：面向数据编程与 Job System", "t": "5. Job System 的核心：协程、Fiber 与“一核一线程”", "x": "为什么有了任务图还需要 Job System？因为线程切换太贵。课件给出的答案是：把“执行单元”和“执行上下文”拆开。\n先看协程（Coroutine）：它是一种轻量执行上下文，能在某个点让出（yield）、之后从原地恢复，而不需要内核参与调度。和线程相比：\n\n线程由 OS 调度，协程由程序员/框架调", "u": "GAMES104/104_L20.html#s5"}, {"c": "GAMES104 L20 · 第 20 讲：面向数据编程与 Job System", "t": "6. 调度器细节：全局队列、LIFO/FIFO、依赖与工作窃取", "x": "Job System 的调度器要回答四个问题：\n\n任务从哪拿？ 全局 job 队列 + 每个工作线程的本地队列。新任务通常先压入本地队列。\n本地队列用什么顺序？ 课件对比了 FIFO（先进先出） 与 LIFO（后进先出）。大多数情况下任务依赖呈“树状”：父任务派生出子任务后等待它们完成，此时 LIF", "u": "GAMES104/104_L20.html#s6"}, {"c": "GAMES104 L20 · 第 20 讲：面向数据编程与 Job System", "t": "7. 从 OOP 到 DOP：对象范式在引擎里的三个痛点", "x": "课件先回顾了编程范式：面向过程（POP）把任务拆成变量和例程一步步执行；面向对象（OOP）把数据和行为封装进对象，符合人的直觉，也是游戏引擎长期的主流。\n但在大型引擎里，OOP 暴露出三个具体问题：\n\n代码放哪？ Attacker.doDamageTo() 还是 Victim.receiveDama", "u": "GAMES104/104_L20.html#s7"}, {"c": "GAMES104 L20 · 第 20 讲：面向数据编程与 Job System", "t": "8. 缓存为王：局部性、缓存行、伪共享与数据布局", "x": "这一节是全讲的技术核心。先看事实：处理器性能增长远快于内存，这个“处理器-内存性能差距”让内存访问成为瓶颈，于是有了多级缓存：L1 很小（几百 KB 量级）但极快，L2/L3 依次变大变慢。\n缓存能起作用，靠的是局部性原理（Principle of Locality）：\n\n时间局部性：刚访问过的数据", "u": "GAMES104/104_L20.html#s8"}, {"c": "GAMES104 L20 · 第 20 讲：面向数据编程与 Job System", "t": "9. ECS 落地：Unity DOTS 与 UE Mass 的对应关系", "x": "ECS（Entity Component System） 是用数据导向方式组织游戏代码的模式，目标是最大性能：\n\nEntity：一个 ID，代表场景里的一个东西；本身不含数据。\nComponent：纯数据，挂在 Entity 上（如位置、速度）。\nSystem：批量处理“拥有某组组件”的所有 Ent", "u": "GAMES104/104_L20.html#s9"}, {"c": "GAMES104 L20 · 核心结论", "t": "代码不是跑在纸面上的：硬件与操作系统决定了并行的真实代价，线程切换、缓存未命中、分支预测失败都会吃掉性能。", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 核心结论", "t": "多核时代单核频率见顶，性能提升主要靠并行；但并行会带来数据竞争，锁能保证正确性却带来挂起/唤醒、死锁、优先级反转等开销。", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 核心结论", "t": "原子操作与无锁编程可以避免锁的开销，但要小心编译器重排与 CPU 乱序执行，需要内存屏障/原子语义来约束顺序。", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 核心结论", "t": "游戏引擎的并行框架从固定多线程 → Fork-Join 线程池 → 任务图（DAG）→ 基于 fiber 的 Job System 演进，目标是负载均衡、低切换", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 核心结论", "t": "性能敏感编程的核心是缓存：利用时间/空间局部性、按缓存行组织数据、避免伪共享、减少指针追逐、用数据布局替代分支。", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 核心结论", "t": "OOP 把数据和行为绑在对象里，导致内存分散、虚函数跳转、代码归属不清、难测试；DOP 反过来以数据布局为中心组织代码。", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 核心结论", "t": "ECS 是 DOP 的工程化落地：Entity 是 ID，Component 是纯数据，System 是批量处理同构数据的逻辑；Unity DOTS 与 UE ", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 核心结论", "t": "Job System 让逻辑程序员用“小任务 + 依赖”表达并行，由调度器把任务映射到固定数量的工作线程上执行，避免频繁创建线程。", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 术语", "t": "Data Race / 数据竞争", "x": "多线程同时访问同一内存且至少一个写，结果依赖调度顺序。", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 术语", "t": "Context Switch / 上下文切换", "x": "保存/恢复线程状态，需进内核，开销远大于函数调用。", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 术语", "t": "Atomic Operation / 原子操作", "x": "不可分割的读改写，用于无锁编程。", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 术语", "t": "Memory Barrier / 内存屏障", "x": "约束编译器/CPU 重排，保证读写顺序可见性。", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 术语", "t": "Task Graph / 任务图", "x": "用 DAG 表达任务与依赖，节点是任务、边是依赖。", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 术语", "t": "Fiber / 纤程", "x": "用户态手动调度的执行上下文，切换不陷入内核。", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 术语", "t": "Job Stealing / 工作窃取", "x": "空闲线程从其他线程队列偷任务，实现负载均衡。", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 术语", "t": "Cache Line / 缓存行", "x": "内存与缓存间搬运的固定大小数据块。", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 术语", "t": "False Sharing / 伪共享", "x": "多线程写同一缓存行不同变量，导致缓存行来回同步。", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 术语", "t": "ECS / 实体组件系统", "x": "Entity 是 ID、Component 是数据、System 是批量逻辑的数据导向模式。", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 练习", "t": "解释为什么“线程数越多并行越快”是错的，并说明 Job System 为什么用固定数量的工作线程。", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 练习", "t": "一个粒子系统有 100 万个粒子，每帧只更新位置。分别用 AoS（`struct {vec3 pos; vec3 vel; color c;}` 的数组）和 S", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 练习", "t": "两个线程分别高频自增同一结构体里的 `counterA` 和 `counterB`，两者在内存中相邻。程序正确但很慢，为什么？怎么改？", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 练习", "t": "画出一个任务图：A 完成后才能做 B 和 C，B、C 都完成后才能做 D。说明调度器如何用依赖计数判断 D 就绪。", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L20 · 练习", "t": "在 Unity DOTS 或 UE Mass 中任选其一，说明 Entity/Component/System 三者在 API 上的对应物，并解释 Archet", "x": "", "u": "GAMES104/104_L20.html"}, {"c": "GAMES104 L18 · 第 18 讲：在线游戏架构——从网络协议到状态同步", "t": "1. 为什么联机这么难：五大挑战与全讲地图", "x": "单机游戏里，玩家输入 → 游戏逻辑 → 渲染，全在一台机器上，顺序确定、延迟为零。一旦联机，这条链被网络劈成两半，问题就全冒出来了。课件把挑战归纳为五类：\n\n一致性（Consistency）：所有玩家看到的游戏世界必须一致，否则「我明明打中了」就会变成争吵。\n可靠性（Reliability）：网络会", "u": "GAMES104/104_L18.html#s1"}, {"c": "GAMES104 L18 · 第 18 讲：在线游戏架构——从网络协议到状态同步", "t": "2. 网络基础：分层、Socket 与 TCP/UDP 的真实性格", "x": "两台 PC 要通信，必须先约定「说什么语言」（协议）、「怎么找到对方」（地址与端口）。课件从互联网之父设计 TCP/IP 讲起，核心思想是分层：应用层（HTTP、SSH、FTP、游戏协议）不关心底下怎么传，中间层（TCP/UDP）负责端到端，网络层（IP）负责寻址路由，链路层负责物理传输。OSI 七", "u": "GAMES104/104_L18.html#s2"}, {"c": "GAMES104 L18 · 第 18 讲：在线游戏架构——从网络协议到状态同步", "t": "3. 在 UDP 上造可靠：ARQ、滑动窗口与 FEC 的混合拳", "x": "既然直接用 TCP 不行、裸 UDP 又太野，工程上的答案是自定义可靠 UDP。课件把它拆成两套互补机制。\n第一套：ARQ（自动重传请求），靠反馈重传。基础三件套是：\n\nACK + 序列号：接收方确认收到哪些序号，发送方据此知道谁丢了。\n超时重传：等不到 ACK 就重发。\n\n滑动窗口：一次发多个包（", "u": "GAMES104/104_L18.html#s3"}, {"c": "GAMES104 L18 · 第 18 讲：在线游戏架构——从网络协议到状态同步", "t": "4. 时钟同步：NTP 与流式估计，联机的地基", "x": "联机里「现在几点」不是哲学问题，而是工程问题：客户端和服务器时钟不一致，就没法判断「这个输入是早还是晚」，也没法做延迟补偿。\n\\n先定义 RTT（往返时延）：从发出到收到回应的时间，包含发送/接收处理、传播延迟、排队延迟。RTT 的一半常被当作单程延迟的估计。\nNTP（网络时间协议） 的思路很巧：客", "u": "GAMES104/104_L18.html#s4"}, {"c": "GAMES104 L18 · 第 18 讲：在线游戏架构——从网络协议到状态同步", "t": "5. 从 Socket 到 RPC：让网络调用像本地函数", "x": "直接用 Socket 编程很痛苦：要手写序列化、处理粘包、管理连接、写一堆 if-else 分发消息类型。课件把这叫「still not great」。于是有了消息通信的抽象：客户端发「嘿，做件事」，服务器回结果，而不是直接操作字节流。\n\\n再往上就是 RPC（远程过程调用）：让调用远程函数像调用本", "u": "GAMES104/104_L18.html#s5"}, {"c": "GAMES104 L18 · 第 18 讲：在线游戏架构——从网络协议到状态同步", "t": "6. 网络拓扑：P2P、主机式与专用服务器", "x": "谁来当「真相的来源」，决定了拓扑。\n\n纯 P2P：每个客户端把游戏事件广播给其他所有客户端，没有中心。实现简单、延迟低（直连），但 N 个玩家就有 \\(O(N^2)\\) 条连接，作弊无法监管，掉线影响大。\n主机式 P2P（Host Server）：选一个玩家当「主机」，其他人连他。省服务器成本，但主", "u": "GAMES104/104_L18.html#s6"}, {"c": "GAMES104 L18 · 第 18 讲：在线游戏架构——从网络协议到状态同步", "t": "7. 同步三大流派：快照、帧同步与状态同步", "x": "这是全讲的核心。课件把同步方法分为三类：\n快照同步（Snapshot Synchronization）：客户端把输入发给服务器，服务器按 tick 模拟，定期把整个世界状态的快照发给客户端，客户端渲染。问题是快照到达有抖动（jitter），直接渲染会卡顿，于是用快照插值（延迟一小段时间，在两个快照间", "u": "GAMES104/104_L18.html#s7"}, {"c": "GAMES104 L18 · 第 18 讲：在线游戏架构——从网络协议到状态同步", "t": "8. 帧同步的命门：确定性、浮点与随机数", "x": "帧同步的优雅建立在「确定性」上：相同输入 + 相同初始状态 = 相同结果。但计算机偏偏不保证这点。\n浮点数是头号杀手。IEEE 754 浮点在不同 CPU、不同编译器优化、不同指令集（x87 80 位中间精度 vs SSE）下，舍入可能不同，累积几百帧后位置就分叉了。课件给的解法是定点数（Fixed", "u": "GAMES104/104_L18.html#s8"}, {"c": "GAMES104 L18 · 第 18 讲：在线游戏架构——从网络协议到状态同步", "t": "9. 状态同步的工程细节：预测、校正与重连", "x": "状态同步的骨架是：服务器权威模拟，客户端发输入、收状态。但直接这么做，玩家会感觉「按了键要等一个 RTT 才动」，这就是哑客户端问题。\n客户端预测（Client-side Prediction）：客户端按下输入后，立刻在本地按同样规则模拟一遍，画面马上响应。同时把输入存入环形缓冲（ring buff", "u": "GAMES104/104_L18.html#s9"}, {"c": "GAMES104 L18 · 核心结论", "t": "联机游戏的核心矛盾是「一致性 vs 响应性」，所有同步方案都是在这条轴上做取舍。", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 核心结论", "t": "TCP 可靠但队头阻塞、重传延迟不可控；UDP 快但会丢包乱序，所以游戏普遍在 UDP 上自建可靠层。", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 核心结论", "t": "可靠 UDP = ARQ（ACK/序列号/滑动窗口/重传）+ FEC（冗余包，用带宽换延迟），按场景混合使用。", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 核心结论", "t": "时钟同步是联机的地基：NTP 用四次时间戳估计偏移与 RTT，流式同步则持续采样剔除高延迟样本。", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 核心结论", "t": "网络拓扑从纯 P2P、主机式 P2P 到专用服务器（Dedicated Server），权威性与作弊难度依次提高。", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 核心结论", "t": "快照同步简单但带宽高、有抖动；帧同步带宽极低但要求严格确定性，浮点与随机数是最大敌人。", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 核心结论", "t": "状态同步由服务器授权，客户端预测 + 服务器校正（回滚重放）解决「哑客户端」手感问题。", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 核心结论", "t": "帧同步难防作弊（服务器无法验证客户端模拟），状态同步天然更适合 PVP 竞技。", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 术语", "t": "RTT / 往返时延", "x": "一个包从发出到收到回应的时间，常被用作延迟估计。", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 术语", "t": "ARQ / 自动重传请求", "x": "靠 ACK 与超时重传保证可靠，含停等/回退 N/选择重传。", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 术语", "t": "FEC / 前向纠错", "x": "发冗余包，丢包时无需重传即可恢复，用带宽换延迟。", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 术语", "t": "NTP / 网络时间协议", "x": "用四次时间戳估计时钟偏移与 RTT。", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 术语", "t": "RPC / 远程过程调用", "x": "让远程调用像本地函数，靠 IDL 与 Stub 生成。", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 术语", "t": "Lockstep / 帧同步", "x": "只传输入，各端用确定性逻辑模拟出相同结果。", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 术语", "t": "Snapshot / 快照同步", "x": "服务器定期发送世界状态，客户端插值渲染。", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 术语", "t": "Client-side Prediction / 客户端预测", "x": "本地先模拟输入以消除等待感。", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 术语", "t": "Server Reconciliation / 服务器校正", "x": "服务器结果与预测不符时回滚重放未确认输入。", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 术语", "t": "Determinism / 确定性", "x": "相同输入必得相同结果，帧同步的前提。", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 练习", "t": "为什么实时动作游戏通常不直接用 TCP，而选择在 UDP 上自建可靠层？请从队头阻塞和重传价值两个角度回答。", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 练习", "t": "NTP 中客户端记录 t0=1000ms（发出）、服务器 t1=1050ms（收到）、t2=1052ms（发出）、客户端 t3=1110ms（收到）。求时钟偏移", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 练习", "t": "帧同步中，两个客户端用 float 做位置积分，跑 500 帧后位置出现微小差异并逐渐放大。请给出至少两条根因与对应解法。", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 练习", "t": "状态同步中，客户端预测后收到服务器校正，发现位置不一致。请描述客户端应执行的步骤。", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES104 L18 · 练习", "t": "为一个 4 人合作的 PVE 射击游戏选同步方案：要求低延迟手感、服务器能防作弊、带宽可接受。请给出你的架构选择并说明理由。", "x": "", "u": "GAMES104/104_L18.html"}, {"c": "GAMES105 L01 · 第 1 讲：3D 角色动画导论——从关键帧到物理与学习", "t": "1. 角色动画在 3D 图形流水线中的位置", "x": "先建立全局图景。3D 计算机图形学通常被拆成三大块：几何（Geometry）负责“长什么样”，动画（Animation）负责“怎么动”，渲染（Rendering）负责“看起来如何”。角色动画属于中间那块，它的输出是一串随时间变化的姿态（pose），渲染再把这些姿态画成像素。\n课件进一步把 3D 计算", "u": "GAMES105/105_L01.html#s1"}, {"c": "GAMES105 L01 · 第 1 讲：3D 角色动画导论——从关键帧到物理与学习", "t": "2. 运动从哪来：神经→肌肉→力→姿态，以及两条技术路线", "x": "课件用一条因果链回答“运动从哪来”：神经元兴奋（Neuronal excitation）→ 肌肉激活（Muscle activation）→ 作用于骨骼肌肉系统的力/力矩（Forces/torques）→ 物理 → 身体姿态（Body pose）。这是生物体的真实产生过程。\n角色动画的两大方法，本质", "u": "GAMES105/105_L01.html#s2"}, {"c": "GAMES105 L01 · 第 1 讲：3D 角色动画导论——从关键帧到物理与学习", "t": "3. 运动学主线：关键帧、FK/IK 与插值", "x": "运动学方法最典型的代表是关键帧动画（Keyframe Animation）：动画师在时间轴上摆出若干关键姿态，软件在关键帧之间做插值（Interpolation），生成连续运动。课件引用了《The Animator's Survival Kit》和迪士尼十二动画原则，强调关键帧动画不仅是技术，更是表", "u": "GAMES105/105_L01.html#s3"}, {"c": "GAMES105 L01 · 第 1 讲：3D 角色动画导论——从关键帧到物理与学习", "t": "4. 数据驱动主线：动作捕捉、重定向与动作图", "x": "当手工关键帧成本太高时，工业界转向动作捕捉（Motion Capture）：让真人演员穿上动捕服表演，直接记录关节运动。课件展示了《战神：诸神黄昏》的幕后动捕、光学动捕、以及基于视频的 2D/3D 姿态估计（如 OpenPose、DeepMotion）。\n动捕数据不能直接套到任意角色上，因为源角色和", "u": "GAMES105/105_L01.html#s4"}, {"c": "GAMES105 L01 · 第 1 讲：3D 角色动画导论——从关键帧到物理与学习", "t": "5. 物理主线：PD 控制、轨迹优化与抽象模型", "x": "物理方法的核心是：不直接改姿态，而是施加力/力矩，让仿真产生姿态。课件先复习力矩定义：\\(\\tau = \\sum_i r_i \\times F_i\\)，即力臂叉乘力。\n最常用的低层控制器是比例-微分控制（Proportional-Derivative, PD）：\n\\[\n\\tau = k_p (\\ti", "u": "GAMES105/105_L01.html#s5"}, {"c": "GAMES105 L01 · 第 1 讲：3D 角色动画导论——从关键帧到物理与学习", "t": "6. 学习主线：强化学习、生成模型与跨模态合成", "x": "当手工设计控制器太贵时，深度强化学习（Deep Reinforcement Learning, DRL）提供了一条新路：把控制问题建模为马尔可夫决策过程——智能体（Agent）在环境（Environment）中根据状态 \\(s\\) 输出动作 \\(a\\)，获得奖励 \\(r\\)。通过最大化累积奖励，网络", "u": "GAMES105/105_L01.html#s6"}, {"c": "GAMES105 L01 · 第 1 讲：3D 角色动画导论——从关键帧到物理与学习", "t": "7. 统一视角：控制信号→运动模型→下一状态", "x": "课件最后用两张对比图收束全讲：\n\n运动学方法：控制信号 → 运动模型 → 下一状态。运动模型直接根据控制信号算出下一姿态，没有物理仿真。\n物理方法：控制信号 → 运动控制 → 物理仿真 → 下一状态。控制信号先变成力/力矩，再由物理引擎积分出下一状态。\n\n这个统一视角的价值在于：无论你面对的是关键帧", "u": "GAMES105/105_L01.html#s7"}, {"c": "GAMES105 L01 · 核心结论", "t": "角色动画的本质是生成人体（或生物）关节随时间的运动，核心难点是高维、受物理约束且需自然可信。", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 核心结论", "t": "角色动画方法可分成两大阵营：运动学方法（直接编辑姿态/速度）与物理方法（施力/力矩，由仿真产生运动）。", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 核心结论", "t": "关键帧动画依赖动画师手工摆姿势并插值，是工业界最成熟、最可控的管线基础。", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 核心结论", "t": "动作捕捉提供高质量真实数据，但需要重定向（retargeting）才能适配不同骨架与体型。", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 核心结论", "t": "动作图/状态机把片段组织成可交互系统，Motion Matching 用数据库检索替代手工连边，显著降低状态机复杂度。", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 核心结论", "t": "物理方法用 PD 控制器跟踪目标姿态，或用轨迹优化、抽象模型、强化学习生成控制策略，能产生真实接触与交互。", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 核心结论", "t": "学习型方法（生成模型、跨模态合成）让角色能从文本、音频、稀疏传感器等信号生成动作，是当前研究前沿。", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 核心结论", "t": "所有方法最终都落在同一个抽象上：给定当前状态与控制信号，产生下一状态；区别只在“运动模型”是运动学还是物理仿真。", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 术语", "t": "Character Animation / 角色动画", "x": "生成人/动物/虚拟生物等角色随时间变化的运动。", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 术语", "t": "Forward Kinematics (FK) / 正向运动学", "x": "已知关节旋转，计算末端执行器位置。", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 术语", "t": "Inverse Kinematics (IK) / 反向运动学", "x": "已知末端执行器目标位置，反解关节旋转。", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 术语", "t": "Motion Capture / 动作捕捉", "x": "记录真人演员运动并映射到虚拟角色。", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 术语", "t": "Motion Retargeting / 动作重定向", "x": "把源角色运动映射到不同骨架/体型的角色。", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 术语", "t": "Motion Graphs / State Machines / 动作图/状态机", "x": "用节点和边组织动作片段，支持交互切换。", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 术语", "t": "Motion Matching / 运动匹配", "x": "每帧从动作数据库中检索最匹配的下一帧，替代手工连边。", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 术语", "t": "PD Control / 比例-微分控制", "x": "用比例项拉向目标、微分项提供阻尼的经典控制器。", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 术语", "t": "Deep Reinforcement Learning (DRL) / 深度强化学习", "x": "通过奖励信号训练神经网络控制策略。", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 术语", "t": "Cross-Modal Synthesis / 跨模态合成", "x": "从文本、音频等非运动信号生成动作。", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 练习", "t": "用自己的话解释运动学方法与物理方法的核心区别，并各举一个适合的应用场景。", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 练习", "t": "给定 PD 控制公式 \\(\\tau = k_p (\\tilde{q} - q) + k_d (\\dot{\\tilde{q}} - \\dot{q})\\)，说明 \\", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 练习", "t": "动作重定向（Motion Retargeting）要解决什么问题？列出至少三个需要处理的差异。", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 练习", "t": "假设你要在 UE 中实现一个“角色走到桌前拿起水杯”的交互，请描述你会用到哪些动画技术，并说明它们分别属于运动学还是物理方法。", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L01 · 练习", "t": "为什么课程强调“不教 Maya/UE 操作，而教方法原理”？结合本讲的方法地图谈谈你的理解。", "x": "", "u": "GAMES105/105_L01.html"}, {"c": "GAMES105 L02 · 第 2 讲：线性代数复习——从向量、矩阵到四元数旋转", "t": "1. 向量：既有大小又有方向", "x": "向量（vector）是既有大小（magnitude）又有方向（direction）的量。在角色动画里，它既可以表示位置、速度，也可以表示抽象的方向，比如骨骼的朝向、关节的旋转轴。\n表示：在笛卡尔坐标系中，三维向量写成三个分量的列向量：\n\\[ \\mathbf{a} = \\begin{bmatrix} ", "u": "GAMES105/105_L02.html#s1"}, {"c": "GAMES105 L02 · 第 2 讲：线性代数复习——从向量、矩阵到四元数旋转", "t": "2. 矩阵：旋转与变换的载体", "x": "矩阵（matrix）是二维数组。在图形学里，我们主要用 3×3 矩阵表示旋转/缩放，用 4×4 矩阵表示包含平移的仿射变换。\n基本运算：\n\n转置（transpose）：\\( (A^T)_{ij} = A_{ji} \\)，行列互换。\n数乘与加法：逐元素进行。\n矩阵乘法：\\( (AB)_{ij} = \\", "u": "GAMES105/105_L02.html#s2"}, {"c": "GAMES105 L02 · 第 2 讲：线性代数复习——从向量、矩阵到四元数旋转", "t": "3. 旋转的轴角表示与 Rodrigues 公式", "x": "给定两个向量 a 和 b，如何求把 a 转到 b 的旋转？\n旋转轴：取叉积方向 \\( \\mathbf{u} = \\frac{\\mathbf{a}\\times\\mathbf{b}}{\\|\\mathbf{a}\\times\\mathbf{b}\\|} \\)。注意，任何在 a、b 角平分面内的向量都可以作为轴", "u": "GAMES105/105_L02.html#s3"}, {"c": "GAMES105 L02 · 第 2 讲：线性代数复习——从向量、矩阵到四元数旋转", "t": "4. 正交基与坐标变换", "x": "正交基（orthogonal basis）是一组两两垂直、长度为 1 的基向量 \\( \\mathbf{e}_x, \\mathbf{e}_y, \\mathbf{e}_z \\)。任何向量都可以写成它们的线性组合：\n\\[ \\mathbf{a} = a_x \\mathbf{e}_x + a_y \\mathb", "u": "GAMES105/105_L02.html#s4"}, {"c": "GAMES105 L02 · 第 2 讲：线性代数复习——从向量、矩阵到四元数旋转", "t": "5. 旋转的四种表示：矩阵、欧拉角、轴角、四元数", "x": "同一个三维旋转有很多种表示方式，课件对比了四种，每种都有取舍。\n旋转矩阵（rotation matrix）：3×3 正交矩阵，行列式为 1。优点是组合旋转就是矩阵乘法，应用旋转就是矩阵乘向量，非常方便；缺点是 9 个参数只有 3 个自由度，冗余大，且不能直接线性插值。\n欧拉角（Euler angle", "u": "GAMES105/105_L02.html#s5"}, {"c": "GAMES105 L02 · 第 2 讲：线性代数复习——从向量、矩阵到四元数旋转", "t": "6. 四元数：定义、运算与旋转", "x": "四元数（quaternion）是复数的推广：\n\\[ q = w + x\\mathbf{i} + y\\mathbf{j} + z\\mathbf{k} \\]\n其中 \\( \\mathbf{i}^2 = \\mathbf{j}^2 = \\mathbf{k}^2 = \\mathbf{ijk} = -1 \\)，且", "u": "GAMES105/105_L02.html#s6"}, {"c": "GAMES105 L02 · 第 2 讲：线性代数复习——从向量、矩阵到四元数旋转", "t": "7. 旋转插值：为什么不能直接线性插值，SLERP 怎么做", "x": "动画里经常需要在两个旋转之间过渡。平移可以直接线性插值：\\( \\mathbf{x}(t) = (1-t)\\mathbf{x}_0 + t\\mathbf{x}_1 \\)。但旋转不行。\n直接线性插值旋转矩阵：\\( R(t) = (1-t)R_0 + tR_1 \\) 一般不再是旋转矩阵（不正交），会导致缩", "u": "GAMES105/105_L02.html#s7"}, {"c": "GAMES105 L02 · 核心结论", "t": "向量点积给出夹角余弦与投影长度，叉积给出垂直于两向量的轴，两者是旋转计算的基础。", "x": "", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 核心结论", "t": "绕单位轴 u 旋转 θ 的矩阵可用 Rodrigues 公式 R = I + sinθ [u]× + (1-cosθ)[u]×² 构造。", "x": "", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 核心结论", "t": "旋转矩阵是正交矩阵且行列式为 1，逆等于转置，组合旋转就是矩阵相乘。", "x": "", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 核心结论", "t": "欧拉角直观但有万向锁和约定依赖问题；轴角紧凑但表示不唯一；四元数无万向锁且适合插值。", "x": "", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 核心结论", "t": "单位四元数 q = (cos(θ/2), u sin(θ/2)) 与轴角一一对应，旋转向量用 p' = q p q*。", "x": "", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 核心结论", "t": "旋转不能直接线性插值，SLERP 在单位四元数球面上沿大圆插值，保证角速度恒定。", "x": "", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 术语", "t": "dot product / 点积", "x": "两向量对应分量乘积之和，几何上等于模长乘积乘夹角余弦。", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 术语", "t": "cross product / 叉积", "x": "三维向量特有的运算，结果垂直于原两向量，方向由右手定则决定。", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 术语", "t": "Rodrigues' rotation formula / 罗德里格斯旋转公式", "x": "用轴和角直接构造旋转矩阵的公式。", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 术语", "t": "orthogonal matrix / 正交矩阵", "x": "满足 A^T A = I 的矩阵，逆等于转置，旋转矩阵是正交矩阵。", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 术语", "t": "Euler angles / 欧拉角", "x": "用绕三个坐标轴的转角表示旋转，直观但有万向锁问题。", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 术语", "t": "gimbal lock / 万向锁", "x": "欧拉角中两个旋转轴平行导致丢失一个自由度。", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 术语", "t": "quaternion / 四元数", "x": "形如 w + xi + yj + zk 的数，单位四元数可表示三维旋转。", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 术语", "t": "SLERP / 球面线性插值", "x": "在单位球面上沿大圆插值，保证角速度恒定。", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 术语", "t": "skew-symmetric matrix / 反对称矩阵", "x": "满足 A^T = -A 的矩阵，叉积可写成反对称矩阵乘向量。", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 练习", "t": "已知 a = (1, 0, 0)，b = (0, 1, 0)，求 a·b、a×b，并说明叉积结果的几何意义。", "x": "", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 练习", "t": "用 Rodrigues 公式写出绕 z 轴旋转 θ 的旋转矩阵，并与标准 Rz(θ) 对比。", "x": "", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 练习", "t": "为什么旋转矩阵不能直接线性插值？四元数直接线性插值有什么问题？", "x": "", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L02 · 练习", "t": "在 UE 中，如何把一个 FRotator 转成 FQuat 再做 SLERP？写出关键代码。", "x": "", "u": "GAMES105/105_L02.html"}, {"c": "GAMES105 L04 · 第 4 讲：角色运动学（续）与关键帧动画", "t": "1. 参考姿态：旋转的“零点”与重定向问题的由来", "x": "上一讲把正向运动学（Forward Kinematics, FK）讲完了：给定每个关节相对父关节的局部旋转 \\(Q_i\\) 和骨长 \\(\\boldsymbol{l}_i\\)，从根节点一路累乘就能算出每个关节的全局位置和朝向。这一讲先补一个容易被忽略的前提——参考姿态（reference pose /", "u": "GAMES105/105_L04.html#s1"}, {"c": "GAMES105 L04 · 第 4 讲：角色运动学（续）与关键帧动画", "t": "2. 单关节与链式重定向：把参考姿态差异算成一个全局偏移", "x": "先看最简单的情况：只有一个物体（或一个关节），A、B 的参考姿态分别对应全局旋转 \\(R_A\\)、\\(R_B\\)（这里把参考姿态本身也看成相对世界的一个朝向）。我们希望找一个全局偏移 \\(R_{A\\to B}\\)，使得在参考姿态下把 A 的朝向“搬”到 B 上：\n\\[ R_B = R_A \\, R_", "u": "GAMES105/105_L04.html#s2"}, {"c": "GAMES105 L04 · 第 4 讲：角色运动学（续）与关键帧动画", "t": "3. CCD：一次只转一个关节的迭代 IK", "x": "逆运动学（Inverse Kinematics, IK）是已知末端目标 \\(\\tilde{\\boldsymbol{x}}\\)，求关节角 \\(\\boldsymbol{\\theta}\\)。课件先回顾把它写成优化问题：\n\\[ \\min_{\\boldsymbol{\\theta}} \\; \\big\\| f(\\", "u": "GAMES105/105_L04.html#s3"}, {"c": "GAMES105 L04 · 第 4 讲：角色运动学（续）与关键帧动画", "t": "4. 雅可比方法与全身 IK：把末端速度映射回关节速度", "x": "雅可比矩阵（Jacobian matrix）\\(J\\) 描述末端位置对关节角的偏导：\n\\[ J = \\frac{\\partial f}{\\partial \\boldsymbol{\\theta}} = \\left[ \\frac{\\partial f}{\\partial \\theta_1} \\; \\fr", "u": "GAMES105/105_L04.html#s4"}, {"c": "GAMES105 L04 · 第 4 讲：角色运动学（续）与关键帧动画", "t": "5. 关键帧与插值：阶跃、线性与连续性", "x": "从这一节开始进入关键帧动画（keyframe animation）。课件用走马灯（zoetrope）说明动画的本质是离散画面快速播放；在数字动画里，美术只摆少量关键帧（keyframe），中间帧（in-betweens）由插值算法生成。\n插值的数学定义：给定数据点 \\(D = \\{(x_i, y_i", "u": "GAMES105/105_L04.html#s5"}, {"c": "GAMES105 L04 · 第 4 讲：角色运动学（续）与关键帧动画", "t": "6. 多项式插值与 Runge 现象：为什么不用一条高次曲线", "x": "最直接的想法是用一个 \\(n\\) 次多项式 \\(f(x) = a_0 + a_1 x + \\cdots + a_n x^n\\) 穿过所有 \\(N\\) 个点。因为 \\(N\\) 个点给出 \\(N\\) 个方程，恰好能定出 \\(N\\) 个系数（\\(n = N-1\\)）。课件展示了这个线性方程组的矩阵形式，并", "u": "GAMES105/105_L04.html#s6"}, {"c": "GAMES105 L04 · 第 4 讲：角色运动学（续）与关键帧动画", "t": "7. 三次样条与 Hermite 基函数：工程上真正用的插值", "x": "样条插值（spline interpolation）用分段低次多项式：\\(f(x) = S_i(x)\\) 当 \\(x \\in [x_i, x_{i+1}]\\)。课件从分段线性（C0）讲到三次多项式（C2），并说明三次是“能保证 C2 连续的最低次数”。\n对每个区间，三次多项式写成 \\(S_i(x) ", "u": "GAMES105/105_L04.html#s7"}, {"c": "GAMES105 L04 · 第 4 讲：角色运动学（续）与关键帧动画", "t": "8. 旋转的插值：为什么必须用四元数 SLERP", "x": "位置可以逐分量插值，旋转不行。课件列出旋转的几种表示：旋转矩阵、欧拉角、轴角、四元数。对矩阵元素直接线性插值会破坏正交性（插值结果不再是旋转）；对欧拉角线性插值会在万向节附近出现诡异路径，而且“绕哪个轴转”依赖参数化。\n四元数（quaternion）\\(\\boldsymbol{q} = (w, \\b", "u": "GAMES105/105_L04.html#s8"}, {"c": "GAMES105 L04 · 核心结论", "t": "参考姿态（bind/reference pose）是旋转的“零点”，两个角色参考姿态不同，同一组局部旋转会摆出不同姿势，所以重定向必须做参考姿态之间的变换。", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 核心结论", "t": "单关节重定向的核心是找一个全局偏移 \\(R_{A\\to B}\\)，使得 \\(R_B = R_A R_{A\\to B}\\) 在参考姿态下成立；链式重定向则把这个偏", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 核心结论", "t": "CCD 每次只转一个关节，让“该关节到末端”的向量指向目标，反复扫过所有关节直到收敛，简单但可能不自然。", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 核心结论", "t": "雅可比矩阵把关节角速度映射到末端线速度，几何上每个铰链关节贡献 \\(\\boldsymbol{a}\\times\\boldsymbol{r}\\)；球关节可拆成多个铰", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 核心结论", "t": "全身 IK 的难点是根节点也参与运动链，以及多个约束（手、脚）同时存在，通常用带权最小二乘或分约束轮流求解。", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 核心结论", "t": "关键帧动画 = 少量关键帧 + 插值；阶跃不连续、线性只有 C0，三次样条能做到 C1/C2 连续。", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 核心结论", "t": "高次多项式插值会出现 Runge 现象（边缘振荡），所以实践中用分段低次样条（三次）而不是一个高次多项式。", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 核心结论", "t": "三次 Hermite 由两端点的值和切线决定，Catmull-Rom 用相邻点差分当切线；旋转插值要用四元数 SLERP，不能对欧拉角或矩阵元素直接线性插值。", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 术语", "t": "Reference Pose / Bind Pose / 参考姿态/绑定姿态", "x": "所有局部旋转为单位阵时的骨架姿态，是旋转的零点。", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 术语", "t": "Motion Retargeting / 运动重定向", "x": "把一套骨架的动画映射到另一套骨架，需处理参考姿态差异。", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 术语", "t": "CCD / 循环坐标下降", "x": "每次只转一个关节使末端指向目标的迭代 IK。", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 术语", "t": "Jacobian Matrix / 雅可比矩阵", "x": "末端位置对关节角的偏导矩阵，把关节速度映射为末端速度。", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 术语", "t": "Full-body IK / 全身 IK", "x": "多约束、运动链穿过根节点的 IK 问题。", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 术语", "t": "Keyframe / 关键帧", "x": "美术手工摆放的关键姿态，中间帧由插值生成。", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 术语", "t": "C0/C1/C2 Continuity / C0/C1/C2 连续性", "x": "位置/速度/加速度连续，动画至少需要 C1。", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 术语", "t": "Runge's Phenomenon / 龙格现象", "x": "高次多项式插值在区间边缘剧烈振荡。", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 术语", "t": "Cubic Hermite Spline / 三次 Hermite 样条", "x": "由端点值和切线决定的三次曲线，四个基函数。", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 术语", "t": "SLERP / 球面线性插值", "x": "单位四元数之间的等角速度插值，保证结果为旋转。", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 练习", "t": "设角色 A 的参考姿态全局旋转为 \\(R_A\\)，角色 B 为 \\(R_B\\)。写出单关节重定向的全局偏移 \\(R_{A\\to B}\\)，并说明当 A 的局部旋", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 练习", "t": "用 CCD 解一个两骨 IK：根在原点，骨长均为 1，目标在 \\((2,0)\\)。描述第一轮迭代后末端能否到达目标，若不能说明原因和拉伸处理。", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 练习", "t": "写出三次 Hermite 插值的四个基函数，并验证 \\(H_{00}(0)=1\\)、\\(H_{00}(1)=0\\)、\\(H_{00}'(0)=0\\)。", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 练习", "t": "为什么旋转不能用欧拉角线性插值？给出一个会出问题的具体例子。", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L04 · 练习", "t": "在 UE 里做一个实验：给同一个角色导入两套参考姿态不同的动画（T-Pose 与 A-Pose），观察直接播放与用 IK Retargeter 重定向的差异，记", "x": "", "u": "GAMES105/105_L04.html"}, {"c": "GAMES105 L06 · 第 6 讲：基于学习的角色动画", "t": "1. 从“片段末尾做决定”到“每一帧做决定”", "x": "交互式角色动画要解决的问题只有一句话：角色如何响应用户输入。课件先把最朴素的方案摆出来：检查用户输入 → 找一段合适的动画片段 → 播放它。运动图（Motion Graph）与状态机（State Machine）就是这套思路的代表：把动捕片段当作节点，把可以无缝衔接的帧对当作边，在当前片段快要结束时", "u": "GAMES105/105_L06.html#s1"}, {"c": "GAMES105 L06 · 第 6 讲：基于学习的角色动画", "t": "2. Motion Matching：用特征距离找“下一个姿态”", "x": "运动匹配的核心循环可以写成四步：检查用户输入 → 在当前状态附近找最近邻 → 把当前姿态平滑混合到最近邻姿态 → 更新角色。关键在第二步：什么叫“最近”？课件给出一个统一形式：\n\\[ \\text{next\\_pose} = \\arg\\min_{i \\in \\text{Dataset}} \\lVert", "u": "GAMES105/105_L06.html#s2"}, {"c": "GAMES105 L06 · 第 6 讲：基于学习的角色动画", "t": "3. 人体运动为什么是低维的：PCA 的直觉", "x": "课件先问一个看似哲学的问题：什么看起来才“自然”？然后给出可操作的答案：自然动作不是姿态空间里随便一个点，而是落在一个低维结构附近。原因有三：手臂与腿的运动是协调的（不会各走各的）、骨骼肌肉结构限制了关节组合、物理规律约束了运动。于是“整个姿态空间”很大，但“自然姿态”只占其中很小一片——这就是人体", "u": "GAMES105/105_L06.html#s3"}, {"c": "GAMES105 L06 · 第 6 讲：基于学习的角色动画", "t": "4. 从 PCA 到“自然度”：把先验写进 IK", "x": "PCA 不只是压缩工具，它还给出一个可计算的“自然度”。课件指出：在 PCA 空间里，一个姿态的得分相对其特征值 \\(\\sigma_k\\) 越小，越可能自然；换句话说，偏离主成分方向越少越自然。这等价于用高斯分布 \\(p(x) = \\mathcal{N}(\\bar{x}, \\Sigma)\\) 评价姿", "u": "GAMES105/105_L06.html#s4"}, {"c": "GAMES105 L06 · 第 6 讲：基于学习的角色动画", "t": "5. 概率视角：高斯先验及其不足", "x": "把“自然度”正式化，就是定义一个概率密度 \\(p(x)\\)：\\(x\\) 是自然姿态的概率。给定动捕姿态数据集 \\(x_i\\)，课件用高斯分布建模：\n\\[ p(x) = \\mathcal{N}(\\mu, \\Sigma) = \\frac{1}{\\sqrt{(2\\pi)^k |\\Sigma|}} \\exp", "u": "GAMES105/105_L06.html#s5"}, {"c": "GAMES105 L06 · 核心结论", "t": "交互式动画的本质是“读输入 → 选片段/姿态 → 播放或过渡”，区别只在于决策发生在片段末尾还是每一帧。", "x": "", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 核心结论", "t": "Motion Matching 把“选片段”换成“逐帧找最近邻姿态”，用特征向量距离定义相似度，再用弹簧/惯性化混合平滑过渡。", "x": "", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 核心结论", "t": "人体运动是低维的：协调性、骨骼肌肉结构与物理规律让自然姿态落在高维姿态空间中的低维流形附近。", "x": "", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 核心结论", "t": "PCA 用均值加若干主成分的加权和近似姿态，主成分是协方差矩阵的特征向量，特征值代表该方向解释的方差。", "x": "", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 核心结论", "t": "在 PCA 空间里，得分相对特征值越小（偏离主成分方向越少）的姿态越可能自然，这给出了一个可计算的“自然度”先验。", "x": "", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 核心结论", "t": "把先验写进 IK 目标函数（残差项 + λ·先验项）就能在满足末端约束的同时把姿态拉向自然流形。", "x": "", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 核心结论", "t": "单个高斯不足以描述多模态的运动分布，于是有 GMM、GPLVM 以及基于神经网络的运动先验。", "x": "", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 术语", "t": "Motion Graph / 运动图", "x": "以动捕片段为节点、可衔接帧对为边的图，在片段末尾做决策。", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 术语", "t": "Motion Matching / 运动匹配", "x": "逐帧在数据库中检索特征距离最近的姿态并平滑过渡。", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 术语", "t": "Feature Vector / 特征向量", "x": "描述运动意图的量（根速度、末端位置、未来朝向、脚接触等）。", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 术语", "t": "Inertialization Blending / 惯性化混合", "x": "用弹簧/惯性模型平滑过渡姿态，避免硬切跳变。", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 术语", "t": "Principal Component Analysis / 主成分分析", "x": "找方差最大的正交方向，用于降维与去相关。", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 术语", "t": "Explained Variance / 解释方差", "x": "特征值大小，表示该主成分解释了多少数据方差。", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 术语", "t": "Score / 得分", "x": "姿态在某个主成分方向上的投影系数 \\(w_k\\)。", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 术语", "t": "Gaussian Mixture Model / 高斯混合模型", "x": "多个高斯加权和，用于建模多模态运动分布。", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 术语", "t": "GPLVM / 高斯过程隐变量模型", "x": "用高斯过程把低维隐空间映射到高维姿态的先验模型。", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 术语", "t": "Motion Prior / 运动先验", "x": "评价姿态/动作是否自然的概率或惩罚项，常写进优化目标。", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 练习", "t": "说明 Motion Graph 与 Motion Matching 在“决策时机”和“决策单位”上的区别。", "x": "", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 练习", "t": "写出 Motion Matching 的最近邻目标式，并列出至少 5 类特征向量分量。", "x": "", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 练习", "t": "给定去均值后的数据矩阵 \\(X\\)，PCA 的主成分与特征值分别对应什么？如何用前 \\(n\\) 个主成分近似一个姿态？", "x": "", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 练习", "t": "在带运动先验的 IK 目标函数中，为什么先验项要除以 \\(\\sigma_k\\)？如果 \\(w\\) 取得过大或过小分别会出现什么现象？", "x": "", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L06 · 练习", "t": "为什么单个高斯分布不足以作为运动先验？课件给出了哪些后续模型？", "x": "", "u": "GAMES105/105_L06.html"}, {"c": "GAMES105 L08 · 第 8 讲：基于物理的模拟与关节刚体", "t": "1. 为什么需要物理模拟", "x": "运动学方法（如关键帧动画、动作捕捉）能产生逼真的角色动作，但有一个根本缺陷：角色无法与环境交互。例如角色推一个箱子、在斜坡上行走、被外力击倒，这些都需要根据物理规律实时计算反作用力。物理模拟通过求解动力学方程，让角色自然地响应环境。\n物理模拟的基本流程是：\n\n定义状态（位置、速度等）\n计算受力（重力", "u": "GAMES105/105_L08.html#s1"}, {"c": "GAMES105 L08 · 第 8 讲：基于物理的模拟与关节刚体", "t": "2. 质点动力学与数值积分", "x": "先从最简单的质点开始。质点的状态是位置 \\(x\\) 和速度 \\(v\\)，质量 \\(m\\)，受力 \\(f\\)。根据牛顿第二定律：\n\\[ f = ma \\]\n加速度 \\(a = \\dot{v}\\)，速度 \\(v = \\dot{x}\\)。因此：\n\\[ \\dot{v} = \\frac{f}{m}, \\qua", "u": "GAMES105/105_L08.html#s2"}, {"c": "GAMES105 L08 · 第 8 讲：基于物理的模拟与关节刚体", "t": "3. 刚体的运动学表示", "x": "刚体有位置 \\(x\\) 和朝向 \\(R\\)（旋转矩阵）。刚体上一点 \\(r\\)（在刚体局部坐标系中）的世界坐标为：\n\\[ x' = x + R r \\]\n对时间求导得到速度：\n\\[ \\dot{x}' = \\dot{x} + \\dot{R} r \\]\n其中 \\(\\dot{R}\\) 与角速度 \\(\\om", "u": "GAMES105/105_L08.html#s3"}, {"c": "GAMES105 L08 · 第 8 讲：基于物理的模拟与关节刚体", "t": "4. 刚体的动力学：质量、惯量与动量", "x": "刚体可以看作无数质点的集合。总质量 \\(M = \\sum m_i\\)，质心位置 \\(x_c = \\frac{\\sum m_i x_i}{M}\\)。\n线动量 \\(p = M v_c\\)，角动量 \\(L = I \\omega\\)，其中 \\(I\\) 是转动惯量张量：\n\\[ I = \\sum m_i (r_", "u": "GAMES105/105_L08.html#s4"}, {"c": "GAMES105 L08 · 第 8 讲：基于物理的模拟与关节刚体", "t": "5. 多刚体系统与约束", "x": "角色由多个刚体通过关节连接。每个刚体有自己的运动方程，关节施加约束力。\n约束：例如两个刚体在关节处的位置必须相同：\\(g(x) = 0\\)。对时间求导得到速度约束：\\(J v = 0\\)，其中 \\(J\\) 是雅可比矩阵。\n约束力不做功（理想约束），因此约束力可以写成 \\(f_c = J^T \\lam", "u": "GAMES105/105_L08.html#s5"}, {"c": "GAMES105 L08 · 第 8 讲：基于物理的模拟与关节刚体", "t": "6. 接触与摩擦", "x": "接触是角色与环境交互的关键。接触力需要满足：\n\n法向力非负（只能推不能拉）\n法向速度非负（不能穿透）\n法向力与法向速度互补：\\(f_n \\cdot v_n = 0\\)\n\n这构成了一个线性互补问题（LCP）。对于摩擦，还需满足库仑摩擦定律：\\(|f_t| \\le \\mu f_n\\)。\n接触可以建模为约", "u": "GAMES105/105_L08.html#s6"}, {"c": "GAMES105 L08 · 核心结论", "t": "物理模拟的核心是求解微分方程：已知力，通过数值积分更新状态", "x": "", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 核心结论", "t": "显式欧拉简单但不稳定，半隐式欧拉（辛欧拉）在游戏/实时模拟中最常用，隐式欧拉稳定但需解方程", "x": "", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 核心结论", "t": "刚体状态包括位置 x、朝向 R（或四元数 q）、线速度 v、角速度 ω", "x": "", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 核心结论", "t": "刚体运动方程：M v̇ = f，I ω̇ + ω × (Iω) = τ，其中 I 是转动惯量张量", "x": "", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 核心结论", "t": "多个刚体通过约束连接，约束力不做功，用雅可比矩阵 J 和拉格朗日乘子 λ 表示", "x": "", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 核心结论", "t": "约束求解最终化为线性系统（或 LCP），可用投影高斯-赛德尔等方法迭代求解", "x": "", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 核心结论", "t": "接触可以建模为约束：法向非穿透 + 摩擦锥，形成线性互补问题（LCP）", "x": "", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 术语", "t": "Explicit Euler / 显式欧拉", "x": "用当前导数更新状态，简单但不稳定", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 术语", "t": "Semi-implicit Euler / 半隐式欧拉", "x": "先用当前加速度更新速度，再用新速度更新位置，稳定且高效", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 术语", "t": "Implicit Euler / 隐式欧拉", "x": "用未来导数更新状态，需要解方程，无条件稳定", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 术语", "t": "Angular Velocity / 角速度", "x": "描述旋转快慢和方向的向量", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 术语", "t": "Moment of Inertia / 转动惯量", "x": "刚体对角速度的抵抗程度，张量形式", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 术语", "t": "Newton-Euler Equations / 牛顿-欧拉方程", "x": "刚体的平动和转动运动方程", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 术语", "t": "Jacobian Matrix / 雅可比矩阵", "x": "描述约束速度与广义速度关系的矩阵", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 术语", "t": "Lagrange Multiplier / 拉格朗日乘子", "x": "用于引入约束力的未知量", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 术语", "t": "Linear Complementary Problem (LCP) / 线性互补问题", "x": "接触力与速度的互补条件形成的数学问题", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 术语", "t": "Baumgarte Stabilization / Baumgarte 稳定化", "x": "在约束求解中加入位置误差修正项，防止漂移", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 练习", "t": "比较显式欧拉、半隐式欧拉和隐式欧拉的稳定性，并说明为什么游戏物理引擎常用半隐式欧拉。", "x": "", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 练习", "t": "一个刚体的局部转动惯量为 diag(2, 3, 4) kg·m²，当前朝向旋转矩阵为 R（绕 z 轴旋转 90 度）。求世界坐标系下的转动惯量张量。", "x": "", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 练习", "t": "解释约束力为什么可以写成 \\(J^T \\lambda\\)，并说明 \\(\\lambda\\) 的物理意义。", "x": "", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L08 · 练习", "t": "在 UE 中，如何为一个角色设置布娃娃（Ragdoll）物理？简述步骤。", "x": "", "u": "GAMES105/105_L08.html"}, {"c": "GAMES105 L05 · 第 5 讲：数据驱动角色动画——动捕、重定向、过渡与运动图", "t": "1. 从关键帧到动作捕捉：为什么需要真实运动数据", "x": "传统角色动画靠关键帧动画（Keyframe Animation）：动画师在时间轴上摆出关键姿势，中间帧由插值生成。这种方式可控、表现力强，但制作成本高，尤其是大量写实的人体运动（走、跑、跳、转身）很难靠手摆做到自然。\n动作捕捉（Motion Capture，简称动捕） 换了个思路：直接数字化记录真人", "u": "GAMES105/105_L05.html#s1"}, {"c": "GAMES105 L05 · 第 5 讲：数据驱动角色动画——动捕、重定向、过渡与运动图", "t": "2. 现代动捕系统的几条技术路线", "x": "课件把现代动捕系统分成几类，每类的原理和取舍不同：\n\n机械式动捕（Mechanical Mocap）：用外骨骼（Exoskeleton） 直接测量关节角度。优点是抗遮挡、可户外；缺点是穿戴笨重、限制动作幅度。\n惯性动捕（Inertial Mocap）：用惯性测量单元（IMU），典型是 3 轴加速度计", "u": "GAMES105/105_L05.html#s2"}, {"c": "GAMES105 L05 · 第 5 讲：数据驱动角色动画——动捕、重定向、过渡与运动图", "t": "3. 运动重定向：让一段动捕驱动另一副骨骼", "x": "拿到动捕数据后，常见问题是：这段运动是为演员 A 的骨骼录的，怎么驱动游戏里角色 B 的骨骼？ 这就是运动重定向（Motion Retargeting）。课件列出要跨越的差异：\n\n骨骼数量不同；\n骨骼命名不同；\n参考姿势（reference pose）不同（比如 A-pose vs T-pose）；", "u": "GAMES105/105_L05.html#s3"}, {"c": "GAMES105 L05 · 第 5 讲：数据驱动角色动画——动捕、重定向、过渡与运动图", "t": "4. 运动过渡：两段动画怎么接才不跳", "x": "游戏里角色不会只播一段动画，走→跑→停需要运动过渡（Motion Transition）。最朴素的做法是“播完 A 直接播 B”，但两段运动在切换帧的姿态不同，会出现不连续（discontinuity），视觉上就是“跳一下”。\n课件的解法是姿态混合（Pose Blending）：在过渡区间内，把两段", "u": "GAMES105/105_L05.html#s4"}, {"c": "GAMES105 L05 · 第 5 讲：数据驱动角色动画——动捕、重定向、过渡与运动图", "t": "5. 朝向坐标系与旋转分解：让两段运动“对得上”", "x": "两段运动来自不同方向时，直接混合会扭曲。课件引入朝向坐标系（Facing Frame）：一个随角色水平移动、其中一个轴指向角色“面朝方向”的特殊坐标系。它的平移只含水平分量：\n\\[\n\\mathbf{t} = (t_x, 0, t_z)\n\\]\n旋转 \\(R\\) 是绕 y 轴的朝向旋转：\n\\[\nR = ", "u": "GAMES105/105_L05.html#s5"}, {"c": "GAMES105 L05 · 第 5 讲：数据驱动角色动画——动捕、重定向、过渡与运动图", "t": "6. 没有根位移的运动与路径拟合", "x": "很多动捕数据是原地运动（in-place）：角色在跑步机上跑，根骨骼不产生世界位移。课件专门用几页讲“Motion Data without Root Translation”，并举例 GTA 角色被“带回现实”的视频——说明游戏里大量使用原地动画，再由程序驱动位移。\n原地动画的好处：一段跑步可以复", "u": "GAMES105/105_L05.html#s6"}, {"c": "GAMES105 L05 · 第 5 讲：数据驱动角色动画——动捕、重定向、过渡与运动图", "t": "7. 运动合成与运动图：把片段组织成可交互的系统", "x": "有了动捕数据、重定向、过渡混合，最后一步是运动合成（Motion Composition）：根据用户控制、环境物体、其他角色的运动，计算生成新的运动。课件引用 Heck &amp; Gleicher 2007 的参数化运动图与 Treuille et al. 2007 的连续控制工作。\n核心数据结构", "u": "GAMES105/105_L05.html#s7"}, {"c": "GAMES105 L05 · 核心结论", "t": "动作捕捉是“记录真人运动”的数据来源，关键帧动画是“手工摆姿势”，两者互补而非替代。", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 核心结论", "t": "现代动捕分机械外骨骼、惯性 IMU、光学标记点、无标记多目/深度相机、稀疏传感器几类，精度、成本、便携性各不相同。", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 核心结论", "t": "运动重定向要跨越骨骼数量/命名/参考姿势/骨长比例/骨骼结构的差异，典型管线是：映射骨骼名→缩放位移→复制或重定向旋转→IK 后处理修脚滑与自穿透。", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 核心结论", "t": "两段运动直接拼接会在过渡帧出现姿态不连续，解决办法是在过渡区间内对姿态做线性插值：p(t) = (1−t)p_i + t p_{i+1}。", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 核心结论", "t": "当两段运动来自不同朝向时，需要先把它们变换到同一个“朝向坐标系”下再混合，否则混合结果会扭曲。", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 核心结论", "t": "朝向坐标系（Facing Frame）是随角色水平移动、一个轴指向角色朝向的特殊坐标系，旋转可分解为绕 y 轴的朝向旋转与剩余旋转的乘积。", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 核心结论", "t": "运动图把长运动切成片段，节点是片段、边是可能的过渡，用状态机在运行时根据用户输入/环境选择下一条边。", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 核心结论", "t": "距离图（Distance Map）用两两姿态之间的距离找局部极小值作为候选过渡点，是自动切分运动片段的实用工具。", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 术语", "t": "Motion Capture / 动作捕捉", "x": "数字化记录真人/物体运动并转成骨骼动画数据", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 术语", "t": "Keyframe Animation / 关键帧动画", "x": "动画师摆关键姿势、中间帧插值的传统做法", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 术语", "t": "Rotoscoping / 转描", "x": "把实拍影像逐帧描成动画的早期技术", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 术语", "t": "IMU / 惯性测量单元", "x": "加速度计+陀螺仪，惯性动捕的核心传感器", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 术语", "t": "Optical Mocap / 光学动捕", "x": "反光/发光标记点+多视图几何解算身体运动", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 术语", "t": "Motion Retargeting / 运动重定向", "x": "把一段运动迁移到骨骼数量/比例/结构不同的角色上", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 术语", "t": "Foot-skating / 脚滑", "x": "脚与地面接触时仍滑动，重定向/过渡常见问题", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 术语", "t": "Facing Frame / 朝向坐标系", "x": "随角色水平移动、一个轴指向朝向的特殊坐标系", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 术语", "t": "Motion Graph / 运动图", "x": "节点是运动片段、边是可能过渡的图结构", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 术语", "t": "Distance Map / 距离图", "x": "两两帧姿态差异矩阵，局部极小值作过渡点", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 术语", "t": "Motion Matching / 运动匹配", "x": "以姿态为单位从长运动数据中检索下一帧的合成方法", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 练习", "t": "简述光学动捕与惯性动捕各自的优缺点，并说明为什么影视/3A 项目更常用光学动捕。", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 练习", "t": "两段运动在过渡点的姿态分别为 p_i 与 p_{i+1}，写出过渡区间内的姿态混合公式，并说明 φ(t) 应满足什么条件。", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 练习", "t": "给定源运动朝向坐标系 (R_1, t_1) 与目标 (R_2, t_2)，写出把源运动变换到目标坐标系的刚体变换 R 与 t。", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 练习", "t": "运动图里“在哪里切分运动片段”为什么用距离图的局部极小值？如果切在差异大的帧会怎样？", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L05 · 练习", "t": "实践题：在 UE 里把一段为 A-pose 骨骼录制的走路动捕重定向到 T-pose 的游戏角色，列出你会做的步骤与可能遇到的问题。", "x": "", "u": "GAMES105/105_L05.html"}, {"c": "GAMES105 L07 · 第 7 讲：蒙皮（Skinning）——从 LBS 到 DQS 与 Blendshapes", "t": "1. 蒙皮在角色动画管线中的位置", "x": "角色动画的典型管线是：建模 → 绑定（Rigging）→ 蒙皮（Skinning）→ 骨骼动画（Skeletal Animation）→ 渲染。\n\nRigging：搭建骨骼层级，定义每根骨骼的原点、朝向、父子关系。可以理解为给角色装上一副“骨架”。\nSkinning：把静态网格的每个顶点“绑”到一根", "u": "GAMES105/105_L07.html#s1"}, {"c": "GAMES105 L07 · 第 7 讲：蒙皮（Skinning）——从 LBS 到 DQS 与 Blendshapes", "t": "2. 从单根骨骼的刚体变换到蒙皮公式", "x": "先看最简单的情况：一个顶点只受一根骨骼影响。\n设骨骼在绑定姿势下的旋转为 \\(Q\\)、原点为 \\(\\boldsymbol{o}\\)，当前姿势下旋转为 \\(Q'\\)、原点为 \\(\\boldsymbol{o}'\\)。顶点在绑定姿势下的位置是 \\(\\boldsymbol{x}\\)。\n第一步：把顶点变换到骨", "u": "GAMES105/105_L07.html#s2"}, {"c": "GAMES105 L07 · 第 7 讲：蒙皮（Skinning）——从 LBS 到 DQS 与 Blendshapes", "t": "3. LBS 的糖果纸伪影：线性混合旋转的代价", "x": "LBS 在工业界用得非常广：高效、GPU 友好、游戏引擎都支持。但它有一个著名的缺陷——糖果纸伪影（Candy-Wrapper Artifact）。\n把 LBS 公式里的旋转部分单独拿出来看：\n\\[ \\boldsymbol{x}' = \\sum_j w_{ij} R_j \\boldsymbol{x}", "u": "GAMES105/105_L07.html#s3"}, {"c": "GAMES105 L07 · 第 7 讲：蒙皮（Skinning）——从 LBS 到 DQS 与 Blendshapes", "t": "4. 对偶四元数与 DQS：在 SE(3) 上做插值", "x": "要理解 DQS，先要理解对偶四元数（Dual Quaternion）。\n对偶数（Dual Number）：形如 \\(x = a + b\\varepsilon\\)，其中 \\(\\varepsilon^2 = 0\\) 但 \\(\\varepsilon \\ne 0\\)。它和复数 \\(a + bi\\)（\\(i^", "u": "GAMES105/105_L07.html#s4"}, {"c": "GAMES105 L07 · 第 7 讲：蒙皮（Skinning）——从 LBS 到 DQS 与 Blendshapes", "t": "5. Blendshapes 与 Pose Space Deformation：叠加修正层", "x": "LBS/DQS 解决的是“骨骼驱动的大范围变形”，但肌肉鼓起、血管凸起、表情细节这类姿态相关的形状变化很难用骨骼权重表达。这就是 Blendshapes（形变目标 / Morph Targets） 的用武之地。\n基本 Blendshapes：给定一组示例形状 \\(B_i\\)（相对于基础形状的偏移），", "u": "GAMES105/105_L07.html#s5"}, {"c": "GAMES105 L07 · 第 7 讲：蒙皮（Skinning）——从 LBS 到 DQS 与 Blendshapes", "t": "6. 实例：SMPL 人体模型与面部动画", "x": "SMPL 模型（Skinned Multi-Person Linear Model）是 ML/CV 里广泛采用的人体参数化模型，它把前面所有技术组合起来：\n\n\n形状主成分：从大量人体扫描中用 PCA（主成分分析） 提取形状基 \\(S_m\\)，用参数 \\(\\beta\\) 控制体型：\n\\[ T(\\bet", "u": "GAMES105/105_L07.html#s6"}, {"c": "GAMES105 L07 · 核心结论", "t": "蒙皮 = 把网格顶点按权重绑定到一根或多根骨骼上，骨骼运动时顶点跟着做刚体变换的加权平均。", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 核心结论", "t": "LBS 公式：顶点新位置 = Σ_j w_ij · (Q'_j · (Q_j^T · (x_i - o_j)) + o'_j)，其中 Q_j、Q'_j 是骨骼在", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 核心结论", "t": "LBS 本质是对旋转矩阵做线性插值，当两个骨骼旋转差异大时，加权平均的旋转矩阵不再正交，导致体积塌陷——这就是糖果纸伪影。", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 核心结论", "t": "DQS 把刚体变换表示为单位对偶四元数，在对偶四元数空间做线性混合再归一化，相当于在 SE(3) 上做近似球面插值，能保持刚体性、避免糖果纸。", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 核心结论", "t": "Blendshapes（形变目标）用“平均形状 + Σ 权重 × 偏移形状”表示表情/姿态相关的细节，是 LBS 之外叠加的修正层。", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 核心结论", "t": "Pose Space Deformation（PSD）把 Blendshapes 的权重看成姿态 θ 的函数，用 RBF 等散点插值从示例姿态中学习修正量。", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 核心结论", "t": "SMPL 模型 = 用 PCA 从大量人体扫描中提取形状主成分 + 姿态 Blendshapes + LBS 蒙皮，是 ML/CV 里广泛采用的人体参数化模型。", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 核心结论", "t": "面部动画通常 = 身份（Identity）+ 表情（Expression），用一组 ARKit 风格的 Blendshapes 线性组合驱动。", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 术语", "t": "Skinning / 蒙皮", "x": "把网格顶点按权重绑定到骨骼上，骨骼运动时顶点跟着变形的技术。", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 术语", "t": "Bind Pose / Rest Pose / 绑定姿势 / 静止姿势", "x": "建模时网格与骨骼对齐的默认姿势，蒙皮变换的参考基准。", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 术语", "t": "Linear Blend Skinning (LBS) / 线性混合蒙皮", "x": "对每根骨骼的刚体变换按权重做线性加权平均的蒙皮方法。", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 术语", "t": "Candy-Wrapper Artifact / 糖果纸伪影", "x": "LBS 在大角度弯曲时关节体积塌陷、像糖果纸被拧紧的现象。", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 术语", "t": "Dual Quaternion Skinning (DQS) / 对偶四元数蒙皮", "x": "用单位对偶四元数表示刚体变换并做归一化线性混合，保持刚体性。", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 术语", "t": "Blendshapes / Morph Targets / 形变目标", "x": "一组示例形状的线性组合，用于表达表情或姿态相关细节。", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 术语", "t": "Pose Space Deformation (PSD) / 姿态空间变形", "x": "把 Blendshapes 权重看成姿态的函数，用 RBF 等插值从示例姿态学习修正量。", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 术语", "t": "Radial Basis Function (RBF) / 径向基函数", "x": "一种散点插值方法，用核函数 \\(\\varphi(\\|\\boldsymbol{x}-\\boldsymbol{x}_i\\|)\\) 的加权和拟合数据。", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 术语", "t": "Principal Component Analysis (PCA) / 主成分分析", "x": "降维技术，用少数主成分方向表示高维数据的主要变化。", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 术语", "t": "SMPL / SMPL 人体模型", "x": "用形状 PCA + 姿态 Blendshapes + LBS 表示人体的参数化模型。", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 练习", "t": "写出 LBS 的完整公式，并解释每一项的几何含义。", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 练习", "t": "为什么 LBS 会产生糖果纸伪影？DQS 如何缓解它？", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 练习", "t": "给定两个旋转矩阵 \\(R_1 = I\\) 和 \\(R_2 = \\text{Rot}(\\pi, \\boldsymbol{z})\\)，权重各 0.5，计算 LBS ", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 练习", "t": "在 UE 里如何用 Morph Target 实现一个“手臂弯曲时肱二头肌鼓起”的效果？", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L07 · 练习", "t": "SMPL 模型里 \\(\\beta\\) 和 \\(\\theta\\) 分别控制什么？PCA 在其中起什么作用？", "x": "", "u": "GAMES105/105_L07.html"}, {"c": "GAMES105 L10 · 第 10 讲：角色控制——从 PD 到反馈与平衡", "t": "1. 用 PD 伺服驱动角色关节", "x": "角色动画里，我们通常不直接指定每个关节的力矩，而是给每个关节一个目标姿态，让控制器去追。最常用的就是 PD 控制（比例-微分控制）：\n\\[\n\\tau = k_p(\\bar{q} - q) - k_d \\dot{q}\n\\]\n其中 \\(\\bar{q}\\) 是目标关节角，\\(q\\) 是当前关节角，\\(\\d", "u": "GAMES105/105_L10.html#s1"}, {"c": "GAMES105 L10 · 第 10 讲：角色控制——从 PD 到反馈与平衡", "t": "2. PD 控制的两个典型问题：稳态误差与跟踪滞后", "x": "PD 只根据误差算力矩，这带来两个工程上很常见的问题。\n（1）稳态误差\n如果关节上持续有外力（比如重力），PD 必须保留一个非零误差才能产生足以对抗重力的力矩。平衡时 \\(k_p(\\bar{q}-q) = \\tau_{\\text{gravity}}\\)，所以 \\(q\\) 永远到不了 \\(\\bar{q", "u": "GAMES105/105_L10.html#s2"}, {"c": "GAMES105 L10 · 第 10 讲：角色控制——从 PD 到反馈与平衡", "t": "3. PD 控制的稳定性：离散化后看特征值", "x": "为什么增益太大会不稳定？因为仿真不是连续的，而是按固定步长 \\(h\\) 离散积分。课件用最简单的质量-弹簧-阻尼系统来分析：\n\\[\nm\\ddot{x} = -k_p x - k_d \\dot{x}\n\\]\n采用半隐式欧拉（先更新速度，再用新速度更新位置）：\n\\[\nv_{n+1} = v_n + h\\f", "u": "GAMES105/105_L10.html#s3"}, {"c": "GAMES105 L10 · 第 10 讲：角色控制——从 PD 到反馈与平衡", "t": "4. Stable PD：用更新后的速度做阻尼", "x": "既然不稳定来自离散化，一个自然的改进是：阻尼项不要用旧速度 \\(v_n\\)，而用更新后的速度 \\(v_{n+1}\\)。这就是 Stable PD 的核心思想。\n普通 PD 的半隐式欧拉：\n\\[\nv_{n+1} = v_n + h(-k_p x_n - k_d v_n)\n\\]\nStable PD 改为", "u": "GAMES105/105_L10.html#s4"}, {"c": "GAMES105 L10 · 第 10 讲：角色控制——从 PD 到反馈与平衡", "t": "5. 前馈与反馈：开环控制轨迹 + 在线修正", "x": "有了稳定的 PD 伺服，接下来要解决“让角色做动作”的问题。课件把控制分成两层：\n前馈控制（Feedforward Control）\n把一段动作片段（动捕或关键帧）转换成每个控制周期 \\(\\delta t\\) 的目标姿态序列，作为开环控制轨迹 \\(\\hat{m}\\) 送给 PD 伺服。PD 伺服再驱", "u": "GAMES105/105_L10.html#s5"}, {"c": "GAMES105 L10 · 第 10 讲：角色控制——从 PD 到反馈与平衡", "t": "6. 轨迹优化：把“找控制”写成优化问题", "x": "如果希望角色完成复杂动作（跳跃、翻滚、带接触的动作），手工调 PD 目标很困难。轨迹优化把这件事形式化：\n寻找状态轨迹 \\(s_0, s_1, \\dots, s_T\\) 和控制轨迹 \\(a_0, a_1, \\dots, a_{T-1}\\)，使得目标函数最小：\n\\[\n\\min_{s_t, a_t} f", "u": "GAMES105/105_L10.html#s6"}, {"c": "GAMES105 L10 · 第 10 讲：角色控制——从 PD 到反馈与平衡", "t": "7. 无梯度优化：CMA-ES 与 SAMCON", "x": "当梯度不可用或不可靠时，用无梯度优化（Derivative-Free Optimization）。基本迭代框架是：\n\n给一个初始猜测 \\(x\\)；\n根据当前 \\(x\\) 提出一组候选 \\(x_i\\)；\n评估目标函数 \\(f(x_i)\\)；\n根据评估结果更新 \\(x\\)，重复。\n\nCMA-ES（协方差", "u": "GAMES105/105_L10.html#s7"}, {"c": "GAMES105 L10 · 第 10 讲：角色控制——从 PD 到反馈与平衡", "t": "8. 静态平衡：CoM 投影、支撑多边形与 Jacobian 转置", "x": "角色站着不动时也要保持平衡。课件给出一个简单策略：\n判据：把质心（CoM）投影到地面，若投影落在支撑多边形（Support Polygon）内，角色就是静态稳定的。支撑多边形是脚与地面接触点围成的区域。\n控制策略：在跟踪站立姿态的同时，让 CoM 投影尽量靠近支撑多边形的中心。用 PD 计算一个“虚", "u": "GAMES105/105_L10.html#s8"}, {"c": "GAMES105 L10 · 核心结论", "t": "角色关节常用 PD 伺服：τ = k_p(q̄−q) − k_d q̇，用误差驱动关节跟踪目标姿态。", "x": "", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 核心结论", "t": "PD 是“基于误差”的控制：重力等持续外力会造成稳态误差，快速参考会造成跟踪滞后。", "x": "", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 核心结论", "t": "提高 k_p 能减小误差，但会降低稳定性；稳定性由离散时间步长 h 与增益共同决定，需满足特征值模长 < 1。", "x": "", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 核心结论", "t": "Stable PD 通过用更新后的速度计算阻尼项，改善大增益下的稳定性。", "x": "", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 核心结论", "t": "前馈控制把动作片段转成开环控制轨迹（目标姿态序列）交给 PD 伺服；反馈控制再根据仿真状态施加修正量。", "x": "", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 核心结论", "t": "轨迹优化把“找控制轨迹”写成带动力学约束的优化问题；当梯度不可靠时用无梯度方法（CMA-ES、SAMCON）。", "x": "", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 核心结论", "t": "静态平衡的简单策略：让 CoM 投影靠近支撑多边形中心，用 PD 计算虚拟力，再经 Jacobian 转置映射为关节力矩。", "x": "", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 术语", "t": "PD Control / 比例-微分控制", "x": "根据目标与当前状态的误差及速度计算力矩的伺服控制。", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 术语", "t": "Steady-State Error / 稳态误差", "x": "持续外力下 PD 无法完全消除的残余偏差。", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 术语", "t": "Semi-implicit Euler / 半隐式欧拉", "x": "先更新速度再用新速度更新位置的积分方法。", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 术语", "t": "Stable PD / 稳定 PD", "x": "用更新后的速度计算阻尼项，扩大稳定域的 PD 变体。", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 术语", "t": "Feedforward Control / 前馈控制", "x": "按预定目标轨迹驱动，不依赖状态反馈。", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 术语", "t": "Feedback Control / 反馈控制", "x": "根据仿真状态计算修正量，抵消扰动。", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 术语", "t": "Trajectory Optimization / 轨迹优化", "x": "在动力学约束下寻找最优状态/控制轨迹。", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 术语", "t": "CMA-ES / 协方差矩阵自适应进化策略", "x": "广泛使用的无梯度优化方法。", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 术语", "t": "SAMCON / 采样式运动控制", "x": "序列蒙特卡洛方法，逐段采样并选择 PD 目标。", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 术语", "t": "Jacobian Transpose / Jacobian 转置控制", "x": "用 τ = Jᵀf 把虚拟力映射为关节力矩。", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 练习", "t": "写出角色单关节 PD 控制律，并说明 k_p 和 k_d 分别起什么作用。", "x": "", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 练习", "t": "为什么 PD 控制在重力下存在稳态误差？如何减小它？", "x": "", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 练习", "t": "用半隐式欧拉离散化 PD 系统，说明稳定性由哪些量决定。", "x": "", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 练习", "t": "解释前馈控制和反馈控制的分工，并说明为什么工程上通常两者都要。", "x": "", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L10 · 练习", "t": "给定虚拟力 f 和关节位置 p_i、作用点 x，写出用 Jacobian 转置把 f 映射为关节力矩的公式，并说明推导依据。", "x": "", "u": "GAMES105/105_L10.html"}, {"c": "GAMES105 L11 · 第 11 讲：学习行走——动态平衡、ZMP、倒立摆与 SIMBICON", "t": "1. 步态周期：行走与跑步的分界线", "x": "先把“走路”这件事拆成时间轴。一个完整的步态周期（gait cycle）从一只脚触地开始，到同一只脚再次触地结束。课件把周期分成两类阶段：\n\n支撑期（Stance Phase）：脚在地面上、承担体重。\n摆动期（Swing Phase）：脚离地、向前摆动。\n\n对行走（Walking）来说，任意时刻至少", "u": "GAMES105/105_L11.html#s1"}, {"c": "GAMES105 L11 · 第 11 讲：学习行走——动态平衡、ZMP、倒立摆与 SIMBICON", "t": "2. 静态平衡 vs 动态平衡：质心要不要待在支撑多边形里", "x": "有了支撑多边形，就可以定义两种平衡策略。\n静态平衡（Static Balance）：要求质心（Center of Mass, CoM）在水平面上的投影始终落在支撑多边形内部。这样即使人突然停住，也不会倒。课件用连续几页动画展示：双支撑期质心在两脚之间，单支撑期质心必须移到支撑脚正上方。结果就是走路像", "u": "GAMES105/105_L11.html#s2"}, {"c": "GAMES105 L11 · 第 11 讲：学习行走——动态平衡、ZMP、倒立摆与 SIMBICON", "t": "3. ZMP：地面反力合力的作用点，也是“零矩点”", "x": "要判断动态平衡，需要一个可计算的量。课件从地面反力（Ground Reaction Force, GRF）出发。脚踩地时，地面给脚分布式的法向力和摩擦力，把所有分布力合成一个合力 \\(\\boldsymbol{f}_{\\mathrm{GRF}}\\) 和一个合力矩 \\(\\boldsymbol{\\tau}", "u": "GAMES105/105_L11.html#s3"}, {"c": "GAMES105 L11 · 第 11 讲：学习行走——动态平衡、ZMP、倒立摆与 SIMBICON", "t": "4. 从力矩平衡解出 ZMP：为什么它必须落在支撑多边形内", "x": "课件接着用静力平衡把 ZMP 和质心、脚踝力矩联系起来。考虑支撑脚，它受到三个力：脚踝处的力 \\(\\boldsymbol{f}_{\\mathrm{ankle}}\\)、地面反力 \\(\\boldsymbol{f}_{\\mathrm{GRF}}\\)、重力 \\(m\\boldsymbol{g}\\)。平衡条件为", "u": "GAMES105/105_L11.html#s4"}, {"c": "GAMES105 L11 · 第 11 讲：学习行走——动态平衡、ZMP、倒立摆与 SIMBICON", "t": "5. 简化模型：倒立摆与“受控的跌倒”", "x": "真实人形有几十个自由度，直接控制太难。课件的思路是：先把系统简化成抽象模型，规划抽象模型的运动，再映射回真实角色。\n最常用的简化模型是倒立摆模型（Inverted Pendulum Model, IPM）：把整个身体的质量集中到质心（CoM），质心通过一根无质量连杆连接到支撑脚（或支撑点）。这就像把", "u": "GAMES105/105_L11.html#s5"}, {"c": "GAMES105 L11 · 第 11 讲：学习行走——动态平衡、ZMP、倒立摆与 SIMBICON", "t": "6. SIMBICON：用反馈控制把“跌倒”变成“行走”", "x": "有了简化模型和 ZMP 判据，接下来要问：怎么真正控制一个双足角色走起来？课件介绍了 SIMBICON（SIMple BIped Locomotion CONtrol），Yin et al. 2007。它的结构可以拆成三步：\n第一步：周期基运动 + PD 跟踪。 先设计一个周期性的基础动作（base", "u": "GAMES105/105_L11.html#s6"}, {"c": "GAMES105 L11 · 核心结论", "t": "行走的本质是“没有飞行阶段的连续移动”，每一步都包含双支撑期和单支撑期；跑步才有飞行阶段。", "x": "", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 核心结论", "t": "静态平衡行走要求质心（CoM）在支撑多边形（Support Polygon）正上方，这既慢又笨拙；动态平衡允许质心跑到支撑多边形外，靠惯性“倒”过去再迈步接住。", "x": "", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 核心结论", "t": "ZMP（零矩点）是地面反力合力作用点，也是地面反力关于该点的水平力矩为零的点；只要 ZMP 落在支撑多边形内，脚就不会转动，人就能保持动态平衡。", "x": "", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 核心结论", "t": "ZMP 的存在性是动态平衡的判据：解出的 ZMP 跑出支撑多边形，意味着脚会绕边缘翻转，平衡被破坏。", "x": "", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 核心结论", "t": "简化模型（倒立摆 IPM）把复杂的人形系统抽象成质心+无质量连杆，先规划抽象模型，再用 IK/逆动力学映射回真实角色。", "x": "", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 核心结论", "t": "倒立摆模型告诉我们：行走 = 受控的跌倒 + 及时迈步（Falling + Step Planning）。", "x": "", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 核心结论", "t": "SIMBICON 用“周期基运动 + PD 跟踪 + 有限状态机 + 质心线性反馈”实现鲁棒行走，反馈项同时看质心位置误差和速度误差。", "x": "", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 术语", "t": "Gait Cycle / 步态周期", "x": "同一只脚两次触地之间的完整动作序列。", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 术语", "t": "Double Stance Phase / 双支撑期", "x": "两只脚同时着地的阶段，行走特有。", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 术语", "t": "Flight Phase / 飞行期", "x": "两只脚都离地的阶段，跑步特有。", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 术语", "t": "Support Polygon / 支撑多边形", "x": "所有着地点形成的凸多边形，是 ZMP 必须落入的区域。", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 术语", "t": "Center of Mass (CoM) / 质心", "x": "质量分布的中心，简化模型的核心状态。", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 术语", "t": "Zero-Moment Point (ZMP) / 零矩点", "x": "地面反力关于该点的水平力矩为零，是动态平衡判据。", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 术语", "t": "Center of Pressure (CoP) / 压力中心", "x": "地面反力按垂直力加权的平均作用点，脚不转时与 ZMP 重合。", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 术语", "t": "Inverted Pendulum Model (IPM) / 倒立摆模型", "x": "把身体简化为质心+无质量连杆，支点在支撑脚。", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 术语", "t": "SIMBICON / 简单双足运动控制", "x": "Yin et al. 2007 提出的行走控制方法，基运动+PD+质心反馈。", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 术语", "t": "PD Controller / 比例-微分控制器", "x": "用位置误差和速度误差计算力矩的反馈控制器。", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 练习", "t": "画出步行一个完整步态周期的时间轴，标出左脚的支撑期、摆动期，以及双支撑期和单支撑期。并说明行走与跑步在步态上的根本区别。", "x": "", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 练习", "t": "解释 ZMP 的定义，并说明为什么 ZMP 必须落在支撑多边形内。如果解出的 ZMP 跑出支撑多边形，物理上会发生什么？", "x": "", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 练习", "t": "倒立摆模型把双足角色简化成什么？用这个模型解释“行走 = 受控的跌倒 + 迈步规划”。", "x": "", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 练习", "t": "SIMBICON 的质心反馈公式是 \\(\\theta_d = \\theta_{d0} + c_d d + c_v v\\)。说明 \\(d\\)、\\(v\\) 的物理意", "x": "", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L11 · 练习", "t": "在 UE 或 Unity 中，设计一个简易的行走控制器：说明你会用哪些组件/节点实现 FSM、PD 跟踪、质心反馈和 IK。", "x": "", "u": "GAMES105/105_L11.html"}, {"c": "GAMES105 L12 · 第 12 讲：最优控制与强化学习", "t": "从轨迹优化到最优控制：开环与反馈", "x": "这一讲的主题是最优控制（Optimal Control）与强化学习（Reinforcement Learning）。在角色动画中，我们经常需要让虚拟角色完成某个任务（比如走到目标点、跑步、跳跃），而控制就是给角色施加一系列动作（关节力矩或目标姿态）。最优控制要解决的问题是：找到一组合适的控制，使得角", "u": "GAMES105/105_L12.html#s1"}, {"c": "GAMES105 L12 · 第 12 讲：最优控制与强化学习", "t": "约束优化与拉格朗日乘子法", "x": "最优控制问题是一个约束优化问题：在满足动力学约束 \\(g(x)=0\\) 的前提下，最小化目标函数 \\(f(x)\\)。这里 \\(x\\) 可以理解为所有状态和动作组成的向量。\n处理约束的一种简单方法是软约束：把约束违反程度作为惩罚项加入目标函数，即 \\(\\min_x f(x) + w g(x)\\)，其中", "u": "GAMES105/105_L12.html#s2"}, {"c": "GAMES105 L12 · 第 12 讲：最优控制与强化学习", "t": "庞特里亚金最大值原理（PMP）", "x": "对最优控制问题应用拉格朗日乘子法，我们得到拉格朗日函数：\n\\[\nL = h(s_T) + \\sum_{t=0}^{T-1} h(s_t, a_t) + \\sum_{t=0}^{T-1} \\lambda_{t+1}^T (f(s_t, a_t) - s_{t+1})\n\\]\n对 \\(s_t\\)、\\(a_", "u": "GAMES105/105_L12.html#s3"}, {"c": "GAMES105 L12 · 第 12 讲：最优控制与强化学习", "t": "动态规划与贝尔曼方程", "x": "动态规划（Dynamic Programming）是求解最优控制的另一类方法，它基于贝尔曼最优性原理（Bellman's Principle of Optimality）：最优策略的子策略也是最优的。\n定义值函数（Value Function）\\(V(s)\\)：从状态 \\(s\\) 出发，完成剩余任务", "u": "GAMES105/105_L12.html#s4"}, {"c": "GAMES105 L12 · 第 12 讲：最优控制与强化学习", "t": "线性二次型调节器（LQR）", "x": "线性二次型调节器（Linear Quadratic Regulator, LQR）是一类特殊的最优控制问题，其动力学是线性的，目标函数是二次型的：\n\\[\ns_{t+1} = A_t s_t + B_t a_t\n\\]\n\\[\n\\min \\; s_T^T Q_T s_T + \\sum_{t=0}^{T-1", "u": "GAMES105/105_L12.html#s5"}, {"c": "GAMES105 L12 · 第 12 讲：最优控制与强化学习", "t": "基于采样的策略优化", "x": "对于非线性、高维的角色动画问题，LQR 不再适用。一种实用的方法是基于采样的策略优化：用参数化的策略 \\(\\pi(s; \\theta)\\) 表示控制律，然后通过采样优化参数 \\(\\theta\\) 来最小化目标函数 \\(J(\\theta)\\)。\n常用算法是 CMA-ES（Covariance Matr", "u": "GAMES105/105_L12.html#s6"}, {"c": "GAMES105 L12 · 第 12 讲：最优控制与强化学习", "t": "强化学习与马尔可夫决策过程", "x": "强化学习（Reinforcement Learning, RL）与最优控制目标一致：最大化累积奖励（或最小化累积代价）。但强化学习通常假设模型未知，智能体通过与环境交互来学习。\n马尔可夫决策过程（Markov Decision Process, MDP）是强化学习的数学框架，由以下要素组成：\n\n状态", "u": "GAMES105/105_L12.html#s7"}, {"c": "GAMES105 L12 · 核心结论", "t": "最优控制的目标是找到一个控制序列或策略，使得在满足动力学约束的前提下，累积代价最小（或累积奖励最大）。", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 核心结论", "t": "开环控制只针对一个起始状态求解动作序列，鲁棒性差；反馈控制针对任意状态求解策略，鲁棒性好，但求解更难。", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 核心结论", "t": "拉格朗日乘子法将约束优化转化为无约束优化，最优性条件是拉格朗日函数对状态、动作和乘子的偏导为零。", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 核心结论", "t": "庞特里亚金最大值原理（PMP）给出了最优控制的必要条件，但求解两点边值问题在复杂角色动画中非常困难。", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 核心结论", "t": "动态规划利用贝尔曼最优性原理，将问题分解为子问题，通过值函数递归求解；贝尔曼方程是强化学习的核心。", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 核心结论", "t": "LQR 是线性动力学 + 二次型目标的最优控制问题，可以通过反向递推得到最优反馈策略。", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 核心结论", "t": "对于非线性问题，可以用基于采样的方法（如 CMA-ES）优化策略参数，或者用强化学习直接学习策略。", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 核心结论", "t": "强化学习与最优控制目标一致，但强化学习通常假设模型未知，通过与环境交互学习值函数或策略；MDP 是其数学框架。", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 术语", "t": "Optimal Control / 最优控制", "x": "在满足动力学约束下最小化代价函数，求解控制序列或策略。", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 术语", "t": "Open-loop Control / 开环控制", "x": "只针对给定起始状态求解动作序列，不依赖反馈。", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 术语", "t": "Feedback Control / 反馈控制", "x": "根据当前状态求解动作的策略，对扰动鲁棒。", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 术语", "t": "Lagrange Multiplier / 拉格朗日乘子", "x": "处理等式约束优化，构造拉格朗日函数。", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 术语", "t": "Pontryagin's Maximum Principle / 庞特里亚金最大值原理", "x": "最优控制的必要条件，导出两点边值问题。", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 术语", "t": "Dynamic Programming / 动态规划", "x": "基于贝尔曼最优性原理，递归求解值函数。", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 术语", "t": "Bellman Equation / 贝尔曼方程", "x": "值函数的递归定义，是强化学习的核心。", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 术语", "t": "LQR / 线性二次型调节器", "x": "线性动力学+二次型目标的最优控制，可解析求解。", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 术语", "t": "MDP / 马尔可夫决策过程", "x": "强化学习的数学框架，包含状态、动作、转移概率、奖励。", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 术语", "t": "CMA-ES / 协方差矩阵自适应进化策略", "x": "一种无梯度的优化算法，常用于策略参数优化。", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 练习", "t": "简述开环控制与反馈控制的主要区别，并说明为什么角色动画中通常更倾向于使用反馈控制。", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 练习", "t": "写出离散时间最优控制问题的拉格朗日函数，并说明庞特里亚金最大值原理中的哈密顿函数是什么。", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 练习", "t": "考虑一个简单的一维线性系统：\\(s_{t+1} = s_t + a_t\\)，目标函数为 \\(\\sum_{t=0}^{T-1} (s_t^2 + a_t^2) +", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 练习", "t": "解释强化学习中的值函数 \\(V^\\pi(s)\\) 和 Q 函数 \\(Q^\\pi(s,a)\\) 的含义，并写出它们之间的关系。", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L12 · 练习", "t": "在基于采样的策略优化中，为什么要对状态和控制进行降维？请结合角色动画的例子说明。", "x": "", "u": "GAMES105/105_L12.html"}, {"c": "GAMES105 L09 · 第 9 讲：驱动仿真角色——关节力矩与 PD 控制", "t": "1. 从质点、刚体到关节系统：动力学回顾", "x": "这一讲的主题是「驱动仿真角色」（Actuating Simulated Characters），即在物理仿真中让角色产生运动。在讲驱动之前，课件先快速回顾了刚体动力学的基础，因为驱动本质上就是给系统施加力或力矩。\n质点动力学：牛顿第二定律 \\( \\mathbf{f} = m\\dot{\\mathbf{", "u": "GAMES105/105_L09.html#s1"}, {"c": "GAMES105 L09 · 第 9 讲：驱动仿真角色——关节力矩与 PD 控制", "t": "2. 如何驱动一个刚体：力与力矩", "x": "要让一个刚体运动，需要施加力（force）或力矩（torque）。对于单个刚体，线运动由力 \\( \\mathbf{f} \\) 驱动，角运动由力矩 \\( \\boldsymbol{\\tau} \\) 驱动。\n但力矩如何产生？有两种方式：\n\n直接施加纯力矩 \\( \\boldsymbol{\\tau} \\)（例", "u": "GAMES105/105_L09.html#s2"}, {"c": "GAMES105 L09 · 第 9 讲：驱动仿真角色——关节力矩与 PD 控制", "t": "3. 前向动力学 vs. 逆向动力学", "x": "在动力学系统中，有两个基本问题：\n\n前向动力学（Forward Dynamics）：已知当前状态（位置、速度）和施加的力/力矩，求加速度，进而通过积分得到下一状态。即 \\( (\\mathbf{x}, \\mathbf{v}, \\mathbf{f}) \\mapsto \\dot{\\mathbf{v}} \\", "u": "GAMES105/105_L09.html#s3"}, {"c": "GAMES105 L09 · 第 9 讲：驱动仿真角色——关节力矩与 PD 控制", "t": "4. PD 控制：比例-微分控制律", "x": "PD 控制是最常用的控制器之一，用于让系统跟踪目标状态。\n基本思想：根据当前状态与目标状态的误差，计算控制力。误差 \\( e = \\bar{x} - x \\)（目标减当前）。控制律为：\n\\[ f = k_p e + k_d \\dot{e} \\]\n其中 \\( k_p \\) 是比例增益（刚度），\\( k", "u": "GAMES105/105_L09.html#s4"}, {"c": "GAMES105 L09 · 第 9 讲：驱动仿真角色——关节力矩与 PD 控制", "t": "5. 角色动画中的 PD 控制应用", "x": "PD 控制广泛应用于角色动画中，主要有以下几种场景：\n\n姿态控制：给定目标姿态（关节角度），用 PD 控制计算关节力矩，使角色保持或达到该姿态。例如，物理动画中让角色跟随动画蓝图的目标姿势。\n轨迹跟踪：给定目标轨迹（随时间变化的关节角度），PD 控制使角色跟踪该轨迹。常用于运动捕捉数据驱动仿真角色。", "u": "GAMES105/105_L09.html#s5"}, {"c": "GAMES105 L09 · 核心结论", "t": "刚体动力学由牛顿-欧拉方程描述：线动量变化率等于外力，角动量变化率等于外力矩。", "x": "", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 核心结论", "t": "关节力矩是作用在关节上的内部力矩，施加时对子刚体加 τ，对父刚体加 -τ，系统总力矩为零。", "x": "", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 核心结论", "t": "前向动力学：已知力/力矩求运动；逆向动力学：已知运动求力/力矩。", "x": "", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 核心结论", "t": "欠驱动系统：执行器数量少于自由度，无法任意产生所有运动。", "x": "", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 核心结论", "t": "PD 控制律：f = kp * e + kd * ė，其中 e = 目标状态 - 当前状态；比例项消除误差，微分项抑制振荡。", "x": "", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 核心结论", "t": "PD 控制存在稳态误差，增大 kp 可减小误差但可能导致不稳定。", "x": "", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 核心结论", "t": "角色动画中常用 PD 控制跟踪目标姿态或轨迹，通过调整刚度和阻尼来改变运动风格。", "x": "", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 术语", "t": "Joint Torque / 关节力矩", "x": "作用在关节上的内部力矩，成对施加于父子刚体，不改变系统总动量。", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 术语", "t": "Forward Dynamics / 前向动力学", "x": "已知力/力矩求运动，是物理仿真器的工作。", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 术语", "t": "Inverse Dynamics / 逆向动力学", "x": "已知运动求力/力矩，是控制器的工作。", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 术语", "t": "Underactuated / 欠驱动", "x": "执行器数量少于自由度，无法任意产生所有运动。", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 术语", "t": "PD Control / 比例-微分控制", "x": "根据误差和误差变化率计算控制力，f = kp e + kd ė。", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 术语", "t": "Steady-state Error / 稳态误差", "x": "PD 控制中，由于比例项需要误差来产生力平衡外力，系统稳定时存在的偏差。", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 术语", "t": "Stiffness / 刚度", "x": "PD 控制中的比例增益 kp，越大系统越硬，响应越快，但可能不稳定。", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 术语", "t": "Damping / 阻尼", "x": "PD 控制中的微分增益 kd，抑制振荡，提供稳定性。", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 练习", "t": "解释关节力矩如何施加到关节系统上，并说明为什么系统总力矩为零。", "x": "", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 练习", "t": "给定一个 PD 控制器，kp=100, kd=10，当前误差 e=0.1，误差变化率 ė=0.05，求控制力。若目标速度为零，当前速度为 0.2，误差 e=0.", "x": "", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 练习", "t": "在角色动画中，如何调整 PD 控制器的参数来改变角色的运动风格？请举例说明。", "x": "", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L09 · 练习", "t": "解释欠驱动系统的概念，并说明为什么人形机器人是欠驱动的。", "x": "", "u": "GAMES105/105_L09.html"}, {"c": "GAMES105 L06a · 第 6a 讲：学习型角色动画（续）——从运动模型到 PFNN 与生成模型", "t": "1. 为什么要把运动当成概率分布来学", "x": "传统角色动画靠状态机、混合树和手工调参：走、跑、跳每个状态各做一段，切换靠条件。问题是状态一多，组合爆炸，而且“自然不自然”很难用规则写清楚。\n\\n这一讲的出发点很朴素：给一堆示例运动，让模型学会“什么样的运动是自然的”。课件里把一段运动记作 \\(X=(x_1,\\dots,x_T)\\)，每一帧 \\(", "u": "GAMES105/105_L06a.html#s1"}, {"c": "GAMES105 L06a · 第 6a 讲：学习型角色动画（续）——从运动模型到 PFNN 与生成模型", "t": "2. 从整段运动到逐帧预测：链式法则与马尔可夫假设", "x": "直接对整段 \\(X\\) 建模维度太高（\\(T\\) 帧 × 每帧几十维）。课件用条件概率链式法则把它拆开：\n\\[ p(X|z)=p(x_1|z)\\prod_{t=2}^{T}p(x_t|x_{t-1},\\dots,x_1;z) \\]\\n意思是：整段运动的概率 = 第一帧的概率 × 每一帧在给定历史下的", "u": "GAMES105/105_L06a.html#s2"}, {"c": "GAMES105 L06a · 第 6a 讲：学习型角色动画（续）——从运动模型到 PFNN 与生成模型", "t": "3. 怎么训练这个一步预测网络", "x": "有了 \\(x_t=f(x_{t-1};\\theta)\\)，训练就是标准的监督学习：从示例运动里切出大量相邻帧对 \\((x_{t-1},x_t)\\)，让网络输出逼近真实下一帧。课件给出的损失是平方误差之和：\n\\[ F(\\theta)=\\sum_{(x_{t-1},x_t)}\\big\\|f(x_{t-1", "u": "GAMES105/105_L06a.html#s3"}, {"c": "GAMES105 L06a · 第 6a 讲：学习型角色动画（续）——从运动模型到 PFNN 与生成模型", "t": "4. 歧义问题：一帧输入不够，需要隐变量", "x": "只用 \\(x_{t-1}\\) 预测 \\(x_t\\) 会遇到歧义（Ambiguity）：同一个当前姿态，下一步可能是继续走、转弯、停下、起跳。课件 P35–P39 用同一张图反复追问“\\(x_t\\) 到底是哪个？”，说明这是一个多模态问题。\n\\n用 MSE 训练时，网络会把多个合理答案平均掉，得到一个", "u": "GAMES105/105_L06a.html#s4"}, {"c": "GAMES105 L06a · 第 6a 讲：学习型角色动画（续）——从运动模型到 PFNN 与生成模型", "t": "5. 混合专家与 PFNN 的相位插值", "x": "有了相位 \\(\\phi\\)，怎么让网络随相位变化？最直接的想法是混合专家（Mixture of Experts, MoE）：训练 \\(N\\) 个专家网络 \\(f(x;\\theta_i)\\)，输出加权和\n\\[ y=\\sum_i w_i\\,f(x;\\theta_i) \\]\\n但这样每帧要跑 \\(N\\) ", "u": "GAMES105/105_L06a.html#s5"}, {"c": "GAMES105 L06a · 第 6a 讲：学习型角色动画（续）——从运动模型到 PFNN 与生成模型", "t": "6. 生成模型：从噪声到运动", "x": "自回归模型给的是确定性映射 \\(x_t=f(x_{t-1};z)\\)，生成模型则直接学分布 \\(p(x)\\)，从随机噪声采样出运动。课件把主流做法归为四类，共同点是：先定义 \\(z\\sim\\mathcal{N}(0,I)\\)，再学一个映射 \\(f(z)\\) 去逼近真实数据分布。\n\n变分自编码器（Va", "u": "GAMES105/105_L06a.html#s6"}, {"c": "GAMES105 L06a · 核心结论", "t": "运动模型就是对“一段运动是否自然”建模：\\(p(X)\\) 越大越自然，控制参数 \\(z\\) 给定时变成条件分布 \\(p(X|z)\\)。", "x": "", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 核心结论", "t": "整段运动的概率可用链式法则拆成 \\(p(x_1)\\prod_t p(x_t|x_{t-1},\\dots;z)\\)，这是自回归建模的数学基础。", "x": "", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 核心结论", "t": "马尔可夫假设把无限历史压成上一帧：\\(x_t=f(x_{t-1};z)\\)，网络只学“一步转移”。", "x": "", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 核心结论", "t": "只用 \\(x_{t-1}\\) 预测 \\(x_t\\) 会有歧义（同一帧可能对应多种下一步），需要隐变量 \\(z\\) 提供额外信息。", "x": "", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 核心结论", "t": "PFNN 把 \\(z\\) 取为相位 \\(\\phi\\) 加控制参数 \\(c\\)，用相位在多个专家网络参数间做 Catmull-Rom 插值，得到随步态周期平滑变化", "x": "", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 核心结论", "t": "生成模型（VAE/GAN/Flow/Diffusion）从噪声 \\(z\\sim\\mathcal{N}(0,I)\\) 出发，学习映射 \\(f(z)\\) 去逼近真实", "x": "", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 术语", "t": "Autoregressive Model / 自回归模型", "x": "用上一帧预测下一帧并滚动生成的模型。", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 术语", "t": "Markov Property / 马尔可夫性质", "x": "假设下一步只依赖当前帧，与更早历史无关。", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 术语", "t": "Latent Variable / 隐变量", "x": "未观测到的内部状态，用来消除多模态歧义。", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 术语", "t": "Phase / 相位", "x": "表示步态周期进行到哪的循环变量，取值在 \\([0,2\\pi)\\)。", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 术语", "t": "Mixture of Experts / 混合专家", "x": "多个子网络加权组合，权重可由输入决定。", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 术语", "t": "Catmull-Rom Spline / Catmull-Rom 样条", "x": "一阶连续的三次插值，用于平滑混合网络参数。", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 术语", "t": "Variational Autoencoder / 变分自编码器", "x": "用编码器-解码器学隐空间分布的生成模型。", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 术语", "t": "Diffusion Model / 扩散模型", "x": "通过加噪/去噪过程学习数据分布的生成模型。", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 术语", "t": "Stochastic Gradient Descent / 随机梯度下降", "x": "用小批量样本估计梯度并迭代更新参数。", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 练习", "t": "用条件概率链式法则写出 \\(p(X|z)\\) 的分解式，并说明马尔可夫假设做了哪一步简化。", "x": "", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 练习", "t": "为什么只用 \\(x_{t-1}\\) 预测 \\(x_t\\) 会出现歧义？举一个角色动画中的具体例子，并说明 PFNN 如何缓解。", "x": "", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 练习", "t": "PFNN 的加权混合专家与普通混合专家在计算上有何区别？为什么前者更适合实时？", "x": "", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 练习", "t": "写出 SGD 的参数更新式，并解释式中每一项的含义。", "x": "", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L06a · 练习", "t": "实践题：如果你要用 PFNN 思路做一个 UE 角色控制器，列出你需要准备的三类数据和两个运行时模块。", "x": "", "u": "GAMES105/105_L06a.html"}, {"c": "GAMES105 L03 · 第 3 讲：角色运动学——正向运动学与逆向运动学", "t": "1. 骨架、关节与“为什么转了关节却没动”", "x": "角色动画里的“运动学（kinematics）”只关心几何运动本身，不关心力和质量——用课件里的定义：研究物体运动而不考虑受力。所以这一讲我们只谈位置、朝向、旋转，不谈物理。\n\\n一个角色（character）在引擎里通常由骨架（skeleton）驱动。骨架由关节（joint）和连接它们的骨骼/连杆（", "u": "GAMES105/105_L03.html#s1"}, {"c": "GAMES105 L03 · 第 3 讲：角色运动学——正向运动学与逆向运动学", "t": "2. 正向运动学：朝向累乘、位置累加", "x": "设第 \\(i\\) 个关节的局部旋转为 \\(R_i\\)，它相对父关节的骨长为 \\(\\boldsymbol{l}_i\\)（在父关节局部坐标下表示）。课件给出的递推关系是：\n\\[\\nQ_i = Q_{i-1} R_i\n\\]\n\\[\n\\boldsymbol{p}_i = \\boldsymbol{p}_{i-1", "u": "GAMES105/105_L03.html#s2"}, {"c": "GAMES105 L03 · 第 3 讲：角色运动学——正向运动学与逆向运动学", "t": "3. 逆向运动学：从目标位置反推关节旋转", "x": "FK 是“旋转 → 位置”，IK 则反过来：给定末端执行器的目标位置 \\(\\tilde{\\boldsymbol{x}}\\)，求各关节旋转。课件用“手要够到桌上的杯子”这类例子说明需求：动画师不想手动摆每一根手指和手腕，只想把脚/手钉在一个点上，让系统自动解出关节角。\n\\nIK 比 FK 难，原因有三", "u": "GAMES105/105_L03.html#s3"}, {"c": "GAMES105 L03 · 第 3 讲：角色运动学——正向运动学与逆向运动学", "t": "4. 把 IK 写成优化问题", "x": "一般 IK 没有闭式解，课件把它统一成优化问题。定义目标函数为末端位置与目标位置之差的平方：\n\\[\\nF(\\boldsymbol{\\theta}) = \\| f(\\boldsymbol{\\theta}) - \\tilde{\\boldsymbol{x}} \\|^2\n\\]\n\\n其中 \\(f(\\bolds", "u": "GAMES105/105_L03.html#s4"}, {"c": "GAMES105 L03 · 第 3 讲：角色运动学——正向运动学与逆向运动学", "t": "5. CCD 与梯度下降：两种“找方向”的直觉", "x": "循环坐标下降（Cyclic Coordinate Descent, CCD） 是最容易实现的 IK：从末端往根依次处理每个关节，每次只转这一个关节，使得“该关节到末端的向量”尽量指向目标 \\(\\tilde{\\boldsymbol{x}}\\)。因为只转一个关节时问题退化成一维，可以直接用向量夹角算出旋", "u": "GAMES105/105_L03.html#s5"}, {"c": "GAMES105 L03 · 第 3 讲：角色运动学——正向运动学与逆向运动学", "t": "6. Jacobian：有限差分与几何法", "x": "上面所有方法都绕不开 Jacobian 矩阵 \\(J = \\partial f / \\partial \\boldsymbol{\\theta}\\)。它的第 \\(i\\) 列表示“只动第 \\(i\\) 个关节参数时，末端位置怎么变”。对 \\(n\\) 个参数、三维末端，\\(J\\) 是 \\(3 \\times n", "u": "GAMES105/105_L03.html#s6"}, {"c": "GAMES105 L03 · 第 3 讲：角色运动学——正向运动学与逆向运动学", "t": "7. Gauss-Newton、伪逆与阻尼：稳定地解 IK", "x": "梯度下降只用一阶信息，收敛慢。Gauss-Newton 法 在当前姿态处对 \\(f\\) 做一阶近似：\n\\[\\nf(\\boldsymbol{\\theta}) \\approx f(\\boldsymbol{\\theta}_i) + J (\\boldsymbol{\\theta} - \\boldsymbol{", "u": "GAMES105/105_L03.html#s7"}, {"c": "GAMES105 L03 · 核心结论", "t": "角色姿态由根节点平移加各关节旋转共同决定；关节旋转必须通过运动学计算才能变成可见的骨骼位置。", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 核心结论", "t": "FK 是“已知所有关节旋转，求末端位置”，沿链从根到末端递推：朝向累乘、位置累加。", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 核心结论", "t": "IK 是“已知末端目标位置，求关节旋转”，本质是求解 \\(f(\\boldsymbol{\\theta}) = \\tilde{\\boldsymbol{x}}\\)，通", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 核心结论", "t": "IK 的通用做法是把它变成优化问题：最小化末端与目标的距离平方，再用迭代算法逼近。", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 核心结论", "t": "CCD 每次只转一个关节，让该关节到末端的向量指向目标，简单但收敛慢、结果依赖关节顺序。", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 核心结论", "t": "梯度下降沿负梯度方向更新；Jacobian 转置法用 \\(J^T \\Delta\\) 作为更新方向，不需要求逆。", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 核心结论", "t": "Gauss-Newton 用一阶近似把问题变成线性最小二乘，得到 \\(J^T J \\Delta\\boldsymbol{\\theta} = -J^T \\Delta", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 核心结论", "t": "Jacobian 可用有限差分逐参数扰动求得，也可用几何法（旋转轴叉乘末端相对位置）直接写出，后者更快更准。", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 术语", "t": "Kinematics / 运动学", "x": "只研究位置、朝向、速度等几何运动，不考虑力。", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 术语", "t": "Forward Kinematics (FK) / 正向运动学", "x": "已知所有关节旋转，递推求末端位置。", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 术语", "t": "Inverse Kinematics (IK) / 逆向运动学", "x": "已知末端目标位置，反求关节旋转。", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 术语", "t": "End Effector / 末端执行器", "x": "链条末端我们关心的点，如脚踝、手腕。", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 术语", "t": "Degrees of Freedom (DoF) / 自由度", "x": "独立参数的个数，铰链 1 个、球关节 3 个。", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 术语", "t": "Jacobian Matrix / 雅可比矩阵", "x": "末端位置对关节参数的偏导矩阵，描述参数扰动如何影响末端。", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 术语", "t": "CCD / 循环坐标下降", "x": "逐关节旋转使末端指向目标的迭代 IK 方法。", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 术语", "t": "Gauss-Newton / 高斯-牛顿法", "x": "用一阶近似把非线性最小二乘化为线性方程求解。", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 术语", "t": "Pseudoinverse / 伪逆", "x": "矩阵不可逆时的广义逆，用于最小范数解。", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 术语", "t": "Damping / 阻尼", "x": "在正规方程上加 \\( \\lambda I \\)，避免奇异并抑制关节角爆炸。", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 练习", "t": "一条两关节链，骨长 \\(l_1 = l_2 = 1\\)，目标点距根关节距离 \\(d = 2.5\\)，问 IK 有解吗？若 \\(d = 0.1\\) 呢？", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 练习", "t": "写出 FK 的递推公式，并说明为什么位置递推用 \\(Q_{i-1}\\) 而不是 \\(Q_i\\)。", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 练习", "t": "用几何法写出铰链关节 \\(i\\) 的 Jacobian 列，并解释每个量的含义。", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 练习", "t": "Gauss-Newton 更新中 \\(J^T J\\) 不可逆时会怎样？给出两种补救方案。", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES105 L03 · 练习", "t": "在 UE 里做一个“脚踩地面”的 IK：需要哪些节点与目标？为什么 Two Bone IK 需要 Joint Target？", "x": "", "u": "GAMES105/105_L03.html"}, {"c": "GAMES202 L01 · 第 1 讲：课程导论——实时高质量渲染的全景与学习路线", "t": "1. 这门课到底在讲什么：速度、真实感与可靠性", "x": "GAMES202 的标题是 Real-Time High Quality Rendering（实时高质量渲染），定位是「中级课程」——上接图形学基础（GAMES101 一类），下接研究前沿。它不教你从零写渲染器，而是把工业界已经在用的高级实时技术系统地过一遍。\n先把标题拆成两个词：\n\nReal-Ti", "u": "GAMES202/202_L01.html#s1"}, {"c": "GAMES202 L01 · 第 1 讲：课程导论——实时高质量渲染的全景与学习路线", "t": "2. 渲染的定义与课程主题地图", "x": "课件用一句话定义了渲染：计算光 → 眼睛（Calculating light -&gt; eye）。输入是一个 3D 场景（meshes、lights 等），输出是一张图像。这个定义看似简单，但它决定了整门课的所有主题都是在回答「光怎么从光源到相机」。\n课件把实时渲染的「最高层」拆成几大块，对应本课", "u": "GAMES202/202_L01.html#s2"}, {"c": "GAMES202 L01 · 第 1 讲：课程导论——实时高质量渲染的全景与学习路线", "t": "3. 这门课不教什么：划清边界才不会走偏", "x": "导论课最有价值的部分之一，是明确「不教什么」。课件列了四类：\n\n不教 3D 建模和用 UE 做游戏开发。课件甚至贴了 CSGO 的 POV 相机设置、Maya 里做角色动画的教程链接，意思是这些请去别处学。本课程假设你已经有场景和模型，只关心「怎么把它渲染好」。\n不教电影/动画里昂贵但更准确的光传输", "u": "GAMES202/202_L01.html#s3"}, {"c": "GAMES202 L01 · 第 1 讲：课程导论——实时高质量渲染的全景与学习路线", "t": "4. 怎么学：科学 vs 技术，以及「工业界领先学术界」", "x": "课件给了一条很重要的学习心法：理解科学与技术的区别。\n\nScience（科学）= knowledge（知识）：回答「为什么」「规律是什么」。\nTechnology（技术）= engineering skills that turn science into product（把科学变成产品的工程技能）", "u": "GAMES202/202_L01.html#s4"}, {"c": "GAMES202 L01 · 第 1 讲：课程导论——实时高质量渲染的全景与学习路线", "t": "5. 课程安排：前置、作业、项目与工具", "x": "这一节把课程的后勤信息整理清楚，方便你规划学习节奏。\n前置要求（Prerequisites）\n\n对渲染/图形学有强烈兴趣；\n有计算机图形学基础（或等价经验）；\n基础微积分；\n基础 GLSL（OpenGL Shader Language）——下一讲会快速复习，并配一个可选的热身作业。\n\n课程信息\n\n课", "u": "GAMES202/202_L01.html#s5"}, {"c": "GAMES202 L01 · 第 1 讲：课程导论——实时高质量渲染的全景与学习路线", "t": "6. 实时渲染的五十年：从 SGI 到光追", "x": "课件用一条时间线串起实时渲染的演进，这条线是理解后续所有技术「为什么出现」的背景。\n（1）最早的交互式 3D 图形管线\n从 SGI 机器（Clark 等人）到今天的 OpenGL 管线，早期重点一直是「更多几何、更多纹理」，再加一些提升真实感的小技巧（shadow mapping、accumulat", "u": "GAMES202/202_L01.html#s6"}, {"c": "GAMES202 L01 · 第 1 讲：课程导论——实时高质量渲染的全景与学习路线", "t": "7. 三块技术里程碑：shader、预计算、交互式光追", "x": "课件把实时渲染的技术与算法里程碑归纳为三块，这也是理解后续各讲的「索引」。\n（1）可编程图形硬件（Programmable Graphics Hardware，约 20 年前）\n代表是 NVIDIA 的 A New Dawn demo。现代 GPU 管线里，Vertex Shader（顶点着色器） ", "u": "GAMES202/202_L01.html#s7"}, {"c": "GAMES202 L01 · 第 1 讲：课程导论——实时高质量渲染的全景与学习路线", "t": "8. 下一讲预告与本讲收束", "x": "课件最后预告了下一讲：一次快速而「粗暴」的复习（a swift and brutal recap），内容包括：\n\nGraphics Pipeline（图形管线）；\nShader Language（着色语言）；\nRendering Equation（渲染方程）；\nCalculus（微积分）。\n\n这四样", "u": "GAMES202/202_L01.html#s8"}, {"c": "GAMES202 L01 · 核心结论", "t": "实时渲染的核心矛盾是「速度 vs 质量」：必须在每帧毫秒级预算内给出可信结果，因此本质是「快速 + 近似」的离线渲染。", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 核心结论", "t": "实时渲染不仅要求快，还要求可靠（dependability）：不允许出现不可控的失败，结果必须每帧稳定正确（精确或近似均可）。", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 核心结论", "t": "渲染的定义始终是「计算光 → 眼睛」：输入是 3D 场景（网格、光源等），输出是图像。", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 核心结论", "t": "实时渲染技术演进的三块里程碑：可编程图形硬件（shader）、基于预计算的方法、交互式光线追踪（CUDA/OptiX + 降噪）。", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 核心结论", "t": "预计算方法的典型套路是「固定几何、固定视角，动态改变光照」，把复杂效果提前算好，运行时只付最小代价。", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 核心结论", "t": "工业界在实时渲染技术上领先学术界，学习要靠大量实践（practice makes perfect），而不是只读论文。", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 核心结论", "t": "本课程是「基础课」与「研究前沿」之间的桥梁：讲的是工业界已经在用的高级实时技术，而不是 OpenGL 入门或离线渲染。", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 核心结论", "t": "课程作业用 GLSL + WebGL 骨架，重点是写 shader，不需要 IDE；最终以课程项目代替考试。", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 术语", "t": "Real-Time Rendering / 实时渲染", "x": "在毫秒级预算内每帧当场生成图像，要求速度、真实感与可靠性兼顾。", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 术语", "t": "Dependability / 可靠性", "x": "实时渲染要求任何时刻结果都正确（精确或近似），不允许不可控失败。", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 术语", "t": "Interactivity / 交互性", "x": "每一帧都在运行时生成，而非预渲染整段动画。", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 术语", "t": "Programmable Shader / 可编程着色器", "x": "GPU 上可编程的顶点/片元阶段，2000 年前后出现，是实时渲染的转折点。", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 术语", "t": "Precomputation-based Methods / 基于预计算的方法", "x": "把复杂效果提前算好，运行时只付最小代价；典型如 PRT、Lightmap。", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 术语", "t": "PRT (Precomputed Radiance Transfer) / 预计算辐射传输", "x": "把光传输预计算成系数，运行时点乘，支持动态光照但几何/视角受限。", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 术语", "t": "Interactive Ray Tracing / 交互式光线追踪", "x": "GPU 低采样率光追 + 降噪，代表技术为 CUDA/OptiX。", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 术语", "t": "SPP (Samples Per Pixel) / 每像素采样数", "x": "光追中每个像素的采样次数；实时常用约 1 SPP，靠降噪补画质。", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 术语", "t": "NPR (Non-Photorealistic Rendering) / 非真实感渲染", "x": "刻意风格化的渲染，如卡通渲染；课程不深入讲。", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 术语", "t": "GLSL / OpenGL 着色语言", "x": "本课程作业使用的着色语言，语法与 HLSL 高度相似。", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 练习", "t": "用一句话解释「实时高质量渲染」中的「高质量」包含哪两层含义，并各举一个反例说明缺少它会怎样。", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 练习", "t": "课件把实时渲染定义为「fast & approximate offline rendering + systematic engineering」。请解释为什么", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 练习", "t": "课件把实时渲染的技术里程碑分为三块。请分别写出名称、大致年代、代表技术或工作，并说明各自「换速度」的思路。", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 练习", "t": "判断以下说法是否正确并说明理由：（a）片元 shader 可以读取同一帧中任意其他像素的颜色；（b）预计算方法适合几何和视角都频繁变化的场景；（c）实时渲染不允", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L01 · 练习", "t": "实践题：在 UE 或 Unity 中新建一个场景，开启实时 GI（UE 用 Lumen，Unity 用 HDRP Ray Tracing 或 Enlighten", "x": "", "u": "GAMES202/202_L01.html"}, {"c": "GAMES202 L03 · 第 3 讲：实时阴影（一）——Shadow Mapping、PCF 与 PCSS", "t": "1. 两趟 Shadow Mapping：从光源拍一张深度图，再从眼睛做比较", "x": "Shadow Mapping 是实时阴影最经典、最基础的算法，早在《玩具总动员》时代的离线渲染里就在用。它只需要两趟（two-pass）：\n第一趟：从光源渲染。 把虚拟相机放在光源位置，朝场景渲染一遍，但只输出深度——得到一张「深度纹理」（depth texture），通常叫 shadow map（", "u": "GAMES202/202_L03.html#s1"}, {"c": "GAMES202 L03 · 第 3 讲：实时阴影（一）——Shadow Mapping、PCF 与 PCSS", "t": "2. 自遮挡与 bias：为什么阴影会“长毛”，又为什么会“飘起来”", "x": "Shadow Mapping 最烦人的瑕疵是自遮挡（self occlusion）：明明朝着光的表面，却被自己投上了条纹状阴影，俗称 shadow acne。\n原因很朴素：SM 是按像素离散存储的，一个像素记录的是该小区域内最近表面的深度。当光线斜着打到表面时，同一个像素覆盖的表面深度差异很大，着色", "u": "GAMES202/202_L03.html#s2"}, {"c": "GAMES202 L03 · 第 3 讲：实时阴影（一）——Shadow Mapping、PCF 与 PCSS", "t": "3. 阴影背后的数学：把可见性从积分里提出来", "x": "这一节回答一个更深的问题：Shadow Mapping 到底在近似什么？\n带显式可见性的渲染方程是：\n\\[ L_o(p,\\omega_o)=\\int_{\\Omega^+} L_i(p,\\omega_i)\\, f_r(p,\\omega_i,\\omega_o)\\, \\cos\\theta_i\\, V(p,", "u": "GAMES202/202_L03.html#s3"}, {"c": "GAMES202 L03 · 第 3 讲：实时阴影（一）——Shadow Mapping、PCF 与 PCSS", "t": "4. PCF：比较之后再平均，才能得到非 0/1 的可见性", "x": "硬阴影边缘是锯齿状的，最直觉的修法是“把 shadow map 模糊一下”。但课件明确说：不行。纹理滤波只是对颜色做平均，先模糊 shadow map 得到的是模糊的深度值，再拿它去比较，结果仍然是 0 或 1 的二值可见性——边缘该硬还是硬。\n正确做法是 Percentage Closer Fil", "u": "GAMES202/202_L03.html#s4"}, {"c": "GAMES202 L03 · 第 3 讲：实时阴影（一）——Shadow Mapping、PCF 与 PCSS", "t": "5. PCSS：用遮挡物距离决定滤波核大小", "x": "现实中的阴影有本影（umbra）和半影（penumbra）：遮挡物离接收面越近，半影越窄、阴影越锐；越远，半影越宽、阴影越软。PCF 的核大小固定，做不到这一点。\nPercentage Closer Soft Shadows（PCSS） 的关键观察就是：滤波核大小 ↔ 遮挡物距离。更准确地说，取决于", "u": "GAMES202/202_L03.html#s5"}, {"c": "GAMES202 L03 · 核心结论", "t": "Shadow Mapping 是两趟算法：先从光源渲染一张深度图（SM），再从相机渲染，把可见点投影回光源空间比较深度，深度更大则被遮挡。", "x": "", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 核心结论", "t": "它是图像空间算法：不需要场景几何信息，但会带来自遮挡（shadow acne）与锯齿（aliasing）两类固有问题。", "x": "", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 核心结论", "t": "自遮挡用 bias 缓解，但 bias 过大会产生“阴影脱离物体”（peter-panning）；second-depth shadow mapping 是另一", "x": "", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 核心结论", "t": "实时渲染里大量使用“把可见性从积分中提出来”的近似：只有当光源支撑小（点光/方向光）或 integrand 平滑（漫反射、常量环境光）时才比较准。", "x": "", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 核心结论", "t": "PCF 的正确做法是对每个 fragment 做多次深度比较、再对比较结果求平均，得到非 0/1 的可见性；直接模糊 shadow map 再比较仍然是二值的。", "x": "", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 核心结论", "t": "PCF 滤波核越大阴影越软，但核大小固定时软硬不随距离变化；PCSS 用遮挡物平均深度动态决定核大小，从而得到近实远虚的软阴影。", "x": "", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 核心结论", "t": "PCSS 三步：blocker search 求平均遮挡深度 → 用相似三角形估计半影大小 → 以该大小做 PCF。", "x": "", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 术语", "t": "Shadow Mapping / 阴影贴图", "x": "两趟图像空间阴影算法：光源深度图 + 相机视角深度比较。", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 术语", "t": "Shadow Acne / 自遮挡/阴影痤疮", "x": "离散深度比较导致的表面条纹状错误阴影。", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 术语", "t": "Peter-panning / 阴影脱离", "x": "bias 过大导致阴影与物体接触处分离、物体像浮空。", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 术语", "t": "Second-depth Shadow Mapping / 第二深度阴影", "x": "SM 存第一与第二深度中点，减少自遮挡，但要求水密几何。", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 术语", "t": "PCF / 百分比渐进滤波", "x": "对邻域逐像素比较后平均，得到 0..1 可见性，用于抗锯齿。", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 术语", "t": "PCSS / 百分比渐进软阴影", "x": "用平均遮挡深度动态决定 PCF 核大小，得到近实远虚的半影。", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 术语", "t": "Blocker Search / 遮挡物搜索", "x": "PCSS 第一步：在 SM 区域中找遮挡物并求平均深度。", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 术语", "t": "Penumbra / 半影", "x": "本影外沿的渐变过渡区，宽度由遮挡物距离与光源尺寸决定。", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 术语", "t": "Visibility / 可见性", "x": "渲染方程中的 0/1 项，实时渲染常近似为可分离的平均值。", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 练习", "t": "用自己的话说明 Shadow Mapping 为什么是“图像空间算法”，并各举一个它因此获得的优点和缺点。", "x": "", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 练习", "t": "某方向光场景中，SM 记录某像素深度为 0.40，着色点光源空间深度为 0.42，bias 取 0.01。该点是否被遮挡？若 bias 改为 0.05 呢？并解", "x": "", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 练习", "t": "为什么不能“先把 shadow map 做高斯模糊，再拿模糊后的深度去比较”来获得软阴影？PCF 又是怎么做的？", "x": "", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 练习", "t": "PCSS 中，若接收面深度 \\(d_{Receiver}=0.8\\)，平均遮挡深度 \\(d_{Blocker}=0.5\\)，光源尺寸 \\(w_{Light}=0", "x": "", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L03 · 练习", "t": "在 UE 里做一个实验：把 Directional Light 的 Shadow Bias 从默认值逐步调大，观察阴影根部。记录你看到的现象并解释原因；再说明你", "x": "", "u": "GAMES202/202_L03.html"}, {"c": "GAMES202 L05 · 第 5 讲：实时环境光照与距离场软阴影", "t": "1. 距离场：把几何变成一张标量场", "x": "距离场（Distance Field）是这一讲前半部分的核心工具。它的定义很直白：空间中任意一点 \\(\\mathbf{p}\\)，距离场给出该点到物体表面最近点的距离；如果带符号（Signed Distance Field, SDF），则物体内部为负、外部为正（或相反约定）。\n为什么距离场有用？因为它", "u": "GAMES202/202_L05.html#s1"}, {"c": "GAMES202 L05 · 第 5 讲：实时环境光照与距离场软阴影", "t": "2. 用距离场做射线步进（Sphere Tracing）", "x": "距离场最直接的用法是射线与场景求交。传统求交需要遍历三角形，而用距离场可以做「球体追踪」（Sphere Tracing）：从射线起点 \\(\\mathbf{o}\\) 出发，沿方向 \\(\\mathbf{d}\\) 步进。在当前位置 \\(\\mathbf{p}\\)，距离场值 \\(\\text{SDF}(\\mat", "u": "GAMES202/202_L05.html#s2"}, {"c": "GAMES202 L05 · 第 5 讲：实时环境光照与距离场软阴影", "t": "3. 距离场软阴影：安全角度与可见性", "x": "软阴影的关键是半影（penumbra）。用距离场可以估算每个着色点被遮挡的程度：从眼睛（或光源）出发沿射线步进，每一步计算一个「安全角度」\\(\\theta\\)，它表示以当前点为中心、半径 \\(\\text{SDF}(\\mathbf{p})\\) 的球对观察点所张的角度。角度越大，说明周围越空旷，可见性越", "u": "GAMES202/202_L05.html#s3"}, {"c": "GAMES202 L05 · 第 5 讲：实时环境光照与距离场软阴影", "t": "4. 环境光照：IBL 与渲染方程", "x": "环境光照（Environment Lighting）用一张全景图表示来自所有方向的远处光照，通常存为球面贴图（Spherical Map）或立方体贴图（Cube Map）。用环境光照来着色一个点，称为基于图像的光照（Image-Based Lighting, IBL）。\n着色需要求解渲染方程：\n\\[", "u": "GAMES202/202_L05.html#s4"}, {"c": "GAMES202 L05 · 第 5 讲：实时环境光照与距离场软阴影", "t": "5. 拆分求和近似：把积分拆成两次查表", "x": "拆分求和（Split Sum）是 IBL 的经典近似，分两步。\n第一步：提出光照项。 利用 BRDF 的局部性，把光照项 \\(L_i\\) 从积分中提出：\n\\[\n\\int_{\\Omega^+} L_i(\\mathbf{p}, \\omega_i) f_r(\\mathbf{p}, \\omega_i, \\o", "u": "GAMES202/202_L05.html#s5"}, {"c": "GAMES202 L05 · 第 5 讲：实时环境光照与距离场软阴影", "t": "6. 距离场的优缺点与工业应用", "x": "距离场方法在实时渲染中有明显优势：速度快（步进次数远少于三角形遍历）、质量高（软阴影自然）。但缺点也很突出：需要预计算（生成距离场）、存储量大（三维纹理），且可能产生伪影（分辨率不足、步进误差）。\n工业界已经广泛应用：UE 的 Mesh Distance Fields 用于距离场阴影和环境光遮蔽；一", "u": "GAMES202/202_L05.html#s6"}, {"c": "GAMES202 L05 · 核心结论", "t": "距离场（SDF）给出空间中任意点到最近物体表面的最小距离（可带符号），是射线步进和软阴影的基础。", "x": "", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 核心结论", "t": "距离场软阴影的核心：沿射线步进时，用 SDF 值估算从眼睛看过去的安全角度，取最小值作为可见性度量；安全角度越小，阴影越硬。", "x": "", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 核心结论", "t": "环境光照着色需要求解渲染方程，直接蒙特卡洛采样太慢；利用 BRDF 的局部性（glossy 支撑小、diffuse 平滑）可以做大近似。", "x": "", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 核心结论", "t": "拆分求和近似第一步：把光照项从积分中提出，对环境贴图按不同粗糙度预过滤，运行时按反射方向查表并三线性插值。", "x": "", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 核心结论", "t": "拆分求和近似第二步：将微表面 BRDF 的 Fresnel 项用 Schlick 近似拆开，把 base color 提出，剩余部分预计算成关于粗糙度和入射角的", "x": "", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 核心结论", "t": "拆分求和完全避免了运行时采样，速度极快且结果与参考几乎一致，是工业界 IBL 的标准做法。", "x": "", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 核心结论", "t": "距离场方法优点是快且质量高，缺点是需要预计算、存储量大，且可能产生伪影。", "x": "", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 术语", "t": "Signed Distance Field (SDF) / 有符号距离场", "x": "空间中任意点到最近物体表面的最小距离，内部为负外部为正。", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 术语", "t": "Sphere Tracing / 球体追踪", "x": "利用距离场的安全距离进行射线步进求交的方法。", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 术语", "t": "Penumbra / 半影", "x": "软阴影中部分被遮挡的区域。", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 术语", "t": "Image-Based Lighting (IBL) / 基于图像的光照", "x": "用环境贴图作为光源照亮场景的技术。", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 术语", "t": "Split Sum Approximation / 拆分求和近似", "x": "将环境光照积分拆成光照预过滤和 BRDF 查找表两步的近似方法。", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 术语", "t": "Prefiltered Environment Map / 预过滤环境贴图", "x": "按不同粗糙度模糊后的环境贴图，用于快速查询。", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 术语", "t": "BRDF LUT / BRDF 查找表", "x": "预计算的双通道纹理，存储 BRDF 积分结果，按粗糙度和入射角查询。", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 术语", "t": "Microfacet BRDF / 微表面 BRDF", "x": "用微表面理论描述材质反射的模型，包含 Fresnel、NDF 和几何项。", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 术语", "t": "Schlick's Approximation / Schlick 近似", "x": "Fresnel 项的近似公式，用 \\(F_0\\) 和 \\((1-\\cos\\theta)^5\\) 表示。", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 练习", "t": "解释距离场软阴影中参数 k 的作用，并说明 k 增大时阴影变硬还是变软。", "x": "", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 练习", "t": "拆分求和近似中，第一步把光照项提出积分，这个近似在什么条件下比较准确？", "x": "", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 练习", "t": "为什么拆分求和的第二步需要预计算一张二维查找表？表中每个像素存储什么？", "x": "", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 练习", "t": "在 UE 中如何启用距离场阴影？简述步骤。", "x": "", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L05 · 练习", "t": "距离场方法有哪些主要缺点？如何缓解？", "x": "", "u": "GAMES202/202_L05.html"}, {"c": "GAMES202 L06 · 第 6 讲：环境光照与预计算辐射传输（PRT）", "t": "1. 环境光照下的阴影为什么难做", "x": "环境光照（environment lighting）是指用一张全景图（通常是 HDR）作为光源照亮场景。上一讲我们用 split sum 近似解决了没有阴影的环境光照着色问题，这一讲首先要补上阴影。\n渲染方程中，环境光照下的着色可以写成：\n\\[ L(o) = \\int_{\\Omega} L(i) \\", "u": "GAMES202/202_L06.html#s1"}, {"c": "GAMES202 L06 · 第 6 讲：环境光照与预计算辐射传输（PRT）", "t": "2. 频率与滤波：为什么积分会平滑", "x": "要理解 PRT，先要建立频率的直觉。\n任何函数都可以分解成不同频率的正弦/余弦波叠加——这就是傅里叶变换（Fourier Transform）的思想。低频分量对应函数中变化缓慢的部分（平滑），高频分量对应剧烈变化的部分（细节、边缘）。\n滤波（filtering） 就是去掉某些频率成分。低通滤波（lo", "u": "GAMES202/202_L06.html#s2"}, {"c": "GAMES202 L06 · 第 6 讲：环境光照与预计算辐射传输（PRT）", "t": "3. 基函数：用一组标准件表示任意函数", "x": "基函数（basis functions） 是一组固定的函数，任何其他函数都可以表示成它们的线性组合：\n\\[ f(x) = \\sum_i c_i B_i(x) \\]\n其中 \\(B_i\\) 是基函数，\\(c_i\\) 是系数。\n傅里叶级数就是一组基函数（正弦和余弦），多项式序列也可以是一组基函数。基函数的", "u": "GAMES202/202_L06.html#s3"}, {"c": "GAMES202 L06 · 第 6 讲：环境光照与预计算辐射传输（PRT）", "t": "4. 球谐函数（SH）：球面上的傅里叶", "x": "球谐函数（Spherical Harmonics, SH） 是定义在球面 \\(S^2\\) 上的一组 2D 基函数，可以看作一维傅里叶级数在球面上的推广。每个 SH 基函数 \\(B_i(\\omega)\\) 由一个阶数 \\(l\\) 和指数 \\(m\\) 标记，其中 \\(l \\ge 0\\)，\\(-l \\le", "u": "GAMES202/202_L06.html#s4"}, {"c": "GAMES202 L06 · 第 6 讲：环境光照与预计算辐射传输（PRT）", "t": "5. 用 SH 做环境光照着色：从积分到点积", "x": "把 SH 用到环境光照着色上，思路是：把光照 \\(L(i)\\) 和光传输（包含 BRDF、余弦项、可见性）都投影到 SH 空间，然后运行时只需计算系数点积。\n先看没有阴影的 diffuse 情况。渲染方程简化为：\n\\[ L(o) = \\rho \\int_{\\Omega} L(i) \\max(0, n", "u": "GAMES202/202_L06.html#s5"}, {"c": "GAMES202 L06 · 第 6 讲：环境光照与预计算辐射传输（PRT）", "t": "6. PRT：把阴影和全局光照预计算掉", "x": "前面没有考虑可见性 \\(V(i)\\)。预计算辐射传输（Precomputed Radiance Transfer, PRT） 由 Sloan 在 SIGGRAPH 2002 提出，核心思想是把渲染方程中的光照和光传输分离，并分别投影到基函数空间。\n渲染方程：\n\\[ L(o) = \\int_{\\Ome", "u": "GAMES202/202_L06.html#s6"}, {"c": "GAMES202 L06 · 第 6 讲：环境光照与预计算辐射传输（PRT）", "t": "7. 运行时渲染与效果对比", "x": "PRT 的运行时着色非常简单：\n\n把环境光照投影到 SH 得到系数 \\(l_i\\)（或者直接旋转已有的 SH 系数）。\n对每个着色点，计算 \\(L(o) \\approx \\rho \\sum_i l_i T_i\\)。\n\n对于 diffuse，这就是一个点积，可以在 shader 中高效实现。对于 gl", "u": "GAMES202/202_L06.html#s7"}, {"c": "GAMES202 L06 · 核心结论", "t": "环境光照下的阴影实时计算非常困难：V 项任意复杂且无法与光照分离，多光源方法成本随光源数线性增长。", "x": "", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 核心结论", "t": "工业界常用方案是只从最亮的光源生成少量阴影；研究方案包括 imperfect shadow maps、light cuts、RTRT 和 PRT。", "x": "", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 核心结论", "t": "频率直觉：低频函数变化缓慢，高频函数变化剧烈；两个函数乘积的积分相当于低通滤波，结果频率取两者中较低者。", "x": "", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 核心结论", "t": "基函数是一组可以表示其他函数的函数，傅里叶级数就是一组基函数；用少量基函数可以保留低频内容。", "x": "", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 核心结论", "t": "球谐函数（SH）是定义在球面上的 2D 基函数，与一维傅里叶级数类似，具有正交性、简单投影/重建、简单旋转和卷积等性质。", "x": "", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 核心结论", "t": "PRT 将渲染方程中的光照和光传输分离：光照投影到 SH 空间得到系数，光传输预计算并投影到 SH 空间，运行时只需点积（diffuse）或矩阵-向量乘法（gl", "x": "", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 核心结论", "t": "PRT 可以处理阴影和全局光照（互反射），代价是预计算和低频光照假设（不能处理高频动态光照）。", "x": "", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 术语", "t": "Environment Lighting / 环境光照", "x": "用全景图作为光源照亮场景。", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 术语", "t": "Fourier Transform / 傅里叶变换", "x": "把函数分解为不同频率正弦/余弦波叠加。", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 术语", "t": "Low-pass Filter / 低通滤波", "x": "保留低频、去掉高频，使信号平滑。", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 术语", "t": "Basis Functions / 基函数", "x": "一组标准函数，可线性组合表示其他函数。", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 术语", "t": "Spherical Harmonics (SH) / 球谐函数", "x": "球面上的正交基函数，常用于表示低频方向性信号。", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 术语", "t": "Projection / 投影", "x": "求函数在基函数上的系数：积分 f*B。", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 术语", "t": "Reconstruction / 重建", "x": "用系数和基函数恢复原函数。", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 术语", "t": "Precomputed Radiance Transfer (PRT) / 预计算辐射传输", "x": "预计算光传输并投影到基函数，运行时点积。", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 术语", "t": "Light Transport / 光传输", "x": "包含可见性、BRDF、余弦项的积分核。", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 术语", "t": "Irradiance / 辐照度", "x": "单位面积接收的光功率，diffuse 着色常用。", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 练习", "t": "为什么环境光照下的阴影难以实时计算？请从多光源和采样两个角度解释。", "x": "", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 练习", "t": "用 3 阶 SH（9 个系数）表示环境光照，投影和重建的公式分别是什么？", "x": "", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 练习", "t": "PRT 的预计算阶段和运行时阶段分别做什么？diffuse 和 glossy 的运行时计算有何不同？", "x": "", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 练习", "t": "在 Unity 中，Light Probes 使用几阶 SH？如何在 shader 中重建环境光照？", "x": "", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L06 · 练习", "t": "PRT 有哪些局限性？举出至少两点。", "x": "", "u": "GAMES202/202_L06.html"}, {"c": "GAMES202 L07 · 第 7 讲：实时全局光照（一）——从 PRT 到反射阴影贴图", "t": "1. 从 PRT 复习到光泽反射：光照与传输的分离", "x": "上一讲把环境光照下的着色问题拆成「光照」和「光传输」两部分。渲染方程写作：\n\\[ L_o(p,\\omega_o)=\\int_{\\Omega^+} L_i(p,\\omega_i)\\, f_r(p,\\omega_i,\\omega_o)\\, \\cos\\theta_i\\, V(p,\\omega_i)\\, d", "u": "GAMES202/202_L07.html#s1"}, {"c": "GAMES202 L07 · 第 7 讲：实时全局光照（一）——从 PRT 到反射阴影贴图", "t": "2. PRT 的边界：低频、静态与预计算数据", "x": "PRT 很优雅，但课件明确列出三条限制：\n\n低频：SH 是低频基函数，阶数有限时只能表示平滑变化的光照和传输。高频细节（锐利阴影、小面积光源、焦散）会被抹平。\n动态光照但静态场景/材质：传输项 \\(T\\) 是在固定场景几何和材质下预计算的。一旦物体移动或材质改变，预计算的传输就失效，必须重新计算。\n", "u": "GAMES202/202_L07.html#s2"}, {"c": "GAMES202 L07 · 第 7 讲：实时全局光照（一）——从 PRT 到反射阴影贴图", "t": "3. 小波：用非线性逼近换取全频率", "x": "SH 的问题是低频。课件引入小波（Wavelet），具体是二维 Haar 小波。与 SH 不同，小波变换后只保留少量非零系数，这是一种非线性逼近（non-linear approximation）：不是固定截断到前 \\(N\\) 个基函数，而是保留绝对值最大的 \\(N\\) 个系数。\n课件给出的对比很直", "u": "GAMES202/202_L07.html#s3"}, {"c": "GAMES202 L07 · 第 7 讲：实时全局光照（一）——从 PRT 到反射阴影贴图", "t": "4. 实时全局光照：一次反弹间接光的两个问题", "x": "课件从 PRT 转向实时 3D 全局光照（GI）。先给直觉：任何被直接照亮的表面都会再次成为光源，这就是一次反弹（one-bounce）间接光。实时渲染通常只做这一次反弹，因为多次反弹代价太高。\n要计算某个点 \\(p\\) 的间接光照，需要回答两个问题：\n\nQ1：哪些面片被直接照亮？ 提示：什么技术能", "u": "GAMES202/202_L07.html#s4"}, {"c": "GAMES202 L07 · 第 7 讲：实时全局光照（一）——从 PRT 到反射阴影贴图", "t": "5. 反射阴影贴图（RSM）：把 shadow map 像素当小面片光源", "x": "RSM 直接回答上一节的两个问题。\nQ1 的答案：用一张经典 shadow map。每个像素记录一个小面片的信息：深度、世界坐标、法线、通量（flux）。课件强调一个假设：反射面是漫反射，因此该面片向所有方向出射的辐射度相同，我们可以用相机方向上的出射辐射度代表所有方向。\nQ2 的答案：每个面片对 ", "u": "GAMES202/202_L07.html#s5"}, {"c": "GAMES202 L07 · 第 7 讲：实时全局光照（一）——从 PRT 到反射阴影贴图", "t": "6. RSM 的优缺点与工程取舍", "x": "课件最后总结 RSM：\n优点：容易实现。复用已有的 shadow map 管线，增加一张 G-Buffer 记录面片信息即可。\n缺点：\n\n性能随光源数线性增长：每个光源都需要一张 RSM 和一次采样求和，光源一多就撑不住。\n间接光没有可见性检查：面片对 \\(p\\) 的贡献没有做遮挡测试，会出现漏光。", "u": "GAMES202/202_L07.html#s6"}, {"c": "GAMES202 L07 · 核心结论", "t": "PRT 把渲染方程拆成光照项与传输项，各自投影到 SH 基函数上；漫反射渲染是系数点积，光泽反射是向量乘传输矩阵。", "x": "", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 核心结论", "t": "SH 是低频基函数，因此 PRT 只能表示低频光照与低频传输；小波是非线性逼近，能保留少量大系数表示全频率。", "x": "", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 核心结论", "t": "PRT 的传输与场景/材质绑定，场景或材质一变预计算就失效，且预计算数据量大。", "x": "", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 核心结论", "t": "实时 GI 通常只做一次反弹：直接光照照亮的表面再次作为光源照亮其他点。", "x": "", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 核心结论", "t": "RSM 用 shadow map 的每个像素记录位置、法线、通量，把每个像素当作小面片光源，对 shading point 做采样求和。", "x": "", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 核心结论", "t": "RSM 的间接光没有可见性检查，且假设反射面是漫反射、用深度近似距离，质量与采样率需要权衡。", "x": "", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 核心结论", "t": "RSM 性能随光源数线性增长，适合手电筒等少量局部光源，不适合大量光源。", "x": "", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 术语", "t": "Precomputed Radiance Transfer (PRT) / 预计算辐射传输", "x": "把光照与传输分离，传输在静态场景下预计算，运行时只做点积或矩阵乘法。", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 术语", "t": "Spherical Harmonics (SH) / 球谐函数", "x": "一组正交的低频球面基函数，常用于表示环境光照和漫反射传输。", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 术语", "t": "Wavelet / 小波", "x": "非正交基函数，通过保留少量大系数实现全频率的非线性逼近。", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 术语", "t": "Reflective Shadow Map (RSM) / 反射阴影贴图", "x": "把 shadow map 每个像素当作小面片光源，用于计算一次反弹间接光。", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 术语", "t": "Flux / 通量", "x": "面片接收或发出的辐射能量，RSM 中每个像素记录的量。", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 术语", "t": "One-bounce indirect illumination / 一次反弹间接光照", "x": "直接光照照亮的表面再次作为光源照亮其他点，实时 GI 通常只做一次。", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 术语", "t": "Triple product / 三重积", "x": "小波等非正交基函数下，光照与传输的积分需要三个函数相乘，运行时更贵。", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 术语", "t": "Non-linear approximation / 非线性逼近", "x": "小波变换后保留绝对值最大的若干系数，而非固定截断前 N 个。", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 练习", "t": "解释 PRT 漫反射情形下，为什么渲染可以化简为两个系数向量的点积，而不是 \\(O(n^2)\\) 的双重求和。", "x": "", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 练习", "t": "RSM 中每个 shadow map 像素需要记录哪些信息？为什么需要这些信息？", "x": "", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 练习", "t": "一个场景有 8 个手电筒光源，使用 RSM 做间接光。如果每个光源的 RSM 采样 64 次，shading point 数量为 100 万，估算采样总次数，并", "x": "", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 练习", "t": "RSM 的间接光没有可见性检查，会导致什么视觉问题？如何缓解？", "x": "", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L07 · 练习", "t": "对比 SH 和小波在 PRT 中的优缺点，并说明为什么工程上不是简单「小波全面优于 SH」。", "x": "", "u": "GAMES202/202_L07.html"}, {"c": "GAMES202 L10 · 第 10 讲：实时物理材质（一）——微表面模型与 Disney BRDF", "t": "1. 实时渲染里的“PBR 材质”到底是什么", "x": "这一讲开场先给“PBR”祛魅。物理基于渲染（Physically-Based Rendering, PBR） 的本意是整条渲染管线都物理基于：材质、光源、相机、光传输都遵守物理规律。但在实时渲染（RTR）社区，大家口中的“PBR 材质”往往只是指表面着色模型，而且和离线渲染相比明显落后。\n课件给了一", "u": "GAMES202/202_L10.html#s1"}, {"c": "GAMES202 L10 · 第 10 讲：实时物理材质（一）——微表面模型与 Disney BRDF", "t": "2. 微表面 BRDF：只有法线对准半程向量的微表面才反光", "x": "微表面模型的核心图像：宏观表面由无数微小镜面组成，每个微表面都是完美镜面。给定入射方向 \\(\\mathbf{i}\\) 与出射方向 \\(\\mathbf{o}\\)，只有法线恰好等于半程向量（half vector） \\(\\mathbf{h}=\\frac{\\mathbf{i}+\\mathbf{o}}{\\|", "u": "GAMES202/202_L10.html#s2"}, {"c": "GAMES202 L10 · 第 10 讲：实时物理材质（一）——微表面模型与 Disney BRDF", "t": "3. 菲涅尔项：为什么边缘总是更亮", "x": "菲涅尔项描述“反射率随入射角变化”。课件给的例子是：反射率随掠射角增大而增大——这就是为什么你斜着看水面、看桌面时边缘反光更强。严格计算要考虑光的偏振，实时里一般用 Schlick 近似：\n\\[\nF(\\mathbf{i},\\mathbf{h}) \\approx F_0 + (1-F_0)(1-\\ma", "u": "GAMES202/202_L10.html#s3"}, {"c": "GAMES202 L10 · 第 10 讲：实时物理材质（一）——微表面模型与 Disney BRDF", "t": "4. 法线分布 D：Beckmann 与 GGX 的差别", "x": "NDF 描述微表面法线的分布：越集中越像镜面（glossy），越分散越像漫反射（diffuse）。注意它和统计学里的正态分布没有关系，只是形状上像。\n课件给了两种常用模型：\n\nBeckmann NDF：类似高斯，但定义在斜率空间（slope space），形式大致是 \\(D(\\mathbf{h}) ", "u": "GAMES202/202_L10.html#s4"}, {"c": "GAMES202 L10 · 第 10 讲：实时物理材质（一）——微表面模型与 Disney BRDF", "t": "5. 阴影遮蔽项 G：没有它，掠射角会亮到离谱", "x": "G 项负责微表面之间的自遮挡：shadowing 是光源方向被挡，masking 是眼睛方向被挡。课件用一个反例说明它为什么不能省：如果去掉 G，当入射或出射接近掠射角时，分母 \\((\\mathbf{n}\\cdot\\mathbf{i})(\\mathbf{n}\\cdot\\mathbf{o})\\) 趋近", "u": "GAMES202/202_L10.html#s5"}, {"c": "GAMES202 L10 · 第 10 讲：实时物理材质（一）——微表面模型与 Disney BRDF", "t": "6. 多次反弹与 Kulla-Conty 能量补偿", "x": "单次散射的微表面模型只算了一次“光打到微表面再离开”，但真实表面在粗糙度高时，光会在微表面之间多次反弹。只算一次就会丢能量，粗糙度越高越明显（因为遮挡与反弹机会更多），表现为材质发暗、发灰。\n精确补能量有方法（Heitz 等），但实时太慢。Kulla-Conty 近似的思路是：被遮挡等价于发生下一次", "u": "GAMES202/202_L10.html#s6"}, {"c": "GAMES202 L10 · 第 10 讲：实时物理材质（一）——微表面模型与 Disney BRDF", "t": "7. 一个不该学的 hack：微表面 + 漫反射直接相加", "x": "课件专门用一页“骂”了一个在计算机视觉里被广泛使用的做法：把微表面 BRDF 和一个漫反射 lobe 直接相加。课件原话很重：完全错误、不能更糟、我从没教过你这么干。\n问题有两个：\n\n物理不正确：微表面模型本身已经包含了“没被反射的能量会进入表面”的含义，再额外加一个漫反射项等于凭空造能量；\n不满足", "u": "GAMES202/202_L10.html#s7"}, {"c": "GAMES202 L10 · 第 10 讲：实时物理材质（一）——微表面模型与 Disney BRDF", "t": "8. Disney 原则化 BRDF 与 LTC 一览", "x": "Disney 原则化 BRDF（principled BRDF） 的动机很实际：没有哪个物理模型能很好地表示所有真实材质（多数微表面模型还缺漫反射项），而且物理参数对艺术家不友好（比如“复折射率 n-ik”）。它的高层目标是可艺术指导，而不必物理正确——但在实时渲染里它照样被叫作 PBR。\n“原则化", "u": "GAMES202/202_L10.html#s8"}, {"c": "GAMES202 L10 · 核心结论", "t": "实时渲染里的“PBR 材质”通常只是微表面模型 + Disney BRDF，而且很多实现并不真正物理正确。", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 核心结论", "t": "微表面 BRDF 把表面看成大量朝向随机的微小镜面，只有法线恰好等于半程向量 h 的微表面才能把 wi 反射到 wo。", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 核心结论", "t": "完整形式为 f(i,o)=F(i,h)G(i,o,h)D(h)/(4(n·i)(n·o))，其中 F 是菲涅尔、D 是法线分布、G 是阴影遮蔽项。", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 核心结论", "t": "D 项决定高光的“聚拢/散开”：Beckmann 像高斯、GGX 有长尾，长尾让高光边缘更自然，所以 GGX 成为实时主流。", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 核心结论", "t": "G 项不可省：没有它，掠射角的分母 (n·i)(n·o) 趋近 0 会让 BRDF 任意亮；Smith 模型把 shadowing 与 masking 拆开处理", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 核心结论", "t": "单次散射微表面模型在粗糙度高时明显丢能量，Kulla-Conty 用预计算的 E(μ) 与 E_avg 表补一个多次反弹的附加 lobe。", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 核心结论", "t": "Disney 原则化 BRDF 用少量 0~1 的直觉参数覆盖大量材质，牺牲物理正确换可控性，是实时与离线都广泛使用的“PBR”外观模型。", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 核心结论", "t": "LTC 把 GGX 的 BRDF lobe 线性变换成余弦 lobe，从而让多边形光源下的积分有解析解，但不处理阴影。", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 术语", "t": "Microfacet BRDF / 微表面 BRDF", "x": "把表面看成大量微小镜面，只有法线等于半程向量的微表面才反光。", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 术语", "t": "Half vector / 半程向量", "x": "入射与出射方向的角平分方向 h=normalize(i+o)。", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 术语", "t": "Fresnel term / 菲涅尔项", "x": "反射率随入射角变化，掠射角更大；实时常用 Schlick 近似。", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 术语", "t": "Normal Distribution Function (NDF) / 法线分布函数", "x": "描述微表面法线朝向 h 的比例，决定高光聚拢或散开。", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 术语", "t": "GGX / Trowbridge-Reitz / GGX 分布", "x": "带长尾的 NDF，实时渲染主流选择。", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 术语", "t": "Shadowing-masking term / 阴影遮蔽项", "x": "微表面自遮挡比例，Smith 模型把两个方向解耦。", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 术语", "t": "Kulla-Conty approximation / Kulla-Conty 近似", "x": "用预计算表补回多次反弹丢失的能量。", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 术语", "t": "Disney principled BRDF / Disney 原则化 BRDF", "x": "少量 0~1 直觉参数覆盖大量材质，艺术家友好但不物理正确。", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 术语", "t": "Linearly Transformed Cosines (LTC) / 线性变换余弦", "x": "把 BRDF lobe 变换成余弦 lobe，使多边形光源积分可解析，不处理阴影。", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 练习", "t": "写出微表面 BRDF 的完整表达式，并说明 F、D、G 三项各自对应什么物理现象。", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 练习", "t": "为什么去掉 G 项后，物体在掠射角会出现异常高亮？", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 练习", "t": "Beckmann 与 GGX 两种 NDF 的主要外观差别是什么？为什么实时渲染更常用 GGX？", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 练习", "t": "Kulla-Conty 近似要预计算哪两张表？各自的维度由什么决定？", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L10 · 练习", "t": "实践题：在 UE 里做一个粗糙度从 0 到 1 的球，观察高光与边缘亮度。若发现高粗糙度端明显偏暗，可能是什么原因？", "x": "", "u": "GAMES202/202_L10.html"}, {"c": "GAMES202 L12 · 第 12 讲：实时渲染中的光线追踪——时域复用与降噪", "t": "1. 为什么实时渲染需要光线追踪降噪", "x": "实时渲染中，光线追踪（Ray Tracing）每帧能发射的光线数量极其有限。课件指出，即使是最先进的 GPU，在实时应用中每像素每帧也只能承担大约 1 个采样（1 SPP）。用 1 SPP 做路径追踪（path tracing），得到的图像噪声极大，几乎不可用。\n因此，实时渲染中的光线追踪必须配合降", "u": "GAMES202/202_L12.html#s1"}, {"c": "GAMES202 L12 · 第 12 讲：实时渲染中的光线追踪——时域复用与降噪", "t": "2. 时域复用的核心思想：把上一帧的结果搬过来", "x": "时域复用的基本假设是：上一帧已经降噪好的结果，可以复用到当前帧。因为相邻两帧的画面变化通常很小，上一帧的像素值对当前帧仍然有参考价值。\n具体做法是：对于当前帧的每个像素，找到它在上一帧中对应的位置（通过运动向量（motion vector）），然后把上一帧该位置已经降噪的结果与当前帧的带噪结果按权重", "u": "GAMES202/202_L12.html#s2"}, {"c": "GAMES202 L12 · 第 12 讲：实时渲染中的光线追踪——时域复用与降噪", "t": "3. 反投影：找到上一帧的对应像素", "x": "时域复用的第一步是反投影（back projection）：给定当前帧像素 \\(x_i\\)，找到它在上一帧中的位置。\n如果 G-Buffer 中存有世界坐标 \\(s\\)，可以直接用上一帧的视图投影矩阵把 \\(s\\) 投影到上一帧屏幕：\n\\[ x' = P' V' M' s \\]\n其中 \\(P', V", "u": "GAMES202/202_L12.html#s3"}, {"c": "GAMES202 L12 · 第 12 讲：实时渲染中的光线追踪——时域复用与降噪", "t": "4. 时域失效的典型场景", "x": "时域复用并非总是有效。课件列举了几类典型失效场景：\n\n切换场景：新场景没有上一帧信息，需要一段“预热期（burn-in period）”，期间画面噪声较大。\n屏幕空间问题：例如在走廊中向后走，原本在屏幕外的物体进入视野，上一帧没有对应信息。\n遮挡/新出现背景（disocclusion）：物体移开后露", "u": "GAMES202/202_L12.html#s4"}, {"c": "GAMES202 L12 · 第 12 讲：实时渲染中的光线追踪——时域复用与降噪", "t": "5. 缓解时域失效：钳制、检测与调整 α", "x": "面对时域失效，工业界常用的缓解手段有：\n\n钳制（clamping）：把上一帧的颜色向当前帧的颜色范围钳制，避免历史值偏离太远。\n检测（detection）：利用物体 ID、深度、法线等信息检测时域失效，然后调整 α（二值或连续）。\n加强空域滤波：在失效区域增大空域滤波强度，弥补时域信息的不足。\n\n但", "u": "GAMES202/202_L12.html#s5"}, {"c": "GAMES202 L12 · 第 12 讲：实时渲染中的光线追踪——时域复用与降噪", "t": "6. 从时域到空域：下一讲的铺垫", "x": "时域复用解决了大部分降噪问题，但当前帧本身仍然需要空域滤波（spatial filtering）来进一步降噪。课件指出，下一讲将介绍空域降噪技术，包括：\n\n双边滤波（bilateral filter）：在空间邻域内加权平均，权重同时考虑空间距离和颜色差异。\n联合双边滤波（joint bilatera", "u": "GAMES202/202_L12.html#s6"}, {"c": "GAMES202 L12 · 核心结论", "t": "实时渲染中光线追踪每像素采样数（SPP）极低，结果噪声极大，必须降噪。", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 核心结论", "t": "工业界降噪的核心是时域复用：用运动向量找到当前像素在上一帧的位置，把上一帧已降噪的结果按 α 混合进来。", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 核心结论", "t": "时域复用的本质是提高有效采样率（SPP），相当于把多帧的样本累积起来。", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 核心结论", "t": "反投影需要世界坐标或深度+运动向量，把当前帧像素映射回上一帧屏幕位置。", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 核心结论", "t": "时域复用会失效：切换场景、屏幕空间外信息、遮挡/新出现背景、阴影/反射的运动与物体不一致。", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 核心结论", "t": "失效时盲目复用会导致滞后（lagging），常用钳制（clamping）、检测（detection）和调整 α 来缓解，但会重新引入噪声。", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 核心结论", "t": "时域累积思想来自 TAA（时域抗锯齿），二者非常相似。", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 核心结论", "t": "空域降噪（如联合双边滤波、SVGF）将在下一讲展开，与时域结合使用。", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 术语", "t": "RTRT / 实时渲染中的光线追踪", "x": "Real-Time Ray Tracing，以极低采样率渲染并降噪", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 术语", "t": "SPP / 每像素采样数", "x": "Samples Per Pixel，实时中通常只有 1", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 术语", "t": "Denoising / 降噪", "x": "去除低采样率渲染产生的噪声", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 术语", "t": "Motion Vector / 运动向量", "x": "描述像素从上一帧到当前帧的屏幕空间位移", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 术语", "t": "Back Projection / 反投影", "x": "把当前帧像素映射回上一帧屏幕位置", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 术语", "t": "Temporal Accumulation / 时域累积", "x": "混合多帧结果以提高有效采样率", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 术语", "t": "G-Buffer / 几何缓冲区", "x": "渲染时免费获得的深度、法线、世界坐标等辅助信息", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 术语", "t": "Disocclusion / 遮挡解除", "x": "物体移开后露出的背景区域，缺乏历史信息", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 术语", "t": "TAA / 时域抗锯齿", "x": "Temporal Anti-Aliasing，时域累积思想的来源", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 术语", "t": "SVGF / 时空方差引导滤波", "x": "Spatiotemporal Variance-Guided Filtering，下一讲内容", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 练习", "t": "为什么实时渲染中的光线追踪必须依赖降噪？", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 练习", "t": "写出时域累积的混合公式，并解释 α 的作用。", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 练习", "t": "列举三种时域复用的失效场景，并说明如何缓解。", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 练习", "t": "反投影时如果只有深度值而没有世界坐标，如何找到上一帧的对应像素？", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L12 · 练习", "t": "在 UE 或 Unity 中，如何访问 G-Buffer 信息用于自定义降噪？", "x": "", "u": "GAMES202/202_L12.html"}, {"c": "GAMES202 L04 · 第 4 讲：实时阴影（二）——从 PCSS 到方差软阴影与矩阴影", "t": "1. PCF 到底在滤什么：先比较再平均，而不是先平均再比较", "x": "上一讲我们用 PCF 把硬阴影“软化”，这一讲先把它的数学本质讲透。PCF 的可见性公式可以写成：\n\\[\nV(x)=\\sum_{q\\in N(p)} w(p,q)\\,\\chi^{+}\\big[D_{SM}(q)-D_{scene}(x)\\big]\n\\]\n其中 \\(w(p,q)\\) 是滤波核权重，\\(", "u": "GAMES202/202_L04.html#s1"}, {"c": "GAMES202 L04 · 第 4 讲：实时阴影（二）——从 PCSS 到方差软阴影与矩阴影", "t": "2. PCSS 三步与性能瓶颈：慢在“看遍邻域”", "x": "PCSS（Percentage Closer Soft Shadows）把 PCF 的固定核换成随遮挡距离变化的核，完整算法分三步：\n\nBlocker 搜索：在着色点对应的 shadow map 位置周围取一个区域，找出所有“比着色点更近”的纹素（即遮挡物），求它们的平均深度 \\(z_{avg}\\)", "u": "GAMES202/202_L04.html#s2"}, {"c": "GAMES202 L04 · 第 4 讲：实时阴影（二）——从 PCSS 到方差软阴影与矩阴影", "t": "3. VSSM 的核心：用均值和方差代替直方图", "x": "VSSM 的出发点是一个生活化类比：“考试里有多少人比你考得好？” 精确答案是数直方图；近似答案是假设成绩服从正态分布，只要知道均值和方差，就能算出比例。\n对应到阴影：区域内每个纹素的深度就是一个随机变量 \\(X\\)，我们想知道 \\(P(X \n\n均值 \\(\\mu = E(X)\\)\n方差 \\(\\sig", "u": "GAMES202/202_L04.html#s3"}, {"c": "GAMES202 L04 · 第 4 讲：实时阴影（二）——从 PCSS 到方差软阴影与矩阴影", "t": "4. 把 blocker 搜索也变成 O(1)：VSSM 的第二步近似", "x": "第 3 节解决了 PCF 滤波（第 3 步），但 PCSS 的第 1 步 blocker 搜索仍然要循环。VSSM 用一组巧妙的近似把它也降到 O(1)。\n设区域内总纹素数 \\(N\\)，其中遮挡物（\\(z  t\\)）有 \\(N_2\\) 个，平均深度 \\(z_{unocc}\\)。我们想要的是 \\(z_", "u": "GAMES202/202_L04.html#s4"}, {"c": "GAMES202 L04 · 第 4 讲：实时阴影（二）——从 PCSS 到方差软阴影与矩阴影", "t": "5. 任意矩形范围查询：MIPMAP 与 SAT", "x": "VSSM 反复需要“在任意矩形区域内快速求均值和平方均值”。这本质上是二维范围查询（range query）。课件给了两种经典数据结构。\nMIPMAP：预先生成多级缩小的纹理，每级像素是上一级 2×2 的平均。查询时根据区域大小选合适层级，再做三线性插值。优点是构建快、存储只多约 1/3；缺点是即使", "u": "GAMES202/202_L04.html#s5"}, {"c": "GAMES202 L04 · 第 4 讲：实时阴影（二）——从 PCSS 到方差软阴影与矩阴影", "t": "6. VSSM 的软肋：漏光与非平面伪影，以及矩阴影（MSM）", "x": "VSSM 很快，但它的近似在两种情况下会露馅：\n\n漏光（light leaking）：当 \\(t \\le \\mu\\) 时切比雪夫不等式不成立，公式仍可能返回一个小于 1 的“可见性”，导致本应全暗的区域透出光。表现为阴影内部出现不该有的亮斑。\n非平面伪影（non-planarity artifact", "u": "GAMES202/202_L04.html#s6"}, {"c": "GAMES202 L04 · 核心结论", "t": "PCF 的数学本质是：对每个着色点，在 shadow map 的邻域内做加权平均，但权重作用在“比较结果”上，而不是先滤波深度再比较。", "x": "", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 核心结论", "t": "PCSS 三步：blocker 搜索 → 半影估计 → PCF；前两步都要遍历邻域纹素，半影越大越慢。", "x": "", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 核心结论", "t": "VSSM 的核心：用深度的一阶矩（均值）和二阶矩（平方均值）近似深度分布，再用切比雪夫不等式 O(1) 估计 P(x>t)。", "x": "", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 核心结论", "t": "均值和平方均值都可以用 MIPMAP 或 SAT 在任意矩形范围内快速查询，从而把 PCF 滤波变成 O(1)。", "x": "", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 核心结论", "t": "blocker 平均深度也可用切比雪夫比例和“未遮挡深度≈t”的近似在 O(1) 内算出。", "x": "", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 核心结论", "t": "VSSM 的漏光来自切比雪夫不等式在 t ≤ 均值时失效，以及深度分布非高斯/非平面时近似不准。", "x": "", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 核心结论", "t": "MSM 用前 4 阶矩重建 CDF，能表示多台阶分布，减少漏光，但存储与重建开销更大。", "x": "", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 术语", "t": "PCF / 百分比渐近过滤", "x": "在 shadow map 邻域内逐纹素比较后加权平均，得到软阴影边缘。", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 术语", "t": "PCSS / 百分比渐近软阴影", "x": "blocker 搜索 + 半影估计 + PCF 三步，核大小随遮挡距离变化。", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 术语", "t": "VSSM / 方差软阴影映射", "x": "用深度均值和方差 + 切比雪夫不等式 O(1) 估计可见性。", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 术语", "t": "Chebyshev’s inequality / 切比雪夫不等式", "x": "用方差上界估计尾部概率，不要求高斯分布，但仅在 t > μ 时有效。", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 术语", "t": "SAT / 前缀和表", "x": "二维累加和，四角点加减即可 O(1) 求任意矩形和，精确但构建贵。", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 术语", "t": "MIPMAP / 多级渐远纹理", "x": "预生成多级缩小纹理，三线性插值近似范围查询，快但非精确。", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 术语", "t": "Light leaking / 漏光", "x": "本应全暗的阴影区域透出光，VSSM 在 t ≤ μ 时的典型伪影。", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 术语", "t": "Non-planarity artifact / 非平面伪影", "x": "假设接收面为平面（z_unocc ≈ t）在弯曲表面失效导致的阴影失真。", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 术语", "t": "MSM / 矩阴影映射", "x": "用前 4 阶矩重建深度 CDF，减少漏光，代价是存储与重建开销。", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 练习", "t": "PCF 的可见性公式中，阶跃函数 χ⁺ 为什么必须放在求和号内部？如果放到外面会得到什么错误结果？", "x": "", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 练习", "t": "某区域深度均值 μ=0.5，方差 σ²=0.01，着色点深度 t=0.7。用单边切比雪夫估计 P(X>t) 和 P(X<t)。", "x": "", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 练习", "t": "VSSM 如何在不循环的情况下估计 blocker 的平均深度 z_occ？写出用到的三个近似。", "x": "", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 练习", "t": "为什么 VSSM 会出现漏光？MSM 从哪个角度缓解了这个问题？", "x": "", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L04 · 练习", "t": "在 UE 或 Unity 中实现一个 VSSM 原型：列出你需要创建的 RenderTexture、每帧的 pass 顺序，以及至少两个必须做的数值保护。", "x": "", "u": "GAMES202/202_L04.html"}, {"c": "GAMES202 L02 · 第 2 讲：CG 基础回顾——从 GPU 管线到渲染方程", "t": "1. 图形管线：一条从顶点到像素的流水线", "x": "这一讲是复习课，但复习的正是后面所有高级技术的地基。先看硬件图形管线（graphics pipeline）。课件把它拆成六个阶段，每个阶段吃进一种“流”，吐出下一种“流”：\n\nApplication（应用阶段）：CPU 端准备顶点数据（3D 空间中的顶点）、模型变换、相机参数等。\nVertex Pr", "u": "GAMES202/202_L02.html#s1"}, {"c": "GAMES202 L02 · 第 2 讲：CG 基础回顾——从 GPU 管线到渲染方程", "t": "2. OpenGL：用“画油画”理解一次渲染 pass", "x": "OpenGL 是什么？课件给的定义很朴素：一组从 CPU 调用 GPU 管线的 API。所以它和语言无关（C/C++/Python 都能调），跨平台，替代品有 DirectX、Vulkan、Metal 等。缺点也直白：版本碎片化、C 风格不好用、过去很难调试。\n课件用“画油画”做类比，这个类比值得完", "u": "GAMES202/202_L02.html#s2"}, {"c": "GAMES202 L02 · 第 2 讲：CG 基础回顾——从 GPU 管线到渲染方程", "t": "3. GLSL 与 Shader 的创建流程", "x": "顶点/片元着色器是用一种“像 C 但有诸多限制”的小程序描述的。课件简单回顾了着色语言的历史：从 Cook 的 Shade Trees、RenderMan 离线渲染，到早期 GPU 上的汇编，再到 Stanford 实时着色语言、NVIDIA 的 Cg、DirectX 的 HLSL、OpenGL 的", "u": "GAMES202/202_L02.html#s3"}, {"c": "GAMES202 L02 · 第 2 讲：CG 基础回顾——从 GPU 管线到渲染方程", "t": "4. 调试 Shader：把中间值画成颜色", "x": "Shader 调试是实时渲染里最让人头疼的环节之一，课件专门用两页讲。历史方案：早年用 NVIDIA Nsight 配合 Visual Studio，调试 GLSL 需要多块 GPU，调试 HLSL 还得跑软件模拟模式，非常痛苦。现在好多了：Nsight Graphics（跨平台，但仅限 NVIDI", "u": "GAMES202/202_L02.html#s4"}, {"c": "GAMES202 L02 · 第 2 讲：CG 基础回顾——从 GPU 管线到渲染方程", "t": "5. 渲染方程：实时渲染的总纲", "x": "课件称渲染方程（the rendering equation）为“渲染中最重要的方程”，它描述光能传输。标准形式是：\n\\[ L_o(p, \\omega_o) = L_e(p, \\omega_o) + \\int_{\\Omega^+} f_r(p, \\omega_i, \\omega_o)\\, L_i(p", "u": "GAMES202/202_L02.html#s5"}, {"c": "GAMES202 L02 · 第 2 讲：CG 基础回顾——从 GPU 管线到渲染方程", "t": "6. 环境光照与全局光照的弹射直觉", "x": "渲染方程里的 \\(L_i\\) 是“从所有方向来的入射光”。如果光源是点光/方向光，\\(L_i\\) 只在少数方向非零，积分退化成求和，这就是直接光照。但真实世界的光来自四面八方，课件把这种“来自所有方向的入射光照”称为 环境光照（environment lighting），通常用 cube map 或", "u": "GAMES202/202_L02.html#s6"}, {"c": "GAMES202 L02 · 核心结论", "t": "GPU 图形管线固定顺序：Application → Vertex Processing → Triangle Processing → Rasterizati", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 核心结论", "t": "光栅化（rasterization）的本质是采样三角形覆盖，每个被覆盖的采样点生成一个 fragment。", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 核心结论", "t": "OpenGL 只是 CPU 调用 GPU 管线的 API 集合，语言无关、跨平台；一次 pass 类似画一幅油画：摆模型、架画架、贴画布、作画。", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 核心结论", "t": "真正由用户掌控的是 vertex shader 与 fragment shader，其余步骤大多被封装。", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 核心结论", "t": "渲染方程是渲染领域最重要的方程，描述光能传输：出射辐射 = 发射 + 入射辐射在半球上的积分（BRDF × 余弦项）。", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 核心结论", "t": "实时渲染中常把可见性 V(p,ωi) 显式写进积分，并把 BRDF 与余弦项合并理解。", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 核心结论", "t": "环境光照通常用 cube map 或 sphere map 表示来自所有方向的入射光；直接光照与一次/两次弹射全局光照是理解 GI 的起点。", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 核心结论", "t": "Shader 调试的土办法但极有效：把中间值当颜色输出，肉眼检查。", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 术语", "t": "Graphics Pipeline / 图形管线", "x": "从顶点到像素的固定阶段流水线，GPU 并行执行。", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 术语", "t": "Rasterization / 光栅化", "x": "判断三角形覆盖哪些采样点，被覆盖则生成 fragment。", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 术语", "t": "Fragment / 片元", "x": "光栅化产生的“候选像素”，经深度测试与混合后才可能成为像素。", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 术语", "t": "VBO / 顶点缓冲对象", "x": "把顶点、法线、纹理坐标打包传给 GPU 的缓冲。", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 术语", "t": "GLSL / OpenGL 着色语言", "x": "类 C 的着色器语言，用于编写 vertex/fragment shader。", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 术语", "t": "Rendering Equation / 渲染方程", "x": "描述光能传输的积分方程，实时渲染技术的总纲。", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 术语", "t": "BRDF / 双向反射分布函数", "x": "描述材质如何把入射光反射到出射方向的函数。", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 术语", "t": "Environment Lighting / 环境光照", "x": "来自所有方向的入射光照，常用 cube map / sphere map 表示。", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 术语", "t": "Global Illumination / 全局光照", "x": "考虑物体间多次光反射的照明，分一次弹射、两次弹射等。", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 练习", "t": "按顺序写出 GPU 图形管线的六个阶段，并说明光栅化阶段的输入和输出分别是什么。", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 练习", "t": "用“画油画”的类比解释 OpenGL 一次渲染 pass 的步骤，并指出哪些步骤由用户 shader 控制。", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 练习", "t": "写出渲染方程的标准形式，并解释每一项的物理含义；再写出实时渲染中显式包含可见性 V 的变体。", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 练习", "t": "在 fragment shader 中如何调试一个可疑的法线？写出关键代码，并说明正常与异常时分别看到什么。", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L02 · 练习", "t": "解释直接光照、一次弹射全局光照、两次弹射全局光照的区别，并各举一个画面上的直观现象。", "x": "", "u": "GAMES202/202_L02.html"}, {"c": "GAMES202 L11 · 第 11 讲：实时物理材质（续）与 NPR 风格化渲染", "t": "1. 为什么需要 LTC：多边形光源下的微表面着色难题", "x": "上一讲我们学了微表面 BRDF（NDF、阴影遮蔽项、Kulla-Conty 多次反弹补偿、Disney 原则化 BRDF），也提到多边形光源下的着色可以用线性变换余弦（Linearly Transformed Cosines, LTC）来做。这一讲先把 LTC 讲完。\n先想清楚问题：实时渲染里经常用", "u": "GAMES202/202_L11.html#s1"}, {"c": "GAMES202 L11 · 第 11 讲：实时物理材质（续）与 NPR 风格化渲染", "t": "2. LTC 的核心：变量替换与雅可比", "x": "LTC 的关键思路可以拆成三步：\n\n任意出射的 2D BRDF 波瓣都能被线性变换成余弦波瓣。也就是说，存在一个 3×3 矩阵 \\(M\\)，把 BRDF 波瓣 \\(f(\\omega_i, \\omega_o)\\) 变成余弦波瓣 \\(\\cos(\\omega_i')\\)。\n光源形状也跟着变换。原来的多边形", "u": "GAMES202/202_L11.html#s2"}, {"c": "GAMES202 L11 · 第 11 讲：实时物理材质（续）与 NPR 风格化渲染", "t": "3. Disney Principled BRDF：艺术家友好的“原则化”模型", "x": "上一讲已经提过 Disney Principled BRDF，这一讲展开讲它为什么存在、设计原则是什么、优缺点如何。\n动机：没有哪一种物理材质模型能完美表示所有真实材质，比如大多数微表面模型缺少漫反射项；而且物理参数对艺术家不友好，比如“复折射率 \\(n-ik\\)”这种参数，艺术家根本不知道怎么调。", "u": "GAMES202/202_L11.html#s3"}, {"c": "GAMES202 L11 · 第 11 讲：实时物理材质（续）与 NPR 风格化渲染", "t": "4. NPR 是什么：从真实感出发的风格化", "x": "NPR（Non-Photorealistic Rendering，非真实感渲染）在实时渲染里有一个很实用的定义：快速且可靠的风格化（fast and reliable stylization）。注意“快速”和“可靠”两个词——离线可以慢慢做风格化，实时必须每帧出图且不能闪。\n先对比真实感渲染：目标是", "u": "GAMES202/202_L11.html#s4"}, {"c": "GAMES202 L11 · 第 11 讲：实时物理材质（续）与 NPR 风格化渲染", "t": "5. 轮廓线渲染：着色、几何、图像三条路", "x": "轮廓线（outline）是 NPR 最显眼的特征。但课件提醒：轮廓线不只是外轮廓。它列出了四类边：\n\n边界/边界边（boundary/border edge）：两个面共享的边，但只有一个面可见；\n折痕边（crease）：两个面夹角很大；\n材质边（material edge）：材质属性突变；\n轮廓边（", "u": "GAMES202/202_L11.html#s5"}, {"c": "GAMES202 L11 · 第 11 讲：实时物理材质（续）与 NPR 风格化渲染", "t": "6. 色块与笔触：把连续着色变成风格化图案", "x": "色块（color blocks） 是卡通风格的另一个核心。课件给了两种做法：\n\n硬着色（hard shading）：对着色结果做阈值化，比如 \\(N \\cdot L\\) 大于某个值就取亮色，否则取暗色；\n色调分离（posterization）：对最终图像颜色做阈值化，把连续颜色映射到有限档。\n\n色块", "u": "GAMES202/202_L11.html#s6"}, {"c": "GAMES202 L11 · 第 11 讲：实时物理材质（续）与 NPR 风格化渲染", "t": "7. 工程落地：NPR 是艺术驱动的，沟通比公式重要", "x": "课件最后给了一些“Notes”，这些是工程经验，比公式更值钱：\n\nNPR 是艺术驱动的。技术只是手段，最终效果由艺术需求决定。\n但你需要有能力把艺术家的需求“翻译”成渲染洞察。比如艺术家说“这里要有边”，你要能翻译成“用折痕边检测还是轮廓边检测”。\n沟通很重要。NPR 项目里，程序、TA、美术要反复", "u": "GAMES202/202_L11.html#s7"}, {"c": "GAMES202 L11 · 核心结论", "t": "LTC 把 GGX 等微表面 BRDF 波瓣通过一个 3×3 线性矩阵 M 变换成余弦波瓣，同时把多边形光源也做同样变换，积分就变成余弦对变换后多边形的解析积分", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 核心结论", "t": "变量替换后出现雅可比行列式，但 LTC 的巧妙之处在于变换后的积分恰好是余弦波瓣对变换后多边形的积分，可以解析求出，不需要数值采样。", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 核心结论", "t": "LTC 只处理着色，不处理阴影；它主要针对 GGX，但方法对其他微表面模型也适用。", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 核心结论", "t": "Disney Principled BRDF 的目标是“艺术家可调”，用少量 0~1 的直觉参数覆盖大量材质，不追求严格物理正确，但工业界仍称其为 PBR。", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 核心结论", "t": "NPR 在实时渲染中等于“快速可靠的风格化”，它从真实感渲染出发，通过抽象和强化重要部分来产生艺术外观。", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 核心结论", "t": "轮廓线渲染有三类：基于着色法线变暗、基于几何的背面膨胀、基于图像的 Sobel 边缘检测。", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 核心结论", "t": "色块可以通过硬着色（对着色结果阈值化）、色调分离（对最终颜色阈值化）或量化实现，且不一定是二值。", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 核心结论", "t": "笔触风格化用预生成的笔触纹理（TAMs）替换逐点着色，不同密度对应不同 MIPMAP 层级，以兼顾密度与连续性。", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 术语", "t": "Linearly Transformed Cosines (LTC) / 线性变换余弦", "x": "用线性矩阵把 BRDF 波瓣变换成余弦波瓣，使多边形光源积分解析可求。", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 术语", "t": "Jacobian / 雅可比行列式", "x": "变量替换时面积缩放的比例因子。", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 术语", "t": "Disney Principled BRDF / Disney 原则化 BRDF", "x": "用少量 0~1 直觉参数覆盖大量材质的艺术家友好模型。", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 术语", "t": "Non-Photorealistic Rendering (NPR) / 非真实感渲染", "x": "实时下指快速可靠的风格化渲染。", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 术语", "t": "Silhouette edge / 轮廓边", "x": "物体外轮廓对应的边。", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 术语", "t": "Crease edge / 折痕边", "x": "两个面夹角很大形成的边。", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 术语", "t": "Backface fattening / 背面膨胀", "x": "把背面沿法线膨胀后渲染，形成外描边的几何方法。", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 术语", "t": "Sobel detector / Sobel 边缘检测算子", "x": "图像空间常用的边缘检测卷积核。", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 术语", "t": "Posterization / 色调分离", "x": "把连续颜色量化到有限档，形成色块。", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 术语", "t": "Tonal Art Maps (TAMs) / 色调艺术图", "x": "不同密度的预生成笔触纹理，每个密度对应一个 MIPMAP 层级。", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 练习", "t": "LTC 为什么能把微表面 BRDF 对多边形光源的积分变成解析形式？请用“变量替换”和“余弦波瓣”两个关键词解释。", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 练习", "t": "Disney Principled BRDF 的设计原则有哪些？它为什么不是物理正确的，却仍被称为 PBR？", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 练习", "t": "轮廓线渲染有哪三类方法？各举一个优缺点。", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 练习", "t": "TAMs 如何同时解决笔触的“密度”和“连续性”问题？", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L11 · 练习", "t": "在 UE 里实现一个简单的背面膨胀描边，需要哪些步骤？", "x": "", "u": "GAMES202/202_L11.html"}, {"c": "GAMES202 L13 · 第 13 讲：实时渲染中的滤波实现——双边滤波、大核滤波与异常值处理", "t": "1. 滤波要解决什么问题：从噪声图像到干净图像", "x": "这一讲的主题是如何真正把滤波器写出来。在实时渲染里，我们做路径追踪、软阴影、屏幕空间反射时，每个像素只用了很少的样本，结果就是一张满是噪点的图。滤波（filtering）就是对这些噪声图像做低通滤波，把高频噪声压下去。\n课件把问题限定在空间域：先不管时域复用，只考虑当前这一帧图像。形式化地：\n\n输入", "u": "GAMES202/202_L13.html#s1"}, {"c": "GAMES202 L13 · 第 13 讲：实时渲染中的滤波实现——双边滤波、大核滤波与异常值处理", "t": "2. 双边滤波：在模糊噪声的同时保住边界", "x": "高斯滤波的问题很直观：它只看位置距离，所以图像里颜色突变的地方（物体的边界）也会被一起抹平。但边界恰恰是我们想保留的高频信息。\n双边滤波（bilateral filtering）的观察是：边界 = 颜色剧烈变化的地方。于是它在高斯权重之外再乘一个颜色差权重：如果邻域像素 \\(j\\) 的颜色和中心像素", "u": "GAMES202/202_L13.html#s2"}, {"c": "GAMES202 L13 · 第 13 讲：实时渲染中的滤波实现——双边滤波、大核滤波与异常值处理", "t": "3. 联合双边滤波：用 G-buffer 当引导，专治路径追踪噪声", "x": "双边滤波用“颜色差”当第二个度量。课件接着问：能不能用更多特征来引导滤波？答案是肯定的，这就是交叉/联合双边滤波（cross / joint bilateral filtering）。\n它在渲染里的独特优势来自 G-buffer：法线、深度、世界位置、物体 ID 等等，这些几何信息在渲染管线里是免费", "u": "GAMES202/202_L13.html#s3"}, {"c": "GAMES202 L13 · 第 13 讲：实时渲染中的滤波实现——双边滤波、大核滤波与异常值处理", "t": "4. 大核滤波之一：可分离核拆成两趟", "x": "朴素实现每像素要遍历 \\(N \\times N\\) 邻域，大核（比如 64×64）代价高得不可接受。课件给出两种解决方案，第一种是分离通道（separate passes）。\n核心观察：2D 高斯核是可分离的：\n\\[\nG_{2D}(x,y) = G_{1D}(x) \\cdot G_{1D}(y)\n\\", "u": "GAMES202/202_L13.html#s4"}, {"c": "GAMES202 L13 · 第 13 讲：实时渲染中的滤波实现——双边滤波、大核滤波与异常值处理", "t": "5. 大核滤波之二：渐进式增大尺寸（a-trous 小波）", "x": "第二种方案是渐进式增大尺寸（progressively growing sizes），具体实现叫 à-trous 小波。思路是：不直接做一次大核，而是做多趟小核（每趟都是 5×5），但每趟的采样间隔逐趟增大。\n比如第 0 趟在原始分辨率上采样，第 1 趟每隔 1 个像素采一个（等效核变大），第 2 ", "u": "GAMES202/202_L13.html#s5"}, {"c": "GAMES202 L13 · 第 13 讲：实时渲染中的滤波实现——双边滤波、大核滤波与异常值处理", "t": "6. 异常值剔除与时域钳制：滤波不是万能的", "x": "课件很实在地指出：滤波不是万能的。有时候滤波后的结果仍然有噪声，甚至出现块状伪影，主要原因是图像里存在极亮的像素（异常值，outliers）。一个极亮的像素会在邻域平均里“污染”一大片，形成块状亮斑。\n思路很自然：能不能在滤波之前把这些异常值去掉？关键是怎么定义异常值。课件的做法是：\n\n异常值检测：", "u": "GAMES202/202_L13.html#s6"}, {"c": "GAMES202 L13 · 核心结论", "t": "滤波的本质是邻域加权平均，必须除以权重和做归一化；权重和为零时要特判。", "x": "", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 核心结论", "t": "高斯滤波会模糊边界，双边滤波在距离权重之外再乘一个颜色差权重，从而保边。", "x": "", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 核心结论", "t": "联合双边滤波用 G-buffer（法线、深度、物体 ID 等）作为额外引导特征，这些特征无噪声，降噪效果远好于只用颜色。", "x": "", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 核心结论", "t": "大核滤波有两种加速：可分离核拆成水平+垂直两趟（N²→2N），以及 a-trous 小波用多趟 5x5 滤波配合逐趟增大的采样间隔。", "x": "", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 核心结论", "t": "a-trous 能跳采样而不走样的原因是：第 i 趟滤波已经去掉了高频，剩余信号带宽变窄，采样间隔增大也不会混叠。", "x": "", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 核心结论", "t": "异常值（极亮像素）会让滤波结果出现块状噪声，应在滤波前用邻域 μ±kσ 检测并钳制，而不是直接置零。", "x": "", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 核心结论", "t": "时域复用会因历史颜色与当前颜色差异过大而产生拖影，用当前帧邻域的 μ±kσ 对历史颜色做钳制，是在噪声与拖影之间的权衡。", "x": "", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 术语", "t": "filtering / 滤波", "x": "对图像做邻域加权平均，压低高频噪声。", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 术语", "t": "filter kernel / 滤波核", "x": "决定邻域内各像素权重的函数，可逐像素不同。", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 术语", "t": "bilateral filtering / 双边滤波", "x": "距离权重 × 颜色差权重，保边去噪。", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 术语", "t": "joint bilateral filtering / 联合双边滤波", "x": "用 G-buffer 等额外特征做引导的双边滤波。", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 术语", "t": "G-buffer / 几何缓冲", "x": "法线、深度、位置、物体 ID 等无噪声几何信息。", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 术语", "t": "separable kernel / 可分离核", "x": "能写成 f(x)·g(y) 的核，可拆成两趟 1D 滤波。", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 术语", "t": "à-trous wavelet / à-trous 小波", "x": "多趟小核 + 递增采样间隔，实现大等效核。", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 术语", "t": "outlier / 异常值", "x": "极亮像素，会在滤波中造成块状伪影。", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 术语", "t": "temporal clamping / 时域钳制", "x": "把历史颜色钳到当前邻域 μ±kσ 内，抑制拖影。", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 练习", "t": "写出双边滤波的权重公式，并说明两个高斯分别控制什么。如果颜色差权重用未归一化的 HDR 颜色计算，会发生什么？", "x": "", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 练习", "t": "一个 64×64 的高斯核，朴素实现每像素需要多少次采样？用可分离两趟实现需要多少次？用 4 趟 5×5 的 à-trous 实现需要多少次？", "x": "", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 练习", "t": "为什么 à-trous 滤波可以逐趟增大采样间隔而不产生混叠？请用频域语言解释。", "x": "", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 练习", "t": "某像素 7×7 邻域的均值 μ=0.5，标准差 σ=0.1，k=3。像素值为 1.2，应如何处理？如果像素值为 0.1 呢？", "x": "", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L13 · 练习", "t": "在时域复用中，把历史颜色钳制到当前帧邻域的 μ±kσ 区间，k 取大和取小分别有什么后果？这体现了什么权衡？", "x": "", "u": "GAMES202/202_L13.html"}, {"c": "GAMES202 L14 · 第 14 讲：最后一课——工业级实时渲染方案一览", "t": "1. 从时空降噪到 SVGF：用方差告诉滤波器该信谁", "x": "上一讲已经搭好了实时 ray tracing（RTRT）降噪的基本框架：时域累积 + 运动向量 + 空域滤波。这一讲先补两个更具体的滤波方案，第一个是 SVGF（Spatiotemporal Variance-Guided Filtering）。\nSVGF 的整体流程和基础时空降噪几乎一样，区别在于", "u": "GAMES202/202_L14.html#s1"}, {"c": "GAMES202 L14 · 第 14 讲：最后一课——工业级实时渲染方案一览", "t": "2. RAE：让网络自己学时域累积", "x": "第二个方案是 RAE（Recurrent AutoEncoder），论文标题就是“用循环降噪自编码器交互式重建蒙特卡洛图像序列”。它把降噪看成一个后处理网络：输入是噪声图像加上 G-buffer，输出是干净图像。\n和 SVGF 最大的不同是：时域累积不是手写规则，而是网络自己学出来的。网络结构有两个", "u": "GAMES202/202_L14.html#s2"}, {"c": "GAMES202 L14 · 第 14 讲：最后一课——工业级实时渲染方案一览", "t": "3. 抗锯齿与超分：TAA、MSAA/SSAA、SMAA 与 DLSS", "x": "抗锯齿的根源是每像素样本数不够。光栅化时一个像素只采一个点，几何边缘就会走样。终极解法就是多采样，但直接超采样太贵，于是有了几条路线：\n\nSSAA（超采样）：用更大分辨率渲染再降采样，最直接也最贵。\nMSAA（多重采样）：每个图元只着色一次，但每个像素存多个覆盖样本，靠复用样本降低着色成本。\nTAA", "u": "GAMES202/202_L14.html#s3"}, {"c": "GAMES202 L14 · 第 14 讲：最后一课——工业级实时渲染方案一览", "t": "4. 着色架构：延迟着色、分块着色、聚类着色", "x": "延迟着色（deferred shading）最初是为了省着色时间。先看光栅化流程：三角形 → 片元 → 深度测试 → 着色 → 像素。问题是每个片元都要着色，复杂度是 \\(O(\\#fragment \\times \\#light)\\)。但大多数片元最终被遮挡、根本看不见。\n于是延迟着色把场景光栅化两遍", "u": "GAMES202/202_L14.html#s4"}, {"c": "GAMES202 L14 · 第 14 讲：最后一课——工业级实时渲染方案一览", "t": "5. LoD 与级联：工业界的“cascaded”", "x": "LoD（Level of Detail）的思想和纹理 MIPMAP 一样：根据距离选合适的细节层级，省计算。工业界常把多层级方案叫 cascaded（级联）。\n两个典型例子：\n\n级联阴影贴图（cascaded shadow maps）：把相机视锥按距离分成几段，每段用不同分辨率的阴影图，近处精细、远", "u": "GAMES202/202_L14.html#s5"}, {"c": "GAMES202 L14 · 第 14 讲：最后一课——工业级实时渲染方案一览", "t": "6. 全局光照的混合方案与 Lumen", "x": "这一节是全课的收束：没有单一的 GI 方案能适合所有情况，除了完整的 RTRT，但当前世代完全用 RTRT 还是太贵。所以工业界普遍用混合方案（hybrid solutions）。\n课件列出的可能组合包括：\n\nSSR（屏幕空间反射）做粗略 GI 近似——但它会失败：屏幕外的东西、被遮挡的东西都拿不到", "u": "GAMES202/202_L14.html#s6"}, {"c": "GAMES202 L14 · 核心结论", "t": "SVGF 在联合双边滤波中引入方差估计，用方差动态调整亮度权重的敏感度，并对深度权重使用切平面距离而非绝对深度差。", "x": "", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 核心结论", "t": "RAE 用循环自编码器网络做降噪，网络自动完成时域累积，但可解释性差、早期版本偏糊。", "x": "", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 核心结论", "t": "TAA 的本质是跨帧复用样本；DLSS 2 在此基础上用神经网络做超分，时域失败时不能简单 clamp。", "x": "", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 核心结论", "t": "延迟着色把着色复杂度从所有片元降到可见片元，但牺牲了 MSAA 等能力；分块与聚类着色进一步按 tile / 深度段剔除无关光源。", "x": "", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 核心结论", "t": "LoD（工业界常叫 cascaded）的核心挑战是层级切换的过渡与裂缝，几何 LoD 的 popping 可以交给 TAA 掩盖。", "x": "", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 核心结论", "t": "工业 GI 没有银弹，主流是 SSR + SDF 软光追 + RSM + Probe + 硬件光追的混合方案，Lumen 就是这些方案的混合体。", "x": "", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 术语", "t": "SVGF / 时空方差引导滤波", "x": "用方差引导联合双边滤波的 RTRT 降噪方案", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 术语", "t": "RAE / 循环自编码器", "x": "用循环网络自动做时域累积的降噪方案", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 术语", "t": "Joint Bilateral Filtering / 联合双边滤波", "x": "用深度/法线/亮度等引导权重做保边滤波", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 术语", "t": "TAA / 时域抗锯齿", "x": "跨帧复用样本的抗锯齿方法", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 术语", "t": "DLSS / 深度学习超采样", "x": "用神经网络做时域超分，DLSS 2 不依赖低分辨率历史", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 术语", "t": "Deferred Shading / 延迟着色", "x": "先光栅化深度、再只对可见片元着色", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 术语", "t": "Tiled/Clustered Shading / 分块/聚类着色", "x": "按屏幕 tile 和深度段剔除无关光源", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 术语", "t": "Cascaded / 级联", "x": "工业界对多层级 LoD 方案的叫法", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 术语", "t": "DDGI / 动态漫反射全局光照", "x": "用 3D 网格 Probe 存辐照度的 GI 方案", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 术语", "t": "Lumen / UE5 的混合 GI 系统", "x": "SSR+SDF+RSM+DDGI+硬件光追的组合", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 练习", "t": "SVGF 的深度权重为什么用切平面投影后的深度差，而不是直接相减？请举一个反例。", "x": "", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 练习", "t": "延迟着色把复杂度从 \\(O(\\#fragment \\times \\#light)\\) 降到 \\(O(\\#vis.\\ frag. \\times \\#light)\\", "x": "", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 练习", "t": "TAA 和 RTRT 的时域累积有什么共同点？DLSS 2 为什么不能像 TAA 那样在时域失败时简单 clamp？", "x": "", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 练习", "t": "分块着色和聚类着色分别解决了什么问题？复杂度各变成什么？", "x": "", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L14 · 练习", "t": "如果你要在 UE5 里做一个室内小场景，Lumen 的哪条路径可能最划算？如果换成大世界室外呢？", "x": "", "u": "GAMES202/202_L14.html"}, {"c": "GAMES202 L09 · 第 9 讲：屏幕空间全局光照（续）——SSDO 与 SSR", "t": "从 SSAO 到 SSDO：为什么要考虑方向", "x": "上一讲我们讲了屏幕空间环境光遮蔽（SSAO）。SSAO 的做法是：在着色点周围采样深度，统计有多少方向被遮挡，从而估计一个环境光遮蔽因子。它的隐含假设是——入射的间接光在各个方向上都是均匀的，所以只需要知道“被挡了多少”，就能把环境光整体压暗。\n但真实场景里，间接光往往是有方向性的：比如左边有一面红", "u": "GAMES202/202_L09.html#s1"}, {"c": "GAMES202 L09 · 第 9 讲：屏幕空间全局光照（续）——SSDO 与 SSR", "t": "SSDO 的核心：像路径追踪一样在半球上打光线", "x": "SSDO 的算法直觉非常像路径追踪。对屏幕上的每个着色点 \\(p\\)：\n\n在 \\(p\\) 的半球方向内随机取若干条光线；\n对每条光线，在屏幕空间里判断它是否打中障碍物（比较采样点深度与深度缓冲）；\n如果没打中，说明这个方向是“开阔”的，贡献的是直接光照（来自已知光源）；\n如果打中了，说明这个方向被遮", "u": "GAMES202/202_L09.html#s2"}, {"c": "GAMES202 L09 · 第 9 讲：屏幕空间全局光照（续）——SSDO 与 SSR", "t": "SSDO 的局限：短程 GI 与屏幕空间缺失", "x": "SSDO 的效果比 SSAO 更接近离线渲染，但它仍然不是真正的全局光照。课件明确列出两个问题：\n第一，仍然是短程 GI（GI in a short range）。 SSDO 的间接光只来自屏幕空间里邻近的像素，采样半径通常只有几十个像素。这意味着它只能捕捉着色点附近物体之间的颜色渗透（color ", "u": "GAMES202/202_L09.html#s3"}, {"c": "GAMES202 L09 · 第 9 讲：屏幕空间全局光照（续）——SSDO 与 SSR", "t": "SSR 是什么：在屏幕空间做光线追踪", "x": "屏幕空间反射（Screen Space Reflection, SSR） 是另一种在实时渲染里引入全局光照效果的方法。它的核心思想很直接：做光线追踪，但不需要场景的 3D 图元（三角形等），而是直接在屏幕空间的深度缓冲和颜色缓冲上做。\n为什么可以不用三角形？因为深度缓冲已经告诉我们每个像素对应的场景", "u": "GAMES202/202_L09.html#s4"}, {"c": "GAMES202 L09 · 第 9 讲：屏幕空间全局光照（续）——SSDO 与 SSR", "t": "用深度 mipmap 加速求交：min-Z 金字塔与层级追踪", "x": "如果每条光线都逐像素步进，代价会非常高。SSR 的加速思路和 3D 空间里的 BVH、KD-tree 非常像：建立层次结构，快速跳过不可能相交的区域。\n具体做法是构建深度 mipmap（min-Z 金字塔）：第 0 层是原始深度，第 1 层每个像素取 2×2 区域深度的最小值，第 2 层再取第 1 ", "u": "GAMES202/202_L09.html#s5"}, {"c": "GAMES202 L09 · 第 9 讲：屏幕空间全局光照（续）——SSDO 与 SSR", "t": "SSR 的着色与工程改进：粗糙度、接触硬化与预滤波", "x": "求交之后就是着色。SSR 的着色公式和路径追踪完全一样：\n\\[ L_o(p, \\omega_o) = \\int_{\\Omega^+} L_i(p, \\omega_i) f_r(p, \\omega_i, \\omega_o) \\cos\\theta_i \\, d\\omega_i \\]\n其中 \\(L_i\\)", "u": "GAMES202/202_L09.html#s6"}, {"c": "GAMES202 L09 · 第 9 讲：屏幕空间全局光照（续）——SSDO 与 SSR", "t": "SSR 的优缺点与适用场景", "x": "课件最后总结了 SSR 的优缺点：\n优点：\n\n对光泽/镜面反射（glossy and specular reflections）性能很快；\n质量不错；\n没有“尖刺”（spikes）和遮挡问题——相比一些基于探针的方法，SSR 的反射在几何上更准确。\n\n缺点：\n\n在漫反射情况下效率不高（not as ", "u": "GAMES202/202_L09.html#s7"}, {"c": "GAMES202 L09 · 核心结论", "t": "SSDO 是对 SSAO 的改进：不再假设入射间接光均匀，而是利用屏幕空间已渲染的直接光照信息来近似方向性间接光。", "x": "", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 核心结论", "t": "SSDO 在着色点向半球随机发射光线：没打中障碍物就取直接光照，打中了就取该像素作为间接光源，思路与路径追踪一致。", "x": "", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 核心结论", "t": "SSDO 把出射辐射度拆成未遮挡方向与遮挡方向两部分积分，遮挡方向用屏幕空间像素作为次级光源。", "x": "", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 核心结论", "t": "SSR 是在屏幕空间做光线追踪：用深度缓冲和颜色缓冲求交与着色，不需要场景的 3D 图元。", "x": "", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 核心结论", "t": "SSR 的求交可以借助深度 mipmap（min-Z 金字塔）做层级追踪，用保守的 min 操作快速跳过不可能相交的区域。", "x": "", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 核心结论", "t": "SSR 着色与路径追踪公式相同，但要注意平方距离衰减和着色点与次级光源之间的遮挡问题。", "x": "", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 核心结论", "t": "SSR 擅长光滑/光泽反射，对漫反射效率不高，且屏幕外信息缺失会导致反射断裂。", "x": "", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 术语", "t": "SSDO / 屏幕空间方向性遮蔽", "x": "在 SSAO 基础上引入方向性间接光的屏幕空间 GI 方法。", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 术语", "t": "SSR / 屏幕空间反射", "x": "在屏幕空间用深度和颜色缓冲做光线追踪来近似反射。", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 术语", "t": "Min-Z Pyramid / 最小深度金字塔", "x": "对深度图逐级取 min 构建的层次结构，用于保守地加速光线求交。", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 术语", "t": "Hierarchical Tracing / 层级追踪", "x": "根据光线与表面的相对位置动态调整 mip 层级的光线步进方法。", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 术语", "t": "Contact Hardening / 接触硬化", "x": "反射/遮蔽在靠近物体处更清晰、远处更模糊的现象。", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 术语", "t": "Specular Elongation / 高光拉长", "x": "掠射角下高光沿切线方向被拉长的现象。", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 术语", "t": "BRDF Importance Sampling / BRDF 重要性采样", "x": "按 BRDF 分布采样方向，让样本集中在贡献大的区域。", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 术语", "t": "Color Bleeding / 颜色渗透", "x": "物体表面颜色通过间接光影响邻近表面的现象。", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 术语", "t": "Screen Space GI / 屏幕空间全局光照", "x": "仅利用相机可见信息近似全局光照的一类方法的总称。", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 练习", "t": "SSAO 与 SSDO 的核心区别是什么？为什么说 SSDO 更接近路径追踪？", "x": "", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 练习", "t": "SSR 为什么不需要三角形等 3D 图元？它的两个基本任务是什么？", "x": "", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 练习", "t": "深度 mipmap 为什么取 min 而不是平均值？请用“保守性”解释。", "x": "", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 练习", "t": "SSR 的着色公式与路径追踪相同，课件提出两个问题：是否引入平方距离衰减？是否处理遮挡？请说明为什么这两个问题在 SSR 里同样存在。", "x": "", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L09 · 练习", "t": "在一个有大面积粗糙地面的场景里，你会如何配置 SSR？为什么？", "x": "", "u": "GAMES202/202_L09.html"}, {"c": "GAMES202 L08 · 第 8 讲：实时全局光照（下）——LPV、VXGI 与屏幕空间环境光遮蔽", "t": "1. LPV：用三维网格把光“扩散”出去", "x": "光传播体积（Light Propagation Volumes, LPV）最早在 CryEngine 中引入，特点是性能快、质量尚可。它要解决的核心问题是：在任意着色点、任意方向上查询辐照度。直接光照好算，但间接光需要知道从四面八方来的光，这本来是个全局问题。\nLPV 的关键假设非常朴素：辐照度沿直", "u": "GAMES202/202_L08.html#s1"}, {"c": "GAMES202 L08 · 第 8 讲：实时全局光照（下）——LPV、VXGI 与屏幕空间环境光遮蔽", "t": "2. VXGI：体素化场景 + 锥体追踪", "x": "体素全局光照（Voxel Global Illumination, VXGI）仍然是两趟（two-pass）算法，和 RSM 同属“从光源出发、再从相机出发”的结构，但有两个关键区别：\n\n直接光照的载体不同：RSM 存的是被直接照亮的像素，VXGI 存的是（分层的）体素。\n查询方式不同：RSM 是在", "u": "GAMES202/202_L08.html#s2"}, {"c": "GAMES202 L08 · 第 8 讲：实时全局光照（下）——LPV、VXGI 与屏幕空间环境光遮蔽", "t": "3. 什么是“屏幕空间”：只用已经渲染出来的画面", "x": "屏幕空间（screen space）这个词在实时渲染里出现频率极高，它的意思很直接：只使用“屏幕”上已有的信息。换句话说，就是在已经渲染好的画面上做后处理（post processing）。这些信息通常包括颜色缓冲、深度缓冲、法线缓冲（G-buffer）。\n这样做的好处是：不需要场景的完整三维表示，", "u": "GAMES202/202_L08.html#s3"}, {"c": "GAMES202 L08 · 第 8 讲：实时全局光照（下）——LPV、VXGI 与屏幕空间环境光遮蔽", "t": "4. SSAO 的动机：用可见性补上缺失的间接光", "x": "屏幕空间环境光遮蔽（Screen Space Ambient Occlusion, SSAO）同样最早由 Crytek 引入。先问为什么需要 AO：它实现便宜，但能显著增强物体相对位置的感知——角落、缝隙、物体接触处变暗，人眼立刻觉得“这些东西是放在一起的”。课件展示了开启 AO 前后的对比，暗部让", "u": "GAMES202/202_L08.html#s4"}, {"c": "GAMES202 L08 · 第 8 讲：实时全局光照（下）——LPV、VXGI 与屏幕空间环境光遮蔽", "t": "5. SSAO 的推导：把渲染方程拆成“常数 × 可见性积分”", "x": "一切还是从渲染方程出发：\n\\[ L_o(p,\\omega_o) = \\int_{\\Omega^+} L_i(p,\\omega_i) f_r(p,\\omega_i,\\omega_o) V(p,\\omega_i) \\cos\\theta_i \\, d\\omega_i \\]\n这里只关心间接光部分。用实时渲染", "u": "GAMES202/202_L08.html#s5"}, {"c": "GAMES202 L08 · 第 8 讲：实时全局光照（下）——LPV、VXGI 与屏幕空间环境光遮蔽", "t": "6. 从 SSAO 到 SSDO 与 SSR：屏幕空间 GI 的全景", "x": "SSAO 只回答了“有多少间接光能到达”，没有回答“从哪个方向来”。屏幕空间方向性遮蔽（Screen Space Directional Occlusion, SSDO）在此基础上进一步：它不仅估计可见性，还利用屏幕空间信息估计间接光的方向性，从而能产生带颜色的间接光（比如红墙旁边的白球会染上红色）", "u": "GAMES202/202_L08.html#s6"}, {"c": "GAMES202 L08 · 核心结论", "t": "LPV 用三维网格传播辐照度：先把直接光照表面当作虚拟光源注入网格（用一阶 SH 存方向分布），再逐格向邻居传播直到稳定，最后着色时查所在格子的入射辐照度。", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 核心结论", "t": "LPV 的核心假设是“辐照度沿直线传播且不衰减”，这导致光会穿过遮挡物——即漏光（light leaking），是它的致命缺陷。", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 核心结论", "t": "VXGI 把场景体素化并建层次结构，从光源 Pass 存每个体素的入射与法线分布，从相机 Pass 沿反射方向追踪锥体，按锥体大小查询对应层级的体素。", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 核心结论", "t": "VXGI 对 glossy 表面追踪一个锥体，对 diffuse 表面追踪多个锥体（如 8 个），效果接近光线追踪，但仍有体素化带来的精度问题。", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 核心结论", "t": "“屏幕空间”指只用屏幕上已有的信息（颜色、深度、法线）做后处理，因此看不到屏幕外的物体，会产生边缘缺失、拖影等问题。", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 核心结论", "t": "SSAO 把间接光近似为常数，把渲染方程拆成“常数项 × 可见性积分”，可见性积分就是环境光遮蔽（AO），用屏幕空间深度采样来估计。", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 核心结论", "t": "SSAO 中可以把余弦项和可见性放在一起积分，是因为投影立体角（projected solid angle）在整个半球上的积分等于单位圆盘面积 π，归一化后正好", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 核心结论", "t": "SSAO 的近似在“入射光为常数且材质为漫反射”时是准确的，这也是它只适用于间接光低频部分的原因。", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 术语", "t": "Light Propagation Volumes (LPV) / 光传播体积", "x": "用三维网格把直接光照的辐照度传播到整个场景，不检查遮挡，会漏光。", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 术语", "t": "Voxel Global Illumination (VXGI) / 体素全局光照", "x": "体素化场景并建层次结构，用锥体追踪查询间接光。", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 术语", "t": "Cone Tracing / 锥体追踪", "x": "沿方向追踪一个逐渐变粗的锥体，按锥体大小查询对应层级的体素。", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 术语", "t": "Screen Space Ambient Occlusion (SSAO) / 屏幕空间环境光遮蔽", "x": "假设间接光为常数，用屏幕空间深度采样估计加权平均可见性。", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 术语", "t": "Screen Space Directional Occlusion (SSDO) / 屏幕空间方向性遮蔽", "x": "在 SSAO 基础上估计间接光方向性，能产生带颜色的间接光。", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 术语", "t": "Screen Space Reflection (SSR) / 屏幕空间反射", "x": "用深度缓冲做射线步进，在屏幕空间找反射光线击中的物体。", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 术语", "t": "Projected Solid Angle / 投影立体角", "x": "余弦加权的立体角，单位半球映射到单位圆盘，总积分为 π。", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 术语", "t": "Split-Sum Approximation / 拆分近似", "x": "把积分拆成两个积分相乘，前提是其中一个函数近似常数。", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 术语", "t": "Light Leaking / 漏光", "x": "光穿过遮挡物照亮本应黑暗的区域，是 LPV 等方法的典型缺陷。", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 术语", "t": "Reflective Shadow Maps (RSM) / 反射阴影图", "x": "把直接光照像素当作虚拟光源，是 LPV 和 VXGI 的输入来源。", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 练习", "t": "LPV 的四个步骤分别是什么？为什么它会产生漏光？", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 练习", "t": "VXGI 与 RSM 的两个主要区别是什么？VXGI 对 glossy 和 diffuse 表面分别如何查询？", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 练习", "t": "从渲染方程出发，推导 SSAO 的近似公式，并说明为什么可以把余弦项和可见性放在一起积分。", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 练习", "t": "在 UE 或 Unity 中开启 SSAO 后，为什么物体边缘会出现一圈暗边？这是 bug 吗？", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES202 L08 · 练习", "t": "实践题：在 UE 中创建一个角落场景（两面墙 + 地面），分别关闭和开启 SSAO，观察画面差异；然后调大 Radius 和 Intensity，记录变化并解释", "x": "", "u": "GAMES202/202_L08.html"}, {"c": "GAMES101", "t": "现代计算机图形学入门 · 课程总览", "x": "从向量与变换讲到光栅化、着色、几何、光线追踪与动画模拟，是整条图形学知识链的地基。", "u": "GAMES101/index.html"}, {"c": "GAMES104", "t": "现代游戏引擎：理论、实践与架构 · 课程总览", "x": "以现代游戏引擎为主线，覆盖渲染、动画、物理、特效、玩法系统、工具链与网络架构。", "u": "GAMES104/index.html"}, {"c": "GAMES202", "t": "高质量实时渲染 · 课程总览", "x": "阴影、环境光照、实时全局光照与降噪，把 101 的原理推进到可落地的实时渲染方案。", "u": "GAMES202/index.html"}, {"c": "GAMES105", "t": "计算机角色动画基础 · 课程总览", "x": "骨骼、蒙皮、动作捕捉、物理驱动与强化学习，覆盖角色动画从手工到数据驱动的完整谱系。", "u": "GAMES105/index.html"}];